int main() {
	long long N;
	cin >> N;
	vector <long long> an (N+1);
	vector <long long> bn (N);

	for (int i=0;i<N+1;i++){
		cin >> an.at(i);
	}

	for (int i=0;i<N;i++){
		cin  >> bn.at(i);
	}

	long long count=0;
	long long q =0;

	if (an.at(0)<=bn.at(0)){
			count = count +an.at(0);
			q= bn.at(0)-an.at(0);
		}

		else if (bn.at(0)<an.at(0)){
			count = count +bn.at(0);
			q= 0;
		}

	for (int i=1; i<N;i++){

		if (q>=an.at(i)){
			count = count +an.at(i);
			q = bn.at(i);
		}

		else if (q< an.at(i) && bn.at(i)+q >= an.at(i)){
			count = count + an.at(i);
			q = bn.at(i)+q-an.at(i);
		}

		else if(bn.at(i)+q<an.at(i)){
			count = count + bn.at(i)+q;
			q=0;
		}
	}

	count = count + min(q,an.at(N));

	cout << count << endl;


}
