vector<string> split(const string &s, char remove) {
    istringstream stream(s);
    string field;
    vector<string> ans;
    while (getline(stream, field, remove)) {
        ans.emplace_back(field);
    }
    return ans;
}

int main() {
    string s;
    cin >> s;
    ll ans = 0;

    auto sum = [](string x) {
        auto v = split(x, '+');
        ll ret = 0;
        for (auto &&i : v) {
            ret += stoll(i);
        }
        return ret;
    };

    auto dfs = [&](auto f, int now, string formula) {
        if (now == s.size()) {
            ans += sum(formula);
            return;
        }
        f(f, now + 1, formula + string{s[now]});
        f(f, now + 1, formula + "+" + string{s[now]});
    };

    dfs(dfs, 1, {s[0]});
    cout << ans << endl;

    return 0;
