ll gcd(ll a, ll b) {
    assert(a >= 0);
    assert(b >= 0);
    if (b == 0) return a;
    return gcd(b, a % b);
}

ll extgcd(ll a, ll b, ll& x, ll& y) {
    x = 1; y = 0;
    assert(a >= 0);
    assert(b >= 0);
    if (b == 0) return a;
    ll X, Y;
    auto d = extgcd(b, a % b, X, Y);
    x = Y;
    y = X - (a / b) * Y;
    return d;
}

int run(istream& in, ostream& out) {
    std::string S;
    in >> S;
    ll ans = 0;

    char prev = 0;
    ll max_len = 0;
    REP(i, S.size()) {
        if (S[i] == 'R') {
            if (prev == S[i]) {
                ++max_len;
            } else {
                max_len = 1;
            }
        } else {
            ans = max(max_len, ans);
            max_len=0;
        }
        prev = S[i];
    }
    ans = max(max_len, ans);
    out << ans << endl;
    return 0;
}

int main() {
    return run(cin, cout);
}
