#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define rp(i,s,e) for(int i=(s);i<(e);++i)

#define MOD 1000000007
#define MAX 1000001
ll fac[MAX]; // 累乗 n!
ll inv[MAX]; // 逆元 1/n
ll finv[MAX]; // 逆元の累乗 (n^-1)! = (1/n)!

void init(int n, int p){
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	rp(i, 2, n+1){
		fac[i] = fac[i-1] * i % p;
		inv[i] = p - inv[p%i] * (p/i) % p;
		finv[i] = finv[i-1] * inv[i] % p;
	}
}

ll comb(int n, int r, int m){
	if(n<r || n<0 || r<0) return 0;
	return fac[n] * (finv[n-r] * finv[r] % m) % m;
}

int main(){
	int X,Y; cin>>X>>Y;
	init(max(X,Y)+1, MOD);
	if((X+Y)%3 != 0){
		puts("0");
	}
	else{
		int r = (2*X-Y)/3;
		int n = (2*Y-X)/3 + r;
		cout<< comb(n, r, MOD) % MOD << endl;
	}
},accepted,,p02862

#include <bits/stdc++.h>
