using namespace std;

int n,m;
vector<int> preci[100010];
vector<int> potomci[100010];
int br[100010];
int dp[100010];

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin>>n>>m;
	int x,y;
	for(int i=0;i<m;i++)
    {
        cin>>x>>y;
        preci[y].push_back(x);
        potomci[x].push_back(y);
        br[y]++;
    }

    queue<int> red;
    vector<int> topolosko;
    for(int i=1;i<=n;i++)
        if(br[i]==0)
            red.push(i);

    while(!red.empty())
    {
        int tek=red.front();
        red.pop();
        topolosko.push_back(tek);
        for(int i=0;i<potomci[tek].size();i++)
        {
            br[potomci[tek][i]]--;
            if(br[potomci[tek][i]]==0)
                red.push(potomci[tek][i]);
        }
    }

    for(int i=0;i<n;i++)
    {
        int tek=topolosko[i];
        for(int i=0;i<preci[tek].size();i++)
            dp[tek]=max(dp[tek], dp[preci[tek][i]]+1);
    }

    int sol=0;
    for(int i=1;i<=n;i++)
        if(dp[i]>sol)
            sol=dp[i];

    cout<<sol;

	return 0;
}
