  }

  mint ans = 0_m;
  times(size(gc[0]), i) times(size(gc[1]), j) {
    if((i ^ j) < size(gc[2])) {
      {if(debug)cerr<<'#'<<__LINE__ ln<<"  i:                                  "<<(i)ln<<"  j:                                  "<<(j)ln<<"  i^j:                                "<<(i^j)ln<<"  gc[0][i] * gc[1][j] * gc[2][i ^ j]: "<<(gc[0][i] * gc[1][j] * gc[2][i ^ j])ln;}
      ans += gc[0][i] * gc[1][j] * gc[2][i ^ j];
    }
  }

