          a[i][j]--;
          a[i-1][j]++;
          from.push_back({i,j});
          to.push_back({i-1,j});
        }
        else if(j!=0 && a[i][j-1]%2!=0)
        {
          a[i][j]--;
          a[i][j-1]++;
          from.push_back({i,j});
          to.push_back({i,j-1});
        }
        else if(i!=h-1 && a[i+1][j]%2!=0)
        {
          a[i][j]--;
          a[i+1][j]++;
          from.push_back({i,j});
          to.push_back({i+1,j});
        }
        else if(j!=w-1 && a[i][j+1]%2!=0)
        {
          a[i][j]--;
          a[i][j+1]++;
          from.push_back({i,j});
          to.push_back({i,j+1});
        }
        else 
        {
          if(j!=w-1)
          {
            a[i][j]--;
          	a[i][j+1]++;
          	from.push_back({i,j});
          	to.push_back({i,j+1});
          }
