typedef long long ll;
const int mod = 1e+9 + 7;

ll r1, r2, c1, c2;

ll qPow(ll a, ll b)
{
    a %= mod;

    ll res = 1;
    while(b) {
        if(b & 1) res = res * a % mod;
        a = a * a % mod, b >>= 1;
    }
    return res;
}

ll C(ll n, ll m)
{
    if(n < m) return 0;

    ll res = 1;
    for(int i = 1; i <= m; ++i)
        res = res * (n - i + 1) % mod * qPow(i, mod - 2) % mod;
    return res;
}

int main()
{
    scanf("%lld%lld%lld%lld", &r1, &c1, &r2, &c2);

    ++r2, ++c2;
    printf("%lld", ((C(r2 + c2, c2) - C(r1 + c2, c2) - C(r2 + c1, c1) + C(r1 + c1, c1)) % mod + mod) % mod);
