#include <bits/stdc++.h>
using namespace std;
#define REP(i, n) for(int i = 0; i < n; i++)

int root(int r[], int x)
{
  if(r[x] == x)
    return x;
  else
  {
    return r[x] = root(r, r[x]);
  }
}

bool same(int r[], int x, int y)
{
  return (root(r, x) == root(r, y));
}

void punion(int r[], int x, int y)
{
  if(same(r,x,y))
    return;
  r[root(r,x)] = root(r,y);
}

int main()
{
  int n, k, l;
  cin >> n >> k >> l;
  int rd[n];
  int rw[n];
  REP(i, n)
  {
    rd[i] = i;
    rw[i] = i;
  }

  REP(i, k)
  {
    int p, q;
    cin >> p >> q;
    p--; q--;
    punion(rd, p, q);
  }
  REP(i, l)
  {
    int p, q;
    cin >> p >> q;
    p--; q--;
    punion(rw, p, q);
  }

  pair<int, int> q[n];
  map<pair<int, int>, int> ans;
  REP(i, n)
