const int MAX = 1000005;
//const int mod = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod/i) % mod;
        finv[i] = finv[i-1] * inv[i] % mod;
    }
}
long long COM(int n, int k){
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}


int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll H, W, A, B;
    cin >> H >> W >> A >> B;

    COMinit();

    ll ans = 0;
    for(int i=B+1; i<=W; ++i) {
        ans += COM(H-A-1 + i-1, i-1) * COM(A-1 + W-i, W-i);
        chmod(ans);
    }
    cout << ans << endl;

    return 0;
}
