void check(int n, long long x) {
	if (n > 0) {
		if (x == la[n] || x == la[n] - 1) {
			ans += pa[n];
			x = 0;
		}
		else if (la[n] / 2 + 1 < x&&x < la[n] - 1) {
			ans += pa[n - 1]+1;
			x -= la[n] / 2 + 1;
		}
		else if (x == la[n]/2 + 1) {
			ans += 1;
			x -= 2;
		}
		else if (x == 0 || x == 1)
			x = 0;
		else
			x--;
		check(n - 1, x);
	}
	else
		ans += x;
}

