ll fact[1000005], invfact[1000005];

ll fastExp(ll base, ll p) {
	ll ret = 1;
	while (p) {
		if (p & 1ll) {
			ret *= base;
			ret %= MOD;
		}
		base *= base;
		base %= MOD;
		p >>= 1ll;
	}
	return ret;
}

ll comb(ll a, ll b) {
	ll ret = fact[a] * invfact[b];
	ret %= MOD;
	ret *= invfact[a-b];
	ret %= MOD;
	return ret;
}

int main() {
