	invfact[0] = 1;
	for (ll i = 1; i <= 1000000; i++) {
		fact[i] = i * fact[i-1];
		fact[i] %= MOD;
		invfact[i] = fastExp(fact[i], MOD-2);
	}
	int x,y;
	scanf("%d %d", &x, &y);
	ll ans = 0;
	for (int a = x%2; a <= x; a += 2) {
		int b = (x-a)/2;
		if (2*a + b != y) continue;
		ans += comb(a+b, b);
		ans %= MOD;
	}
