ll solve() {
    string S, T;
    cin >> S >> T;
    vector<vector<int>> pos(26, vector<int>());
    ll ns = S.size(), nt = T.size();
    for ( int i = 0; i < ns; i++ ) {
        pos[S[i] - 'a'].push_back(i);
    }
    ll lp = 0, ps = 0;
    for ( int pt = 0; pt < nt; pt++ ) {
        int c = T[pt] - 'a';
        auto ips = lower_bound(pos[c].begin(), pos[c].end(), ps);
        if ( ips == pos[c].end() ) {
            lp++;
            ips = lower_bound(pos[c].begin(), pos[c].end(), 0);
            if ( ips == pos[c].end() ) return -1;
        }
        ps = *ips + 1;
    }
    ll ans = lp * ns + ps;
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
