void MakePrime(int n) {
	prime.emplace_back(2);
	for (int i = 3; i <= n; i += 2) {
		bool a = false;
		for (int j = 3; j <= sqrt(i); j += 2) {
			if (i%j == 0) {
				a = true;
			}
		}
		if (a == false) {
			prime.emplace_back(i);
		}
	}
}
