void bfs()
{
	queue<pii> q;
	q.push(mp(cx,cy));d[cx][cy]=0;
	while(!q.empty())
	{
		int x=q.front().first,y=q.front().second;
		q.pop();
		for(int i=0;i<4;i++)
		{
			int nx=x+dx[i],ny=y+dy[i];
			if(d[nx][ny]<=d[x][y]+1||s[nx][ny]=='#')continue;
			d[nx][ny]=d[x][y]+1;
		    q.push(mp(nx,ny));
	    }
	}
}
