{
	scanf("%d%d%d",&n,&m,&k);
	for(int i=1;i<=n;i++)
	{
		scanf("%s",s[i]+1);
		for(int j=1;j<=m;j++)
		{if(s[i][j]=='S')cx=i,cy=j,s[i][j]='.';d[i][j]=1e9;} 
	}
	bfs();
	for(int i=1;i<=n;i++)
	for(int j=1;j<=m;j++)
	if(d[i][j]<=k)
	ans=min(ans,1+(min(min(i-1,n-i),min(j-1,m-j))+k-1)/k);
