int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	int H, W, N;
	cin >> H >> W >> N;
	vector<vector<int> > G(H);
	for (int i = 0; i < N; ++i) {
		int a, b;
		cin >> a >> b; --a, --b;
		G[a].push_back(b);
	}
	function<int(int, int)> get_fin = [&](int x, int y) {
		if (y == 0 && x % 2 == 0) --x;
		if (y == W - 1 && (x + y) % 2 == 1) --x;
		if (x == -1) return y;
		int rem = x % (2 * W);
		int pot = y;
		if (x % 2 != y % 2) pot = 2 * W - y - 1;
		pot %= 2 * W;
		int fin = (pot - rem + 2 * W) % (2 * W);
		int ans = (fin < W ? fin : 2 * W - fin - 1);
		if (fin == -1) fin = 0;
		return ans;
	};
	vector<int> perm(W);
	for (int i = 0; i < W; ++i) perm[i] = i;
	for (int i = 0; i < H; ++i) {
		for (int j : G[i]) {
			int lc = get_fin(i, j);
			int rc = get_fin(i, j + 1);
			swap(perm[lc], perm[rc]);
		}
	}
	vector<int> ans(W);
	for (int i = 0; i < W; ++i) {
		int res = get_fin(H, i);
		ans[perm[res]] = i;
	}
	for (int i = 0; i < W; ++i) {
		cout << ans[i] + 1 << '\n';
	}
	return 0;
}
