int d;
constexpr int m = 26;
int c[26];
int s[365][26];
inline int calc(vector<int> &t) {
    vector<int> last(26, -1);
    int res = 0;
    rep(i, d) {
        res += s[i][t[i]];
        last[t[i]] = i;
        rep(j, 26) res -= c[j] * (i - last[j]);
    }
    return res;
}
struct Data {
    array<int, m> last;
    array<int, 365> ans;
    int score;
    Data() {
        rep(i, m) last[i] = -1;
        score = 0;
    }
    bool const operator<(const Data &rhs) const { return score > rhs.score; }
    bool const operator>(const Data &rhs) const { return score < rhs.score; }
};
int LAST[26];
inline void calc(Data &x) {
    rep(i, 26) LAST[i] = -1;
    x.score = 0;
    rep(i, d) {
        x.score += s[i][x.ans[i]];
        LAST[x.ans[i]] = i;
        rep(j, m) { x.score -= c[j] * (i - LAST[j]); }
    }
}
inline Data get(Data x, int day, int num) {
    x.score += s[day][num];
    x.ans[day] = num;
    x.last[num] = day;
    rep(i, m) x.score -= c[i] * (day - x.last[i]);
    return x;
}
inline int change(Data &x, int a, int b) {
    if(x.ans[a] == b) return 0;
    int res = s[a][b] - s[a][x.ans[a]];
    int pre = x.ans[a];
    int K = a + 1, L = d - a;
    rep3(i, a - 1, 0) if(x.ans[i] == b) {
        K = a - i;
        break;
    }
    rep2(i, a + 1, d - 1) if(x.ans[i] == b) {
        L = i - a;
        break;
    }
    res += c[b] * K * L;
    K = a + 1, L = d - a;
    rep3(i, a - 1, 0) if(x.ans[i] == pre) {
        K = a - i;
        break;
    }
    rep2(i, a + 1, d - 1) if(x.ans[i] == pre) {
        L = i - a;
        break;
    }
    res -= c[pre] * K * L;
    return res;
}
constexpr int sz = 350;
Data ds[sz];
Data tmp[sz * m];
const int N = 1e6;
inline bool prob(int dx, double temp) { return exp(dx / temp) * N > rnd(N); }
main() {
    auto start = clock();
    cin >> d;
    rep(i, 26) cin >> c[i];
    rep(i, d) rep(j, 26) cin >> s[i][j];
    vector<Data> v(1);
    int cnt = 1;
    rep(i, d) {
        int now = 0;
        rep(a, cnt) rep(j, m) tmp[now++] = get(ds[a], i, j);
        if(now < sz) {
            rep(j, now) ds[j] = tmp[j];
            cnt = now;
        } else {
            nth_element(tmp, tmp + sz, tmp + now);
            rep(j, sz) ds[j] = tmp[j];
            cnt = sz;
        }
    }
    Data best = ds[0];
    // cerr << best.score << endl;
    rep(i, sz) chmin(best, ds[i]);
    Data now = best;
    auto End = start + (double)CLOCKS_PER_SEC * 1.9;
    const double temp = 200;
    while(clock() < End) {
        int a = rnd(d), b = rnd(26);
        int dx = change(now, a, b);
        if(prob(dx, temp * (clock() - start) / (End - start))) {
            now.ans[a] = b;
            now.score += dx;
            if(now.score > best.score) best = now;
        }
    }
    // calc(best);
    // cerr << best.score << endl;
    for(auto e : best.ans) { cout << ++e << endl; }
}
