#include <iostream>
#include <vector>
#include <string>

using namespace std;

int calc_gcd(int a, int b)
{
  if (b == 0)
    return a;
  return calc_gcd(b, a%b);
}

int main()
{
  int n;

  cin >> n;

  int a[n];
  for (int i=0;i<n;++i) {
    cin >> a[i];
  }

  int gcd[n][2];
  for (int i=0;i<n;++i) {
    gcd[i][0] = 0;
    gcd[i][1] = 0;
  }

  //[0-i)のgcd
  for (int i=0;i<n;++i) {
    if (i == 0) {
      gcd[i][0] = 0;
    } else if (i == 1) {
      gcd[i][0] = a[0];
    } else {
	  gcd[i][0] = calc_gcd(gcd[i-1][0], a[i-1]);
    }
  }

  // (i-(n-1)]のgcd
  for (int i=n-1;i>=0;--i) {
    //(i-(n-1)]のgcd
    if (i == n-1) {
      gcd[i][1] = 0;
    } else if (i == n-2) {
      gcd[i][1] = a[n-1];
    } else {
      gcd[i][1] = calc_gcd(gcd[i+1][1], a[i+1]);
    }
  }

  for (int i=0;i<n;++i) {
    if (gcd[i][0] == 0) {
      gcd[i][0] = gcd[i][1];
    } 
    else if (gcd[i][1] == 0) {
      gcd[i][1] = gcd[i][0];
    } 
  }
  /*
  for (int i=0;i<n;++i) {
    cout << gcd[i][0];
    cout << ',';
    cout << gcd[i][1];
    cout << endl;
  }
  */

  int max_gcd = 0;
  for (int i=0;i<n;++i) {
    int tmp_gcd = calc_gcd(gcd[i][0], gcd[i][1]);
    if (max_gcd < tmp_gcd)
      max_gcd = tmp_gcd;
  }


  int ans = max_gcd;
  cout << ans << endl;

  return 0;
}
