ll read() {
	ll x=0,f=1;char c=getchar();
	while(c<'0'||c>'9') {
		if(c=='-') f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9') {
		x=x*10+c-'0';
		c=getchar();
	}
	return x*f;
}
int *f[N],trans[N][2];
char s[N];
int main() {
	int n = read(),K = read();
	f[1] = new int[1 << (n + 1)];
	f[1][0] = 0;
	for(int i = 0;i <= n;++i) {
		int p = 1 << i;
		scanf("%s",s);
		for(int j = 0;j < p;++j) f[1][p + j] = s[j] - '0';
		for(int j = 0;j < p;++j) trans[p + j][1] = j;
		trans[p + p - 1][0] = 0;
		for(int j = 1;j < p;++j) trans[p + p - j - 1][0] = j ^ ((1 << (31 - __builtin_clz(j))) - 1);
	}

	// puts("!!!");

	int ans = 1;
	for(int i = 1;i <= n;++i) {
		int p = 1 << i;
		for(int j = p + p - 1;j >= p;--j) {
			f[j] = new int[1 << (n - i + 1)];
			memset(f[j],0,sizeof(int) << (n - i + 1));
			for(int k = 1;k < (1 << (n - i + 2));++k) f[j][trans[k][j & 1]] += f[j >> 1][k];
			f[j][0] = 0;
			if(accumulate(f[j],f[j] + (1 << (n - i + 1)),0) >= K) ans = j;
		}
	}
	// puts("!!!");
	for(int i = 30 - __builtin_clz(ans);i >= 0;--i) printf("%d",ans >> i & 1);

	return 0;
