    if (i < j && a[i] > a[j]) c[i]++;
    if (i > j && a[i] > a[j]) d[i]++;
  }
  mint ans = 0;
  rep(i, n) {
    ans += (mint) k * (k + 1) * c[i];
    ans += (mint) k * (k - 1) * d[i];
  }
  cout << ans / 2 << endl;
}
