using namespace std;

struct SegmentTree {
private:
	int N;
	vector<LL> node;
	const long long DEFAULT = -9223372036854775807LL;
public:
	void init(int n) {
		node.clear();
		N = 1;
		while (N < n) N *= 2;
		for (int i = 0; i < 2 * N - 1; i++) node.push_back(DEFAULT);
	}
	void update(int i, long long x) {
		i += N - 1;
		node[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
		}
	}
	long long maximum(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r == -1) r = N;
		if (r <= a || b <= l) return DEFAULT;
		if (a <= l && r <= b) return node[k];
		return max(maximum(a, b, k * 2 + 1, l, (l + r) / 2), maximum(a, b, k * 2 + 2, (l + r) / 2, r));
	}
	long long m;
	int find(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r == -1) {
			m = maximum(a, b);
			r = N;
		}
		if (r <= a || b <= l) return 99999999;
		if (r - l == 1) {
			if (node[k] == m) return l;
			else return 99999999;
		}
		if (a <= l && r <= b) {
			LL valueL = maximum(a, b, k * 2 + 1, l, (l + r) / 2);
			LL valueR = maximum(a, b, k * 2 + 2, (l + r) / 2, r);
			if (valueL >= valueR) return find(a, b, k * 2 + 1, l, (l + r) / 2);
			else return find(a, b, k * 2 + 2, (l + r) / 2, r);
		}
		return min(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}
};

int N, K;
int a[200000];
SegmentTree st;
int main() {
	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	st.init(N);
	for (int i = 0; i < N; i++) {
		st.update(i, a[i]);
	}
	int l = 0;
	for (int i = 0; i < N - K; i++) {
		int p = st.find(l, K+i+1);
		l = p + 1;
		//cout << K+i+1 << " " << p << endl;
		cout << a[p];
	}
	cout << endl;
	return 0;
}



