template< typename Monoid >
struct SegmentTree {
    using F = function< Monoid(Monoid, Monoid) >;

    int sz;
    vector< Monoid > seg;

    const F f;
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n) sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x) {
        seg[k + sz] = x;
    }

    void build() {
        for(int k = sz - 1; k > 0; k--) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    void update(int k, const Monoid &x) {
        k += sz;
        seg[k] = x;
        while(k >>= 1) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    Monoid query(int a, int b) {
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1) L = f(L, seg[a++]);
            if(b & 1) R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const {
        return seg[k + sz];
    }

    template< typename C >
    int find_subtree(int a, const C &check, Monoid &M, bool type) {
        while(a < sz) {
            Monoid nxt = type ? f(seg[2 * a + type], M) : f(M, seg[2 * a + type]);
            if(check(nxt)) a = 2 * a + type;
            else M = nxt, a = 2 * a + 1 - type;
        }
        return a - sz;
    }


    template< typename C >
    int find_first(int a, const C &check) {
        Monoid L = M1;
        if(a <= 0) {
            if(check(f(L, seg[1]))) return find_subtree(1, check, L, false);
            return -1;
        }
        int b = sz;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1) {
                Monoid nxt = f(L, seg[a]);
                if(check(nxt)) return find_subtree(a, check, L, false);
                L = nxt;
                ++a;
            }
        }
        return -1;
    }

    template< typename C >
    int find_last(int b, const C &check) {
        Monoid R = M1;
        if(b >= sz) {
            if(check(f(seg[1], R))) return find_subtree(1, check, R, true);
            return -1;
        }
        int a = sz;
        for(b += sz; a < b; a >>= 1, b >>= 1) {
            if(b & 1) {
                Monoid nxt = f(seg[--b], R);
                if(check(nxt)) return find_subtree(b, check, R, true);
                R = nxt;
            }
        }
        return -1;
    }
};
class FRangeSetQuery {
public:

        struct Query {
           int l,r,i;
            bool operator<(const Query R) const {
                return r < R.r;
            }


        };
void solve(std::istream& cin, std::ostream& cout, std::ostream& cerr) {
    int N,Q;cin >> N >> Q;
    VI a(N);cin >> a;
    VI b(N+1), lv(1e6, -1), ans(Q);
    vector<Query> queries(Q);
    REP(i,Q){int l,r;cin >> l >> r;l--,r--;queries[i] = {l, r, i};}
    sort(ALL(queries));
//    ERR(queries)
    int q = 0;
    SegmentTree<int> seg(N+2, [](int a, int b){return a + b;}, 0);
    REP(i,N){
        if(~lv[a[i]]){ERR(i,-1, lv[a[i]]);seg.update(lv[a[i]], 0);}
        lv[a[i]] = i;
        seg.update(i,1);
        while(q < Q && queries[q].r == i)ans[queries[q].i] = seg.query(0, queries[q].r+1) - seg.query(0, queries[q].l), q++;
    }
    ERR(seg.seg)
    REP(i,Q)print(ans[i]);
}


};


