//********rev 2;
#include <iostream>
#include <list>
#include <cctype>

using namespace std;

// data class
class D {
public:
	int n;
	int sets;

	list<D*> child;

	D() :child() {
		n = 0;
		sets = 0;
	};
};

// global var for input
char c[10002];

// get inputs
int get(D *d, int &l) {
	int sum = 0;
	if (c[l] == '[') { // if has datasets
		// loop for all sets
		list<int> ilist;
		while (c[l] == '[') {
			D *dd = new D();
			++l; // INFO: skip '['
			// INFO: rec.
			ilist.push_back(get(dd, l));
			// add to childlen
			d->child.push_back(dd);
			// inc. sets
			d->sets++;
			l++; // INFO: skip ']'
		}
		ilist.sort([](int &i1, int &i2){return i1 < i2;});
		auto iter = ilist.begin();
		for (int i = 0; i < d->sets / 2 + 1; i++) {
			sum += *iter;
			iter++;
		}
		d->n = sum;
		return sum;
	} else { // if has NO datasets (== only num)
		// char[] to num
		int num = c[l] - '0';
		for (l++; isdigit(c[l]); l++) {
			num = num * 10 + (c[l] - '0');
		}
		d->n = num / 2 + 1;
		return d->n;
	}
}

// solve from data
int ans(D *d) {
	if (d->sets == 0) { //if has NO datasets
		return d->n / 2 + 1; // min points for win
	}
	// else

	// function: conversion d with n
	auto func = [](D *d1, D *d2){return d1->n < d2->n;};
	// sort
	d->child.sort(func);
	// get lowlevel answer list
	// lowlevel ans list
	list <int> ilist;
	// iterator
	auto it = d->child.begin();
	for (int i = 0; i < d->sets; i++) {
		D *cur = *it;
		ilist.push_back(ans(cur));
		it++;
	}
	// sort for min
	ilist.sort([](int &i1, int &i2){return i1 < i2;});

	//get sum (== minpoints for win in thislevel)
	int sum = 0;
	auto iit = ilist.begin();
	for (int i = 0; i < d->sets / 2 + 1; i++) {
		sum += *iit;
		iit++;
	}
	return sum;
}

// solve
void solve() {
	int n;
	// input dataset length
	cin >> n;
	for (int i = 0; i < n; i++) {
		// input dataset
		cin >> c;
		D *d = new D();
		// INFO: 1: skip first '['
		int l = 1;
		// string to dataobj;
		get(d, l);
		// get answer
		//cout << ans(d) << endl;
		cout << d->n << endl;
		delete d;
	}
}



//----main----
int main(void) {
	solve();
},accepted,,p00769

