#include <cstdio>
#include <cmath>
#include <vector>
#include <utility>

using namespace std;

#define INF 2000000000

#define min_aplly(x, y) if (x > y) x = y;

int dp[81][150][10];

int main() {
    while (1) {
        int i, j, k, l;
        int n, m;
        vector<pair<int, int> > points[150];
        int min = INF;

        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) return 0;

        for (l=0;l<m+1;l++) {
            for (i=0;i<n;i++) {
                for (j=0;j<10;j++) {
                    dp[l][i][j] = INF;
                }
            }
        }

        for (i=0;i<n;i++) {
            scanf("%d", &k);
            for (j=0;j<k;j++) {
                int x, d;
                scanf("%d %d", &x, &d);
                points[i].push_back(make_pair(x, d));
            }
        }

        for (j=0;j<10;j++) {
            dp[0][0][j] = 0;
            dp[1][1][j] = 0;
        }

        for (l=0;l<m+1;l++) {
            for (i=1;i<n;i++) {
                int pos1 = 0;
                vector<pair<int, int> >::iterator it1 = points[i].begin();

                for (;it1 != points[i].end();it1++, pos1++) {
                    if (l > 0 && i > 1) {
                         int pos2 = 0;
                         vector<pair<int, int> >::iterator it2 = points[i-2].begin();

                         for (;it2 != points[i-2].end();it2++, pos2++) {
                             int danger;

                             if (dp[l-1][i-2][pos2] == INF) continue;
                             danger = dp[l-1][i-2][pos2] + (it1->second + it2->second) * abs(it1->first - it2->first);
                             min_aplly(dp[l][i][pos1], danger);
                         }
                    }

                    int pos2 = 0;
                    vector<pair<int, int> >::iterator it2 = points[i-1].begin();

                    for (;it2 != points[i-1].end();it2++, pos2++) {
                        int danger;

                        if (dp[l][i-1][pos2] == INF) continue;
                        danger = dp[l][i-1][pos2] + (it1->second + it2->second) * abs(it1->first - it2->first);
                        min_aplly(dp[l][i][pos1], danger);
                    }
                }
            }
        }

        for (l=0;l<m+1;l++) {
            for (j=0;j<10;j++) {
                if (l < m) {
                    min_aplly(min, dp[l][n-2][j]);
                }

                min_aplly(min, dp[l][n-1][j]);
            }
        }

        printf("%d\n", min);
    }
