int dp[3011][3011];
int movs[3011][3011];

int main() {
	string s,t;

	cin >> s >> t;

	for(int i = 0; i < 3010; i++) {
		dp[0][i] = 0;
		dp[i][0] = 0;
	}

	for(int i = 0; i < s.size(); i++) {
		for(int j = 0; j < t.size(); j++) {
			if (s[i] == t[j]) {
				dp[i+1][j+1] = dp[i][j] + 1;
				movs[i+1][j+1] = DIAG;
			} else if (dp[i+1][j] > dp[i][j+1]){
				dp[i+1][j+1] = dp[i+1][j];
				movs[i+1][j+1] = LEFT;
			} else {
				dp[i+1][j+1] = dp[i][j+1];
				movs[i+1][j+1] = UP;
			}
		}
	}
	string r = "";
	int i = s.size();
	int j = t.size();
	while(i > 0 and j > 0) {
		switch(movs[i][j]){
			case DIAG:
				i--; j--;
				r = s[i] + r;
				break;
			case UP:
				i--;
				break;
			case LEFT:
				j--;
				break;
		}
	}
	cout << r << endl;
}
