#include <bits/stdc++.h>
using namespace std;

struct node{
    int value;
    node *p,*l,*r;
};

node *root, *NIL;

void insert(int value){
    node *y, *x;
    y = NIL;
    x = root;
    node *n = (node *)malloc(sizeof(node));
    n->value = value;
    n->l = n->r = NIL;
    while(x != NIL){
        y = x;
        if(n->value < x->value)
            x = x->l;
        else
            x = x->r;
    }
    n->p = y;
    if(y == NIL) root = n;
    else{
        //x = n;
        if(n->value < y->value) y->l = n;
        else y->r = n;
    }
}


void Preorder(node *u){
    if(u==NIL) return;
    printf(" %d",u->value);
    Preorder(u->l);
    Preorder(u->r);
}

void Inorder(node *u){
    if(u==NIL) return;
    Inorder(u->l);
    printf(" %d",u->value);
    Inorder(u->r);
}

void print(){
    Inorder(root);
    printf("\n");
    Preorder(root);
    printf("\n");
}

void find(int value){
    node *x = root;
    while(x != NIL){
        if(value == x->value){
            printf("yes\n");
            return;
        }
        else{
            if(value<x->value){
                x = x->l;
            }
            else x = x->r;
        }
    }
    printf("no\n");
    return;
}

node* findNode(int value){
    node *x = root;
    while(x != NIL){
        if(value == x->value){
            return x;
        }
        else{
            if(value<x->value){
                x = x->l;
            }
            else x = x->r;
        }
    }
    return x;
}

node* getSuccessor(node *n){
    if(n->r != NIL){
        n = n->r;
        while(n->l != NIL){
            n = n->l;
        }
    }
    return n;
}

void deletenode(node *n){
    node *y, *x;
    if(n->l==NIL || n->r==NIL){
        y = n;
    }
    else{
        y = getSuccessor(n);
    }
    // determine which child node of y will be connect to y parent
    if(y->l!=NIL) x = y->l;
    else x = y->r;
    // change child's parent
    if(x!=NIL) x->p = y->p;
    // change parent's child
    if(y->p == NIL) root = x;
    else if(y == y->p->l) y->p->l = x;
    else y->p->r = x;
    //
    if(y != n) n->value = y->value;

    free(y);
}


int main(){
    int n, value;
    scanf("%d",&n);
    root = (node *)malloc(sizeof(node));
    root = NIL;
    //root->l = root->r = NIL;
    string cmd;
    for(int i=0;i<n;++i){
        cin >> cmd;
        if(cmd == "insert"){
            scanf("%d",&value);
            insert(value);
        }
        else if(cmd == "print"){
            print();
        }
        else if(cmd == "find"){
            scanf("%d",&value);
            find(value);
        }
        else if(cmd == "delete"){
            scanf("%d",&value);
            deletenode(findNode(value));
        }
    }
    return 0;
}

