typedef long long ll;
typedef long double Double;
typedef complex<double> P;


void solve(ll N, vector<ll> x, vector<ll> y) {
    vector<P> ps;
    for (int i = 0; i < N; i++) {
        ps.push_back(P(x[i], y[i]));
    }
    for (int i = 0; i < N; i++) {
        vector<pair<double, double> > seg;
        for (int j = 0; j < N; j++) {
            if (i != j) {
                P v = ps[j] - ps[i];
                P s = v * P(0, 1);
                P t = v / P(0, 1);

                seg.push_back({atan2(s.imag(), s.real()), atan2(t.imag(), t.real())});
            }
        }
        vector<pair<double, int> > add;
        for (auto &s : seg) {
            if (s.second < s.first) s.second += 2 * M_PI;
            if (s.first < 0) {
                if (s.second > 0) {
                    add.push_back({0, 1});
                    add.push_back({s.second, -1});
                    add.push_back({s.first + 2 * M_PI, 1});
                } else {
                    add.push_back({s.first + 2 * M_PI, 1});
                    add.push_back({s.second + 2 * M_PI, 1});
                }
            } else {
                add.push_back({s.first, 1});
                add.push_back({s.second, -1});
            }
        }
        for (int i = add.size() - 1; i >= 0; i--) {
            add.push_back({add[i].first + 1e-9, 0});
            add.push_back({add[i].first - 1e-9, 0});
        }
        add.push_back({0, 0});
        add.push_back({2 * M_PI, 0});
        sort(add.begin(), add.end());

        double prv = 0;

        int ans = 0;
        double tot = 0;
        for (auto a : add) {
            if (ans > 0) tot += a.first - prv;
            ans += a.second;
            prv = a.first;
        }
        printf("%.15lf\n", 1 - tot / (2 * M_PI));

    }
}

int main() {
    ll N;
    scanf("%lld", &N);
    vector<ll> y(N - 1 + 1);
    vector<ll> x(N - 1 + 1);
    for (int i = 0; i <= N - 1; i++) {
        scanf("%lld", &x[i]);
        scanf("%lld", &y[i]);
    }
    solve(N, x, y);
    return 0;
}

