int N, M, B;
int ax[100], ay[100];
int bx[5], by[5], c[5], f[5];

int calc(int bit, int D) {
	PrimalDual pd(N + M + 2);
	int S = N + M, T = S + 1;
	for(int i = 0; i < N; i++) {
		pd.add_edge(S, i, 1, 0);
		for(int j = 0; j < M; j++) {
			if(bit >> j & 1) {
				int d = abs(ax[i] - bx[j]) + abs(ay[i] - by[j]);
				int cost = max(0, d - D);
				pd.add_edge(i, N + j, 1, cost);
			}
		}
	}

	int sum = 0;
	for(int i = 0; i < M; i++) {
		if(bit >> i & 1) {
			sum += f[i] + D * B;
			pd.add_edge(N + i, T, c[i], 0);
		}
	}
	return pd.solve(S, T, N) + sum;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	while(cin >> N >> M >> B, N + M + B) {
		for(int i = 0; i < N; i++) {
			cin >> ax[i] >> ay[i];
		}
		for(int i = 0; i < M; i++) {
			cin >> bx[i] >> by[i] >> c[i] >> f[i];
		}

		int ans = 1e9;
		for(int bit = 1; bit < 1 << M; bit++) {
			int csum = 0;
			for(int i = 0; i < M; i++) {
				if(bit >> i & 1) {
					csum += c[i];
				}
			}
			if(csum < N) continue;
			int l = -1, r = 4010;
			while(abs(l - r) > 1) {
				int mid = (l + r) / 2;
				int res1 = calc(bit, mid);
				int res2 = calc(bit, mid + 1);
				ans = min({ ans, res1, res2 });
				if(res1 <= res2) r = mid;
				else l = mid;
			}
		}

		cout << ans << endl;
	}
