#include<stdio.h>
#include<stdlib.h>
#include<algorithm>
#include<string.h>
using namespace std;

struct Node { int key; Node *parent, *left, *right; };

Node *root, *NIL;

void insert(int k) {
  Node *y = NIL;
  Node *x = root;
  Node *z = (Node *)malloc(sizeof(Node));
  z->key = k;
  z->parent = NIL;
  z->left = NIL;
  z->right = NIL;
  while (x != NIL) {
    y = x;
    if (z->key < x->key) {
      x = x->left;
    } else {
      x = x->right;
    }
  }
  z->parent = y;

  if (y == NIL) {
    root = z;
  } else if (z->key < y->key) {
    y->left = z;
  } else {
    y->right = z;
  }
}

void Preorder(Node *p) {
  printf(" %d", p->key);
  if (p->left != NIL) Preorder(p->left);
  if (p->right != NIL) Preorder(p->right);
}

void Inorder(Node *p) {
  if (p->left != NIL) Inorder(p->left);
  printf(" %d", p->key);
  if (p->right != NIL) Inorder(p->right);
}

void Postorder(Node *p) {
  if (p->left != NIL) Postorder(p->left);
  if (p->right != NIL) Postorder(p->right);
  printf(" %d", p->key);
}

Node * find(int key) {
  Node *x = root;
  while (x != NIL) {
    if (key < x->key) {
      x = x->left;
    } else if (key > x->key) {
      x = x->right;
    } else if (key == x->key) {
      return x;
    }
  }
  return x;
}

Node * getMinimum (int key) {
  Node *x = find(key);
  while (x->left != NIL) {
    x = x->left;
  }
  return x;
}

Node * getSuccessor(int key) {
  Node *x;
  x = find(key);
  if ( x->right != NIL ) {
    return getMinimum(x->right->key);
  }
  Node *y = x->parent;
  while ( y != NIL && x == y->right ) {
    x = y;
    y = y->parent;
  }
  return y;
}

void deleteKey(int key) {
  Node *x, *y, *z;
  z = find(key);
  if ( z->left == NIL || z->right == NIL) {
    y = z;
  } else {
    y = getSuccessor(z->key);
  }

  if ( y->left != NIL) {
    x = y->left;
  } else {
    x = y->right;
  }

  if ( x != NIL ) x->parent = y->parent;

  if ( y == NIL ) {
    x = root;
  } else if (y->parent->left == y) {
    y->parent->left = x;
  } else {
    y->parent->right = x;
  }

  if (y != z) {
    z->key = y->key;
  }

  free(y);
}

int main() {
	int n;
  scanf("%d", &n);

  char str[12];
  int key;
  for ( int i = 0; i < n; i++ ) {
    scanf("%s", str);
    if ( strcmp(str, "insert") == 0 ) {
      scanf("%d", &key);
      insert(key);
    } else if ( strcmp(str, "print") == 0 ) {
      Inorder(root);
      printf("\n");
      Preorder(root);
      printf("\n");
    } else if ( strcmp(str, "find") == 0 ) {
      scanf("%d", &key);
      if ( find(key) != NIL ) {
        printf("yes\n");
      } else {
        printf("no\n");
      }
    } else if ( strcmp(str, "delete") == 0 ) {
      scanf("%d", &key);
      deleteKey(key);
    }
  }

  return 0;
}

