#include<cstdio>
#include<cstdlib>
#include<cstring>

struct Node{
    int key;
    Node *next,*prev; //ポインタ　要素をNodeとする．
};

Node *nil;

Node* listSearch(int key){ //要素を探索する．
    Node *cur = nil->next; //番兵の次の要素 現在位置の要素のポインタをcur 
    while(cur != nil && cur->key != key){ //->　…アロー演算子，a->bの時，aの構造体の中のフィールドbを指す．
        cur = cur->next; //curが番兵nilに戻ってしまうか，keyを発見すると探索は終了する
    }
    return cur; 
}

void init(){ //リストの初期化
    nil = (Node *)malloc(sizeof(Node)); //mallocは指定したサイズだけメモリを動的に確保する関数
    nil->next = nil; //ポインタ変数からメンバにアクセスするアロー演算子 ->
    nil->prev = nil;
}

void printList(){
    Node *cur = nil->next;
    int isf = 0;
    while(1){
        if(cur == nil) break;
        if(isf++ > 0)printf(" ");
        printf("%d", cur->key); 
        cur = cur->next;
    }
    printf("\n");
}

void deleteNode(Node *t){
    if(t==nil)return; //tが番兵なら処理しない
    t->prev->next = t->next;
    t->next->prev = t->prev;
    free(t);
}

void deleteFirst(){
    deleteNode(nil->next);
}

void deleteLast(){
    deleteNode(nil->prev);
}

void deletekey(int key){ //検索した要素(Node)を削除
    deleteNode(listSearch(key));//keyと同じものを探し，削除する
}

void insert(int key){
    Node *x = (Node *)malloc(sizeof(Node));
    x->key = key;//番兵の直後に要素を追加
    x->next = nil->next;
    nil->next->prev = x;
    nil->next = x;
    x->prev = nil;
}

int main(){
    int key,n,i;
    int size = 0;
    char com[20];
    int np = 0,nd = 0;
    scanf("%d", &n);
    init();
    for(i=0;i<n;i++){
        scanf("%s%d",com,&key); //cinよりscanfの方が早い．
        if(com[0] == 'i'){
            insert(key);np++;size++;
        }else if(com[0] == 'd'){
            if(strlen(com) > 6){
                if(com[6] == 'F') deleteFirst();
                else if(com[6] == 'L')deleteLast();
            }else{
                deletekey(key);
                nd++;
            }
            size--;
        }
    }
    printList();

    return 0;
}
