void divisor(ll n) {
  for (ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      dvs.push_back(i);
      if (i != n / i) {
        dvs.push_back(n / i);
      }
    }
  }
}

void solve() {
  divisor(N);
  sort(dvs.begin(), dvs.end());

  ll n = dvs.size();
  ll res = 0;
  for (ll i = 0; i < n; i++) {
    if (N / dvs[i] < dvs[i] - 1) {
      res += dvs[i] - 1;
    }
  }
  cout << res << '\n';
}

int main() {
  cin >> N;
  solve();
  return 0;
