std::size_t ctz32(std::uint_fast32_t c) {
	std::size_t t = 0x1F;
	if (c & 0x0000FFFF)
		c &= 0x0000FFFF, t ^= 0x10;
	if (c & 0x00FF00FF)
		c &= 0x00FF00FF, t ^= 0x8;
	if (c & 0x0F0F0F0F)
		c &= 0x0F0F0F0F, t ^= 0x4;
	if (c & 0x33333333)
		c &= 0x33333333, t ^= 0x2;
	if (c & 0x55555555)
		t ^= 0x1;
	return t;
}
