long long MOD = 998244353;

long long Calc(long long X, long long Y) {
	if (Y == 0) return 1;
	if (Y % 2 == 0) {
		long long Z = Calc(X, Y / 2);
		return (Z * Z) % MOD;
	}
	return (X * Calc(X, Y - 1)) % MOD;
}

int main() {
	static long long N, A, S[1000010] = {}, X[1000010] = {}, ANS = 0;
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> A;
		S[A]++;
	}
	for (long long i = 1; i <= 1000000; i++) {
		X[i] = Calc(i, MOD - 2);
	}
	for (long long i = 1; i <= 1000000; i++) {
		for (long long j = 2; i * j <= 1000000; j++) X[i * j] = (MOD + X[i * j] - X[i]) % MOD;
	}
	for (long long i = 1; i <= 1000000; i++) {
		long long COUNT = 0, Cur = 0;
		for (long long j = 1; i * j <= 1000000; j++) {
			if (S[i * j] == 0) continue;
			long long P = S[i * j];
			COUNT += (((Cur * (i * j) % MOD) % MOD) * P) % MOD;
			COUNT %= MOD;
			COUNT += (((P * (P - 1) / 2) % MOD) * ((i * j * i * j) % MOD)) % MOD;
			COUNT %= MOD;
			Cur += i * j * P;
			Cur %= MOD;
		}
		ANS += (COUNT * X[i]) % MOD;
		ANS %= MOD;
	}
	cout << ANS << endl;
