const int maxh = 19;
const int maxn = 1 << maxh;
const llong mod = (llong)1e9 + 7;

llong mpow(llong base, llong exp) {
    llong ans = 1;;
    for (; exp > 0; exp >>= 1) {
        if (exp & 1) (ans *= base) %= mod;
        (base *= base) %= mod;
    }
    return ans;
}

int h, n;
int p[maxn];

llong prod[maxn], iprod[maxn];
void cal_prod(int i = 1, int lv = h - 1) {
    prod[i] = i * prod[i / 2] % mod;
    iprod[i] = mpow(prod[i], mod - 2);
    if (lv == 0) return ;
    cal_prod(2 * i, lv - 1);
    cal_prod(2 * i + 1, lv - 1);
}

llong ans = 0;
llong cur_sum[maxn];

void dfs(int i = 1, int lv = h - 1) {
    DB(""; deb(i));
    if (lv == 0) return ;
    dfs(2 * i, lv - 1);
    dfs(2 * i + 1, lv - 1);

    rep(tail, (1 << (lv - 1))) {
        int cur = i << lv | tail;
        int other = p[cur];

        llong up_prod = prod[cur] * iprod[i / 2] % mod;
        deb(cur, other, up_prod, prod[cur], iprod[i / 2]);
        for (int par = other / 2; par > 0; par >>= 1) {
            llong down_prod = prod[other] * iprod[par / 2] % mod;
            deb(par, down_prod, up_prod * down_prod);
            cur_sum[par] += up_prod * down_prod % mod;
            if (cur_sum[par] >= mod) cur_sum[par] -= mod;
        }
    }

    clog << "seg" << endl;

    rep(tail, (1 << (lv - 1))) {
        int cur = (i << 1 | 1) << (lv - 1) | tail;
        int other = p[cur];

        llong up_prod = prod[cur] * iprod[i] % mod;
        deb(cur, other, up_prod, prod[cur], iprod[i / 2]);

        for (int par = other / 2, prev = other; par > 0; prev = par, par >>= 1) {
            llong down_prod = prod[other] * iprod[par] % mod;
            llong exluded_sum = (cur_sum[par] - cur_sum[prev] * par % mod + mod) % mod;
            llong cur_ans = up_prod * down_prod % mod * exluded_sum % mod;
            deb(par, down_prod, up_prod * down_prod, cur_ans);
            ans += cur_ans;
            if (ans >= mod) ans -= mod;
        }
    }
    rep(tail, (1 << (lv - 1))) {
        int cur = i << lv | tail;
        int other = p[cur];

        for (int par = other / 2; par > 0; par >>= 1) {
            cur_sum[par] = 0;
        }
    }
}

int main(void) {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    cin >> h;
    n = (1 << h);
    rep1(i, n / 2) {
        int x; cin >> x;
        p[i + n / 2 - 1] = x + n / 2 - 1;
    }

    prod[0] = iprod[0] = 1;
    cal_prod();
    dfs();
    cout << ans % mod;

    return 0;
}

