        dp[node]=max(dp[node],dfs(i,dp));
    }
    dp[node]++;
    return dp[node];
}

int main()
{
    int n,m;
    cin>>n>>m;
    for(int i=0;i<m;i++)
    {
        int a,b;
        cin>>a>>b;
        graph[a].push_back(b);
    }

    vector<int> dp(n+1);
    for(int i=1;i<=n;i++)
    {
        if(dp[i]==0)
        {
            dp[i]=dfs(i,dp);
        }
    }
    int maxm=0;
    for(int i=1;i<=n;i++)
    {
        maxm=max(maxm,dp[i]);
    }
    cout<<maxm-1;

