void search(vvi &G,vb seen,int v,int unreach){
  if(unreach == 0){
    ans++;
    return;
  }
  seen.at(v) = true;
  rep(i,G.at(v).size()){
    int nv = G.at(v).at(i);
    if(seen.at(nv)) continue;
    search(G,seen,nv,unreach-1);
  }
  return;
}

