		for( int y = 0; y < h; y++ ) {
			if( screen[y][x] != '.' ) {
				int i = screen[y][x] - 'A';
				maxx[i] = max( maxx[i], x );
				minx[i] = min( minx[i], x );
				maxy[i] = max( maxy[i], y );
				miny[i] = min( miny[i], y );
			}
		}
	}


