		for( int x = 0; x < w; x++ ) {
			for( int y = 0; y < h; y++ ) {

					char ch = screen[ y ][ x ];
					if( ch == '.' || ch == '*' ) continue;
					int i = ch - 'A';

					bool fflg = true;
					for( int tx = minx[i]; tx <= maxx[i] && fflg; tx ++ )
						for( int ty = miny[i]; ty <= maxy[i] && fflg; ty ++ )
							fflg &= ( screen[ ty ][ tx ] == ch || screen[ ty ][ tx ] == '*' );

					fig |= fflg;
					if( !fflg ) continue;

					for( int tx = minx[i]; tx <= maxx[i]; tx ++ )
						for( int ty = miny[i]; ty <= maxy[i]; ty ++ ) 
