int a[100005], memo[100005];
int n;

int dp(int i)
{
	if(i>=n-1)
		return 0;
	if(memo[i]!=-1)
		return memo[i];
	if(i<n-2)
	{
		memo[i] = min(abs(a[i]-a[i+1])+dp(i+1),
							abs(a[i]-a[i+2])+dp(i+2));
	}
	else if(i==n-2)
		memo[i] = abs(a[i]-a[i+1]) + dp(i+1);

	return memo[i];
}

