#include<bits/stdc++.h>
using namespace std;

const int maxn = 3e5 + 10;

int n;
int ans;
int a[maxn];
int b[maxn];
int P[maxn];
int HOLD;
int CMP;
int par[maxn];
vector<int> cmp;
vector<int> bois;
set<int> badbois;
vector<int> inds[2][maxn];
map<int, int> comp;

void in();
void solve();
void dsu(int, int);
int root(int);
void out();

int main(){
	ios::sync_with_stdio(false);
	cout.tie(0);
	cin.tie(0);
	in();
	solve();
	out();
}

void in(){
	cin >> n;
	for(int i = 0; i < n; i++){
		cin >> a[i];
		cmp.push_back(a[i]);
		HOLD ^= a[i];
	}
	cmp.push_back(HOLD);
	for(int i = 0; i < n; i++){
		cin >> b[i];
		cmp.push_back(b[i]);
	}
	sort(cmp.begin(), cmp.end());
	cmp.resize(unique(cmp.begin(), cmp.end()) - cmp.begin());
	for(int i = 0; i < cmp.size(); i++)
		comp[cmp[i]] = i;
	HOLD = comp[HOLD];
	for(int i = 0; i < n; i++){
		a[i] = comp[a[i]];
		b[i] = comp[b[i]];
	}
}

void solve(){
	int hold = HOLD;
	for(int i = 0; i < n; i++){
		if(a[i] != b[i]){
			inds[0][a[i]].push_back(i);
			inds[1][b[i]].push_back(i);
			bois.push_back(b[i]);
		}
	}
	memset(par, -1, sizeof par);
	int pfft = 0;
	inds[0][hold].push_back(n);
	sort(bois.begin(), bois.end());
	bois.resize(unique(bois.begin(), bois.end()) - bois.begin());
	CMP = bois.size();
	for(auto i: bois){
		if(inds[1][i].size() > inds[0][i].size()){
			ans = -1;
			return;
		}
		if(inds[1][i].size() < inds[0][i].size())
			pfft = 1;
		for(int j = 0; j < inds[1][i].size(); j++){
			dsu(i, a[inds[1][i][j]]);
			ans++;
		}
	}
	int now = n;
	ans += CMP - pfft;
}

void dsu(int u, int v){
	u = root(u);
	v = root(v);
	if(u == v)
		return;
	if(par[u] < par[v])
		swap(u, v);
	par[u] += par[v];
	par[v] = u;
	CMP--;
}

int root(int u){
	return par[u] < 0 ? u : par[u] = root(par[u]);
}

void out(){
	cout << ans;
