using P=pair<pair<int,int>,int>;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H,W,K; cin >> H >> W >> K;
    vector<int> s(2),t(2);
    for (int i=0;i<2;++i) cin >> s[i],--s[i];
    for (int i=0;i<2;++i) cin >> t[i],--t[i];
    vector<string> S(H);
    for (int i=0;i<H;++i) cin >> S[i];
    int N=H*W*4;
    struct edge{
        int u,c1,c2;
        edge(int u,int c1,int c2):u(u),c1(c1),c2(c2){}
    };
    vector<vector<edge>> G(N);
    for (int i=0;i<N;++i){
        int I=i;
        int id=I%4; (I-=id)/=4;
        int w=I%W; (I-=w)/=W;
        int h=I;
        if (S[h][w]=='@') continue;
        for (int j=0;j<4;++j) if (j%2!=id%2){
            G[i].emplace_back((h*W+w)*4+j,1,0);
        }
        if (id==0&&h<H-1&&S[h+1][w]!='@') G[i].emplace_back(((h+1)*W+w)*4+id,0,1);
        if (id==1&&w<W-1&&S[h][w+1]!='@') G[i].emplace_back((h*W+(w+1))*4+id,0,1);
        if (id==2&&h>0&&S[h-1][w]!='@') G[i].emplace_back(((h-1)*W+w)*4+id,0,1);
        if (id==3&&w>0&&S[h][w-1]!='@') G[i].emplace_back((h*W+(w-1))*4+id,0,1);
    }
    vector<pair<int,int>> d(N,{INF,INF});
    priority_queue<P,vector<P>,greater<P>> pq;
    for (int i=0;i<4;++i){
        d[(s[0]*W+s[1])*4+i]={1,0};
        pq.push({{1,0},(s[0]*W+s[1])*4+i});
    }
    while(!pq.empty()){
        auto p=pq.top(); pq.pop();
        int v=p.second;
        auto cost=p.first;
        if (d[v]<cost) continue;
        for (auto e:G[v]){
            int u=e.u;
            pair<int,int> ncost;
            if (e.c1==1) ncost={cost.first+1,0};
            else {
                ncost={cost.first,cost.second+e.c2};
            }
            if (ncost.second==K+1) ncost.first+=1,ncost.second=1;
            if (ncost<d[u]){
                d[u]=ncost;
                pq.push({d[u],u});
            }
        }
    }
    int ans=INF;
    for (int i=0;i<4;++i) ans=min(ans,d[(t[0]*W+t[1])*4+i].first);
    cout << (ans==INF?-1:ans) << '\n';
