mt19937 rnd(chrono::high_resolution_clock::now().time_since_epoch().count());


int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};

class DWizardInMaze {
public:

  void solve(std::istream& cin, std::ostream& cout) {
    int n, m;
    cin >> n >> m;
    pair<int, int> s, e;
    cin >> s.first >> s.second;
    cin >> e.first >> e.second;
    s.first--, s.second--;
    e.first--, e.second--;

    vector<string> a(n);
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    vector<vector<int>> vis(n, vector<int>(m, 0));
    auto ok = [&](int x, int y) -> bool {
      if (x >= 0 and y >= 0 and x < n and y < m) return a[x][y] == '.';
      return false;
    };
    deque<pair<int, int>> q;
    vis[s.first][s.second] = 1;
    q.emplace_back(s.first, s.second);
    while (!q.empty()) {
      auto[x, y] = q.front();
      q.pop_front();
      for (int i = 0; i < 4; ++i) {
        int xx = x + dx[i];
        int yy = y + dy[i];
        if (ok(xx, yy) && (!vis[xx][yy] || vis[x][y] < vis[xx][yy])) {
          vis[xx][yy] = vis[x][y];
          q.emplace_front(xx, yy);
        }
      }
      for (int i = x - 2; i <= x + 2; ++i) {
        for (int j = y - 2; j <= y + 2; ++j) {
          if (ok(i, j) && !vis[i][j]) {
            vis[i][j] = vis[x][y] + 1;
            q.emplace_back(i, j);
          }
        }
      }
    }
    int ans = vis[e.first][e.second];
    cout << (ans ? ans - 1 : -1) << '\n';
  }
};

int32_t main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);
	DWizardInMaze solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}
