void MargeSort(int x[],int left,int right){
    int i,j,mid;
    if(left>=right)return;
    mid=(left+right)/2;
    MargeSort(x,left,mid);
    MargeSort(x,mid+1,right);
    for(int i=left;i<=mid;i++){
        temp[i]=x[i];
    }
    for(int i=mid+1,int j=right;i<=right;i++,j--){
        temp[i]=x[j];
    }
    i=left; j=right;
    for(k=left;k<=right;k++){
        if(int temp[i]>=temp[j])x[k]=temp[i++];
        else x[k]=temp[j--];
    }
}

