#include <map> 
using namespace std;

int N;

int K = 0;

void solve(map<pair<int,int>,int> color,vector<vector<int>> list){
	vector<int> used(N);
	vector<int> col(N);
	used[1] = 1;
	queue<int> q;
	q.push(1);
	while(!q.empty()){
		int point = q.front();
		q.pop();
		used[point] = 1;
		int color = 1;
		for(int i=0;i<list[point].size();i++){
			if(!used[list[point][i]]){
				q.push(list[point][i]);
				if(point==col[point]) color++;
				col[list[point][i]] = color;
				color[make_pair(list[point][i],point)] = color;
				color[make_pair(point,list[point][i])] = color;
				if(K<color) K=color;
				color++;
			}
		}
	}
}

int main(){
	vector<pair<int,int>> edge; 
	vector<vector<int>> list(N);
	map<pair<int,int>,int> color;

	cin >> N;
	for(int i=1;i<N;i++){
		int a,b;
		cin >> a >> b;
		edge.push_back(make_pair(a,b));
		list[a].push_back(b);
		list[b].push_back(a);
	}

	solve(color,list);

	cout << K << endl;
	for(int i=1;i<N;i++){
		cout << color[edge[i]] << endl;
	}
	return 0;
}
