#define SHAPE_A 1
#define SHAPE_B 2

#define FRONT 0x01
#define RIGHT 0x02
#define BACK 0x04
#define LEFT 0x08
#define OVER 0x10

#define sc second
#define fr first

#define REP(i,n) for(int i = 0; i < (int)(n); ++i)
#define CUR(i,n) (i%n)
#define NEXT(i,n) ((i+1)%n)
#define PREV(i,n) ((i-1+n)%n)

using namespace std;

typedef double elem;
typedef complex<elem> point, vec;
typedef pair<point, point> line, hline, seg, pp;

const elem eps = 1.0e-4;
const elem infty = 1e40;
const elem pi = acos(-1.0);
point base(0,0);

// oÍ
