void read_matrix(matrix &a, int n, int m);
void matrix_mult(matrix &a, matrix &b, matrix &c);
void print_matrix(matrix &a);

int main(){
    int n, m, l;
    cin >> n >> m >> l;
    matrix a, b, c;

    read_matrix(a, n, m);
    read_matrix(b, m, l);
    matrix_mult(a, b, c);
    print_matrix(c);
