#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll N, Z, W;
vector<ll> A;
unordered_map<tuple<ll, ll, bool>, ll> Memo;

ll calc(ll me, ll him, ll deck, bool turn_x) {
  if (deck == N) return abs(me - him);
  auto key = make_tuple(him, deck, turn_x);
  if (Memo.count(key)) return Memo.at(key);
  ll res = calc(him, A[deck], deck + 1, !turn_x);
  if (deck != N - 1) {
    ll rest = calc(me, him, deck + 1, turn_x);
    res = turn_x ? max(res, rest) : min(res, rest);
  }
  return Memo[key] = res;
}
int main() {
  cin >> N >> Z >> W;
  A.resize(N);
  for (ll i = 0; i < N; ++i) cin >> A[i];
  cout << calc(Z, W, 0, true) << endl;
  return 0;
}
