template<typename T>
void cout_vec(vector<T> &vec){
    for(int i=0; i<vec.size(); i++){
        if (i!=0){
            cout << ' ';
        }
        cout << vec[i];
    }
    cout << endl;
}

long long bin_search(int l, int r, int x, vector<int> &A){
    int mid=(l+r)/2;
    if(mid==l){
        return mid;
    }

    if(A[mid]>=x){
        return bin_search(mid, r, x, A);
    }else{
        return bin_search(l, mid, x, A);
    }

}

long long N, M;
long long bin_search2(int l, int r, vector<int> &A){
    int mid=(l+r)/2;
    if(mid==l){
        return mid;
    }

    long long cnt =0;
    for(int i=0; i<N; i++){
        cnt+=bin_search(0, N, mid-A[i], vector<int> &A);
    }

    if(cnt>=M){
        return bin_search2(mid, r, A);
    }else{
        return bin_search2(l, mid, A);
    }
}

int main(){
    cin >> N >> M;
    vector<long long> A(N,0);
    for(int i=0; i<N; i++){
        cin >> A[i];
