const int MAXN = (int)1e5+10;
struct edge {
    int to, next;
}ed[MAXN << 1];

int head[MAXN], cnt;
void addedge(int u, int v) {
    ed[cnt].to = v;
    ed[cnt].next = head[u];
    head[u] = cnt++;
}

int sz[MAXN], fa[MAXN], dep[MAXN];
void dfs(int u, int pre) {
    sz[u] = 1;
    dep[u] = dep[pre] + 1;
    fa[u] = pre;
    for ( int i = head[u]; i != -1; i = ed[i].next ) {
        int v = ed[i].to;
        if ( v != pre ) {
            dfs(v, u);
            sz[u] += sz[v];
        }
    }
}

int main() {
    memset(head, -1, sizeof(head));
    int n;
    cin >> n;
    for ( int i = 1; i < n; i++ ) {
        int u, v;
        cin >> u >> v;
        addedge(u, v);
        addedge(v, u);
    }
    dfs(1, 0);
    int d = (dep[n] - 2) / 2;
    int ans = n;
    while ( d ) {
        d--;
        ans = fa[ans];
    }
    if ( sz[ans] * 2 >= n ) cout << "Snuke" << endl;
    else cout << "Fennec" << endl;

    return 0;
