template<typename T>
std::tuple<size_t, vector<T>> getN(istream& in)
{
  size_t N;
  in >> N;
  vector<T> seq;
  for (auto i = 0u; i < N; ++i) {
    T x;
    in >> x;
    seq.push_back(x);
  }
  return make_tuple(N, move(seq));
}

template<typename T>
long count(const vector<T>& input)
{
  const auto N = input.size();
  assert(N >= 3);
  T a = input[0];
  T b = input[1];
  T c = 0;

  long count = 0;
  for (auto i = 2u; i < N; ++i, a = b, b = c) {
    c = input[i];
    if ((a < b && b < c) || (c < b && b < a)) ++count;
  }
  return count;
}

long solve(istream& in)
{
  auto [N, input] = getN<long>(in);
  assert(3 <= N && N <= 20);
  return count(input);
}

void test()
{
  {
    constexpr auto str = R"(
5
1 3 5 4 2
)";
    stringstream in{str};
    assert(solve(in) == 2);
  }

  {
    constexpr auto str = R"(
  9
  9 6 3 2 5 8 7 4 1
  )";
    stringstream in{str};
    assert(solve(in) == 5);
