struct edge {int from, to, cost; };

const int MAX_V = 200;
int V;
vector<int> G[MAX_V];
int match[MAX_V];
bool used[MAX_V];

void add_edge(int u, int v){
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(int v){
    used[v] = true;
    for(int i = 0; i < G[v].size(); i++){
        int u = G[v][i], w = match[u];
        if(w < 0 || (!used[w] && dfs(w))){
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching(){
    int res = 0;
    memset(match, -1, sizeof(match));
    for(int v = 0; v < V; v++){
        if(match[v] < 0){
            memset(used, 0, sizeof(used));
            if(dfs(v)){
                res++;
            }
        }
    }
    return res;
}

void solve(){
    cin >> V;
    int a[V], b[V], c[V], d[V];
    rep(i, V) cin >> a[i] >> b[i];
    rep(i, V) cin >> c[i] >> d[i];
    rep(i, V){
        rep(j, V){
            if(a[i] < c[j] && b[i] < d[j]){
                add_edge(i, V+j);
            }
        }
    }
    cout << bipartite_matching() << endl;
}

int main(){
    solve();
    return 0;
}
