#include <bits/stdc++.h>

using namespace std;

long countPalindromes(string s)
{
    const char kNullChar = '\0';
        string str = string(1, kNullChar);

        for(auto c: s) str += string(1, c) + kNullChar;

        string max_str = "";
        long len = str.size();
        long right = 0;
        long center = 0;
        vector<long> dp(len, 0);

        for(long i = 1; i < len; i++) {
            long mirr = 2*center - i;

            if(i < right) {
                dp[i] = min(right - i, dp[mirr]);
            }

            long left_index = i - (1 + dp[i]);
            long right_index = i + (1 + dp[i]);
            while(left_index != -1 && right_index != len && str[left_index] == str[right_index]) {
                left_index--;
                right_index++;
                dp[i]++;
            }

            if(i + dp[i] > right) {
                center = i;
                right = i + dp[i];
            }
        }

        long count = 0;
        for(long i = 0; i < len; i++) {
            count += ceil((double)dp[i]/2.0);
        }
        return count;

}

int main()
{
    string s;
    cin>>s;
    long n = s.length();
    cout<<n*(n-1)/2+1+n-countPalindromes(s)<<endl;
