int dfs(int t, int N, bool visited) {
  bool all_visited = true;

  for(int i = 0; i < N; i++) {
    if(visited[i] == false) {
      all_visited = false;
    }
  }
  if(all _visited) {
    return 1;
  }

  int ret = 0;

  for(int i = 0; i < N; i++) {
    if(graph[t][i] == false) {
      continue;
    }
    if(visited[i]) {
      continue;
    }

    visited[i] = true;
    ret += dfs(i, N, visited);
    visited[i] = false;
  }
  return ret;
}

