ll dp(ll i, ll j) {
  if (i == n) {
    return 0;
  }
  if (a[i][j] != INF) {
    return a[i][j];
  }
  if (j == 0) {
    a[i][j] = dp(i + 1, 1) + ((s[i] == 'g') ? 0 : -1); // gを出す
    return a[i][j];
  } else {
    x = dp(i + 1, j + 1) + ((s[i] == 'g') ? 0 : -1); // gを出す
    y = dp(i + 1, j - 1) + ((s[i] == 'g') ? 1 : 0);  // pを出す
    a[i][j] = max(x, y);
    return a[i][j];
  }
}

int main() {
