bool valid(int x, int y, int h, int w) { return (x >= 0 && y >= 0 && x < h&&y < w); }
int place(int x, int y, int w) { return w*x + y; }


bool fld[1200][1200] = {};
int index[1200][1200];
pii hs[1111111];

void init()
{
	REP(i, 1200)REP(j, 1200) index[i][j] = INF;
	hurui();
	int p = 1, x = 600, y = 600;
	FOR(i, 1, 11111111)
	{
		if (i % 2)
		{
			REP(j, i)
			{
				index[x][y] = p;
				hs[p] = pii(x, y);
				if (primes.count(p)) fld[x][y] = true;
				p++;
				y++;
			}
			REP(j, i)
			{
				index[x][y] = p;
				hs[p] = pii(x, y);
				if (primes.count(p)) fld[x][y] = true;
				p++;
				x--;
			}
		}
		else
		{
			REP(j, i)
			{
				index[x][y] = p;
				hs[p] = pii(x, y);
				if (primes.count(p)) fld[x][y] = true;
				p++;
				y--;
			}
			REP(j, i)
			{
				index[x][y] = p;
				hs[p] = pii(x, y);
				if (primes.count(p)) fld[x][y] = true;
				p++;
				x++;
			}
		}
		if (p > 1000000) break;
	}
}

pii dp[1200][1200];
int n, m;

pii solve(int x, int y)
{
	if (dp[x][y] !=pii(-1,-1)) return dp[x][y];
	pii res(0, -1);
	FOR(i, -1, 2)
	{
		int nx = x + 1, ny = y + i;
		if (index[nx][ny] > m) continue;
		pii next = solve(nx, ny);
		if (fld[nx][ny])
		{
			if (next.first == 0) chmax(res, pii(next.first + 1, index[nx][ny]));
			else chmax(res, pii(next.first + 1, next.second));
		}
		else chmax(res, next);
	}
	return dp[x][y] = res;
}

int main()
{
	init();
	while (cin >> m >> n, n)
	{
		REP(i, 1200)REP(j, 1200) dp[i][j] = pii(-1, -1);
		pii ans = solve(hs[n].first, hs[n].second);
		if (primes.count(n))
		{
			ans.first++;
			chmax(ans.second, n);
		}
		if (ans.first == 0) cout << "0 0" << endl;
		else cout << ans.first << " " << ans.second << endl;
	}
	return 0;
