#include <bits/stdc++.h>

using namespace std;

#define whole(xs) (xs).begin(),(xs).end()

template<class T>
ostream& operator<<(ostream& os, const vector<T>& vs) {
    if (vs.empty()) return os << "[]";
    os << "[" << vs[0];
    for (int i = 1; i < vs.size(); i++) os << " " << vs[i];
    return os << "]";
}

typedef long long Long;

/* 領域木ライブラリ.
 *   Node : 領域木の各ノード
 *   construct(Point[] ps) 
 *      : ps(x座標でソートされた点集合)をもとに領域木を作成.
 *   query(Node root, long sx, long sy, long gx, long gy, vector<Point>& result) 
 *      : rootに含まれる点のうち, (sx <= x <= gx && sy <= y <= gy)なるもののをresultに入れる
 */
struct Point {
    Long x, y;
    char type;
    Point() {}
    Point(Long x, Long y, char type='c') : x(x), y(y), type(type) {}
    static bool compY(const Point& a, const Point& b) {
        return a.y == b.y ? a.x < b.x : a.y < b.y;
    }
};
struct Node {
    shared_ptr<Node> parent, left, right;
    Long left_x, right_x;
    vector<Point> ys;
};
ostream& operator<<(ostream& os, const Node& node) {
    return os << "( [" << node.left_x << "," << node.right_x << "] -> " << node.ys;
}
shared_ptr<Node> construct(vector<Point>::iterator lb, vector<Point>::iterator ub) {
    auto n = make_shared<Node>();
    n->left_x = lb->x;
    n->right_x = (ub - 1)->x;
    if (ub - lb == 1) {
        n->ys.clear(); n->ys.push_back(*lb);
        return n;
    }
    auto mid = lb + (ub - lb) / 2;
    auto l = construct(lb, mid),
         r = construct(mid, ub);
    l->parent = n;
    r->parent = n;
    n->left = l;
    n->right = r;
    size_t li = 0, ri = 0;
    while (true) {
        if (li >= l->ys.size() && ri >= r->ys.size()) break;
        if (li >= l->ys.size()) n->ys.push_back(r->ys[ri++]);
        else if (ri >= r->ys.size()) n->ys.push_back(l->ys[li++]);
        else {
            n->ys.push_back( l->ys[li].y < r->ys[ri].y ? l->ys[li++] : r->ys[ri++] );
        }
    }
    return n;
}

/* (sx <= x <= gx && sy <= y <= gy)なる点(x, y)の個数を返す 
 * 閉区間なの注意 */
void query(shared_ptr<Node> root, Long sx, Long sy, Long gx, Long gy, vector<Point>& result) {
    if (gx < root->left_x || root->right_x < sx) {
        // do nothing;
    } else if (sx <= root->left_x && root->right_x <= gx) {
        auto& ys = root->ys;
        auto lb = upper_bound(whole(ys), Point(0, sy - 1), Point::compY);
        auto ub = lower_bound(whole(ys), Point(0, gy + 1), Point::compY);
        result.insert(result.end(), lb, ub);
    } else {
        query(root->left, sx, sy, gx, gy, result);
        query(root->right, sx, sy, gx, gy, result);
    }
}

int AN, BN, R;
vector<Point> A, B;

bool input() {
    cin >> AN >> BN >> R;
    if (AN == 0 && BN == 0 && R == 0) return false;
    A.clear(); B.clear();
    for (int i = 0; i < AN; i++) {
        int xa, ya;
        cin >> xa >> ya;
        A.push_back(Point(xa, ya, 'a'));
    }
    for (int i = 0; i < AN; i++) {
        int xb, yb;
        cin >> xb >> yb;
        B.push_back(Point(xb, yb, 'b'));
    }
    return true;
}

