    return a.x == b.x ? a.y < b.y : a.x < b.x;
}

Long dist2(const Point& a, const Point& b) {
    Long dx = a.x - b.x,
         dy = a.y - b.y;
    return dx * dx + dy * dy;
}
void solve() {
    vector<Point> p = A;
    p.insert(p.end(), B.begin(), B.end());
    sort(whole(p));
    auto rtree = construct(whole(p));
    Long ans = 0;
    for (int i = 0; i < AN; i++) {
        Point& p = A[i];
        vector<Point> area;
        query(rtree, p.x - 4 * R, p.y - 4 * R, p.x + 4 * R, p.y + 4 * R, area);
        for (int j = 0; j < area.size(); j++) {
            if (area[j].type == 'a') continue;
            if (dist2(area[j], p) <= (4 * R) * (4 * R)) ans++;
        }
    }
    cout << ans << endl;
}

int main() {
    while (input()) solve();
    return 0;
