#include<bits/stdc++.h>
using namespace std;

template<size_t n, class... F>
struct coex_uf{
    int t[n];
    constexpr coex_uf(F ...f) : t(){
        for(auto& i : t)i = -1;
        auto root = [](auto& t, int x) -> int{
            while(t[x] >= 0)x = t[t[x]] >= 0 ? t[x] = t[t[x]] : t[x];
            return x;
        };
        auto unite = [&root](auto& t, int x, int y){
            x = root(t, x);
            y = root(t, y);
            if(x == y)return;
            if(t[x] > t[y])swap(x, y);
            t[x] += t[y];
            t[y] = x;
        };
        auto c = [&unite](auto& t, int i){
            int d(0), p(0);
            while(i /= 2){
                ++d;
                if(i & 1)
                    if(p)
                        unite(t, p, d);
                    else
                        p = d;
            }
        };
        for(auto i : {f...})c(t, i);
    }
    constexpr int root(int x) const {
        return t[x] < 0 ? x : root(t[x]);
    }
    constexpr int find(int x, int y) const {
        return root(x) == root(y);
    }
    int unite(int x, int y){
        x = root(x);
        y = root(y);
        if(t[x] > t[y])swap(x, y);
        t[x] += t[y];
        t[y] = x;
    }
};

int main(){
    constexpr auto uf = coex_uf<13, int, int>(5546, 2640);
    int a, b;
    cin >> a >> b;
    puts(uf.find(a, b) ? "Yes" : "No");
}
