#include <cstdio>
#include <algorithm>
#include <cstring>

using namespace std;

int sum[600][600] = {};

int solve(){
  int h, w, n, m;

  memset(sum, 0, sizeof(sum));

  scanf("%d%d%d%d", &w, &h, &n, &m);

  if(!h)return false;

  for(int i=0;i<h;i++)
    for(int j=0;j<w;j++)
      sum[i][j] = 1;

  int l = 0, u = 0;

  for(int i=0;i<n;i++){
    int d, c;

    scanf("%d%d", &d, &c);

    if(d == 1){
      c += l;
      for(int j=l;j<c;j++){
        for(int k=u;k<u+32;k++){
          sum[k][c+(c-j-1)] += sum[k][j];
          sum[k][j] = 0;
        }
      }
    }else{
      c += u;
      for(int j=u;j<c;j++){
        for(int k=l;k<l+32;k++){
          sum[c+(c-j-1)][k] += sum[j][k];
          sum[j][k] = 0;
        }
      }
    }

    int l2 = l, u2 = u;

    l = -1;
    for(int i=u2;i<u2+32;i++){
      for(int j=l2;j<l2+32;j++){
        if(sum[i][j]){
          l = j; u = i;
          break;
        }
      }
      if(l != -1) break;
    }
  }


  assert(l != -1);

  for(int i=0;i<m;i++){
    int x, y;

    scanf("%d%d", &x, &y);

    printf("%d\n", sum[y+u][x+l]);
  }

  return 1;
}

int main(){
  while(solve());
}

