#include<stdio.h>
#include<vector>
#include<algorithm>
#include<cmath>
#define MAX_N 1005
#define MAX_R 20005
using namespace std;

typedef struct edge
{
	int from,to,cost;
} edge;

bool mcmp(edge x,edge y)
{
	return x.cost<y.cost;
}

int uft[MAX_N];
vector<edge>e;

void init(int n)
{
	int i;
	for (i=0;i<=n;i++)
	uft[i]=i;
}

int parent(int n)
{
	if (uft[n]==n)
		return n;
	else
		return uft[n]=parent(uft[n]);
}

void unit(int p, int q)
{
	uft[parent(p)]=parent(q);
}

int same(int p, int q)
{
	return parent(p)==parent(q);
}

int kruskal(int n,int r)
{
	int res=0;
	sort(e.begin(),e.end(),mcmp);
	init(n);
	for(int i=0;i<r;i++)
	{
		edge tmp=e[i];
		if(!same(tmp.from,tmp.to))
		{
			res+=tmp.cost;
			unit(tmp.from,tmp.to);
			e[i].cost=0;
		}
	}
	return res;
}

int piles[10001][2];
int distance(int f,int t)
{
	return pow((double)piles[f][0]-piles[t][0],2)+pow((double)piles[f][1]-piles[t][1],2);
}

