using namespace std;

int n,k,sz,q[2010],dist[2010],ans=1e9;
vector<int> pos[2010];

inline void bfs()
{
	for(int i=0;i<sz;i++)
	{
		int cur=q[i];
		for(int j:pos[cur])
		{
			int w=dist[cur]+2;
			if(dist[j]<=w) continue;
			dist[j]=w;
			q[sz++]=j;
		}
	}
}

inline int solveVertex(int i)
{
	fill(dist,dist+n,1e9);
	dist[i]=0;
	sz=0;

	q[sz++]=i;
	bfs();
	int sum=0;
	for(int j=0;j<n;j++) if(dist[j]>k) sum++;

	return sum;
}

inline int solveEdge(int i,int j)
{
	fill(dist,dist+n,1e9);
	dist[i]=dist[j]=1;
	sz=0;

	q[sz++]=i;
	q[sz++]=j;
	bfs();
	int sum=0;
	for(int m=0;m<n;m++) if(dist[m]>k) sum++;

	return sum;
}

int main()
{
	cin>>n>>k;
	for(int i=0;i<n-1;i++)
	{
		int a,b;
		cin>>a>>b;
		a--;b--;
		pos[a].push_back(b);
		pos[b].push_back(a);
	}

	for(int i=0;i<n;i++) ans=min(ans,solveVertex(i));
	for(int i=0;i<n;i++)
		for(int j:pos[i])
			if(j>i) ans=min(ans,solveEdge(i,j));

	cout<<ans;

	return 0;
