	rep(i, n) {
		cin >> p[i];
		p[i]--;
		graph[i].pb(p[i]);
		graph[p[i]].pb(i);
	}
	rep(i, n) if (!vis[i]) dfs1(i, i);
	vector<int> root = ver;
	root.resize(n);
	sort(all(root)); root.erase(unique(all(root)), root.end());
	vector<int> si(n);
	rep(i, n) si[ver[i]]++;
	vector<int> cycle(n + 1);
	ll ans = 1;
	rep(i, root.size()) {
		int v = root[i];
		int now = v;
		bool flag = true;
		rep(j, si[v]) {
			if (j && now == v) flag = false;
			now = p[now];
		}
		if (flag && now == v) cycle[si[v]]++;
		else {
			set<int> st;
			now = v;
			int start;
			while (true) {
				if (st.count(now)) {
					start = now;
