			}
			int cycsz = cyc.size();
			set<int> cycst;
			rep(j, cycsz) cycst.insert(cyc[j]);
			vector<int> check;
			for (int ve : cyc) {
				dfs2(ve, -1, ve, cycst);
				if (cnt[ve] >= inf) ans = 0;
				check.pb(cnt[ve]);
			}
			reverse(all(check));
			vector<int> nonzero(2 * cycsz + 1);
			rep(j, 2 * cycsz) {
				nonzero[j + 1] = nonzero[j];
				if (check[j % cycsz]) nonzero[j + 1]++;
			}
			ll pat = 1;
			rep(j, cycsz) {
				if (!check[j]) continue;
				if (check[j] > cycsz) ans = 0;
				else {
					int x = check[j] - 1;
					int pa = 0;
					if (nonzero[j + 1] == nonzero[j + x + 1]) pa++;
					if (nonzero[j + 1] == nonzero[j + x + 2]) pa++;
					if (pa == 0) ans = 0;
					else if (pa == 2) {
						pat *= 2;
						if (pat >= mod) pat -= mod;
					}
				}
			}
			ans *= pat; ans %= mod;
		}
	}
	rep(i, n + 1) {
		int m = cycle[i];
		ll sum = 0;
		for (int j = 0; j <= m / 2; j++) sum += fac[m] * facinv[m - 2 * j] % mod * modinv(modpow(2, j)) % mod * modpow(i, j) % mod * modpow((i + 1) / 2, m - 2 * j) % mod;
		sum %= mod;
		ans *= sum; ans %= mod;
	}
	assert(0 <= ans && ans < mod);
	cout << ans << '\n';
