    if (H == 0) return false;

    vector<string> S(H);
    for (auto& s : S) cin >> s;

    vector<vector<vector<lint>>> dist(H, vector<vector<lint>>(W, vector<lint>(4, INF)));
    int sx, sy, sd;
    for (int x = 0; x < H; ++x) {
        for (int y = 0; y < W; ++y) {
            for (int d = 0; d < 4; ++d) {
                if (S[x][y] == "NESW"[d]) {
                    sx = x;
                    sy = y;
                    sd = d;
                }
            }
        }
    }

    dist[sx][sy][sd] = 0;
    lint step = 0;
    while (step < L) {
        int nx = sx + dx[sd], ny = sy + dy[sd];
        if (nx < 0 || H <= nx || ny < 0 || W <= ny ||
            S[nx][ny] == '#') {
            sd = (sd + 1) % 4;
        } else {
            sx = nx, sy = ny;
            ++step;
        }

        if (dist[sx][sy][sd] < INF) {
            lint diff = step - dist[sx][sy][sd];
            L -= (L - step) / diff * diff;
        } else {
            dist[sx][sy][sd] = step;
        }
    }

    cout << sx + 1 << " " << sy + 1 << " "
         << "NESW"[sd] << endl;
    return true;
}

int main() {
    while (solve()) {}
    return 0;
}

