  }
}

string CountBomb(vector<string> vec, int column, int row, int maxcolumn, int maxrow)
{
  //#の場合は＃を返す
  if(vec[column].at(row) == '#')
  {
    return "#";
  }

  int BombCount = 0;
  //上の行を確認
  for(int i = -1; i < 2; i ++)
  {
    for(int j = -1; j < 2; j ++)
