using namespace std;
typedef pair<int,int> P;
typedef pair<P,int> PI;


const int d[3] = {0,1,2};


class AOJ0230{
private:
  int n;
  int imap[110][2];
  int mincost[110][2];
public:
  AOJ0230(int n):n(n){
    rep(i,n+1)mincost[i][0] = mincost[i][1] = INT_MAX;
  }
  ~AOJ0230(){}

  void input(){
    rep(i,n)cin >> imap[i][0];
    rep(i,n)cin >> imap[i][1];
  }

  void run(){
    queue<PI> deq;
    deq.push(insert(0,0,1));
    deq.push(insert(0,1,1));
    mincost[0][0] = mincost[0][1] = 1;

    bool arrived = false;
    while(!deq.empty()){
      PI pi = deq.front(); deq.pop();

      if(pi.F.F == n-1){
	int lorr = pi.F.S==1?0:1;
	mincost[n-1][lorr] = min(mincost[n-1][lorr],pi.S);
	arrived = true;
	continue;
      }


      rep(i,3){
	int np = pi.F.F+d[i];
	int lorr = pi.F.S==1?0:1;

	if(np > n-1)continue;
	if(imap[np][lorr] == 1){
	  for(int i=np;i<n && imap[np][lorr] == 1;i++,np++){}
	} 
	else if(imap[np][lorr] == 2){
	  for(int i=np;i>=0 && imap[np][lorr] == 2;i--,np--){}
	}
	if(np > n-1)np = n-1;
	if(mincost[np][lorr] < pi.S+1)continue;


	mincost[np][lorr] = pi.S+1;
	deq.push(insert(np,lorr,pi.S+1));
      }

    }
    if(!arrived)cout << "NA" << endl;
    else cout << min(mincost[n-1][0],mincost[n-1][1]) << endl;

  }


};








int main(){
  int N;
  while(cin >> N && N){
    AOJ0230 ans = AOJ0230(N);
    ans.input();
    ans.run();
  }
  return 0;
