//       if (all[all[now].d[i]].nodenum == val &&
// 	  all[all[now].d[i]].pnum    == val2)
// 	return true;
//     }
  }
  return false;
}

void search(int n,int now,int *in,vector<int> &p,int pp,int cur,int prev){
  ///if (all[cur].d.size() > 10||
  //all[cur].s.size() > 10)
  //cout << now<<" " << pp << endl;
  //cout << now << " " << pp <<": " << cur <<" " << all[cur].nodenum<<" " << 
  //all[cur].d.size()<<" "<< all[cur].s.size() << endl;

  if (pp != p.size()){
    int np = p[pp];
    if (np&BIT(f)){
      if (all[cur].f == -1){
	if (all[cur].m != -1 && all[all[cur].m].h != -1){
	  all[cur].f = all[all[cur].m].h;
	  if (all[cur].ismale)all[all[cur].f].s.pb(cur);
	  else all[all[cur].f].d.pb(cur);
	}else {
	  all[cur].f=total;
	  all[total]=Node(now,pp,true);
	  if (all[cur].ismale)all[total].s.pb(cur);
	  else all[total].d.pb(cur);
	  if (all[cur].m != -1){
	    all[total     ].w=all[cur].m;//define wife
	    all[all[cur].m].h=total;//define husband;
	    all[total].d=all[all[cur].m].d;
	    all[total].s=all[all[cur].m].s;
	  }
	  total++;
	}
      }
      search(n,now,in,p,pp+1,all[cur].f,cur);
    }

    if (np&BIT(m)){
      if (all[cur].m == -1){
	if (all[cur].f!=-1 && all[all[cur].f].w != -1){
	  all[cur].m=all[all[cur].f].w;
	  if (all[cur].ismale)all[all[cur].m].s.pb(cur);
	  else all[all[cur].m].d.pb(cur);
	}else {
	  all[cur].m=total;
	  all[total]=Node(now,pp,false);
	  if (all[cur].ismale)all[total].s.pb(cur);
	  else all[total].d.pb(cur);
	  if (all[cur].f != -1){
	    all[all[cur].f].w=total;
	    all[total     ].h=all[cur].f;
	    all[total].s=all[all[cur].f].s;
	    all[total].d=all[all[cur].f].d;
	  }
	  total++;
	}
      }
      search(n,now,in,p,pp+1,all[cur].m,cur);
    }
    if (np&BIT(s)){
      if (!haschild(now,pp,cur,true)){
	all[cur].s.pb(total);
	all[total]=Node(now,pp,true);
	if (all[cur].ismale){//cur is male
	  all[total].f=cur;
	  if (all[cur].w != -1)all[total].m=all[cur].w;
	}
	else {//cur is female
	  all[total].m=cur;
	  if (all[cur].h != -1)all[total].f=all[cur].h;
	}
	total++;
      }
      rep(i,all[cur].s.size()){
	if (all[cur].s[i]!=prev)
	search(n,now,in,p,pp+1,all[cur].s[i],cur);
      }
    }

    if (np&BIT(d)){
      if (!haschild(now,pp,cur,false)){
	all[cur].d.pb(total);
	all[total]=Node(now,pp,false);
	if (all[cur].ismale){// cur is male
	  all[total].f=cur;
	  if (all[cur].w != -1)all[total].m=all[cur].w;
	}else {//cur is female
	  all[total].m=cur;
	  if (all[cur].h != -1)all[total].f=all[cur].h;
	}
	total++;
      }
      rep(i,all[cur].d.size()){
	if (all[cur].d[i] != prev)
	search(n,now,in,p,pp+1,all[cur].d[i],cur);
      }
    }

    if (np&BIT(w)&& all[cur].ismale){
      if (all[cur].w == -1){
	all[cur].w=total;
	all[total]=Node(now,pp,false);
	all[total].h=cur;
	all[total].d=all[cur].d;
	all[total].s=all[cur].s;
	total++;
      }
      search(n,now,in,p,pp+1,all[cur].w,cur);
    }

    if (np&BIT(h) && !all[cur].ismale){
      if (all[cur].h == -1){
	all[cur].h=total;
	all[total]=Node(now,pp,true);
	all[total].w=cur;
	all[total].d=all[cur].d;
	all[total].s=all[cur].s;
	total++;
      }
      search(n,now,in,p,pp+1,all[cur].h,cur);
    }
    return;
  }
  if (now == n){
    isgoal[cur]=true;
    return;
  }else {
    search(n,now+1,in,path[in[now]],0,cur,-1);
  }
}


