short cost[N];
pii dijkstra(int n){
  makegraph();
  rep(i,n)cost[i]=inf;
  cost[0]=0;
  priority_queue<st> Q;
  Q.push((st){0,0});
  while(!Q.empty()){
    st now = Q.top();Q.pop();
    if (now.cost != cost[now.now])continue;
    rep(i,edge[now.now].size()){
      int nex=edge[now.now][i].fir;
      int nec=now.cost+edge[now.now][i].sec;
      if (nec < cost[nex])cost[nex]=nec,Q.push((st){nex,nec});
    }
  }
  pii ret(inf,-inf);
  rep(i,n){
    if (isgoal[i] && cost[i] != inf){
      ret.fir=min(ret.fir,(int)cost[i]);
      ret.sec=max(ret.sec,(int)cost[i]);
    }
  }

  /*
  rep(i,n)cout << i <<" " << isgoal[i] <<" "<<
    cost[i] << endl;
  */

  return ret;
}

