using namespace std;

using int64 = long long;

const int MAX_N = 200000;

int N;
int64 L;

int64 result = 0;

string s[MAX_N];
vector<int64> heights;

int64 calc_grundy(int64 x) {
    if (x == 0) return 0;

    int64 res = 1;
    while (x % 2 == 0) {
        x /= 2;
        res *= 2;
    }
    return res;
}

void dfs(int64 dep, int lb, int ub, string prefix) {
    int num = ub - lb;
    if (num == 0) {
        result ^= calc_grundy(L + 1 - dep);
        // heights.push_back(L + 1 - dep);
        return;
    // } else if (num == 1 and prefix == s[lb]) return;
    } else if (num == 1) {
        int64 h = L - dep + 1;
        int64 sh = L - s[lb].size() + 1;

        // cerr << "h: " << h << " sh: " << sh << endl;

        for (int64 x = sh; x < h; x++) {
            result ^= calc_grundy(x);
            // heights.push_back(x);
        }
        return;
    }

    string zero = prefix + "0";
    string one = prefix + "1";
    int b = lower_bound(s + lb, s + ub, one) - s;
    dfs(dep + 1, lb, b, zero);
    dfs(dep + 1, b, ub, one);
}

int main() {
    cin >> N >> L;

    for (int i = 0; i < N; i++) {
        cin >> s[i];
    }
    sort(s, s + N);

    dfs(0, 0, N, "");

    /*
    for (auto h : heights) {
