	if(id == C[axis].size()) return pos[axis] == p;
	if(dp[id][ID_MAX + p] >= 0) return dp[id][ID_MAX + p];
	dp[id][ID_MAX + p] = recursive(axis, id + 1, p + C[axis][id]) ||
			recursive(axis, id + 1, p - C[axis][id]);
	return dp[id][ID_MAX + p];
}

