#include <bits/stdc++.h>
using namespace std;

#define FOR(i, a, b) for (int i = (int)(a); i < (int)(b); i++)
#define REP(i, n) FOR(i, 0, n)

int sq(int a)
{
	return a * a;
}

int n;
int x[24], y[24], r[24], c[24];

int dist(int i, int j)
{
	return sq(x[i] - x[j]) + sq(y[i] - y[j]);
}

bool isec(int i, int j)
{
	return dist(i, j) < sq(r[i] + r[j]);
}

vector<pair<int, int>> v;
int ng[24];
int dp[1 << 24];

int calc(int bit)
{
	if (~dp[bit]) return dp[bit];

	int res = 0;

	for (auto p : v){
		int c = (1 << p.first) | (1 << p.second);
		if (bit & c) continue;
		if (~bit & ng[p.first]) continue;
		if (~bit & ng[p.second]) continue;
		res = max(res, 2 + calc(bit | c));
	}

	return dp[bit] = res;
}

int solve()
{
	v.clear();
	REP(i, n) FOR(j, i + 1, n){
		if (isec(i, j)) continue;
		if (c[i] != c[j]) continue;
		v.emplace_back(i, j);
	}

	memset(ng, 0, sizeof ng);
	REP(i, n) FOR(j, 0, i){
		if (isec(i, j)) ng[i] |= 1 << j;
	}

	memset(dp, -1, sizeof dp);
	return calc(0);
}

int main()
{
	while (cin >> n, n){
		REP(i, n) cin >> x[i] >> y[i] >> r[i] >> c[i];
		cout << solve() << endl;
	}
