ll solve(int i, int a, int t, int g, int c)
{
	ll res = 0;
	if (i == tar.size())
	{
		if (a == A&&t == T&&g == G&&c == C) return 1;
		else return 0;
	}
	if (dp[i][a][t][g][c] >= 0) return dp[i][a][t][g][c];
	REP(j, tar[i].size())
	{
		if (tar[i][j] == 'A') res += solve(i + 1, a + 1, t, g, c);
		if (tar[i][j] == 'T') res += solve(i + 1, a, t + 1, g, c);
		if (tar[i][j] == 'G') res += solve(i + 1, a, t, g + 1, c);
		if (tar[i][j] == 'C') res += solve(i + 1, a, t, g, c + 1);
		res %= MOD;
	}
	return dp[i][a][t][g][c] = res%MOD;
}

