		else
		{
			int nx = mp[v[i][j]];
			vs tmp = search(nx);
			if (tmp == vs{ "-1" } || res.size() + tmp.size() > A + T + G + C) return vs{ "-1" };
			res.insert(res.end(), ALL(tmp));
		}
	}
	return res;
}

