const int MN = 1010;
const int MV = 1000100;
//const int SV = MV-3;
//const int TV = MV-1;
//const int TV2 = MV-2;
const int INF = 1<<28;

int SV, TV, TV2;
SCC<MV> scc;
vector<int> sccg[MV];
int dp[MV];

int solve() {
    scc.exec(TV+1);
    for (int i = 0; i < MV; i++) {
        for (int j: scc.g[i]) {
//            printf("edge %d %d\n", scc.res[i], scc.res[j]);
            sccg[scc.res[i]].push_back(scc.res[j]);
        }
    }
//    printf("sv: %d tv2: %d tv: %d\n", scc.res[SV], scc.res[TV2], scc.res[TV]);
    fill_n(dp, MV, -INF);
    dp[scc.res[TV]] = -3;
    dp[scc.res[TV2]] = -2;
    for (int i = MV-1; i >= 0; i--) {
//        if (sccg[i].size() == 0) continue;
        if (i == scc.res[TV] or i == scc.res[TV2]) continue;
        int ma = -INF;
        bool loop = false;
        for (int j: sccg[i]) {
            if (i == j) {
                loop = true;
                continue;
            }
            if (dp[j] == -INF) continue;
            ma = max(ma, dp[j]+2);
        }
        if (ma < -INF/2) ma = -INF;
        if (ma == -INF) {
            dp[i] = -INF;
            continue;
        }
        if (loop) ma = INF;
        dp[i] = ma;
    }
    if (dp[scc.res[SV]] > INF/2) return -1;
    return dp[scc.res[SV]];
}

