#include<iostream>
#include<map>
using namespace std;
const int NQmax = 100000;
int N,Q;
string S[NQmax];
int prefix[NQmax];
map<int, int> former[NQmax];

struct trie {
  int k; // index of this node
  int n; // number of children
  struct trie *c[26];
};

void init(struct trie *t){
  t->k = -1;
  t->n = 0;
  for(int i=0; i<26; i++) t->c[i] = NULL;
}

struct trie *add(struct trie *t, string s){
  t->n++;
  if(s.empty()) return t;

  int c = s[0]-'a';
  if(t->c[c] == NULL){
    t->c[c] = new struct trie;
    init(t->c[c]);
  }
  return add(t->c[c], s.substr(1, s.size()-1));
}

int main(){
  cin >> N;
  for(int i=0; i<N; i++){
    cin >> S[i];
  }
  struct trie *root = new struct trie;
  init(root);
  for(int i=0; i<N; i++){
    add(root, S[i])->k = i;
  }

  for(int i=0; i<N; i++){
    struct trie *t=root;
    for(int j=0; j<S[i].size(); j++){
      int c = S[i][j]-'a';
      struct trie* s = t->c[c];
      if(t->k >= 0) prefix[i]++;
      for(int k=0; k<26; k++){
        if(k==S[i][j]-'a'|| t->c[k]==NULL) continue;
        former[i][k*26+c] += t->c[k]->n;
      }
      t=s;
    }
  }

  cin >> Q;
  for(int i=0; i<Q; i++){
    int K;
    string P;
    cin >> K;
    cin >> P;
    int res = prefix[K-1]+1;
    for(int j=0; j<26; j++){
      for(int k=j; k<26; k++){
        res += former[K-1][(P[j]-'a')*26+P[k]-'a'];
      }
    }
    cout << res << endl;
  }


  return 0;
}
