#define HMAX 1000
#define WMAX 1000
#define NMAX 9
#define INF 10000000
#define EMPTY -1
#define OBSTACLE -2

int H, W, N;
int map[HMAX + 2][WMAX + 2];

int dirs_h[] = {0, 0, 1, -1};
int dirs_w[] = {1, -1, 0, 0};

struct Position {
	int h;
	int w;
};
Position factory[NMAX + 1];
Position dirs[4] = {
	Position{ 0,  1},
	Position{ 0, -1},
	Position{ 1,  0},
	Position{-1,  0}
};

using namespace std;

int go(Position start, Position end) {
	queue<Position> q;
	q.push(start);

	map[start.h][start.w] = 0;
	int min = 0;
	while (!q.empty()) {
		Position pos = q.front();

		q.pop();

		rep(i, 4){
			Position pos_n = Position{pos.h + dirs[i].h, pos.w + dirs[i].w};

			if (map[pos_n.h][pos_n.w] != OBSTACLE) {
				if (map[pos_n.h][pos_n.w] == EMPTY) {
					q.push(pos_n);
				}else{
					if (min > map[pos_n.h][pos_n.w] + 1)
						min = map[pos_n.h][pos_n.w] + 1;
				}
			}
		}
		map[pos.h][pos.w] = min;
		min = INF;
		if (pos.h == end.h && pos.w == end.w)
			break;
	}
	int ans = map[end.h][end.w];

	rep(i, H + 2){
		rep(j, W + 2){
			/*debug
			switch(map[i][j]){
				case OBSTACLE:
					cout << "  X";
				break;
				case EMPTY:
					cout << "   ";
				break;
				default:
					cout << setw(3) << map[i][j];
				break;
			}*/

			map[i][j] = map[i][j] >= 0 ? EMPTY : map[i][j];
		}
		//cout << endl;
	}
	return ans;
}

int main() {
	scanf("%d%d%d", &H, &W, &N);

	rep(i, H){
		rep(j, W){
			char m;
			scanf(" %c",&m);
			int m_i = m - '0';
			switch (m) {
				case 'S':
					factory[0] = Position{i + 1, j + 1};
					map[i + 1][j + 1] = EMPTY;
				break;
				case 'X':
					map[i + 1][j + 1] = OBSTACLE;
				break;
				case '.':
					map[i + 1][j + 1] = EMPTY;
				break;
				default:
					int num = m - '0';
					factory[num] = Position{i + 1, j + 1};
					map[i + 1][j + 1] = EMPTY;
				break;
			}
		}
	}

	rep(i, H + 2){
		map[i][0] = OBSTACLE;
		map[i][W + 1] = OBSTACLE;
	}

	rep(j, W + 2){
		map[0][j] = OBSTACLE;
		map[H + 1][j] = OBSTACLE;
	}

	int sum = 0;
	rep(i, N)
		sum += go(factory[i], factory[i + 1]);

	cout << sum << endl;
