const int MAXN = 24;
int n;
int x[MAXN], y[MAXN], r[MAXN], c[MAXN], top[MAXN], dp[1<<MAXN];

int main() {
  while(cin >> n && n) {
    for(int i = 0; i < n; ++i) {
      cin >> x[i] >> y[i] >> r[i] >> c[i];
    }
    for(int i = 0; i < n; ++i) {
      top[i] = 0;
      for(int j = 0; j < i; ++j) {
        if((x[i]-x[j])*(x[i]-x[j]) + (y[i]-y[j])*(y[i]-y[j])
           < (r[i]+r[j])*(r[i]+r[j])) {
          top[i] |= 1 << j;
        }
      }
    }
    memset(dp, 0, sizeof(dp));
    dp[(1<<n)-1] = 1;
    for(int b = (1<<n)-1; b >= 0; --b) {
      if(!dp[b]) continue;
      for(int i = 0; i < n; ++i) {
        if(!(b>>i&1) || (b & top[i])) continue;
        for(int j = i+1; j < n; ++j) {
          if(!(b>>j&1) || (b & top[j]) || c[i] != c[j]) continue;
          dp[b - (1<<i) - (1<<j)] = 1;
        }
      }
    }
    int res = n;
    for(int b = 0; b < (1<<n); ++b) {
      if(dp[b]) res = min(res, __builtin_popcount(b));
    }
    cout << n - res << endl;
  }
  return 0;
