#include<bits/stdc++.h>
typedef long long ll;
const int MN=24,MOD=1e9+7;
int N,A[MN][MN],dp[MN][1<<MN];
inline int cb(int msk, int b) {
    return msk & ~(1<<b);
}
inline int sb(int msk, int b) {
    return msk | (1<<b);
}
inline int tb(int msk, int b) {
    return msk ^ (1<<b);
}
inline bool ib(int msk, int b) {
    return msk & (1<<b);
}
int solve(int n,int msk) {
    if(n<0) return 1;
    if(~dp[n][msk]) return dp[n][msk];
    dp[n][msk]=0;
    for(int i=0;i<N;++i)
        if(A[n][i] && !ib(msk,i)) dp[n][msk]=(dp[n][msk]+solve(n-1,sb(msk,i)))%MOD;
    return dp[n][msk];
}
int main() {
    scanf("%d",&N);
    for(int i=0;i<N;++i)
        for(int j=0;j<N;++j)
            scanf("%d",&A[i][j]);
    memset(dp,-1,sizeof dp);
    printf("%d\n",solve(N-1,0));
}
