class Mod{
	const int n;
	public:
		Mod(const int _n):n(_n){}
		bool operator()(const int _src){
			return ! (_src % n);
		}
};

const std::vector<int> Eratosthenes(std::vector<int>& src){
	std::vector<int> result;
	int cnt(0);
	while(!src.empty()){
		int n(src[0]);
		result.push_back(n);
		Mod mod(n);
		std::vector<int>::iterator it= std::remove_if( src.begin(), src.end(), mod );
		src.erase(it,src.end());
		if(cnt<10 || cnt%10==0){
			src.swap(src);
		}
	}
	return result;
}
static int const MAX(1000000);

