typedef complex< int > Point;

int N;
Point p[24];
int R[24], C[24];
short f[1 << 24];

void read_plate(void);
void solve(void);
short dp(int);
bool is_valid(int, int);

int main() {
  while (cin >> N, N) {
    read_plate();
    solve();
  }

  return 0;
}

void read_plate(void) {
  for (int i = 0; i < N; ++i) {
    int x, y;
    cin >> x >> y >> R[i] >> C[i];
    p[i] = Point(x, y);
  }
}

void solve(void) {
  fill(&f[0], &f[1 << N], short(-1));
  cout << dp((1 << N) - 1) << endl;
}

short dp(int m) {
  if (f[m] != -1) return f[m];
  if (m == 0)     return short(0);

  f[m] = short(0);
//  cout << "m = " << bitset< 7 >(m) << endl;
  for (int i = 0; i < N; ++i)
    if ((1 << i & m) && is_valid(i, m))
      for (int j = 0; j < N; ++j)
        if ((1 << j & m) && i != j && C[i] == C[j] && is_valid(j, m))
          f[m] = max(f[m], short(dp(m & ~(1 << i) & ~(1 << j)) + 2));

  return f[m];
}

bool is_valid(int qi, int qm) {
  for (int i = qi - 1; i >= 0; --i)
    if ((1 << i & qm) && norm(p[i] - p[qi]) < (R[i] + R[qi]) * (R[i] + R[qi]))
      return false;
  return true;
},memory_limit_exceeded,,p00756

