#define REP(i,n)  FOR(i,0,n)

//constant
//--------------------------------------------
const double EPS = 1e-10;
const double PI  = acos(-1.0);
const int INF = 1e9;

int N, M, C, SZ;
struct Edge{
  int to, cost;

  Edge(int t, int c): to(t), cost(c)
  {}
  bool operator>(const Edge& rhs) const{
	return cost > rhs.cost;
  }
};
typedef vector< vector<Edge> > Graph;
void add_edge(Graph& graph, int u, int v, int cost){
  graph[u].push_back(Edge(v,cost));
  graph[v].push_back(Edge(u,cost));
}

void Dijkstra(const Graph& edges, vector<int>& d, int s){
  const int V = edges.size();
  priority_queue<PII, vector<PII>, greater<PII> > pq;
  fill(d.begin(), d.end(), INF);
  d[s] = 0;
  pq.push(MP(0,s));

  while(!pq.empty()){
	PII pii = pq.top(); pq.pop();
	int v = pii.second;
	if(d[v] < pii.first) continue;
	for(int i=0;i<edges[v].size();++i){
	  const Edge& e = edges[v][i];
	  if(d[e.to] > d[v] + e.cost){
		d[e.to] = d[v] + e.cost;
		pq.push(MP(d[e.to], e.to));
	  }
	}
  }
}

int idx(int u, int cap){
  return cap*SZ+u;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  while(cin>>N>>M>>C,N){
	map<string,int> cor;
	string src, dest; cin >> src >> dest;
	SZ = 0;
	cor[src] = SZ++;
	cor[dest] = SZ++;
	C *= 10;
	vector<tuple<int,int,int>> mem;
	REP(i,N){
	  string s1, s2; int d;
	  cin >> s1 >> s2 >> d;
	  if(!cor.count(s1)) cor[s1] = SZ++;
	  if(!cor.count(s2)) cor[s2] = SZ++;
	  mem.PB(make_tuple(cor[s1],cor[s2],d));
	}

	Graph G(SZ*2100);
	for(auto& tp: mem){
	  int u, v, d;
	  tie(u,v,d) = tp;
	  for(int j=d;j<=C;++j){
		G[idx(u,j)].PB(Edge(idx(v,j-d),d));
		G[idx(v,j)].PB(Edge(idx(u,j-d),d));
	  }
	}
	REP(i,M){
	  string s; cin >> s;
	  if(!cor.count(s)) continue;
	  for(int j=0;j<=C;++j)
		G[idx(cor[s],j)].PB(Edge(idx(cor[s],C),0));	  
	}

	VI dist(SZ*2100);
	Dijkstra(G,dist,idx(cor[src],C));
	int ans = INF;
	for(int j=0;j<=C;++j)
	  ans = min(ans, dist[idx(cor[dest],j)]);

	cout << (ans==INF? -1: ans) << endl;
  }

  return 0;
},memory_limit_exceeded,,p00897

