using namespace std;

int n, m;
vector<vector<double> > win;
vector<vector<vector<double> > > memo;

double solve(int curr, bitset<16> cat, int select)
{
    if(curr == n)
        return 1.0;

    if(memo[curr][cat.to_ulong()][select] > -0.5)
        return memo[curr][cat.to_ulong()][select];

    double ret = 0.0;
    for(int i=0; i<m; ++i){
        if(!cat[i])
            continue;
        if(select != m && select != i)
            continue;

        double p = win[i][curr] * solve(curr+1, cat, i);
        cat[i] = false;
        p += (1.0 - win[i][curr]) * solve(curr, cat, m);
        cat[i] = true;

        ret = max(ret, p);
    }

    return memo[curr][cat.to_ulong()][select] = ret;
}

int main()
{
    cin >> m >> n;
    win.assign(m, vector<double>(n));
    for(int i=0; i<m; ++i){
        for(int j=0; j<n; ++j){
            cin >> win[i][j];
        }
    }

    memo.assign(n, vector<vector<double> >(1<<m, vector<double>(m+1, -1.0)));
    printf("%.10f\n", solve(0, (1<<m)-1, m));

    return 0;
},memory_limit_exceeded,,p01354

