class Prim {
private:
	vector<vector<long>> E; //隣接行列
	pq mincost;
	vector<bool> used;
	size_t V;
public:
	Prim() : V(0) {}

	Prim(size_t v) : 
		V(v),E(v,vector<long>(v,2147483647)),used(v,false){}

	size_t size() {return V;}

	void add_edge_directed(long start,long goal,long weight){
		E[start][goal] = weight;
	}

	void add_edge_undirected(long start,long goal,long weight){
		E[start][goal] = weight;
		E[goal][start] =  weight;
	}

	long min_spanning_tree(void){
		long minval = 0;
		mincost.push(pr(0,0));
		while(1) {
			if (mincost.empty()) break;
			pr node = mincost.top();
			mincost.pop();
			if (used[node.second]) continue;
			minval += node.first;
			used[node.second] = true;

			REP(i,V) 
				if (!used[i] && E[node.second][i] != 2147483647) 
					mincost.push(pr(E[node.second][i],i));
		}

		return minval;
	}

};


