struct rollingHash {
    vector<vll> alphaSize;
    ll alpha;
    vll primes;
    vll val;
    rollingHash(ll alphaSz = 26) {
        alpha = alphaSz;
        val.pb(0);
        val.pb(0);
        primes.pb(mod);
        primes.pb(mod + 2);
        alphaSize.resize(2);
        rep(i,0,2) {
            alphaSize[i].resize(alpha);
            alphaSize[i][0] = 1;
            rep(j,1,alpha) alphaSize[i][j] = ( alphaSize[i][j - 1] * alpha) % primes[i];
        }
    }

    void addC(char& c) {
        int idx = c - 'a';
        rep(i,0,2) {
            val[i] = ( val[i] + alphaSize[i][idx] ) % primes[i];
        }
    }

    void clear() {
        val[0] = 0ll;
        val[1] = 0ll;
    }
};

string a, b;
unordered_set<pair<ll, ll> > memo;

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    rollingHash rk(26);
    cin >> a >> b;
    int lenA = sz(a), lenB = sz(b);
    rep(st, 0, lenA) {
        rk.clear();
        rep(x, st, lenA) {
            rk.addC(a[x]);
            memo.insert(make_pair(rk.val[0], rk.val[1]) );
        }
    }
    int ans = 0;
    rep(st, 0, lenB) {
        rk.clear();
        rep(x, st, lenB) {
            rk.addC(b[x]);
            if(memo.find(make_pair(rk.val[0], rk.val[1]) ) != memo.end() ) {
                ans = max(ans, x - st + 1);
            }
        }
    }
    cout << ans << endl;
    return 0;
}


