    rep(i,0,W){ ll p; cin>>p; xSeg.update(i,{p,i}); }
    rep(i,0,H){ ll q; cin>>q; ySeg.update(i,{q,i}); }
    //cout<<solve(0,W,0,H)<<endl;
    cout<<solve(W,H)<<endl;
    return 0;
}
