typedef long long LL;

const int N=200000 + 10;
const LL MOD = 1000000007;
int n,a[N],b[N];
LL fac[N],inv[N];
LL mpow(LL a, LL x){
    if(x==0)return 1;
    LL t=mpow(a,x>>1);
    if(x%2==0)return t*t%MOD;
    return t*t%MOD*a%MOD; 
}
int getId(int x,int y) {
    return (x+2000)*4000+(y+2000);
}
int dx[2]={1,0};
int dy[2]={0,1};
bool inside(int x,int y){
    return x>=-2000 && x<=2000 && y>=-2000 && y<=2000;
}
const int V=17000000+2;
int S=V-2,T=V-1;
struct Edge {
    int v,nex;
} edge[V<<1];
int head[V],tot;
int dis[V],in[V]; bool vis[V],canreach[V];
void link(int u,int v){
    edge[tot].v=v; edge[tot].nex=head[u]; head[u]=tot++;
}
void init(){
    queue<int> q; q.push(S); canreach[S]=1;
    while(q.size()){
        int u=q.front(); q.pop(); 
        for(int i=head[u];i!=-1;i=edge[i].nex) {
            int v=edge[i].v; 
            if(!canreach[v]) {
                q.push(v); canreach[v]=1;
            }
        }
    }
    for(int i=1;i<V;i++){
        if(!canreach[i]) continue;
        for(int e=head[i];e!=-1;e=edge[e].nex) {
            in[edge[e].v]++;
        }
    }
}
void BFS(){
    queue<int> q;
    q.push(S); vis[S]=1; dis[S]=1;
    while(q.size()){
        int u=q.front(); q.pop();
        //printf("u=%d, %d\n",u,dis[u]);
        for(int i=head[u];i!=-1;i=edge[i].nex){
            //printf("v=%d, %d\n", v, in[v]);
            int v=edge[i].v;
            if(in[v]){
                --in[v]; 
                (dis[v]+=dis[u])%=MOD;
                if(in[v]==0) q.push(v);
            }
        } 
    }
}
int main() {
    memset(head,-1,sizeof(head));
    fac[0]=1; inv[0]=1;
    for(int i=1;i<N;i++){
        fac[i]=fac[i-1]*i%MOD;
        inv[i]=mpow(fac[i],MOD-2);
    }
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d%d",&a[i],&b[i]);
    }
    int L=1999;
    for(int i=-L;i<=L;i++){
        for(int j=-L;j<=L;j++){
            for(int dir=0;dir<2;dir++){
                int nx=i+dx[dir], ny=j+dy[dir];
                if(inside(nx,ny)) {
                    link(getId(i,j), getId(nx,ny));
                }
            }
        }
    }   
    for(int i=1;i<=n;i++){
        link(S,getId(-a[i],-b[i]));
    }
    for(int i=1;i<=n;i++){
        link(getId(a[i],b[i]),T);
    }
    init();
    BFS();
    LL ans=dis[T];
    for(int i=1;i<=n;i++) {
        ans=ans-(fac[2*a[i]+2*b[i]] * inv[2*a[i]] % MOD * inv[2*b[i]] % MOD);
        ans=(ans%MOD+MOD)%MOD;
    }
    printf("%d\n", ans * (MOD+1)/2 % MOD);
}
