using namespace std;

typedef pair<int, int> P;

const int N = 10000;

bool cnt[N][N];
int a, b, r, x, y, dy[] = {-1, 0, 1, 0}, dx[] = {0, 1, 0, -1};
vector<P> d;
set<P> vis;

void dfs(int y, int x){
  vis.insert(P(y, x));
  for(int i=0;i<4;i++){
    int ny = y + dy[i];
    int nx = x + dx[i];
    if(vis.find(P(ny, nx)) != vis.end()) continue;
    int dist = ny * ny + nx * nx;
    if(dist > 4 * 4 * r * r) continue;
    if(2 * 2 * r * r <= dist && dist <= 4 * 4 * r * r) d.push_back(P(ny, nx));
    dfs(ny, nx);
  }
}

void init(){
  fill(cnt[0], cnt[N], false);
  d.clear();
  vis.clear();
  dfs(0, 0);
}

main(){
  while(cin >> a >> b >> r && (a|b|r)){
    init();
    for(int i=0;i<a;i++){
      cin >> x >> y;
      cnt[x][y] = true;
    }
    int ans = 0;
    for(int i=0;i<b;i++){
      cin >> x >> y;
      for(int j=0;j<d.size();j++){
        int ny = y + d[j].first;
        int nx = x + d[j].second;
        if(ny < 0 || ny >= N) continue;
        if(nx < 0 || nx >= N) continue;
        if(cnt[ny][nx]) ans++;
      }
    }
    cout << ans << endl;
  }
