int dp_x(int _ix, int _x) {
	// 値が入ってるならreturn
	if (canArv_x[_ix][_x] != -1) {
		return canArv_x[_ix][_x];
	}
	// 初期値
	if (_ix == 0) {
		if (_x == (xv[0] + 8000)) return canArv_x[_ix][_x] = 1;
		else return canArv_x[_ix][_x] = 0;
