			return canArv_x[_ix][_x] = 1;
		}
		else canArv_x[_ix][_x] = 0;
	}
}

int dp_y(int _ix, int _y) {
	// 値が入ってるならreturn
	if (canArv_y[_ix][_y] != -1) {
