int F(){
	idx = 1;
	stack< pair< pair<int,int> ,pair<int,int> > > st;
	st.push( make_pair( make_pair(0,0) , make_pair(0,0) ) );
	while(st.size()){
		pair< pair<int,int> ,pair<int,int> > X = st.top(); st.pop();
		int x = X.first.second;
		int step = X.second.first;
		int depth = X.second.second;
		dep[x] = depth;
		if( X.first.first == 0 ){
			if( step == 0 ){
				tree[x].push_back(idx++);
				st.push(make_pair(make_pair(0,x),make_pair(1,depth)));
				st.push(make_pair(make_pair(1,idx-1),make_pair(0,depth+1)));
			}
			if( step == 1 ){
				if( s[p] == '|' ){
					p++;
					tree[x].push_back(idx++);
					ex[x].push_back('|');
					st.push(make_pair(make_pair(0,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(1,idx-1),make_pair(0,depth+1)));
				}
			}
		}
		if( X.first.first == 1 ){
			if( step == 0 ){
				tree[x].push_back(idx++);
				st.push(make_pair(make_pair(1,x),make_pair(1,depth)));
				st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
			}
			if( step == 1 ){
				if( s[p] == '&' ){
					p++;
					tree[x].push_back(idx++);
					ex[x].push_back('&');
					st.push(make_pair(make_pair(1,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
				}
			}
		}
		if( X.first.first == 2 ){
			if( step == 0 ){
				if( s[p] == '(' ){
					p++;
					tree[x].push_back(idx++);
					st.push(make_pair(make_pair(2,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(0,idx-1),make_pair(0,depth+1)));
				}else if( s[p] == '~' ){
					p++;
					tree[x].push_back(idx++);
					notflag[idx-1] = 1;
					st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
				}else{
					p++;
					while( s[p] >= '0' && s[p] <= '9' ) p++;
					var[x] = true;
				}
			}
			if( step == 1 ){
				p++;
			}
		}
	}
}
