#include <iostream>
#include <queue>
#include <cstring>

using namespace std;

// →　↓　←　↑
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};

class state {
public:
    int x, y, d;
    state(int a, int b, int c) { x = a; y = b; d = c; }
};

int main()
{
    int h, w;

    while (cin >> w >> h, w || h) {
        bool flag = false;
        bool maze[32][32][4];
        bool past[32][32];
        int inp;

        memset(maze, 0, sizeof(maze));
        memset(past, 0, sizeof(past));
        // Input
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w - 1; x++) {
                cin >> inp;
                if (inp == 0)
                    maze[y][x + 1][2] = maze[y][x][0] = false;
                else
                    maze[y][x + 1][2] = maze[y][x][0] = true;
            }

            if (y < h - 1) 
                for (int x = 0; x < w; x++) {
                    cin >> inp;
                    if (inp == 0)
                        maze[y + 1][x][3] = maze[y][x][1] = false;
                    else
                        maze[y + 1][x][3] = maze[y][x][1] = true;                        
                }
        }

        state s(0, 0, 1);
        queue<state> q;
        q.push(s);

        while (!q.empty()) {
            state now = q.front();
            q.pop();
            past[now.y][now.x] = true;

            if (now.x == w - 1 && now.y == h - 1) {
                cout << now.d << endl;
                flag = true;
                break;
            }

            for (int i = 0; i < 4; i++) {
                if (maze[now.y][now.x][i])
                    continue;
                int nx = now.x + dx[i];
                int ny = now.y + dy[i];

                if (nx < 0 || ny < 0 || nx >= w || ny >= h)
                    continue;

                if (past[ny][nx] == false)
                    q.push(state(nx, ny, now.d + 1));
            }
        }

        if (!flag)
            cout << 0 << endl;
    }

    return 0;
},memory_limit_exceeded,,p00747

