struct P
{
	int x, y;
	int cost;
	int i;
	set<piii> a;
	bool move()
	{
		x += dx[i];
		y += dy[i];
		if (a.count(piii(i,pii(x, y)))||x<=0||y<=0||w<x||h<y)return false;
		a.insert(piii(i,pii(x, y)));
		return true;
	}
	void turn_right()
	{
		i+=1;
		i %= 4;
	}
	void turn_left()
	{
		i+=3;
		i %= 4;
	}
	void turn_back()
	{
		i += 2;
		i %= 4;
	}
	bool operator<(const P &right)const 
	{
		return cost < right.cost;
	}
	bool operator>(const P &right)const
	{
		return cost > right.cost;
	}
};


