				next.cost += cost[i];
				switch (i)
				{
				case 0:
					break;
				case 1:
					next.turn_right();
					break;
				case 2:
					next.turn_back();
					break;
				case 3:
					next.turn_left();
					break;
				}
				if (next.move())
				{
					que.push(next);
				}
			}
