int n, t, s, a[3005], b[3005], dp[3005][3005];

signed main() {
  fill(dp[0], dp[3005], -1);
  cin >> n >> t >> s;

  for (int i = 1; i <= n; ++i)
    cin >> a[i] >> b[i];

  dp[1][0] = 0;
  for (int i = 1; i <= t; ++i) {
    for (int j = 0; j <= n; ++j) {
      if (dp[i][j] == -1) continue;

      for (int k = j + 1; k <= n; ++k) {
	int nxt = i;
	if ((i < s) && (s < i + b[k])) {
	  nxt = s;
	}
	nxt += b[k];
	if (t < nxt) continue;

	dp[nxt][k] = max(dp[nxt][k], dp[i][j] + a[k]);
      }
    }
  }

  int ans = 0;
  for (int i = s; i <= t; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (ans < dp[i][j]) ans = dp[i][j];
    }
  }

  cout << ans << endl;

  return 0;
