#include<iostream>
#include<map>
#include<vector>
const int maxn = 100050;
using namespace std;
vector<int> son[maxn];
struct D{
	vector<int> d;
	int de;
	D(){
		d.clear();de = 0;
	}
	bool operator <(const D& b) const{ 
		int len1=d.size();
		int len2 = b.d.size();
		if(len1 != len2) return len1<len2;//深度 
		else{
			for(int i=0;i<len1;++i){
				if(d[i]==b.d[i]) continue;
				return d[i] < b.d[i];
			}
			return false;
		}
	}
}dep[maxn];
int yz = 0;
map<D,int> T;
void dfs(int cur){
	if(son[cur].empty()){
		yz ++;
		return;
	}
	int i,j;
	int len = son[cur].size();
	dep[cur].d.push_back(len);//把儿子这一层加入
	dep[cur].de = 1; 
	for(i = 0; i <len ;++ i){
		int s=son[cur][i];
		dfs(s); //操作儿子 
		if(dep[cur].de <= dep[s].de + 1){
			for(j = 1;j < dep[cur].de;++j) dep[cur].d[j]+=dep[s].d[j-1];//跟新原有 
			for(j;j < dep[s].de + 1;++j) dep[cur].d.push_back(dep[s].d[j-1]);//需要拓展 
			dep[cur].de = dep[s].de + 1;//更新深度 
		}
		else{
			for(j = 1;j <= dep[s].de; ++j){
				dep[cur].d[j]+=dep[s].d[j-1];
			}
		}
	}//当前结点操作完毕
	 if(T.find(dep[cur])==T.end()){
	 	T[dep[cur]] = 1;
	 }
	 else  ++ T[dep[cur]];
	 return;
}
long long C[100050];
int main(){
	int n,i,a,b;scanf("%d",&n);for(i = 1;i <= n; ++i) son[i].clear();
	C[1] = 0;
	for(i=2;i<100050;++i) C[i] = C[i-1]+i-1;
	for(i = 1;i < n; ++i){
		scanf("%d%d",&a,&b);
		son[a].push_back(b);
	}
	T.clear();
	dfs(1);
	map<D,int>::iterator it;
	long long ans = 0;
	ans += C[yz];
	for(it = T.begin();it!=T.end();++it){
		ans +=C[it->second];
	}
	printf("%d\n",ans);
	return 0;
}
