using namespace std;



vector<int> tree[1000000];
vector<char> ex[1000000];


int dep[1000000];

int var[1000000];

int notflag[1000000];

int idx;

string s;
int p;

int F(){
	idx = 1;
	stack< pair< pair<int,int> ,pair<int,int> > > st;
	st.push( make_pair( make_pair(0,0) , make_pair(0,0) ) );
	while(st.size()){
		pair< pair<int,int> ,pair<int,int> > X = st.top(); st.pop();
		int x = X.first.second;
		int step = X.second.first;
		int depth = X.second.second;
		dep[x] = depth;
		if( X.first.first == 0 ){
			if( step == 0 ){
				tree[x].push_back(idx++);
				st.push(make_pair(make_pair(0,x),make_pair(1,depth)));
				st.push(make_pair(make_pair(1,idx-1),make_pair(0,depth+1)));
			}
			if( step == 1 ){
				if( s[p] == '|' ){
					p++;
					tree[x].push_back(idx++);
					ex[x].push_back('|');
					st.push(make_pair(make_pair(0,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(1,idx-1),make_pair(0,depth+1)));
				}
			}
		}
		if( X.first.first == 1 ){
			if( step == 0 ){
				tree[x].push_back(idx++);
				st.push(make_pair(make_pair(1,x),make_pair(1,depth)));
				st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
			}
			if( step == 1 ){
				if( s[p] == '&' ){
					p++;
					tree[x].push_back(idx++);
					ex[x].push_back('&');
					st.push(make_pair(make_pair(1,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
				}
			}
		}
		if( X.first.first == 2 ){
			if( step == 0 ){
				if( s[p] == '(' ){
					p++;
					tree[x].push_back(idx++);
					st.push(make_pair(make_pair(2,x),make_pair(1,depth)));
					st.push(make_pair(make_pair(0,idx-1),make_pair(0,depth+1)));
				}else if( s[p] == '~' ){
					p++;
					tree[x].push_back(idx++);
					notflag[idx-1] = 1;
					st.push(make_pair(make_pair(2,idx-1),make_pair(0,depth+1)));
				}else{
					p++;
					while( s[p] >= '0' && s[p] <= '9' ) p++;
					var[x] = true;
				}
			}
			if( step == 1 ){
				p++;
			}
		}
	}
}
long long dp[1000000][2];

vector< pair<int,int> > o;

void do_dp(){
	for(int k = 0 ; k < o.size() ; k++){
		int x = o[k].second;
		if( var[x] != 0 ){
			dp[x][0] = dp[x][1] = 1;
			continue;
		}		
		long long dp2[2][2] = {};
		dp2[0][0] = dp[tree[x][0]][0];
		dp2[0][1] = dp[tree[x][0]][1];
		for(int i = 0 ; i < ex[x].size() ; i++){
			if( ex[x][i] == '&'){
				dp2[(i+1)%2][1] = dp[tree[x][i+1]][1] * dp2[i%2][1];
				dp2[(i+1)%2][0] = dp[tree[x][i+1]][1] * dp2[i%2][0] + dp[tree[x][i+1]][0] * dp2[i%2][1] + dp[tree[x][i+1]][0] * dp2[i%2][0];
			}else{
				dp2[(i+1)%2][0] = dp[tree[x][i+1]][0] * dp2[i%2][0];
				dp2[(i+1)%2][1] = dp[tree[x][i+1]][1] * dp2[i%2][0] + dp[tree[x][i+1]][0] * dp2[i%2][1] + dp[tree[x][i+1]][1] * dp2[i%2][1];
			}
			dp2[(i+1)%2][1] %= 1000000007;
			dp2[(i+1)%2][0] %= 1000000007;
		}
		dp[x][1] = dp2[ex[x].size()%2][1];
		dp[x][0] = dp2[ex[x].size()%2][0];
		if( notflag[x] ) swap(dp[x][0],dp[x][1]);
	}
}
