#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>
#include <unordered_map>

using namespace std;

#define INF (1000000000000000000LL)

typedef pair<long long, int> P;

struct Q {
    long long time;
    long long togo;
    int status;
    int room;
    Q() {}
    Q(long long a,long long b,int c,int d) {
        this->time=a; this->togo=b; this->status=c; this->room=d;
    }
    bool operator<(const Q& rhs) const {
        return (this->time==rhs.time)?(this->togo<rhs.togo):(this->time<rhs.time);
    }
    bool operator>(const Q& rhs) const {
        return (this->time==rhs.time)?(this->togo>rhs.togo):(this->time>rhs.time);
    }
};

int main() {
    int N,M;
    long long X;
    cin >> N >> M >> X;

    vector<int> T(N);
    for(int i=0; i<N; ++i) {
        cin >> T[i];
        --T[i];
    }

    vector<P> to[N];
    for(int i=0; i<M; ++i) {
        int a,b,d;
        cin >> a >> b >> d;
        to[a-1].push_back(P((long long)d,b-1));
        to[b-1].push_back(P((long long)d,a-1));
    }

    priority_queue<Q,vector<Q>,greater<Q> > q;
    vector<long long> time(N,INF);
//    unordered_map<int,long long> um;

    q.push(Q(0LL,X,-1,0));

    while(true) {
        Q now=q.top(); q.pop();
        if(T[now.room]!=0 && time[now.room]<now.time) continue;
        time[now.room]=now.time;
        if(now.room==N-1) break;
        for(auto nxt : to[now.room]) {
            if(T[nxt.second]!=0 && time[nxt.second]<now.time+nxt.first) continue;

            if(T[nxt.second]==0 && (T[now.room]==0 || time[nxt.second]>now.time+nxt.first)) {
                time[nxt.second]=now.time+nxt.first;
                q.push(Q(now.time+nxt.first,max(0LL,now.togo-nxt.first),now.status,nxt.second));
            } else if(T[nxt.second]==now.status || nxt.first>=now.togo) {
                time[nxt.second]=now.time+nxt.first;
                q.push(Q(time[nxt.second],X,T[nxt.second],nxt.second));
            }
        }
    }

    cout << time[N-1] << endl;

    return 0;
}
