#include <bits/stdc++.h>

typedef unsigned long long hash_t;

std::mt19937 RND;
std::uniform_int_distribution<hash_t> DST;
#define random() (DST(RND))

hash_t hash_table[10][101];
std::vector<std::vector<int>> T;
std::map<hash_t, int> dp;

void dfs(int i, int s, std::vector<int> v)
{
	if (s == 0){
		T.emplace_back(v);
		return;
	}
	if (i > 9) return;
	if (i > s) return;

	v[i]++;
	dfs(i, s - i, v);
	v[i]--;

	dfs(i + 1, s, v);
}

inline hash_t getHash(const std::vector<int> &v)
{
	hash_t res = 0;
	for (int i = 0; i < 10; i++){
		res ^= hash_table[i][v[i]];
	}
	return res;
}

int calc(std::vector<int> &v)
{	
	hash_t hash = getHash(v);
	if (dp.count(hash)) return dp[hash];

	int res = 0;
	for (auto &table : T){
		bool f = true;
		for (int i = 0; i < table.size(); i++){
			v[i] -= table[i];
			if (v[i] < 0) f = false;
		}
		if (f) res = std::max(res, 1 + calc(v));
		for (int i = 0; i < table.size(); i++){
			v[i] += table[i];
		}
	}

	return dp[hash] = res;
}

int main()
{	
	for (int i = 0; i < 10; i++){
		for (int j = 0; j <= 100; j++){
			hash_table[i][j] = random();
		}
	}

	dfs(1, 10, std::vector<int>(10, 0));

	int n;
	while (std::cin >> n, n){
		std::vector<int> v(10, 0);
		for (int i = 0; i < n; i++){
			int a;
			std::cin >> a;
			v[a]++;
		}
		printf("%d\n", calc(v));
	}

	return 0;
},memory_limit_exceeded,,p00246

