#define Y imag()

typedef long double D;
typedef complex<D> P;

const D EPS = 1e-8;

int sig(D a, D b = 0) {return a < b - EPS ? -1 : a > b + EPS ? 1 : 0;}

typedef pair<D, pair<int, int> > State;

P cr[21], d;
int n;
D dis[1 << 20][21];

D solve(int bit, int p) {
  if (dis[bit][p] < 1e95) return dis[bit][p];
  if (bit == 0) {
    D ds = abs(cr[p] - cr[n]);
    if (sig(ds, abs(cr[p] - d)) >= 0) return dis[bit][p] = 1e92;
    else return dis[bit][p] = ds;
  }
  rep (i, n) if (bit & 1 << i) {
    dis[bit][p] = min(dis[bit][p], solve(bit ^ 1 << i, i) + abs(cr[p] - cr[i]));
  }
  if (sig(dis[bit][p], abs(cr[p] - d)) >= 0) return dis[bit][p] = 1e92;
  return dis[bit][p];
}

