#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAX_N = 330;    // Change as necessary
const ll  MODD = 1000000007; //

ll A[MAX_N][MAX_N][MAX_N];
int n,L;

ll f(int clicks,int l,int last){
  if(l <= last) last = n+1;
  ll& x = A[clicks][l][last];
  if(x >= 0) return x;
  if(clicks == n) return l == L && last == n+1;

  ll opt1 = (l ? f(clicks+1,l-1,last) : f(clicks+1,l,last));
  ll opt2 = (l < L ? f(clicks+1,l+1,last) : f(clicks+1,l+1,min(last,L)));
  ll opt3 = (l < L ? f(clicks+1,l+1,min(last,l)) : f(clicks+1,l+1,min(last,L)));

  x = opt1+opt2+opt3;
  x %= MODD;
  return x;
}

int main(){
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  cin >> n;
  string s; cin >> s;
  L = s.length();

  for(int i=0;i<=n;i++)
    for(int j=0;j<=n+1;j++)
      for(int k=0;k<=n+1;k++)
        A[i][j][k] = -1;

  cout << f(0,0,n+1) << endl;

  return 0;
}
