class Dijkstra{
public:
    Dijkstra(map<P,map<P,ll>> ed,ll firs,ll pnum);
    void Solve();
    map<P,ll> range;// range[a]=b;
    //vector<map<P,ll>> edges;// [a][b]=c;
    map<P,map<P,ll>> edges;
    priority_queue<pair<ll,P>,vector<pair<ll,P>>,greater<pair<ll,P>>> que;// queue=(range,poll);
};

Dijkstra::Dijkstra(map<P,map<P,ll>> ed,ll firs,ll pnum){
    edges=ed;
    range[mp(firs,0)]=0;
    que.push(mp(0,mp(firs,0)));
}

void Dijkstra::Solve(){
    while(!que.empty()){
        pair<ll,P> top_=que.top();
        que.pop();
        FOREACH(x,edges[top_.second]){
            if(!range.count(x.first))range[x.first]=INF;
            if(!range.count(top_.second))range[top_.second]=INF;
            if(range[x.first] > range[top_.second] + x.second){
                range[x.first] = range[top_.second] + x.second;
                que.push(mp(range[x.first],x.first));
            }
        }
    }
}
