    edges[mp(q[i],c[i])][mp(p[i],c[i])]=0;
    comps[p[i]].insert(c[i]);
    comps[q[i]].insert(c[i]);
  }
  REP(i,n){
    FOREACH(xx,comps[i]){
      edges[mp(i,xx)][mp(i,0)]=1;
      edges[mp(i,0)][mp(i,xx)]=0;
    }
  }
  Dijkstra dijk(edges,0,n);
  dijk.Solve();
  REP(i,n);

  if(!dijk.range[mp(n-1,0)])EN(-1);
  COUT(dijk.range[mp(n-1,0)]);



