struct Node {
    Node *parent;
    V<pair<Node*, size_t>> children;
    bool just;
    Node(Node *parent) 
        : parent(parent),
          children(26, make_pair(nullptr, 0)),
          just(false) {}
};

Node root(nullptr);

void insert(const string &str, ll idx, Node *cur) {
    if(idx == str.size()) { 
        cur->just = true;
        return;
    }
    auto ch_idx = str[idx] - 'a';
    if(cur->children[ch_idx].first == nullptr) {
        auto child = new Node(cur);
        cur->children[ch_idx] = make_pair(child, 0);
    }
    cur->children[ch_idx].second++;
    insert(str, idx + 1, cur->children[ch_idx].first);
}

void count_smaller(VV<ll> &counts, ll &cnt_just, const string &str, ll idx, Node *cur) {
    cnt_just += cur->just;
    if(idx == str.size()) return;
    char cur_c = str[idx];
    for(ll i = 0; i < 26; i++) counts[cur_c - 'a'][i] += cur->children[i].second;
    return count_smaller(counts, cnt_just, str, idx + 1, cur->children[cur_c - 'a'].first);
}

int main() {
    ll N;
    cin >> N;
    V<string> vs(N);
    for(auto &&ele : vs) {
        cin >> ele;
        insert(ele, 0, &root);
    }

    auto counts = make_v<ll>(0, N, 26, 26);
    V<ll> cnt_just(N);
    for(ll i = 0; i < N; i++) count_smaller(counts[i], cnt_just[i], vs[i], 0, &root);

    ll Q;
    cin >> Q;
    V<ll> iperm(26);
    while(Q--) {
        ll k;
        cin >> k;
        k--;
        for(ll i = 0; i < 26; i++) {
            char c;
            cin >> c;
            iperm[c - 'a'] = i;
        }
        ll ans = cnt_just[k];
        for(ll i = 0; i < 26; i++) for(ll j = 0; j < 26; j++) if(iperm[i] < iperm[j]) ans += counts[k][j][i];
        cout << ans << endl;
    }
    return 0;
}
