			que.pop();
//			cout<<now.x<<" "<<now.y<<" "<<now.b<<" "<<now.c<<endl;
			if(now.x==gx && now.y==gy) {cout<<now.c<<endl; break;}
			for(int r=0;r<4;r++){
				Dice copy=now;
				copy.roll(r);
				if(in(copy.x,copy.y)){
					copy.c+=copy.b*p[copy.y][copy.x];
					que.push(copy);
				}
			}
		}
	}
	return 0;
