typedef pair<li, li> PI;


map<li, bool> visit[100100];

li n;
vector<PI> edge[100100];

inline li dijkstra() {
	priority_queue<pair<PI, li>> q;
	q.emplace(mp(0, 0), -1);
	while (!q.empty()) {
		li now = q.top().F.S;
		li cost = q.top().F.F;
		li from_rail = q.top().S;
		if (now == n - 1)return -cost;
		q.pop();
		if (visit[now][from_rail])continue;
		visit[now][from_rail] = true;
		rep(i, sz(edge[now])) {
			li next = edge[now][i].F;
			li next_rail = edge[now][i].S;
			li w = (next_rail == from_rail ? 0 : 1);
			if (!visit[next][next_rail]) {
				q.emplace(mp(cost - w, next), next_rail);
			}
		}
	}
	return -1;
}

