#define MAX_BITS 19
using namespace std;
int h,w;
int sum;
int sx,sy;
int dp[(1<<MAX_BITS)+1][23];
int s[MAX][MAX];
int housInd[MAX][MAX];
/*
 2
1 3
 0
*/
int dx[]={0,-1,0,1},dy[]={1,0,-1,0};
int func(int ny, int nx, int bit){
//	cout << "hi" << bit << endl;
	if(housInd[ny][nx] != -1 && bit < (1 << MAX_BITS) && dp[bit][housInd[ny][nx]] != -1){
		return dp[bit][housInd[ny][nx]];
	}

	int ret = 0;
	bool isLast = bit == (1 << sum) - 1;

	if (isLast && dp[1<<MAX_BITS][housInd[ny][nx]] != -1) return dp[1<<19][housInd[ny][nx]];
	for (int i = 0; i < 4; i++) {
		for (int x = nx+dx[i], y = ny+dy[i]; 0 <= x && x < w && 0 <= y && y < h; x += dx[i], y += dy[i]) {
			int ind = housInd[y][x];
			if (ind == -1) {
				if (isLast && s[y][x] == 2) return dp[1<<MAX_BITS][housInd[ny][nx]] = 1;
			}
			else {
				if (!isLast) {
					if ((bit & 1 << ind) == 0) {
						ret += func(y, x, bit | (1 << ind));
						break;
					}
				}
			}
		}
	}

	return isLast ? (dp[1<<MAX_BITS][housInd[ny][nx]] = ret)
			: (housInd[ny][nx] != -1 && bit < (1 << MAX_BITS)) ? (dp[bit][housInd[ny][nx]] = ret) : ret;
}
