int team[11111111]={0};

void updata(int k,int x){
  int no=k;
  k += N-1;
  rmq[k].first += x;
  rmq[k].second = k;
  while(k > 0){
    k = (k - 1) / 2;
    if(rmq[k*2+1].first > rmq[k*2+2].first){
      rmq[k] = rmq[k*2+1];
    }
    else if(rmq[k*2+1].first < rmq[k*2+2].first){
      rmq[k] = rmq[k*2+2];
    }
    else if(rmq[k*2+1].second < rmq[k*2+2].second){
      rmq[k] = rmq[k*2+1];
    }
    else{
      rmq[k] = rmq[k*2+2];
    }
  }
  return;
}


