  for(int i=0;i<1111111;i++){
    rmq[i].first = 0;
    rmq[i].second = 0;
  }
  int smp=0;
  int now=0;
  int now1=0;
  cin >> N >> R >> L;
  for(int i=0;i<R;i++){
    smp = rmq[0].second;
    cin >> d[i] >> t[i] >> x[i];
    updata(d[i],x[i]);
    if(smp != rmq[0].second){
      team[smp-2] += t[i] - now;
      if(t[i] != t[i+1]){ 
	now = t[i];
      }
    }
    smp = rmq[0].second;
