  bool F[52][52];
  unsigned char D[52][52][52][52];

class Point{
public:
  int tx;
  int ty;
  int kx;
  int ky;
  void set(int a,int b,int c,int d){
    tx = a;
    ty = b;
    kx = c;
    ky = d;
  }
};

int is_out_of_area(int y,int x){
  return x < 1 || x > W || y < 1 || y > H;
}
int main(){

  queue<Point> qa;
  Point p;
  int a,tx,ty,kx,ky;
  int inc_ty,inc_ky,inc_tx,inc_kx;
  while(1){

    cin >> W >> H;
    if(W == 0 && H == 0)
    break;
    cin >> tx >> ty >> kx >> ky;

    for(int y=0;y<=H+1;y++){
      for(int x=0;x<=W+1;x++){
        F[y][x] = 1;
      }
    }
    for(int y=1;y<=H;y++){
      for(int x=1;x<=W;x++){
        cin >> a;
        F[y][x] = a;
        for(int i=1;i<=H;i++){
          for(int j=1;j<=W;j++){
            D[y][x][i][j] = INF;
          }
        }
      }
    }

    p.set(tx,ty,kx,ky);
    qa.push(p);
    D[p.ty][p.tx][p.ky][p.kx] = 0;
    int counter=0;
    while(1){
      if(qa.empty()){
        cout << "NA" <<endl;
        break;
      }
      p = qa.front();
      qa.pop();
      cout << p.tx << ',' << p.ty << ',' << p.kx << ',' << p.ky << ',' << (int)D[p.ty][p.tx][p.ky][p.kx] << endl;
      if(D[p.ty][p.tx][p.ky][p.kx] >= 100){
        cout << "NA" << endl;
        break;
      }
      if(p.tx == p.kx && p.ty == p.ky){
        cout << (int)D[p.ty][p.tx][p.ky][p.kx] << endl;
        break;
      }
      counter++;
      if(D[p.ty-1][p.tx][p.ky+1][p.kx] == INF){

           inc_ty = -1 ; inc_ky = 1;
          if(is_out_of_area(p.ty-1,p.tx) || F[p.ty-1][p.tx]){
            inc_ty = 0;
          }
          if(is_out_of_area(p.ky+1,p.kx) || F[p.ky+1][p.kx]){
            inc_ky = 0;
          }

          if(inc_ty || inc_ky){
            Point q;
            q.set(p.tx,p.ty + inc_ty,p.kx,p.ky+inc_ky);
            qa.push(q);
            D[p.ty + inc_ty][p.tx][p.ky + inc_ky][p.kx] = D[p.ty][p.tx][p.ky][p.kx] + 1;
          }
