#include<iostream>
#define vecsize 1000000000
int vec[vecsize];
void W(int x,int y){
    for(int i=0;i<vecsize;++i){
        if(y>0)if(vec[i]==-1)vec[i]=x,--y;
    }
}
void D(int x){
    int size=vecsize-1;
    if(x<=size)for(int i=vecsize-1;i>=0;--i){
        if(vec[i]==x){
            vec[i]=-1;
        }
    }
}
int R(int x){
    int size=vecsize;
    if(x>size-1)return -1;
    else return vec[x];
}
