const int MAXN = 8e3+1; //AREGLAAAAAAAAR!!!!
char a[MAXN];
int memo[MAXN][MAXN][3];
int ini,fin,N;

int dp(int pos,int dir,int x){
	if(pos==N && x==ini) return 1;
	if(pos>=N) return 2;
	if(memo[pos][x][dir]) return memo[pos][x][dir];
	int good=2;
	if(a[pos]=='F'){
		if(dir==0) good=dp(pos+1,dir,x+1);  
		else if(dir==1) good=dp(pos+1,dir,x-1);
		else good=dp(pos+1,dir,x);
	}else{
		if(dir==2){
			good=dp(pos+1,0,x);
			if(good==2) good=dp(pos+1,1,x);
		}else good=dp(pos+1,2,x);
	}
	return memo[pos][x][dir]=good;
}

int dp2(int pos,int dir,int y){
	if(pos==N && y==fin) return 1;
	if(pos>=N) return 2;
	if(memo[pos][y][dir]) return memo[pos][y][dir];
	int good=2;
	if(a[pos]=='F'){
		if(dir==1) good=dp2(pos+1,dir,y-1);  
		else if(dir==0) good=dp2(pos+1,dir,y+1);
		else good=dp2(pos+1,dir,y);
	}else{
		if(dir==2){
			good=dp2(pos+1,0,y);
			if(good==2) good=dp2(pos+1,1,y);
		}else good=dp2(pos+1,2,y);
	}
	return memo[pos][y][dir]=good;
}

