using namespace std;

#define NUM 48

int checkTable[10000]={0};

class Node{
public:
	Node(){
		ch=0;
		num_of_child=num_of_end_str=0;
		parent=0,nodes=0;
		cameFLG=false;
		table=new int[128-NUM];
		for(int i=48;i<=122;i++)table[i-NUM]=0;
	}

	void addSTR(char str[],int index,int ptn_index){
		ch=str[index];
		if(str[index+1]=='\0'){
			end_str.push_back(ptn_index);
			num_of_end_str++;
		}else{
			if(num_of_child==0){
				nodes=new Node*[128-NUM];
			}
			if(table[str[index+1]-NUM]==0){
				nodes[str[index+1]-NUM]=new Node();
				table[str[index+1]-NUM]=1;
			}
			num_of_child++;
			nodes[str[index+1]-NUM]->parent=this;
			nodes[str[index+1]-NUM]->addSTR(str,index+1,ptn_index);
		}
	}
	bool searchSTR(char str[],int index){
		if(!cameFLG){
			for(int i=0;i<num_of_end_str;i++)checkTable[end_str[i]]=1;
			cameFLG=true;
		}
		if(num_of_child==0){
			if(parent != 0){
				Node* tmp=this->parent;
				tmp->num_of_child--;
				tmp->table[this->ch-NUM]=0;
				while(tmp->parent!=0&&tmp->num_of_child==0){
					tmp->parent->num_of_child--;
					tmp->parent->table[tmp->ch-NUM]=0;
					tmp=tmp->parent;
				}
			}
			return false;
		}else{
			if(str[index+1]=='\0')return true;
			else{
				if(table[str[index+1]-NUM]==1){
					return nodes[str[index+1]-NUM]->searchSTR(str,index+1);
				}else{
					return false;
				}
			}
		}
	}
	int num_of_child;
	int num_of_end_str;
	vector<int> end_str;
	Node** nodes;
	Node* parent;
	int* table;
	char ch;
	bool cameFLG;
};


class MotherNode{
public:
	MotherNode(){
		motherNode = new Node*[128-NUM];
		for(int i=48;i<=122;i++){
			motherNode[i-NUM]=new Node();
		}
	}
	void addSTR(char str[],int ptn_index){
		motherNode[str[0]-NUM]->addSTR(str,0,ptn_index);
	}
	bool searchSTR(char str[]){
		return motherNode[str[0]-NUM]->searchSTR(str,0);
	}
private:
	Node** motherNode;
};

