using namespace std;

const double inf = 1e4;

int n;
int x[22];
int y[22];
double d[22][22];
double dp[1 << 20][20];

double dfs(int s, int t){
	if(dp[s][t] != -1){
		return dp[s][t];
	}
	int u = s - (1 << t);
	if(u == 0){
		return dp[s][t] = d[n][t] < d[n + 1][t] ? d[n][t] : inf;
	}
	double p = inf;
	rep(i, n){
		if(u & (1 << i)){
			double q = dfs(u, i) + d[i][t];
			if(q < d[n + 1][t]){
				p = min(q, p);
			}
		}
	}
	return dp[s][t] = p;
}

void init(){
	rep(i, n + 2){
		rep(j, n + 2){
			double dx = x[i] - x[j];
			double dy = y[i] - y[j];
			d[i][j] = sqrt(dx * dx + dy * dy);
		}
	}
}

int main(){
	while(1){
		scanf("%d", &n);
		if(n == 0){
			break;
		}
		rep(i, 2){
			scanf("%d%d", x + n + i, y + n + i);
		}
		rep(i, n){
			scanf("%d%d", x + i, y + i);
		}
		init();
		rep(i, 1 << n){
			fill_n(dp[i], n, -1);
		}
		bool ans = false;
		rep(i, n){
			if(dfs((1 << n) - 1, i) != inf){
				ans = true;
				break;
			}
		}
		printf("%s\n", ans ? "YES" : "NO");
	}
	return 0;
