                d.vy=ins[i].second-ins[j].second;
                if(d.vx<0){
                    d.vx*=-1;
                    d.vy*=-1;
                }
                d.cx=(ins[i].first+ins[j].first)/2;
                d.cy=(ins[i].second+ins[j].second)/2;
