using namespace std;

#define WHITE 0
#define GRAY 1
#define BLACK 2
#define MAX_N 220
#define MAX_R 1020
#define INF 131211109876543210LL

priority_queue<tuple<long long, long long, long long>, vector<tuple<long long, long long, long long>>, greater<tuple<long long, long long, long long>>> Q;
priority_queue<tuple<long long, long long, long long>, vector<tuple<long long, long long, long long>>, greater<tuple<long long, long long, long long>>> Q2;
vector<tuple<long long, long long, int>>X[MAX_N];
string A4;
int N, M, R;
long long A1, A2, A3;
long long travel[MAX_R];
long long DIST[MAX_N][MAX_N], DIST2[MAX_N];
long long COLOR[MAX_N][MAX_N], COLOR2[MAX_N];
long long PATH[MAX_N][MAX_N][MAX_N];
long long DP[MAX_R][MAX_N];
long long cnt;

void dijkstra(long long st) {
	while (!Q.empty()) {
		cnt++;
		tuple<long long, long long, long long>tup = Q.top();
		long long a1 = get<0>(tup);
		long long a2 = get<1>(tup);
		long long a3 = get<2>(tup);
		COLOR[a2][a3] = BLACK;
		Q.pop();

		for (int i = 0; i < X[a2].size(); i++) {
			long long a4 = get<0>(X[a2][i]);
			long long a5 = get<1>(X[a2][i]);
			long long a6 = get<2>(X[a2][i]);

			if (a6 == 0) {
				long long a7 = a1 + a5;
				if (DIST[a4][a3] > a7 && COLOR[a4][a3] != BLACK) {
					DIST[a4][a3] = a7;
					cnt++;
					COLOR[a4][a3] = GRAY;
					Q2.push(make_tuple(DIST[a4][a3], a4, a3));
				}
			}

			if (a6 == 1 && a2 == a3) {
				long long a8 = a1 + a5;
				if (DIST[a4][a4] > a8 && COLOR[a4][a4] != BLACK) {
					DIST[a4][a4] = a8;
					cnt++;
					COLOR[a4][a4] = GRAY;
					Q2.push(make_tuple(DIST[a4][a4], a4, a4));
				}
			}

		}
		while (!Q2.empty()) {
			Q.push(Q2.top());
			Q2.pop();
		}
	}
}

void _memset() {
	N = 0; M = 0; R = 0; A1 = 0; A2 = 0; A3 = 0; A4 = "";
	for (int i = 0; i < MAX_N; i++) {
		for (int j = 0; j < MAX_N; j++) {
			DIST[i][j] = 0;
			DIST2[i] = 0;
			COLOR[i][j] = WHITE;
			COLOR2[i] = WHITE;
		}
	}
	for (int i = 0; i < MAX_N; i++) {
		for (int j = 0; j < MAX_N; j++) {
			for (int k = 0; k < MAX_N; k++) {
				PATH[i][j][k] = INF;
			}
		}
	}
	for (int i = 0; i < MAX_R; i++) {
		for (int j = 0; j < MAX_N; j++) {
			DP[i][j] = INF;
		}
	}
	for (int i = 0; i < MAX_R; i++) {
		travel[i] = 0;
	}
	for (int i = 0; i < MAX_N; i++) {
		X[i].clear();
	}
	while (!Q.empty()) {
		Q.pop();
	}
	while (!Q2.empty()) {
		Q2.pop();
	}
	cnt = 0;
}

