double dfs(int reached) {
	static int used;
	static map<pair<int,int>, double> dp;
	static map<pair<int,int>, bool> done;
	pair<int,int> cur_status = {used, reached};

	if (done[cur_status] == true) {
		return dp[cur_status];
	}
	double res = 0.0;
	if (reached == n) {
		return 1.0;
		if (test) cerr << "!";
	}
	rep(i, m) {
		if ((used >> i) & 1) continue;
		used |= 1 << i;
		double res_i = 0.0;
		double keep_win_p = 1.0;
		REP(j, reached, n) {
			res_i += dfs(j) * keep_win_p * (1.0 - board[i][j]);
			if (test) dump(dfs(j));
			keep_win_p *= board[i][j];
		}
		res_i += keep_win_p;
		chmax(res, res_i);
		used ^= 1 << i;
	}
	done[cur_status] = true;
	return dp[cur_status] = res;
}

void solve() {
	// m = atoi(s_);
	cin >> m;
	cin >> n;
	rep(i, m) rep(j, n) cin >> board[i][j];
	cout << dfs(0) << endl;
}

