using namespace std;

#define INF 1e+9

int n,m,p,a,b;
int t[9];
double d[31][31];
double dd[513][31];

class state{
public:
    double cost;
    int used;
    int node;

    state(double _c, int _u, int _n):cost(_c), used(_u), node(_n){}
    state(){}
    bool operator <(const state &arg) const{
         if(cost != arg.cost){
             return cost > arg.cost;
         }
         return node > arg.node;
     }
 };

void solve(){
    priority_queue<state> q;
    state st;
    bool visited[513][m];
    memset(visited, false, sizeof(visited));
    q.push(state(.0,0,a));

    while(!q.empty()){
        st = q.top();
        q.pop();
        dd[st.used][st.node] = min(dd[st.used][st.node], st.cost);
        visited[st.used][st.node] = true;
        if(st.node == b) break;
        for(int i=0;i<m;i++){
            if(d[st.node][i] != INF){
                for(int j=0;j<n;j++){
                    if((st.used & (1 << j)) == 0 && 
                       !visited[st.used | (1 << j)][i] && 
                       st.cost + (double)d[st.node][i] < dd[st.used | (1 << j)][i]){
                        q.push(state(st.cost + (double)d[st.node][i] / t[j], st.used | (1 << j), i));
                    }
                }
            }
        }
    }
}

int main(){
    while(cin >> n >> m >> p >> a >> b){
        int src,dst,cost;
        if((n | m | p | a | b) == 0) break;
        fill((double *)d, (double *)d+31*31, INF);
        fill((double *)dd, (double *)dd+513*31, INF);

        a--;
        b--;
        for(int i=0;i<n;i++){
            cin >> t[i];
        }
        for(int i=0;i<p;i++){
            cin >> src >> dst >> cost;
            d[src-1][dst-1] = cost;
            d[dst-1][src-1] = cost;
        }
