#include <bits/stdc++.h>
using namespace std;

template <typename T>
class SegmentTree2 {
	using func_t = function<T(T, T)>;
	const int h, w;
	const T id;
	func_t merge;
	vector<vector<T>> data;
	int size(int n) {
		int res;
		for (res = 1; res < n; res <<= 1);
		return res;
	}
	T sub_h(int li, int lj, int ri, int rj, int si, int ti, int k) {
		if (ri <= si || ti <= li) return id;
		if (li <= si && ti <= ri) return sub_w(lj, rj, 0, w, k, 1);
		const int mi = (si + ti) / 2;
		return merge(sub_h(li, lj, ri, rj, si, mi, k * 2), sub_h(li, lj, ri, rj, mi, ti, k * 2 + 1));
	}
	T sub_w(int lj, int rj, int sj, int tj, int i, int k) {
		if (rj <= sj || tj <= lj) return id;
		if (lj <= sj && tj <= rj) return data[i][k];
		const int mj = (sj + tj) / 2;
		return merge(sub_w(lj, rj, sj, mj, i, k * 2), sub_w(lj, rj, mj, tj, i, k * 2 + 1));
	}
public:
	SegmentTree2(int h_, int w_, T id_, func_t merge_) :
		h(size(h_)), w(size(w_)), id(id_), merge(merge_), data(size(w_) * 2, vector<T>(size(h_) * 2, id_)) {}
	SegmentTree2(vector<vector<T>> data_, T id_, func_t merge_) :
		h(size(data_.size())), w(size(data_.front().size())), id(id_), merge(merge_), data(h * 2, vector<T>(w * 2, id_)) {
		for (int i = 0; i < (int)data_.size(); i++)
			for (int j = 0; j < (int)data_.front().size(); j++)
				data[h + i][w + j] = data_[i][j];
		for (int i = h * 2 - 1; i >= h; i--)
			for (int j = w - 1; j > 0; j--)
				data[i][j] = merge(data[i][j * 2], data[i][j * 2 + 1]);
		for (int i = h - 1; i > 0; i--)
			for (int j = 1; j < w * 2; j++)
				data[i][j] = merge(data[i * 2][j], data[i * 2 + 1][j]);
	}
	//void Update(int pi, int pj, T val) { }
	//void Add(int pi, int pj, T val) { }
	T Find(int li, int lj, int ri, int rj) {
		return sub_h(li, lj, ri + 1, rj + 1, 0, h, 1);
	}
};

