#include <algorithm>
#include <cassert>
#include <iostream>
#include <set>
#include <vector>

class TFifteenPuzzle
{
	unsigned long long FNumbers;
	int Position(int Row, int Col)const;
public:
	TFifteenPuzzle();

	bool operator<(const TFifteenPuzzle& Other)const{return FNumbers < Other.FNumbers;}
	bool operator==(const TFifteenPuzzle& Other)const{return FNumbers == Other.FNumbers;}

	int Number(int Row, int Col)const;
	void Swap(int RowA, int ColA, int RowB, int ColB);
	void Input(std::istream& Stream);
	void Output(std::ostream& Stream)const;
};

TFifteenPuzzle::TFifteenPuzzle()
: FNumbers(0x123456789abcdef0LL)
{
}

int TFifteenPuzzle::Position(int Row, int Col)const
{
	return 4 * (4 * (3 - Row) + (3 - Col));
}

int TFifteenPuzzle::Number(int Row, int Col)const
{
	int Pos = Position(Row, Col);
	unsigned long long Result = FNumbers & (0xFLL << Pos);
	return (Result >> Pos);
}

void TFifteenPuzzle::Swap(int RowA, int ColA, int RowB, int ColB)
{
	int PosA = Position(RowA, ColA);
	int PosB = Position(RowB, ColB);
	if(PosA < PosB) std::swap(PosA, PosB);
	unsigned long long MaskA = 0xFLL << PosA;
	unsigned long long MaskB = 0xFLL << PosB;
	unsigned long long A = FNumbers & MaskA;
	unsigned long long B = FNumbers & MaskB;
	FNumbers &= ~(MaskA | MaskB);
	FNumbers |= (A >> (PosA - PosB)) | (B << (PosA - PosB));
}

void TFifteenPuzzle::Input(std::istream& Stream)
{
	FNumbers = 0;
	for(int i = 0; i < 4; ++i){
		for(int j = 0; j < 4; ++j){
			unsigned long long Num;
			Stream >> Num;
			FNumbers |= (Num << Position(i, j));
		}
	}
}

void TFifteenPuzzle::Output(std::ostream& Stream)const
{
	for(int i = 0; i < 4; ++i){
		for(int j = 0; j < 4; ++j){
			Stream << ' ' << std::hex << Number(i, j);
		}
		Stream << std::endl;
	}
	Stream << std::endl;
}

void ZeroPosition(int& Row, int& Col, const TFifteenPuzzle& Puzzle)
{
	bool Found = false;
	for(int i = 0; i < 4; ++i){
		for(int j = 0; j < 4; ++j){
			if(Puzzle.Number(i, j) == 0){
				if(Found) assert(false);
				Row = i;
				Col = j;
				Found = true;
			}
		}
	}
}

enum TMovePattern
{
	mpUp,
	mpDown,
	mpLeft,
	mpRight
};

bool Movable(const TFifteenPuzzle& Puzzle, const TMovePattern& Pattern)
{
	int Row, Col;
	ZeroPosition(Row, Col, Puzzle);
	switch(Pattern){
	case mpUp    : return Row != 0;
	case mpDown  : return Row != 3;
	case mpLeft  : return Col != 0;
	case mpRight : return Col != 3;
	}
	assert(false);
	return false;
}

TFifteenPuzzle Move(TFifteenPuzzle Puzzle, const TMovePattern& Pattern)
{
	int Row, Col;
	ZeroPosition(Row, Col, Puzzle);
	switch(Pattern){
	case mpUp    : Puzzle.Swap(Row, Col, Row - 1, Col);break;
	case mpDown  : Puzzle.Swap(Row, Col, Row + 1, Col);break;
	case mpLeft  : Puzzle.Swap(Row, Col, Row, Col - 1);break;
	case mpRight : Puzzle.Swap(Row, Col, Row, Col + 1);break;
	}
	return Puzzle;
}

void RenewTargets(
	const TFifteenPuzzle& Puzzle,
	const TMovePattern& Pattern,
	std::vector<TFifteenPuzzle>& Targets,
	std::set<TFifteenPuzzle>& History)
{
	if(!Movable(Puzzle, Pattern)) return;
	TFifteenPuzzle Moved = Move(Puzzle, Pattern);
	if(History.find(Moved) != History.end()) return;
	Targets.push_back(Moved);
	History.insert(Moved);
}
