bool is_top(int i, int used) {
	for (int j = i - 1; j >= 0; j--) {
		if (1 << j & used) continue;

		int x = (xs[i] - xs[j]) * (xs[i] - xs[j]);
		int y = (ys[i] - ys[j]) * (ys[i] - ys[j]);
		int dis = x + y;
		int dis2 = (rs[i] + rs[j]) * (rs[i] + rs[j]);

		if (dis < dis2) {	// 重なってる
			return false;
		}
	}

	return true;
}

int dfs(int used) {
	int sum = 0;

	if (memo[used] != -1) return memo[used];

	for(int i = 0;i < n;i++) {
		for (auto j : grp[cs[i]]) {
			if(i == j || (1 << i & used) || (1 << j & used)) continue;
			if(cs[i] != cs[j]) continue;
			if(!is_top(i, used) || !is_top(j, used)) continue;

			int used_tmp = used;
			used_tmp |= 1 << i;
			used_tmp |= 1 << j;

			sum = max(sum, dfs(used_tmp) + 2);
		}
	}

	return memo[used] = sum;
}

int main(void) {
	while(cin >> n, n){
		xs = VI(n);
		ys = VI(n);
		rs = VI(n);
		cs = VI(n);
		grp = VVI(4);
		int used = 0;
		memo = VI(1 << n, -1);

		for(int i = 0;i < n;i++){
			cin >> xs[i] >> ys[i] >> rs[i] >> cs[i];
			cs[i]--;
			grp[cs[i]].push_back(i);
		}

		cout << dfs(used) << endl;
	}
