    int n;
    while(cin >> n, n) {
        vector<int> empty(n);
        for(auto& e: empty) cin >> e;
        sort(empty.begin(), empty.end(), greater<int>());
        vector<int> full = {empty.front()};
        empty.erase(empty.begin());
        cout << (check(full, empty) ? "YES" : "NO") << endl;
    }
