            pii e = empty.front();
            empty.pop_front();
            if(u.second<=e.first){
                tmp.push_back(u);
                empty.push_front(e);
            } else {
                tmp.push_back(e);
                tmp.push_back(u);
            }
        }

        REP(j, tmp.size()){
            pii t = tmp.back();
            tmp.pop_back();
            empty.push_front(t);
        }
    }
    used[f2i[f]].clear();
