#include <string>
#include <iostream>

using namespace std;

string operation(string S)
{
	string T;

	int left = 0;

	if (S.size() == 1)
	{
		return "1" + S;
	}

	for (int i = 1; i < S.size(); i++)
	{
		if (S[i - 1] != S[i])
		{
			T += (to_string(i - left) + S[i - 1]);

			left = i;
		}

		if (i + 1 == S.size())
		{
			T += (to_string(S.size() - left) + S[i]);
		}
	}

	return T;
}

int main()
{
	int n; string S;

	while (true)
	{
		cin >> n;

		if (n == 0) { break; }

		cin >> S;

		for (int i = 0; i < n * 2.5; i++)
		{
			S = operation(S);
		}

		cout << S << endl;
	}

	return 0;
