            dp[i + 1][j][k] += dp[i][j][k] * C.invfact[d[i] - 1];
            if(d[i] >= 2){
                dp[i + 1][j + 1][k + d[i]] += dp[i][j][k] * C.invfact[d[i] - 2];
            }
        }
    }
    mint ans = 0;
    FOR(j, 3, N) FOR(k, 2 * j + 1, 2 * N + 1){
        ans += dp[N][j][k] * C.fact[N - 2 - (j - 1)] * C.fact[j - 1] * inv2 * (k - 2 * j);
    }
    //debug(ans);
    ans += dp[N][N][2 * N] * C.fact[N - 1] * inv2;

    Out(ans);

