using namespace std;

typedef long long ll;
typedef pair <int,vector<stack<short> > > P;
typedef pair <int,P> PP;
typedef pair <int,PP> PPP;

static const double eps = 1e-8;

int bfs(int m,vector<stack<short> >& stks, map<vector<stack<short> >,int>& visited){

	priority_queue<P,vector<P>,greater<P> > que;
	que.push(P(0,stks));
	visited[stks] = 0;

	while(!que.empty()){
		int cost = que.top().first;


		vector<stack<short> > stks = que.top().second;

		if(stks[1].empty() && stks[2].empty()) return cost;
		if(stks[0].empty() && stks[1].empty()) return cost;

		if(cost >= m) break;
		que.pop();
		for(int i=0;i+1<stks.size();i++){
			if((!stks[i].empty() && !stks[i+1].empty() && stks[i].top() < stks[i+1].top()) 
				|| (stks[i].empty() && !stks[i+1].empty())){
				vector<stack<short> > tmp = stks;
				tmp[i].push(tmp[i+1].top());
				tmp[i+1].pop();
				if(visited.find(tmp) == visited.end()){
					visited[tmp] = cost + 1;
					que.push(P(cost+1,tmp));
				}
			}

			else if((!stks[i].empty() && !stks[i+1].empty() && stks[i].top() > stks[i+1].top()) 
				|| (!stks[i].empty() && stks[i+1].empty())){
				vector<stack<short> > tmp = stks;
				tmp[i+1].push(tmp[i].top());
				tmp[i].pop();
				if(visited.find(tmp) == visited.end()){
					visited[tmp] = cost + 1;
					que.push(P(cost+1,tmp));
				}
			}
		}
	}
	return -1;
}

int main(){

	int n,m;
	while(~scanf("%d %d",&n,&m)){
		if(n==m && m==0) break;
		vector<stack<short> > stks(3);
		map<vector<stack<short> >,int> visited;
		for(int i=0;i<3;i++){
			int amount;
			scanf("%d",&amount);
			for(int j=0;j<amount;j++){
				int size;
				scanf("%d",&size);
				stks[i].push(size);
			}
		}

		printf("%d\n",bfs(m,stks,visited));
	}
