bool timeup(int time){
    static bool never = true;
    if(never)message += "may timeup, because slow";
    never = false;

    auto end_time = system_clock::now();
    auto part = duration_cast<milliseconds>(end_time - start_time);
    auto lim = milliseconds(time);
    return part >= lim;
}
#else
