//4e6 >= n なら O(r)で計算する
mint com_big(int n,int r){    int fa = finv[r];    rep(i, r)fa *= n - i, fa %= MOD;    return mint(fa);}
mint com(int n, int r) {    if (r < 0 || r > n) return 0;    /*nが大きくてrが小さい場合、nを上からr個掛ける*/    if (n >= sz(fac)) {        if (n <= 4e6)setmod_resize(n + 1000);        else return com_big(n, r);    }    return mint(finv[r] * fac[n] % MOD * finv[n - r]);}
mint pom(int n, int r) {/*    if (!sz(fac)) com(0, -1);*/    if (r < 0 || r > n) return 0;    return mint(fac[n] * finv[n - r]);}
