            //lを選ばないといけない
            dp[i+1][s+a][l] += dp[i][s][no] * (i+1);
            dp[i+1][s+a][lr] += dp[i][s][no] * (i+1) * (N - i);

            dp[i+1][s][l] += dp[i][s][l];
            dp[i+1][s+a][l] += dp[i][s][l];
            dp[i+1][s+a][lr] += dp[i][s][l] * (N-i);

            dp[i+1][s][lr] += dp[i][s][lr];

        }
    }
    out(dp[N][S][lr]);
}

