int i, j, k, p, q, r, n, m, a, b, c, cost[3001], t, dc[3001][3001], dt[3001][3001];

int dic(const int d[][3001]) {
  cost[p] = 0;
  int min, f[3001] = {};
  for(i = 0; i < m; i++) {
    f[p] = 1;
    for(j = 1; j <= m; j++) {
      if(f[j]) continue;
      if(cost[j] > cost[p] + d[p][j]) cost[j]  = cost[p] + d[p][j];
    }
    min = 200000000;
    for(j = 1; j <= m; j++ ) {
      if(f[j]) continue;
      if(min > cost[j]) min = cost[p = j];
    }
  }
  return cost[q];
}


