typedef long long ll;
const int mod = 998244353;
inline int add(int a,int b){a+=b;return a>=mod?a-mod:a;}
inline int sub(int a,int b){a-=b;return a<0?a+mod:a;}
inline int mul(int a,int b){return 1ll*a*b%mod;}
inline int qpow(int a,int b){int ret=1;for(;b;b>>=1,a=mul(a,a))if(b&1)ret=mul(ret,a);return ret;}
/* math */
const int N = 410;
int n,h[N];

inline void mrg(int *f,int *g,int len){
	for(int i=len;~i;i--){
		f[i] = mul(f[i], g[0]);
		for(int j=i-1;~j;j--){
			f[i] = add(f[i], mul(f[j],g[i-j]));
		}
	}
}
int bin[N][N];
int f[N][N][2][N],g[N][N][2][N];
int pw[N],ipw[N];
int _f[N];
inline void dfs(int l,int r,int x){
	// int empty=0;
	f[x][l][0][0]=f[x][l][1][0]=1;
	for(int u=l,v;u<=r;u=v+1){
		v=u;
		if(h[u]>x){
			while(v+1<=r&&h[v+1]>x)++v;
			dfs(u,v,x+1);
			mrg(f[x][l][0],f[x+1][u][0],r-l+1);
			mrg(f[x][l][1],f[x+1][u][1],r-l+1);
		}else{
			_f[0]=_f[1]=1;
			mrg(f[x][l][0],_f,r-l+1);
			_f[0]=0;
			mrg(f[x][l][1],_f,r-l+1);
		}
	}
	// cout << l << "to" << r << " " << x << endl;
	for(int i=0;i<=r-l+1;i++){
		// cout << f[x][l][1][i] << " " << f[x][l][0][i] << endl;
		//this line empty
		g[x][l][1][i] = add(g[x][l][1][i], f[x][l][1][i]);
		g[x][l][0][i] = add(g[x][l][0][i], f[x][l][1][i]);
	}
	for(int i=0;i<=r-l+1;i++){
		for(int j=0;j<=i;j++){

			g[x][l][0][j] = add(g[x][l][0][j], mul(f[x][l][0][i], mul(bin[i][j], pw[j]-(j==i))));
			// if(j==0)cout << i << " " << j << "::" << bin[i][j] <<" " << pw[j]-(j==i) << "|" << g[x][l][0][j] << endl;
			g[x][l][1][j] = add(g[x][l][1][j], mul(f[x][l][1][i], mul(bin[i][j], pw[j]-(j==i))));
		}
	}
	// cout << g[x][l][0][0] << endl;
	for(int i=0;i<=r-l+1;i++)f[x][l][1][i]=g[x][l][1][i],f[x][l][0][i]=g[x][l][0][i];
}

