#include <iostream>
#include <cstdio>
#include <algorithm>
#include <map>
#include <queue>
#include <cmath>
using namespace std;
const int num = 16, ud[] = { -1, 0, 1, 0 }, lr[] = { 0, -1, 0, 1 }, nd = 4;
int md[num][num];
struct puzzle {
	int sp, p[num], mdp, cost;
	bool operator < (const puzzle &pu) const {
		for (int i = 0; i < num; i++) {
			if (p[i] == pu.p[i]) continue;
			return p[i] < pu.p[i];
		}
		return false;
	}
};
struct state {
	puzzle pu;
	int es;
	bool operator < (const state &s) const {
		//return pu.mdp + pu.cost > s.pu.mdp + s.pu.cost;
		return es > s.es;
	}
};
int getmd(puzzle pz) {
	int sum = 0;
	for (int i = 0; i < num; ++i) {
		if (pz.p[i] == 0) continue;
		sum += md[i][pz.p[i] - 1];
	}
	return sum;
}
int astar(puzzle pz) {
	priority_queue<state> pq;
	/*for (int i = 0; i < num; i++) {
		if (pz.p[i] == 0) continue;
		sum += md[i][pz.p[i] - 1];
	}*/
	pz.mdp = getmd(pz);
	pz.cost = 0;
	map<puzzle, bool> m;
	state initial;
	initial.pu = pz;
	initial.es = getmd(pz);
	pq.push(initial);
	puzzle p, tmp;
	while (!pq.empty()) {
		state st = pq.top(); pq.pop();
		p = st.pu;
		if (!p.mdp) return p.cost;
		m[p] = true;
		int sx = p.sp / nd;
		int sy = p.sp % nd;
		for (int r = 0; r < nd; r++) {
			int tx = sx + ud[r];
			int ty = sy + lr[r];
			if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
			tmp = p;
			tmp.mdp = p.mdp - md[tx * nd + ty][p.p[tx * nd + ty] - 1] + md[sx*nd + sy][p.p[tx * nd + ty] - 1];
			tmp.sp = tx * nd + ty;
			swap(tmp.p[tx * nd + ty], tmp.p[sx * nd + sy]);
			if (!m[tmp]) {
				tmp.cost++;
				state st1;
				st1.es = tmp.cost + tmp.mdp;
				st1.pu = tmp;
				pq.push(st1);
			}
		}
	}
}

int main() {
	int sum = 0;
	puzzle in;
	for (int i = 0; i < num; i++) {
		cin >> in.p[i];
		if (!in.p[i]) { in.sp = i;  }
	}
	for (int i = 0; i < num; i++)
		for (int j = 0; j < num; j++)
			md[i][j] = abs(i / nd - j / nd) + abs(i%nd - j%nd);
	cout << astar(in) << endl;
	return 0;
