  vector<int> q(H);
  int k=0;

  for(i=0;i<W;i++) cin>>p[i];
  for(i=0;i<H;i++) cin>>q[i];

  V=(W+1)*(W+1);
  E=((W+1)*H)+(W*(H+1));

  k=0;
  for(j=0;j<=H;j++){
    for(i=0;i<=W;i++) {
      if(i<W){
        es[k].u=j*(W+1)+i;      
        es[k].v=j*(W+1)+i+1;
        es[k].cost=p[i];
        k++;
      }
      if(j<H){
        es[k].u=j*(W+1)+i;      
        es[k].v=j*(W+1)+i+W+1;
        es[k].cost=q[j];
        k++;
      }
    }
  }
  res=kruskal();
  cout<<res<<endl;
  return 0;
