string calc(int A, int B, int C, const vector<Match> &ms, int start = 0) {
  string result;
  result.reserve(ms.size());

  FOR(i, start, ms.size()) {
    switch (ms[i]) {
    case Match::AB:
      if (A > B || A > 1) {
        A--; B++; result += 'B';
      }
      else if (A < B) {
        A++; B--; result += 'A';
      }
      else if (A == 0) {
        return "";
      }
      else {
        if (i == ms.size() - 1) {
          result += 'A';
        }
        else {
          auto r = calc(A + 1, B - 1, C, ms, i + 1);
          if (r.size() > 0) {
            return result + 'A' + r;
          }

          r = calc(A - 1, B + 1, C, ms, i + 1);
          if (r.size() > 0) {
            return result + 'B' + r;
          }

          return "";
        }
      }
      break;
    case Match::AC:
      if (A > C || A > 1) {
        A--; C++; result += 'C';
      }
      else if (A < C) {
        A++; C--; result += 'A';
      }
      else if (A == 0) {
        return "";
      }
      else {
        if (i == ms.size() - 1) {
          result += 'A';
        }
        else {
          auto r = calc(A + 1, B, C - 1, ms, i + 1);
          if (r.size() > 0) {
            return result + 'A' + r;
          }

          r = calc(A - 1, B, C + 1, ms, i + 1);
          if (r.size() > 0) {
            return result + 'C' + r;
          }

          return "";
        }
      }
      break;
    case Match::BC:
      if (B > C || B > 1) {
        B--; C++; result += 'C';
      }
      else if (B < C) {
        B++; C--; result += 'B';
      }
      else if (B == 0) {
        return "";
      }
      else {
        if (i == ms.size() - 1) {
          result += 'B';
        }
        else {
          auto r = calc(A, B + 1, C - 1, ms, i + 1);
          if (r.size() > 0) {
            return result + 'B' + r;
          }

          r = calc(A, B - 1, C + 1, ms, i + 1);
          if (r.size() > 0) {
            return result + 'C' + r;
          }

          return "";
        }
      }
      break;
    }
  }

  return result;
}

