#define MOD 1000000007 
#define ADD(a,b) a=(a+b)%MOD 

class PMA{//Aho-Corasick
	int id;
	int match;
	PMA *failure;
	PMA *next[256];
public:
	PMA(int id=0):id(id),match(0),failure(0){
		memset(next,0,sizeof(next));
	}
	~PMA(){
		for(int i=0;i<256;i++){
			if(next[i]&&next[i]!=this)delete next[i];
		}
	}
	int getID()const{return id;}
	int matched()const{return match;}
	void build(const vector<string> &p){
		int num=0;
		for(int i=0;i<(int)p.size();i++){
			const string &s=p[i];
			PMA *t=this;
			for(int j=0;j<(int)s.size();j++){
				if(!t->next[s[j]])t->next[s[j]]=new PMA(++num);
				t=t->next[s[j]];
			}
			t->match++;
		}
		queue<PMA*> q;
		for(int i=0;i<256;i++){
			if(next[i]){
				q.push(next[i]);
				next[i]->failure=this;
			}else next[i]=this;
		}
		while(!q.empty()){
			PMA *t=q.front();q.pop();
			for(int i=0;i<256;i++){
				if(t->next[i]){
					q.push(t->next[i]);
					PMA *r=t->failure->step(i);
					t->next[i]->failure=r;
					t->next[i]->match += r->match;
				}
			}
		}
	}
	PMA *step(char c)const{
		const PMA *t=this;
		while(!t->next[c])t=t->failure;
		return t->next[c];
	}
	PMA *step(string s,int *n){
		*n=0;
		PMA *pma=this;
		for(int i=0;i<s.size();i++){
			pma=pma->step(s[i]);
			*n += pma->matched();
		}
		return pma;
	}
};


struct S{
	int pre,hit;
	PMA *pma;
	S(){}
	S(int a,int b,PMA *c):pre(a),hit(b),pma(c){}
	bool operator<(S s)const{
		if(pre!=s.pre)return pre<s.pre;
		if(hit!=s.hit)return hit<s.hit;
		return pma<s.pma;
	}
};

map<S,int> dp[521];

int main(){
	int n,m,k;
	while(cin>>n>>m>>k,n|m|k){
		for(int i=1;i<=m;i++)dp[i].clear();
		vector<int> to[250];
		string str[250];
		map<string,int> id;
		for(int i=0;i<n;i++){
			string a,b;
			int x,y;
			cin>>a>>b;
			if(id.find(a)==id.end()){
				id.insert(make_pair(a,x=id.size()));
				str[x]=a;
			}else x=id.find(a)->second;
			if(id.find(b)==id.end()){
				id.insert(make_pair(b,y=id.size()));
				str[y]=b;
			}else y=id.find(b)->second;
			to[x].push_back(y);
		}
		vector<string> seasonword(k);
		for(int i=0;i<k;i++){
			cin>>seasonword[i];
		}
		PMA pma;
		pma.build(seasonword);
		for(int i=0;i<id.size();i++){
			int n;
			PMA *p=pma.step(str[i],&n);
			if(n<=1)dp[str[i].size()].insert(make_pair(S(i,n,p),1));
		}
		for(int i=1;i<m;i++){
			for(map<S,int>::iterator it=dp[i].begin();it!=dp[i].end();++it){
				const S &s=it->first;
				for(int j=0;j<to[s.pre].size();j++){
					int dest=to[s.pre][j];
					int n;
					PMA *p=s.pma->step(str[dest],&n);
					if(s.hit+n<=1){
						S t(dest,s.hit+n,p);
						ADD(dp[i+str[dest].size()][t],it->second);
					}
				}
			}
		}
		int ans=0;
		for(map<S,int>::iterator it=dp[m].begin();it!=dp[m].end();++it){
			if(it->first.hit==1)ADD(ans,it->second);
		}
		cout<<ans<<endl;
	}
	return 0;
