void dfs(string &p, ll d) {
  if(d == 0) return;
  dfs(p, d - 1);
  REP(i, 0, T.length()) {
    p += T[i];
    dfs(p, d - 1);
  }
}

bool sub(string &p) {
  ll cnt = 0;
  REP(i, 0, S.length()) {
    if(S[i] == p[cnt]) cnt++;
  }
  return cnt == p.size();
}

