		que.push(vD(Data(next_cost, p_pos), now));

		int n_pos = pos+1;
		cnt = 1;
		if(n_pos == N)n_pos = 0;
		while(1){
			if(d[n_pos] != -1)break;
			cnt++;
			n_pos++;
			if(n_pos == N)n_pos = 0;
		}
		next_cost = cost+(cnt*100);
		//cout << "n_pos: " << n_pos << endl;
		//cout << "next_cost:" << next_cost << endl;
		backup.erase(remove(backup.begin(), backup.end(), d[n_pos]), backup.end());
		que.push(vD(Data(next_cost, n_pos), backup));
	}
	FIN(mini);

	return 0;	
}

