      formulae[1].push_back("b");
      formulae[1].push_back("c");
      formulae[1].push_back("d");
    }else{
      for(int i=0 ; i<formulae[n-1].size() ; i++){
        formulae[n].push_back("-" + formulae[n-1][i]);
      }
      if(n > 4){
        for(int k=1 ; k<n-3 ; k++){
          for(int i=0 ; i<formulae[k].size() ; i++){
            for(int j=0 ; j<formulae[n-3-k].size() ; j++){
              formulae[n].push_back("(" + formulae[k][i] + "^" + formulae[n-3-k][j]  + ")");
              formulae[n].push_back("(" + formulae[k][i] + "*" + formulae[n-3-k][j]  + ")");
            }
          }
        }
      }
    }
  }
}

unsigned int eval(string s, int ptr){
  if(s[ptr] == '0'){ return 0b0000000000000000; }
  else if(s[ptr] == '1'){ return 0b1111111111111111; }
  else if(s[ptr] == 'a'){ return 0b0000000011111111; }
  else if(s[ptr] == 'b'){ return 0b0000111100001111; }
  else if(s[ptr] == 'c'){ return 0b0011001100110011; }
  else if(s[ptr] == 'd'){ return 0b0101010101010101; }
  else if(s[ptr] == '-'){
    unsigned int e = eval(s,ptr+1);
    return ((~e)%(1<<16));
  } else {
    int op = ptr; int kakko = 0; bool done=false;
    while(!done){
      op++;
      if(kakko == 0){
        if((s[op] == '*' || s[op] == '^')){
          done=true;
        }
      }
      if (s[op]=='(') {kakko++;} else if(s[op]==')') {kakko--;}
    }
    unsigned int e1 = eval(s,ptr+1);
    unsigned int e2 = eval(s,op+1);
    if(s[op] == '^'){
      return e1^e2;
    }else{
      return e1&e2;
    }
  }
}

