std::vector<std::vector<string>> dp;
std::vector<std::vector<bool>> b;
string lcs(int n, int m)
{
	if(n<0||m<0){return ("");}
	if(b[n][m]){return dp[n][m];}
	b[n][m]=1;
	if(s[n]==t[m]){
		dp[n][m]=(lcs(n-1,m-1)+s[n]);
	}
	else
	{
		string s1=lcs(n-1,m);
		string s2=lcs(n,m-1);
		if(s1.length()<s2.length()){dp[n][m]=s2;}
		else{dp[n][m]=s1;}
	}
	return dp[n][m];
}
