using namespace std;

int N, P;
int X[100], Y[100];
int dp[100][1000000];

int rec(int idx, int p, int pre)
{
  if(idx == N) return (0);
  if(~dp[idx][p]) return (dp[idx][p]);
  int ret = rec(idx + 1, p, 0);
  int get = max(0, Y[idx] - max(0, X[idx] - pre));
  if(p - get >= 0) ret = max(ret, rec(idx + 1, p - get, get) + 1);
  return (dp[idx][p] = ret);
}

int main()
{
  memset(dp, -1, sizeof(dp));
  cin >> N >> P;
  for(int i = 0; i < N; i++) cin >> X[i] >> Y[i];
  cout << rec(0, P, 0) << endl;
