map< pair<int,vector<int> >, int > dp;
vector< vector<int> > e;
int dfs(int pos,vector<int> v){
	if( pos >= e.size() ) return 0;
	if( dp.count(make_pair(pos,v)) ) return dp[make_pair(pos,v)];
	vector<int> V = v;
	int ans = 0 , c = 0;
	while(1){
		ans = max( dfs(pos+1,v) + c , ans);

		c++;
		for(int i = 0 ; i < v.size() ; i++)
			v[i] -= e[pos][i];

		bool f = true;
		for(int i = 0 ; i < v.size() ; i++)
			if( v[i] < 0 ) f = false;
		if( !f ) break;
	}
	return dp[make_pair(pos,V)] = ans;
}


