int rec(int i, int j, int k){

   if(j>4){
      return 0;
   }else if(k==n){
      return 1;
   }else{
      if(memo[i][j][k]) return memo[i][j][k];
      int ret=0;
      for(int l=i; k+l*l<=n; l++){
         ret+=rec(l, j+1, k+l*l);
      }
      return memo[i][j][k]=ret;
   }
}

