//URDL
const static char dir[4] = {'U','R','D','L'};
const static string dir_str[4] = {"U","R","D","L"};
static char dir_idx[256];
class Nodes {
public:
  class Nodes* children[4];
  bool has_word;
  Nodes() : has_word(false){
    for(int i=0;i<4;i++){
      children[i] = NULL;
    }
  }
  ~Nodes(){
    for(int i=0;i<4;i++){
      children[i] = NULL;
    }
  }
};

class Trie {
private:
  Nodes* root;
  int char2idx(char a){
    return dir_idx[a];
  }
public:
  Trie(){
    root = new Nodes();
  }

  void insert(const string& str){
    Nodes* current = root;
    for(int i=0;i<str.size();i++){
      int c = char2idx(str[i]);
      if(current->children[c] == NULL){
	current->children[c] = new Nodes();
      }
      current = current->children[c];
    }
    current->has_word = true;
  }

  bool common_prefix_search(const string& str){
    Nodes* current = root;

    for(int i=0;i<str.size();i++){
      int c = char2idx(str[i]);
      if(current->children[c] != NULL){
	current = current->children[c];
      }
      else{
	return false;
      }

      if(current->has_word) return true;
    }

    return false;
  }

  bool exact_match(const string& str){
    Nodes* current = root;

    for(int i=0;i<str.size();i++){
      int c = char2idx(str[i]);
      if(current->children[c] != NULL){
	current = current->children[c];
      }
      else{
	return false;
      }

      if(i == str.size()-1
	 && current->has_word) return true;
    }

    return false;
  }

};

class State{
public:
  int cost;
  string route;
  int x;
  int y;
  State(int _x,int _y,int _c,string _r) : cost(_c), route(_r),x(_x),y(_y){}
  bool operator<(const State& s) const{
    return cost < s.cost;
  }
  bool operator>(const State& s) const{
    return cost > s.cost;
  }
};

int route2num(const string& str){
  int res = 0;
  for(int i=0;i<str.size();i++){
    res += dir_idx[str[i]];
    res *= 4;
  }
  return res/4;
}

int main(){
  dir_idx['U'] = 0;
  dir_idx['R'] = 1;
  dir_idx['D'] = 2;
  dir_idx['L'] = 3;

  int H,W;
  while(~scanf("%d %d",&H,&W)){
    if(H==0 && W==0) break;
    set<int> dp[50][50];
    Trie trie;
    char stage[50][50];

    int sx = 0;
    int sy = 0;
    int gx = 0;
    int gy = 0;
    for(int y=0;y<H;y++){
      char line[51];
      scanf("%s",line);
      for(int x=0;x<W;x++){
	stage[y][x] = line[x];
	if(line[x] == 'S'){
	  sx = x;
	  sy = y;
	}
	else if(line[x] == 'G'){
	  gx = x;
	  gy = y;
	}
      }
    }
    int total_prohibited_sequences;
    scanf("%d",&total_prohibited_sequences);

    for(int sequence_idx=0;
	sequence_idx < total_prohibited_sequences;
	sequence_idx++){
      string str;
      cin >> str;
      reverse(str.begin(),str.end());
      trie.insert(str);
    }

    priority_queue<State,vector<State>,greater<State> > que;
    que.push(State(sx,sy,0,""));
    int res = INF;
    while(!que.empty()){
      State s = que.top();
      string route = s.route;
      int cost = s.cost;
      int sx = s.x;
      int sy = s.y;

      que.pop();
      for(int i=0;i<4;i++){
	int dx = sx + tx[i];
	int dy = sy + ty[i];
	if(dx < 0 || dx >= W
	   || dy < 0 || dy >= H) continue;

	if(stage[dy][dx] == '#') continue;

	string next = dir_str[i] + route.substr(0,9);
	if(trie.common_prefix_search(next)){
	  // cout << next << endl;
	  continue;
	}

	int route_num = route2num(next);
	if(dp[dy][dx].count(route_num)) continue;
	dp[dy][dx].insert(route_num);

	if(stage[dy][dx] == 'G'){
	  res = cost + 1;
	  goto found;
	}

	que.push(State(dx,dy,cost+1,next));
      }
    }

  found:;
    printf("%d\n",res == INF ? -1 : res);
  }
