#define ALL(c) c.begin(),c.end()
#define RALL(c) c.rbegin(),c.rend()
#define REP(i,x,y) for(int i=(x);i<(y);++i)
#define MP(a,b) make_pair((a),(b))
#define F_ first
#define S_ second

typedef long long int lli;
typedef pair<int,int> Pi;

const int INF=100000000;
const long long int INF_=1000000000000000000;
const int dx[4]={1,0,-1,0},dy[4]={0,1,0,-1};

int memo[23][1<<23];
vector<Pi> houses;
int M,N,SY,SX;

inline bool HasVisited(const int y,const int x,const int state,const vector<vector<int> > &G){
	if(G[y][x]!=1) return false;
	REP(i,0,houses.size()) if(houses[i].F_==y&&houses[i].S_==x&&((state>>i)&1)==1) return true; 
	return false;
}

inline int GetHouseNum(const int y,const int x,const vector<vector<int> > &G){
	if(G[y][x]!=1) return -1;
	REP(i,0,houses.size()) if(houses[i].F_==y&&houses[i].S_==x) return i;
	return -1;
}

int DFS(const int Y,const int X,const vector<vector<int> > &G,int dir,int state){
	//cout << Y << ' ' << X << ' ' << dir << ' ' << state << endl;
	if(Y==SY&&X==SX&&(state&((1<<houses.size())-1))==((1<<houses.size())-1)){
		//cout << "a: " << Y << ' ' << X << ' ' << dir << ' ' << state << endl;
		return 1;
	}
	int house_num=GetHouseNum(Y,X,G);
	if(house_num!=-1&&memo[house_num][state]!=-1) return memo[house_num][state];
	if(G[Y][X]==1){
		memo[house_num][state]=0;
		REP(i,0,4){
			int ny=Y+dy[i],nx=X+dx[i];
			if(0<=ny&&ny<N&&0<=nx&&nx<M&&!HasVisited(ny,nx,state,G)){
				memo[house_num][state]+=DFS(ny,nx,G,i,state|(1<<house_num));
			}
		}
	}
	int ny=Y+dy[dir],nx=X+dx[dir];
	if(0<=ny&&ny<N&&0<=nx&&nx<M&&!HasVisited(ny,nx,state,G)){
		if(house_num!=-1) memo[house_num][state]+=DFS(ny,nx,G,dir,state);
		else return DFS(ny,nx,G,dir,state);
	}
	if(house_num!=-1) return memo[house_num][state];
	else return 0;
}

int Solve(){
	//fill((int*)memo,(int*)(memo+23*(1<<23)),-1);
	REP(i,0,23) REP(j,0,(1<<23)) memo[i][j]=-1;
	houses.clear();
	vector<vector<int> > G(N,vector<int>(M));
	REP(y,0,N) REP(x,0,M) cin >> G[y][x];
	REP(y,0,N) REP(x,0,M){
		if(G[y][x]==2){
			SY=y;
			SX=x;
		}else if(G[y][x]==1){
			houses.push_back(Pi(y,x));
		}
	}
	int result=0;
	REP(i,0,4) result+=DFS(SY,SX,G,i,0);
	return result;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	while(cin >> M >> N&&!(M==0&&N==0)){
		cout << Solve() << endl;
	}
	return 0;
