using namespace std;

#define NUM 2147483647


class RMQ{
public:
	RMQ(int height,int first_N){
		N = 1;
		while(N < first_N)N *= 2;
		table = new int*[height];
		for(int row = 0; row < height; row++){
			table[row] = new int[2*N-1];
			for(int col = 0; col < 2*N-1; col++){
				table[row][col] = NUM;
			}
		}
	}

	void update(int row,int loc,int value){
		loc += N-1;

		table[row][loc] = value;

		if(N == 1)return;

		int parent = (loc-1)/2;

		while(true){
			table[row][parent] = min(table[row][2*parent+1],table[row][2*parent+2]);

			if(parent == 0)break;
			else{
				parent = (parent-1)/2;
			}
		}
	}

	int getN(){
		return N;
	}

	int query(int row,int search_left,int search_right,int node_id,int node_left,int node_right){

		if(search_right < node_left || search_left > node_right)return NUM;

		if(search_left <= node_left && search_right >= node_right){
			return table[row][node_id];
		}

		int left_min = query(row,search_left,search_right,2*node_id+1,node_left,(node_left+node_right)/2);
		int right_min = query(row,search_left,search_right,2*node_id+2,(node_left+node_right)/2+1,node_right);

		return min(left_min,right_min);
	}
	int** table;
	int N;
};


