void func(){

	int** input = new int*[H];
	for(int row = 0; row < H; row++){
		input[row] = new int[W];
	}

	for(int row = 0; row < H; row++){
		for(int col = 0; col < W; col++)scanf("%d",&input[row][col]);
	}

	RMQ YOKO(H,W);
	for(int row = 0; row < H; row++){
		for(int col = 0; col < W; col++){
			YOKO.update(row,col,input[row][col]);
		}
	}

	RMQ TATE(W,H);
	for(int col = 0; col < W; col++){
		for(int row = 0; row < H; row++){
			TATE.update(col,row,input[row][col]);
		}
	}

	int row1,col1,row2,col2;
	int ans;

	for(int loop = 0; loop < Q; loop++){
		scanf("%d %d %d %d",&row1,&col1,&row2,&col2);

		ans = NUM;

		if(row2-row1 >= col2-col1){
			for(int col = col1; col <= col2; col++){
				ans = min(ans,TATE.query(col,row1,row2,0,0,TATE.getN()-1));
			}
		}else{
			for(int row = row1; row <= row2; row++){
				ans = min(ans,YOKO.query(row,col1,col2,0,0,YOKO.getN()-1));
			}
		}
		printf("%d\n",ans);
	}
}


