template<class T> struct mvec {
    vector<T> v;
    int n;
    //+-n
    mvec() : n(0), v(0) {}
    mvec(int n) : n(n), v(n * 2) {}
    mvec(int n, T val) : n(n), v(n * 2, val) {}
    auto& operator[](int i) {
        return v[i + n];
    }
    auto size() {
        return v.size();
    }
    void resize(int sn) {
        assert(n == 0);
        n=sn;
        v.resize(sn * 2);
    }
    auto begin() { return v.begin(); }
    auto rbegin() { return v.rbegin(); }
    auto end() { return v.end(); }
    auto rend() { return v.rend(); }
};

