void moveright(int height,int x){
  bool eraseflag=false;
  if (x == 0)x =1,eraseflag=true;;
  for(int j=2000-1;j>=x;j--){
    m[height+0][j]=m[height][j-1];
    if (height)m[height-1][j]=m[height-1][j-1];
  }

  if (eraseflag){
    m[height+0][0]=' ';
    if (height)m[height-1][0]=' ';
  }
}

void moveright_check(Tree *now,int depth){
  int xfrom=now->x;
  vector<Tree*> isvis;
  Tree *tmp,*prev;
  tmp=now->lsib;
  prev=now;
  while(tmp != NULL){
    if (tmp->l != NULL)break;
    if (tmp->isright){
      ;
    }else {
      xfrom = tmp->x;
    }  
    prev=tmp;
    tmp=tmp->lsib;
    if (tmp == NULL)break;
  }

  tmp = prev;
  while(tmp != NULL){
    isvis.pb(tmp);
    tmp=tmp->rsib;
  }

  if (isvis.size() == 0)isvis.pb(now);

  moveright(depth,xfrom);

  rep(i,isvis.size()){
    isvis[i]->x++;
  }
}

void solve(){
  for(int i=1000-1;i>=0;i--){
    rep(j,node[i].size()){
      Tree *now;
      now =node[i][j];
      //output();
      if (now->l == NULL){//leaf
	while(m[i+1][now->x] == '-'){
	  moveleft_check(now,i);
	  //output();
	}
      }else if(now->r == NULL){//unary
	if (now->l->x == now->x);//nomove
	else if (now->l->x < now->x){//child left move
	  while(now->l->x < now->x){
	    moveleft_check(now,i);
	  }
	}else if (now->l->x > now->x){//now right move
	  while(now->l->x   > now->x){
	    moveright_check(now,i);
	    //output();
	  }	  
	}
      }else {//binary
	int mypos = now->r->x - now->l->x +1;
	if (mypos%2 == 0)mypos=now->l->x + mypos/2-1;
	else mypos=now->l->x + mypos/2;


	if (mypos == now->x){//nomove
	  ;
	}else if (mypos < now->x){//child left move
	  while(mypos < now->x)moveleft_check(now,i);
	}else if (mypos > now->x){//now right move;
	  while(mypos   > now->x){
	    moveright_check(now,i);
	    //output();
	  }
	}
      }
    }
  }
}

