//parsing
Tree* parse(string &in,int &p,bool isright){
  Tree *now;
  now = new Tree();
  now->c = in[p];
  now->isright=isright;

  p++;
  if (p < in.size() && in[p] != '('){//leaf
    ;
  }else{//
    p++;
    now->l = parse(in,p,false);
    if (in[p] == ')'){
    }else if (in[p] == ','){
      p++;
      int tmp = 0;
      now->r=parse(in,p,true);
    }
    p++;
  }
  return now;
}

//parsing
void makepos(Tree *in,int depth){
  node[depth].push_back(in);
  int fpos=-2;
  rep(i,2000)if (m[depth][i] != ' ')fpos=i;
  in->x=fpos+2;
  in->y=depth;
  m[depth][fpos+2]=in->c;
  data[depth][fpos+2]=in;
  if (depth!=0)m[depth-1][fpos+2]='-';
  if (in->isright){
    m[depth-1][fpos+1]='-';
  }
  if (in->l != NULL)makepos(in->l,depth+2);
  if (in->r != NULL)makepos(in->r,depth+2);
}


//moveleft
int movepos[1000];
void dfs(Tree *now,vector<Tree*> & isvis,int depth){
  if (now->vis)return;
  now->vis=true;
  isvis.pb(now);
  movepos[depth]=min(now->x,movepos[depth]);
  if (now->l    != NULL)dfs(now->l,isvis,depth+2);
  if (now->r    != NULL)dfs(now->r,isvis,depth+2);
  if (now->rsib != NULL)dfs(now->rsib,isvis,depth);
}
//moveleft
void moveleft(int height,int x){
  for(int j=2000-1;j>x;j--){
    m[height+0][j]=m[height][j-1];
    if (height)m[height-1][j]=m[height-1][j-1];
  }
  m[height][x]  =' ';
  if (height)m[height-1][x]=' ';
}
//moveleft
void moveleft_check(Tree *now,int depth){
  rep(i,1000)movepos[i]=2000;
  vector<Tree*> isvis;
  dfs(now,isvis,depth);

  rep(i,1000){
    if (movepos[i] == 2000||i == depth)continue;
    moveleft(i,movepos[i]);
  }
  rep(i,isvis.size()){
    isvis[i]->vis=false;
    if (isvis[i]->y != depth)isvis[i]->x++;
  }
}


