int main() {
	int n, m, x; scanf("%d%d%d", &n, &m, &x);
	rep(i, n)scanf("%d", &h[i]);
	rep(i, m) {
		int a, b, t; scanf("%d%d%d", &a, &b, &t);
		a--; b--;
		if (t <= h[a])E[a].push_back(P(t, b));
		if (t <= h[b])E[b].push_back(P(t, a));
	}
	priority_queue<st>que;
	d[0][x] = 0;
	mp[P(0, x)] = 0;
	l[0]++;
	que.push({ 0,x,0 });
	ll Min = LLONG_MAX;
	while (!que.empty()) {
		st s = que.top(); que.pop();
		if (d[s.p][mp[P(s.p, s.h)]] != s.c)continue;
		if (s.p == n - 1)Min = min(Min, s.c + h[n - 1] - s.h);
		for (P u : E[s.p]) {
			int t = 0, k = s.h - u.first;
			if (k < 0)t = 0 - k, k = 0;
			if (k > h[u.second])t = k - h[u.second], k = h[u.second];
			if (mp.find(P(u.second, k)) == mp.end() || d[u.second][mp[P(u.second, k)]] > s.c + u.first + t) {
				if (mp.find(P(u.second, k)) == mp.end())mp[P(u.second, k)] = l[u.second]++;
				d[u.second][mp[P(u.second, k)]] = s.c + u.first + t;
				que.push({ u.second,k,d[u.second][mp[P(u.second,k)]] });
