string cnv(string t) {
    int f=0;
    rep(i,t.size()) {
        int pos=t[i]-'a';
        if(!((f>>pos)&1)) {
            f|=1<<pos;
            t[i]=prev(t[i]);
        }
    }

    return t;
}

