const int maxn = 6e3 + 100;
const ll inf = 2e18, mod = 1e9 + 7;

int n, m, k;
ll dp[maxn][maxn];

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> m >> k;

	if (!n || !m)
	{
		cout << 1 << endl;
		return 0;
	}

	dp[1][k - 1] += 1;
	dp[k][0] -= 1;
	for (int i = k; i <= n + m; i++)
	{
		for (int j = 1; j <= i; j++)
			dp[j][i - j] = (dp[j][i - j] + dp[j - 1][i - j + 1]) % mod;

		for (int j = 0; j <= i; j++)
			if (dp[j][i - j])
			{
				dp[j][i - j + k - 1] = (dp[j][i - j + k - 1] + dp[j][i - j]) % mod;
				if (i - j - 1 >= 0)
					dp[j + k - 1 + 1][i - j - 1] = (dp[j + k - 1 + 1][i - j - 1] - dp[j][i - j] + mod) % mod;
			}
	}

	ll ans = 0;
	for (int i = n; i >= 0 + (n > 0); i -= (k - 1))
		for (int j = m; j >= 0 + (m > 0); j -= (k - 1))
			ans = (ans + dp[i][j]) % mod;
	cout << ans << endl;
}

