void DeepCount(int i, int start, int k) {
  int st, ic = i;

  //  printf("%d %d %d %d :DeepC\n", i, start, k, lc);
  sl[d] = start;
  for(st = start ; st <= k ; st++) {
    if(lake[ic - 1][st + 1] == '\\') {
      sl[d + 1] = st + 1;
      d++; ic--;
