#include <algorithm>
#include <climits>
#include <cstdlib>
#include <iostream>
#include <vector>
using namespace std;

constexpr int BACKET_SIZE = 5000;

unsigned long long x;

void init(int x0) {
	x = x0;
}

inline long long generate() {
	long long res = static_cast<long long>(x);
	x ^= x << 13;
	x ^= x >> 7;
	x ^= x << 17;
	return res;
}

int get_idx(long long x) {
	static constexpr int HALF = BACKET_SIZE / 2;
	static constexpr double backet_hash = static_cast<double>((HALF - 1)) / LLONG_MAX;
	int res = HALF;
	if(x < 0) {
		x += LLONG_MAX;
		res = 0;
	}

	res += static_cast<int>(x * backet_hash);
	return res;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n, k, x0;
	cin >> n >> k >> x0;

	vector<int> cnt(BACKET_SIZE + 1, 0);

	init(x0);
	for(int i = 0; i < n; ++i) {
		const long long value = generate();
		++cnt[get_idx(value)];
	}

	int idx;
	for(int i = 0; i < BACKET_SIZE; ++i) {
		if(k <= cnt[i]) {
			idx = i;
			break;
		}
		else {
			k -= cnt[i];
		}
	}

	vector<long long> a;
	a.reserve(cnt[idx]);

	init(x0);
	for(int i = 0; i < n; ++i) {
		const long long value = generate();
		if(get_idx(value) == idx) {
			a.emplace_back(value);
		}
	}

	sort(a.begin(), a.end());
	cout << a[k - 1] << endl;

	return EXIT_SUCCESS;
