				int d[4]={2,1,-1,-2};
				tar=cur.first;
				int index=check/4;
				swap(tar[check],tar[check+d[index]]);
				next.first=tar;
				next.second=cur.second+1;
				q.push(next);
			}
		}
	}
	return ;
}

