#include <bits/stdc++.h>

using namespace std;

int N, Q;
vector< int > g[100000];
vector< int > query[100000];
int sz[100000];

int lca[100000];
bool buf[100000];

void sub(int idx)
{
  sz[idx] = query[idx].size();
  for(auto &to : g[idx]) {
    sub(to);
    sz[idx] += query[to].size();
  }
}

void dfs(int idx, bool keep)
{
  int heavy = -1;
  for(auto &to : g[idx]) {
    if(heavy == -1 || sz[to] > sz[heavy]) heavy = to;
  }
  for(auto &to : g[idx]) {
    dfs(to, false);
  }
  for(int &v : query[idx]) {
    buf[v] = true;
  }
  for(auto &to : g[idx]) {
    for(int &v : query[to]) {
      if(~lca[v]) continue;
      if(buf[v]++) lca[v] = idx;
      query[idx].push_back(v);
    }
  }
  if(!keep) for(auto &v : query[idx]) buf[v] = false;
}

int main()
{
  scanf("%d", &N);
  for(int i = 0; i < N; i++) {
    int K;
    scanf("%d", &K);
    while(K--) {
      int U;
      scanf("%d", &U);
      g[i].push_back(U);
    }
  }
  scanf("%d", &Q);

  memset(lca, -1, sizeof(lca));

  for(int i = 0; i < Q; i++) {
    int U, V;
    scanf("%d %d", &U, &V);
    if(U == V) {
      lca[i] = V;
    } else {
      query[U].push_back(i);
      query[V].push_back(i);
    }
  }

  sub(0);
  dfs(0, 0);
  for(int i = 0; i < Q; i++) {
    printf("%d\n", lca[i]);
  }
