int main(){
	int n;
	while(cin >> n && n){
		P h,d,p[20];
		cin >> h.real() >> h.imag();
		cin >> d.real() >> d.imag();
		for(int i = 0 ; i < n ; i++){
			cin >> p[i].real() >> p[i].imag();	
		}
		double dist[21][21];
		double fast[21][21];
		for(int i = 0 ; i <= n ; i++){
			for(int j = 0 ; j <= n ; j++){
				if( i == j ) continue;
				P a = (i==n?h:p[i]);
				P b = (j==n?h:p[j]);
				dist[i][j] = distanceSP(L(a,b),d);
				fast[i][j] = intersectSP(L(a,b),getPedal(L(a,b),d)) ? abs(a-getPedal(L(a,b),d)) : 0;
			}
		}

		for(int i = 0 ; i < (1<<n) ; i++)
			for(int j = 0 ; j < n ; j++)
				dp[i][j] = 1e10;
		for(int i = 0 ; i < n ; i++){
			double lim = dist[n][i];
			if( fast[n][i] > lim - EPS ) continue;
			double nextTime = abs(h-p[i]);
			if( abs(d-p[i]) + EPS < nextTime ) continue;
			dp[(1<<i)][i] = nextTime;
		}
		for(int i = 0 ; i < (1<<n) ; i++){
			for(int j = 0 ; j < n ; j++){
				if((i>>j&1) && dp[i][j] < 1e9){
					for(int k = 0 ; k < n ; k++){
						double lim = dist[j][k] - dp[i][j];
						if( fast[i][j] > lim - EPS ) continue;
						double nextTime = dp[i][j] + abs(p[j]-p[k]);
						if( abs(d-p[k]) - EPS < nextTime ) continue;
						dp[i|(1<<k)][j] = min(dp[i|(1<<k)][k],nextTime);
					}
				}
			}
		}
		int f = 0;
		for(int i = 0 ; i < n ; i++){
			f |= dp[(1<<n)-1][i] < 1e9;
			//cout << dp[(1<<n)-1][i] << endl;
		}
		cout << (f?"YES":"NO") << endl;

	}
