		yy = y % (2 * k) + 1;
		ct[id][xx][yy]++;
		ct[id][xx][yy + 2 * k]++;
		ct[id][xx + 2 * k][yy]++;
		ct[id][xx + 2 * k][yy + 2 * k]++;
	}

