int path[26][26];
bool isConnect;
int visited[1<<26];

void dfs(int src,ll remain,int* visited){
	if(remain == 0){
		isConnect = true;
		return;
	}

	if(visited[remain]) return;
	visited[remain] = 1;

	for(int i=0;i<26;i++){
		if(src==i) continue;
		if(remain & (1LL<<i)){		
			if(path[src][i]){
				ll next = remain & ~(1LL<<i);
				//bitset<26> bit((unsigned long long)next);
				//cout << bit << endl;
				dfs(i,next,visited);
			}
		}
	}
}

int main(){
	int n;

	while(~scanf("%d",&n)){
		if(n==0) break;
		memset(path,0,sizeof(path));
		memset(visited,0,sizeof(visited));
		set<int> src;
		for(int i=0;i<n;i++){
			string str;
			cin >> str;		
			path[*str.begin()-'a'][*(str.end()-1)-'a']++;

			src.insert(*(str.end()-1)-'a');
			src.insert(*str.begin()-'a');
		}

		ll remain=0;
		for(set<int>::iterator it = src.begin(); it != src.end(); it++){
			remain |= (1LL<<*it);
		}

		isConnect = false;
		dfs(*src.begin(),remain & ~(1LL<<*src.begin()),visited);

		if(!isConnect){
			printf("NG\n");
			continue;
		}
		bool isok=true;

		for(int i=0;i<26;i++){
			if(src.find(i) == src.end()) continue;
			int out=0;
			for(int j=0;j<26;j++){
				out += path[i][j];
			}

			int in=0;
			for(int j=0;j<26;j++){
				in += path[j][i];
			}

			if(out != in) isok = false;
		}

		printf("%s\n",isok ? "OK" : "NG");
	}
