int ay[]={0,0,1,-1,0};


S i2s(int x){
  return S(x>>12,x&((1<<12)-1));
}
int s2i(const S& s){
  //cout<<s.first<<" "<<s.second<<":"<<(s.first<<13)+s.second<<endl;
  return (s.first<<12)+s.second;
}
S p2s(const P& p){
  int y=0,x=0;
  for(int i=n-1;i>=0;i--){
    y=y*16+p.first[i];
    x=x*16+p.second[i];
  }
  return S(y,x);
}
P s2p(const S& s){
  vector<int> y,x;
  int a=s.first,b=s.second;
  for(int i=0;i<n;i++){
    y.push_back(a%16);
    x.push_back(b%16);
    a/=16;b/=16;
  }
  return P(y,x);
}

int p2i(const P& p){
  return s2i(p2s(p));
}
P i2p(int x){
  return s2p(i2s(x));
}


