template <class T>
class segment_tree_Max{
  private:
    vector<long long>seg;
    int seg_size = SEG_LEN * 2;
  public:
    segment_tree_Max(){
      seg.resize(seg_size);
      for(int i = 0; i < seg_size; i++)seg[i] = -INF;
    }
    void update(int ind,int n){
      ind += SEG_LEN;
      seg[ind] = n;
      while(true){
        ind /= 2;
        if(ind == 0)break;
        seg[ind] = max(seg[ind * 2],seg[ind * 2 + 1]);
      }
    }
    long long Max(int l,int r){
      l += SEG_LEN;
      r += SEG_LEN + 1;
      long long ans = -INF;
      while(l < r){
        if(l % 2 == 1){
          ans = max(seg[l],ans);
          l++;
        }
        if(l >= r)break;
        l /= 2;
        if(r % 2 == 1){
          ans = max(seg[r - 1],ans);
          r--;
        }
        r /= 2;
      }
      if(ans == -INF)return 0;
      return ans;
    }
}; 
