int cipher(string S)
{
	int Ans = 0;

	for (string::size_type i = 0; i < S.size(); i++)
	{
		for (int j = 0; j < 4; j++)
		{
			if (Alphabet[j] == S[i])
			{
				Ans += pow<int>(sizeof(Alphabet) / sizeof(const char), S.size() - i - 1) * j;
			}
		}
	}

	return Ans;
}

