#include<iostream>
using namespace std;


class baumkuchen{
public:
	baumkuchen();
	~baumkuchen();

	int N;	//切れ込みの数
	long long* A;	//一つ一つのバウムクーヘンの大きさ
	long long* memo;
	long long sum_baum;	//全てのバウムクーヘンの大きさの和
	double tripartition;

	void set_value();	//値のセット
	bool set;	//値のセットを行ったかどうかを判別する変数

	long long piece(int cut_1, int cut_2);	//3つに切り分けた後のあるひとつのバウムクーヘンの大きさを求める関数
	long long full_search();	//全探索で答えを求める関数
	long long extended_full_search();	//全探索改良版

};

baumkuchen::baumkuchen(){
	set = false;
}
baumkuchen::~baumkuchen(){
	if (set == true)delete[] A;
	if (set == true)delete[] memo;
}

void baumkuchen::set_value(){
	sum_baum = 0;
	cin >> N;
	A = new long long[4*N];
	memo = new long long[4* N * N]();

	for (int i = 0; i < N; i++){
		cin >> A[i];			//バウムクーヘンの大きさの入力
		A[N + i] = A[i];
		A[2 * N + i] = A[i];
		sum_baum += A[i];	//合計値の計算
	}

	for (int j = 0; j < 3 * N; j++){
//		printf("A[%d] = %d\n",j,A[j]);
	}
	double a = 3.0;
	tripartition = sum_baum / a;

	set = true;	//セットの判定
}

long long baumkuchen::piece(int cut_1, int cut_2){
	long long piece = 0;
	if (cut_1>cut_2){
		while (cut_1 != cut_2){
			piece += A[cut_1 - 1];
			cut_1--;
		}
		piece = sum_baum - piece;

	}
	else{
		while (cut_2 != cut_1){
			piece += A[cut_2 - 1];
			cut_2--;
		}
	}
	return piece;
}


long long baumkuchen::extended_full_search(){
	long long keep_value;
	long long keep_value2;
	long long set_value = 0;

	for (int i = 0; i <4*N; i++){
		int b;
		for (b = i+1; b < 3 * N; b++){
			memo[i * N + b] = memo[i * N + b - 1] + piece(b - 1, b);
			if (memo[i * N + b] >= tripartition)break;
		}
		if (tripartition - memo[i * N + b - 1] < memo[i * N + b] - tripartition){
			keep_value = memo[i * N + b - 1];
			b--;
		}
		else keep_value = memo[i * N + b];
		double half = (sum_baum - memo[i * N + b]) / 2.0;

		int c;
		for (c = b; c < 3 * N; c++){
			memo[i * N + c] = memo[i * N + c - 1] + piece(c - 1, c);
			if (memo[i * N + c] >= keep_value + half)break;
		}
		if (keep_value + half - memo[i * N + c - 1] < memo[i * N + c] - keep_value - half){
			keep_value2 = memo[i * N + c - 1];
			c--;
		}
		else keep_value2 = memo[i * N + c];

		if (keep_value > keep_value2 - keep_value) keep_value = keep_value2 - keep_value;
		if (keep_value > sum_baum - keep_value2) keep_value = sum_baum - keep_value2;
//		printf("i = %d\t", i);
//		printf("c = %d\n\n", c);

		if (set_value < keep_value)set_value = keep_value;
		if (c == N || c == 2*N || c== 3*N)break;

	}

	return set_value;
}

long long baumkuchen::full_search(){
	long long keep_value;
	long long set_value = 0;

	for (int i = 0; i < N; i++){
		for (int j = i + 1; j < N; j++){
			for (int k = j + 1; k < N; k++){
				if (piece(i, j) < piece(j, k)){
					if (piece(i, j) < piece(k, i)){
						keep_value = piece(i, j);
					}
					else{
						keep_value = piece(k, i);
					}
				}
				else{
					if (piece(j, k) < piece(k, i)){
						keep_value = piece(j, k);
					}
					else{
						keep_value = piece(k, i);
					}
				}
				if (set_value < keep_value){
					set_value = keep_value;
				}
			}
		}
	}
	return set_value;
}

int main(){
	baumkuchen *solve = new baumkuchen();
	solve->set_value();
	long long a = solve->extended_full_search();
	cout << a << endl;


	delete solve;
	return 0;
},memory_limit_exceeded,,p00523

