double solve(int n, int k){
  if(n == 0) return 0;
  double& d = dp[n][k];
  if(d != -1.0) return d;
  return d = two[k] * (1.0 + solve(n-1, min(k+1, 100))) + (1.0 - two[k]) * solve(n-1, 0);
}

