using namespace std;
const int surplus = 100000;
int n, m, s, N, ans, ss[50];
int b[50][3001];
bool judge[50][2001][3001];
int dp(int now, int num, int sum){
	if (sum > s)
		return 0;
	ss[now] = 0;
	FOR(i, num, m + 1){
		if (now == N){
			if (sum + i == s){
				return 1;
			}
			else if (i == m){
				return 0;
			}
		}
		else{
			if (!judge[now][i][sum]){
				b[now][sum] += dp(now + 1, i + 1, sum + i);
				judge[now][i][sum] = 1;
				b[now][sum] %= surplus;
			}
		}
	}
	return b[now][sum];
}
