const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

int NN;
class SegT{
private:
  LL dat[2 * (1 << 18) - 1];

public:
  SegT(){
	for(int i=0;i<2*NN-1;++i) dat[i] = 0;
  }

  // dat[idx] = a, 0-indexed
  void update(int idx, LL a){
	idx += NN - 1;
	dat[idx] = a;
	while(idx > 0){
	  idx = (idx - 1) / 2;
	  dat[idx] = max(dat[idx*2+1], dat[idx*2+2]);
	}
  }

  LL query(int a, int b, int k=0, int l=0, int r=NN){
	if(r <= a || b <= l) return 0;
	if(a <= l && r <= b) return dat[k];
	else{
	  LL vl = query(a, b, k*2+1, l, (l+r)/2);
	  LL vr = query(a, b, k*2+2, (l+r)/2, r);
	  return max(vl, vr);
	}
  }
};

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  LL N, M, K; cin >> N >> M >> K;
  vector<LL> xs(N);
  REP(i,N) cin >> xs[i];

  NN = 1;
  while(NN < N) NN <<= 1;
  vector<SegT> seg(310);

  REP(i,N){
	seg[1].update(i, xs[i]);
  }

  for(LL i=2;i<=K;++i){
	for(int j=i-1;j<N;++j){
	  LL nxt = seg[i-1].query(max(0,j-1-(int)M), j) + i * xs[j];
	  if(seg[i].query(j,j+1) < nxt){
		seg[i].update(j, nxt);
	  }
	}
  }
  //LL ans = 0;
  //REP(i,N) ans = max(ans, seg[K].query[i]);
  cout << seg[K].query(0,N) << endl;

  return 0;
}
