#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const function<int(int, int)> minQ = [](int l, int r) { return min(l, r); };

template <typename T>
class node {
public:
	T val, lazy;
	node<T> *l, *r;
	node() {}
	node(T val_, T lazy_, node<T>* l_ = nullptr, node<T>* r_ = nullptr) : val(val_), lazy(lazy_), l(l_), r(r_) {}
	void init(T val_, T lazy_, node<T>* l_ = nullptr, node<T>* r_ = nullptr) {
		val = val_;
		lazy = lazy_;
		l = l_;
		r = r_;
	}
};

template <typename T>
class SaikyoSegmentTree {
	using func_t = function<T(T, T)>;
	const ll n;
	const T id1, id2;
	func_t merge1, merge2;
	vector<node<T>*> root;
	vector<node<T>> pool;
	int it;
	ll size(ll n) {
		ll res = 1;
		while (res < n) res <<= 1;
		return res;
	}
	node<T> *new_node() {
		pool[it].init(id1, id2);
		return &pool[it++];
	}
	node<T> *fix(node<T> *t) {
		pool[it] = *t;
		return &pool[it++];
	}
	node<T> *push(node<T> *t, ll lb, ll ub) {
		t = fix(t);
		if (lb + 1 < ub) {
			if (t->l == nullptr) t->l = new_node();
			else t->l = fix(t->l);
			if (t->r == nullptr) t->r = new_node();
			else t->r = fix(t->r);
			t->l->lazy = merge2(t->l->lazy, t->lazy);
			t->r->lazy = merge2(t->r->lazy, t->lazy);
		}
		t->val = merge2(t->val, t->lazy);
		t->lazy = id2;
		return t;
	}
	node<T> *suc(ll l, ll r, node<T> *t, ll lb, ll ub, T val) {
		if (ub <= l || r <= lb) return t;
		if (t == nullptr) t = new_node();
		if (l <= lb && ub <= r) {
			t->lazy = merge2(t->lazy, val);
			return t;
		}
		t = push(t, lb, ub);
		int c = (lb + ub) / 2;
		t->l = suc(l, r, t->l, lb, c, val);
		t->r = suc(l, r, t->r, c, ub, val);
		t->val = merge1(t->l == nullptr ? id1 : merge2(t->l->val, t->l->lazy), t->r == nullptr ? id1 : merge2(t->r->val, t->r->lazy));
		return t;
	}
	node<T> *sub(ll l, ll r, node<T> *t, ll lb, ll ub, T& res) {
		if (t == nullptr || ub <= l || r <= lb) return t;
		t = push(t, lb, ub);
		if (l <= lb && ub <= r) {
			res = merge1(res, t->val);
			return t;
		}
		int c = (lb + ub) / 2;
		t->l = sub(l, r, t->l, lb, c, res);
		t->r = sub(l, r, t->r, c, ub, res);
		return t;
	}
public:
	SaikyoSegmentTree(ll n_, T id1_, T id2_, func_t merge1_, func_t merge2_, int PMAX = 1.6e7)
		: n(size(n_)), id1(id1_), id2(id2_), merge1(merge1_), merge2(merge2_), root(1, nullptr), pool(PMAX), it(0) {}
	void update(ll l, ll r, T val, int rt = -1) {
		if (rt == -1) rt = root.size() - 1;
		assert(0 <= rt && rt < (int)root.size());
		root.push_back(suc(l, r + 1, root[rt], 0, n, val));
	}
	T find(ll l, ll r, int rt = -1) {
		if (rt == -1) rt = root.size() - 1;
		assert(0 <= rt && rt < (int)root.size());
		T res = id1;
		root.push_back(sub(l, r + 1, root[rt], 0, n, res));
		return res;
	}
	int getversion() {
		return root.size() - 1;
	}
};

int main()
{
	cin.sync_with_stdio(false);
	int n, q, com, s, t, x;
	cin >> n >> q;
	SaikyoSegmentTree<int> lst(n, INT_MAX, -1, minQ, [](int l, int r) { return r != -1 ? r : l; });
	while (q--) {
		cin >> com;
		if (com) {
			cin >> s >> t;
			printf("%d\n", lst.find(s, t));
		}
		else {
			cin >> s >> t >> x;
			lst.update(s, t, x);
		}
	}
	return 0;
},memory_limit_exceeded,,p02350

