	int ret = 0;
	for (int i = 0; i < s.length(); i++) {
		ret *= 10;
		ret += s[i] - '0';
	}
	return ret;
}

int sum(int x) {
	int s = 0;
	while (x > 0) {
		s += x % 10;
		x /= 10;
	}
	return s;
}

int prod(int x) {
	int p = 1;
	while (x > 0) {
		p *= (x % 10) + 1;
		x /= 10;
	}
	return p;
}

