int dy[5]={-1,0,1,0,0};
int dx[5]={0,1,0,-1,0};

queue<dat> q;

bool check(int nay, int nax){
  if(nay<0||nax<0||h<=nay||w<=nax) return false;
  if(s[nay][nax]=='#') return false;
  return true;
}

bool check2(int Ay,int Ax,int By,int Bx,int ai,int bi){

  if(Ay==By){
    if(Ax+1==Bx&&ai==1&&bi==3) return false;
    if(Bx+1==Ax&&bi==1&&ai==3) return false;
  }

  if(Ax==Bx){
    if(Ay+1==By&&ai==2&&bi==0) return false;
    if(By+1==Ay&&bi==2&&ai==0) return false;
  }

  return true;
}

int bnf(){

  rep(i,N) rep(j,N)
    rep(k,N) rep(l,N)
    rep(m,N) rep(o,N)
    d[i][j][k][l][m][o]=(1e4);

  d[ay][ax][by][bx][cy][cx]=0;
  q.push(dat{0,ay,ax,by,bx,cy,cx});

  int res;

  while(!q.empty()){

    dat t=q.front(); q.pop();

    if(s[t.ay][t.ax]=='A'+s[ay][ax]-'a'&&
       s[t.by][t.bx]=='A'+s[by][bx]-'a'&&
       s[t.cy][t.cx]=='A'+s[cy][cx]-'a'){
      res=t.cost;
      break;
    }

    rep(i,5){
      int nay=dy[i]+t.ay, nax=dx[i]+t.ax;
      if(!check(nay,nax)) continue;

      rep(j,5){
	int nby=dy[j]+t.by, nbx=dx[j]+t.bx;
	if(!check(nby,nbx)) continue;

	rep(k,5){

	  int ncy=dy[k]+t.cy, ncx=dx[k]+t.cx;
      	  if(!check(ncy,ncx)) continue;

	  if(!check2(t.ay,t.ax,t.by,t.bx,i,j)) continue;
	  if(!check2(t.ay,t.ax,t.cy,t.cx,i,k)) continue;
	  if(!check2(t.by,t.bx,t.cy,t.cx,j,k)) continue;

	  if(nay==nby&&nax==nbx) continue;
	  if(nay==ncy&&nax==ncx) continue;
	  if(nby==ncy&&nbx==ncx) continue;

	  if(d[nay][nax][nby][nbx][ncy][ncx]>d[t.ay][t.ax][t.by][t.bx][t.cy][t.cx]+1){
	    d[nay][nax][nby][nbx][ncy][ncx]=d[t.ay][t.ax][t.by][t.bx][t.cy][t.cx]+1;
	    q.push(dat{d[nay][nax][nby][nbx][ncy][ncx],nay,nax,nby,nbx,ncy,ncx});
	  }

	}
      }
    }
  }

  return res;  
}

