#include <iostream>
#include <cstdio>
#include <set>
#include <queue>
using namespace std;

typedef pair<int,int> P;

int dx[] = {1,0,-1,0},dy[] = {0,1,0,-1};

int h,w,res = 0,pos = 0;
int field[1000][1000];
int cnt[1000][1000];
bool used[1000][1000];
queue<P> que;

void dfs(int x,int y){
	used[x][y] = true;
	que.push(P(x,y));
	for(int i = 0;i < 4;i++){
		int nx = x + dx[i],ny = y + dy[i];
		if(nx >= 0 && nx < h && ny >= 0 && ny < w && field[nx][ny] > field[x][y]){
			if(!used[nx][ny]) cnt[nx][ny]++;
			if(cnt[nx][ny] < 3) dfs(nx,ny);
		}
	}
}

int main(){
	cin >> h >> w;
	for(int i = 0;i < h;i++){
		for(int j = 0;j < w;j++) scanf("%d",&field[i][j]);
	}
	for(int i = 0;i < h;i++){
		for(int j = 0;j < w;j++){
			bool flag = true;
			for(int k = 0;k < 4;k++){
				int nx = i + dx[k],ny = j + dy[k];
				if(nx >= 0 && nx < h && ny >= 0 && ny < w && field[nx][ny] < field[i][j]) flag = false;
			}
			if(flag) dfs(i,j);
			while(!que.empty()){
				int x = que.front().first,y = que.front().second;que.pop();
				used[x][y] = false;
			}
		}
	}
	for(int i = 0;i < h;i++){
		for(int j = 0;j < w;j++) if(cnt[i][j] >= 2) res++;
	}
	cout << res << endl;
	return 0;
