            sw[i + 1] = sw[i] + w[i];
        }
        map<int, int> nh, nw;
        for (int i = 0; i < N + 1; ++i)
        {
            for (int j = 0; j < i; ++j)
            {
                nh[sh[i] - sh[j]]++;
            }
        }
        for (int i = 0; i < M + 1; ++i)
        {
            for (int j = 0; j < i; ++j)
            {
                nw[sw[i] - sw[j]]++;
            }
        }
        ll sum = 0;
        for (int i = 1; i <= 1500*1000; ++i)
        {
            sum += nh[i] * nw[i];
        }
        cout << sum << endl;
    }
    return 0;
}
