using mi = modint;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<mi> fact(1000, 0);
    fact[0] = 1;
    FOR(i, 1, 1000) fact[i] = fact[i - 1] * i;
    vector<mi> revfact(1000, 0);
    REP(i, 1000) revfact[i] = modint::pow(fact[i], mod - 2);
    vector<int> d(n);
    REP(i, n) cin >> d[i];
    vector<vector<vector<mi>>> dp(n + 1, vector<vector<mi>>(n + 1, vector<mi>(2 * n + 1, 0)));
    // dp[i][j][k] =　頂点 i まで見て j 個閉路に加えて閉路外部への次数が k
    dp[0][0][0] = 1;
    REP(i, n) REP(j, n + 1) REP(k, 2 * n + 1) {
        // 閉路に加える
        if(j && d[i] >= 2 && k - (d[i] - 2) >= 0) {
            dp[i + 1][j][k] += dp[i][j - 1][k - (d[i] - 2)] * revfact[d[i] - 2];
        }
        // 閉路に加えない
        dp[i + 1][j][k] += dp[i][j][k] * revfact[d[i] - 1];
    }
    mi ans = 0;
    FOR(i, 3, n) FOR(j, 1, 2 * n + 1) {
        ans += dp[n][i][j] * fact[n - i - 1] * modint::pow(fact[j - 1], mod - 2) * fact[i - 1] * modint::pow(2, mod - 2) * fact[j];
    }
    ans += dp[n][n][0] * fact[n - 1] * modint::pow(2, mod - 2);
    cout << ans << endl;
    return 0;
}
