struct info {
	int ns;
	int time;
	int count;
	vector<bool> clear;
	bool operator<(const info& right) const {
		return (time <= right.time);
	}
};

int main(void) {
	int N;
	while (cin >> N, N) {
		vector< vector<int> > t(N,vector<int>(N+1));
		priority_queue<info> pq;
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < N+1; ++j) {
				cin >> t[i][j];
				if (j == 0) {
					vector<bool> temp(N,false);
					temp[i] = true;
					pq.push({i,-t[i][j],1,temp});
				}
			}
		}

		int res = -(1 << 28);
		map<vector<bool>,int> memo;
		while (!pq.empty()) {
			info now = pq.top();
			pq.pop();
			if (now.time > res) { 
				if (now.count == N) {
					res = now.time;
				}
				else {
					if (memo[now.clear] == 0 || now.time > memo[now.clear]) {
						memo[now.clear] = now.time;
						for (int i = 0; i < N; ++i) {
							if (!now.clear[i]) {
								vector<bool> temp = now.clear;
								temp[i] = true;
								if (memo[temp] == 0 || now.time-t[i][0] > memo[temp]) {
									pq.push({i,now.time-t[i][0],now.count+1,temp});
								}
								for (int j = 0; j < N; ++j) {
									if (now.clear[j]) {
										if (memo[temp] == 0 || now.time-t[i][j+1] > memo[temp]) {
											pq.push({i,now.time-t[i][j+1],now.count+1,temp});
										}
									}
								}
							}
						}
					}
				}
			}
		}

		cout << -res << endl;
	}

	return 0;
}

