string lcs(int x,int y){

	if(x>=n||y>=m)
		return "";

	if(dp[x][y]!="-1")
		return dp[x][y];
	if(a[x]==b[y])
		return dp[x][y]=a.substr(x,1)+lcs(x+1,y+1);
	string u=lcs(x+1,y),v=lcs(x,y+1);
	if(u.size()>v.size())
		return dp[x][y]=u;
	else
		return dp[x][y]=v;
}

