    int ans = 0;
    for(int i = 0; i < W; i++)
    {
        for(int j = 0; j < H; j++)
        {
            if(field[i][j] == 0)
            {
                ans++;
                queue<pii> que;
                que.push(make_pair(i,j));
                while(que.size())
                {
                    int tx = que.front().first,ty = que.front().second;que.pop();
                    field[tx][ty] = 1;
                    for(int i = 0; i < 4; i++)
                    {
                        if(tx + dx[i] >= W || tx + dx[i] < 0 || ty + dy[i] >= H || ty + dy[i] < 0)continue;
                        if(field[tx + dx[i]][ty + dy[i]] == 0)
                        {
                            que.push(make_pair(tx + dx[i],ty + dy[i]));
                        }
                    }
                }
            }
        }
    }
    //printf("%d %d\n",W,H);
    return ans;
}

int compress(int *m1,int *m2,int w)
{
    vector<int> vec;
    for(int i = 0; i < N; i++)
    {
        for(int j = -1; j < 2; j++)
        {
            if(m1[i] + j >= 0 && m1[i] + j < w)vec.push_back(m1[i] + j);
            if(m2[i] + j >= 0 && m2[i] + j < w)vec.push_back(m2[i] + j);
        }
    }
    sort(vec.begin(),vec.end());
    vec.erase(unique(vec.begin(),vec.end()),vec.end());
    //for(int i = 0; i < vec.size(); i++)printf("%d ",vec[i]);printf("\n");
    for(int i = 0; i < N; i++)
    {
        m1[i] = find(vec.begin(),vec.end(),m1[i]) - vec.begin();
        m2[i] = find(vec.begin(),vec.end(),m2[i]) - vec.begin();
    }
    int res = vec.size();
    vec.clear();
    return res;
