  die d=redice[id];
  rC(d.p);
  mp[id]=dieId(d);
  return mp[id];
}
int RD(int id){
  static map<int,int> mp;
  if(mp.count(id)>0)return mp[id];
  die d=redice[id];
  rD(d.p);
  mp[id]=dieId(d);
  return mp[id];
}
int RE(int id){
  static map<int,int> mp;
  if(mp.count(id)>0)return mp[id];
  die d=redice[id];
  rE(d.p);
  mp[id]=dieId(d);
  return mp[id];
}
int RF(int id){
  static map<int,int> mp;
  if(mp.count(id)>0)return mp[id];
  die d=redice[id];
  rF(d.p);
  mp[id]=dieId(d);
  return mp[id];
}

ull getHash(state s){
  ull res=0, B=5575777;
  int x=s.first.first+150;
  int y=s.first.second+150;
  res=x*B+y;
  die d=redice[s.second];
  for(int i=0;i<20;i++)res=res*B+d.p[i];
  return res;
}

void Push(state s,int cost){
  ull key=getHash(s);
  if(d.count(key)>0)return;
  d[key]=cost+1;
  Q.push(s);
}

int main(){
  die v;
  for(int i=0;i<20;i++)v.p[i]=i;
  state si=state( P(0,0) , dieId(v) );
  d[ getHash(si) ]=0;
  Q.push(si);

  while(!Q.empty()){
    state s=Q.front();Q.pop();
    int cost=d[ getHash(s) ];

    int x=s.first.first;
