    if( ans.count( PP(P(x,y), n ) ) == 0)
      ans[ PP(P(x,y),n) ]=cost;

    if(cost==100)continue;


    if(f==0){
      state A=s;
      A.first=P(x,y+1);
      A.second=RA(s.second);
      Push(A,cost);

      state B=s;
      B.first=P(x+1,y);
      B.second=RB(s.second);
      Push(B,cost);

      state C=s;
      C.first=P(x-1,y);
      C.second=RC(s.second);
      Push(C,cost);


    }else{
      state D=s;
      D.first=P(x,y-1);
      rD(d.p);
      D.second=RD(s.second);
      Push(D,cost);

      state E=s;
      E.first=P(x-1,y);
      rE(d.p);
      E.second=RE(s.second);
      Push(E,cost);

      state F=s;
      F.first=P(x+1,y);
      rF(d.p);
      F.second=RF(s.second);
      Push(F,cost);
    }
  }

  //cout<<dice.size()<<endl;

  while(1){
    int x,y,n;
    cin>>x>>y>>n;
    if(x==0&&y==0&&n==0)break;
    cout<< ans[ PP( P(x,y)  , n ) ] <<endl;
  }
  return 0;
