{
    //cout<<s<<endl;
    if(s.length()==0)return 1;
    if(s[0]=='d')
    {

        if(cha(s,"dreamer"))
        {
            if(dfs(s.substr(7)))return 1;
        }
       if(cha(s,"dream"))
        {
            if(dfs(s.substr(5)))return 1;
        }

    }
    if(s[0]=='e')
    {
        if(cha(s,"eraser"))
        {
            if(dfs(s.substr(6)))return 1;
        }
        else if(cha(s,"erase"))
        {
            if(dfs(s.substr(5)))return 1;
        }
    }
    return 0;
}
