struct Puzzle {
	char x[4][4];
};
queue<pair<Puzzle, int>>Q; Puzzle Z;
char manh(Puzzle y) {
	char sum = 0; pair<char, char> p[16];
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			p[y.x[i][j]] = make_pair(i, j);
		}
	}
	for (int i = 0; i < 16; i++) {
		int X = (i - 1) / 4, Y = (i - 1) % 4;
		if (i == 0) { X = 3; Y = 3; }
		sum += abs(X - p[i].first) + abs(Y - p[i].second);
	}
	return sum;
}
