			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++)s.x[j][k] = r.x[j][k];
			}
			int px = z.first + dx[i], py = z.second + dy[i];
			if (py < 0 || py > 3)continue;
			if (px < 0 || px > 3)continue;
			swap(s.x[z.first][z.second], s.x[px][py]);
			if (manh(r) >= manh(s) - 2) {
				int OK = 1;
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
