#include<iostream>
#include<queue>
#include<cstdio>
using namespace std;

#define MAX_NODE_ID 31
#define MAX_TICKET_NUM 10
#define MAX_TICKET 256
class Node{
public:
	int id;
	double cost;
	int ticketStatus;
	Node(int i,double c,int t){
		id=i;
		cost=c;
		ticketStatus=t;
	}

	bool operator < (const Node &o) const{
		return cost > o.cost;
	}
};


int table[MAX_NODE_ID][MAX_NODE_ID];
bool visited[MAX_NODE_ID][MAX_TICKET];
int t[10];
typedef priority_queue<Node> PQ;
int main(){
	//input
	for(int n,m,p,a,b; cin>>n>>m>>p>>a>>b && n ;){
		int j,k;
		//ツ渉可甘コツ可サ
		for(j=0;j<MAX_NODE_ID;j++)for(k=0;k<MAX_NODE_ID;k++)table[j][k]=0;
		for(j=0;j<MAX_NODE_ID;j++)for(k=0;k<MAX_TICKET;k++)visited[j][k]=false;
		for(j=0; j<n && cin>>t[j] ;j++);

		int x,y,z;
		for(j=0; j<p && cin>>x>>y>>z ;j++){
			table[x][y]=z;
			table[y][x]=z;
		}
		PQ pq;

		pq.push(Node(a,0,0.0));
		while(!pq.empty()){
			int curId=pq.top().id;
			double curCost=pq.top().cost;
			int curTicket=pq.top().ticketStatus;
			if(curId==b||curTicket==(1<<n)-1)break;
			pq.pop();
			if(visited[curId][curTicket-1]){
				continue;
			}
			for(j=1;j<=m;j++){
				if(j==curId)continue;
				if(table[curId][j]==0)continue;
				for(k=1;k<=n;k++){
					int _ticket=1<<k;
					if(!(curTicket & _ticket)){
						double cost=curCost+(double)table[curId][j]/(double)t[k-1];
						int ticketStatus=curTicket+_ticket;
						Node next1(j,cost,ticketStatus);
						pq.push(next1);
