int dijkstra(int s,int N){
    fill(d,d+N,INF);
    fill(used,used+N,false);
    d[s] = 0;
    while(true){
        int v = -1;
        for(int u = 0; u < N; u++){
            if(!used[u] && (v == -1 || d[u] < d[v]))v = u;
        }
        if(v == -1)break;
        used[v] = true;
        for(int u = 0; u < N; u++){
            if(d[u] > d[v] + D[v][u]){
                d[u] = d[v] + D[v][u];
            }
        }
    }
    return d[N-1];
}
