long long calc(long long n1,long long m1){
	long long ans=INF;
	if(dp[n1][m1]>-1)return dp[n1][m1];
	if(m1>0){
		ans=calc(n1,0)+K+m1*(maxD[n1][m1]-minD[n1][m1]);
	}else{
		for(long long i=1;i<M+1&&i<n1+1;++i){
			ans=min(ans,calc(n1-i,i));
		}
	}
	dp[n1][m1]=ans;
	return ans;
}
