bool ok(int t1, int t2)
{
	int res = 0;
	for (int i = 1; i <= n; ++i)
	{
		if ((array[i] & t1) == t2)
			res++;
	}
	return (res <= 1);
}
int dp(int haveAsked, int answer)
{
	int t1 = haveAsked, t2 = answer;
	if (f[t1][t2] != -1)
		return f[t1][t2];

	f[t1][t2] = inf;

	if (ok(t1, t2))
		return f[t1][t2] = 0;

	for (int i = 0; i < m; ++i)
	{
		if (!(t1 & (1 << i)))
			f[t1][t2] = min(f[t1][t2], max(dp(t1 | (1 << i), t2), dp(t1 | (1 << i), t2 ^ (1 << i))) + 1);
	}

	return f[t1][t2];
}


int main()
{
	while (scanf("%d %d", &m, &n) != EOF && n && m)
	{
		memset(f, -1, sizeof f);

		for (int i = 1; i <= n; ++i)
		{
			int res = 0;
			string s;
			cin >> s;
			for (int j = 0; j < m; ++j)
			{
				if (s[j] == '1')
					res |= (1 << j);
			}

			array[i] = res;
		}

