vector<mint> Bellmemo(MAXStir2, Mint);
void Stir2init(){
  Stir2memo[0][0] = 1;
  rep(i, MAXStir2-1)rep(j, i+1)Stir2memo[i+1][j+1] = Stir2memo[i][j] + Stir2memo[i][j+1] * (j+1);
  rep(i, MAXStir2){
    Bellmemo[i] = 0;
    rep(j,i+1) Bellmemo[i] += Stir2memo[i][j];
  }
}
mint Stir2(ll i, ll j){//区別できるi個をjグループに分ける場合の数
  if(i < 0 || j < 0 || i < j) return 0;
  return Stir2memo[i][j];
}
mint Bell(ll x){//区別できるx個をグループ分けする方法全ての場合の数
  if(x < 0) return 0;
  return Bellmemo[x];
}
mint kai_mod(ll K){
  if(K < 0) return 0;
  if(K == 0) return 1;
  return kai_mod(K-1) * K;
}

//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}
ll N, M;
vector<pair<pair<ll, ll>, ll>> rlx;
mint dp[310][310][310];
void solve(){
  dp[0][0][0] = 1;
  ll s = 0;
  rep(i, N){//最大がi
    if(i == 0){
      dp[1][0][0] = 1;
      dp[0][1][0] = 1;
      dp[0][0][1] = 1;
    }
    //Rを塗る
    rep(r, i)rep(g, i){
      dp[i+1][g][i] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[i+1][i][b] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i+1][g][b] += dp[i][g][b];
    }
    //Gを塗る
    rep(r, i)rep(g, i){
      dp[r][i+1][i] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[r][i+1][b] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i][i+1][b] += dp[i][g][b];
    }
    //Bを塗る
    rep(r, i)rep(g, i){
      dp[r][g][i+1] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[r][i][i+1] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i][g][i+1] += dp[i][g][b];
    }


    //r == i+1 の時
    while(rlx[s].f.f == i+1){
      ll left = rlx[s].f.s, right = rlx[s].f.f, x = rlx[s].s;
      if(x == 1){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left <= g || left <= b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left <= r || left <= b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left <= r || left <= g) dp[r][g][right] = 0;
        }
      }
      if(x == 2){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left <= g && left <= b) dp[right][g][b] = 0;
          if(left > g && left > b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left <= r && left <= b) dp[r][right][b] = 0;
          if(left > r && left > b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left <= r && left <= g) dp[r][g][right] = 0;
          if(left > r && left > g) dp[r][g][right] = 0;
        }
      }
      if(x == 3){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left > g || left > b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left > r || left > b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left > r || left > g) dp[r][g][right] = 0;
        }
      }
      s++;
    }
  }
  mint ans = 0;
  //最後にRを塗った
  rep(g, N)rep(b, N){
    ans += dp[N][g][b];
  }
  //最後にGを塗った
  rep(r, N)rep(b, N){
    ans += dp[r][N][b];
  }
  //最後にBを塗った
  rep(r, N)rep(g, N){
    ans += dp[r][g][N];
  }

  ans.get();
}
int main(){
  cin >> N >> M;
  rlx.resize(M);
  rep(i, M){
    cin >> rlx[i].f.s >> rlx[i].f.f >> rlx[i].s;
  }
  sort(rlx.begin(), rlx.end());
  solve();
}
