  bool operator < (const State &p)const {
    for(int i=0;i<50;i++){
      if(u[i]==p.u[i]&&v[i]==p.v[i])continue;
      return (u[i]<p.u[i])||(u[i]==p.u[i]&&v[i]<p.v[i]);
    }
    return false;
  }
};

