    if(s.u[i]==false&&x==-1)x=i;
    if(0<s.v[i]&&s.v[i]<t[i])cnt++;
  }

  if(cnt==0&&x==-1)return true;
  if(cnt>n-x)return false;
  /*
  for(int i=0;i<n;i++)cout<<s.u[i]<<' ';cout<<endl;
  for(int i=0;i<n;i++)cout<<s.v[i]<<' ';cout<<endl;
