			if(bi[i]) dp[i + 1][bit] = dp[i][bit] + dp[i][bit ^ (1 << i)];
			else dp[i + 1][bit] = dp[i][bit];
		}
		ans += prob * dp[n][bit];
	}
	return ans;
}

