void solve() {
    mat s(1, vec(N));
    map<vec,int> m;
    for (auto& i : s[0]) cin >> i;

    ll start = 0;
    ll end = T;
    for (int t = 1; t <= T; t++) {
        s.push_back(vec(N));
        if (m.find(s[t-1]) != m.end()) {
            start = m[s[t-1]];
            end = t - 2;
