            ll b = (B * s[t-1][i]) % M;
            ll c = (C * (i + 1 < N ? s[t-1][i + 1] : 0)) % M;
            s[t][i] = (a + b + c) % M;
        }
    }

    if (end != T) {
        T = (T - start) % (end - start + 1) + start;
    }

    for (auto i : s[T]) cout << i << " ";
    cout << endl;
}

