    double A = cross(P[a1] - Q[b], P[a] - Q[b]);
    double B = cross(Q[b1] - P[a], Q[b] - P[a]);
    point r;
    if (intersect_1pt(P[a1], P[a], Q[b1], Q[b], r)) {
      if (in == Unknown) aa = ba = 0;
      R.push_back( r );
      in = B > 0 ? Pin : A > 0 ? Qin : in;
    }
    if (C == 0 && B == 0 && A == 0) {
      if (in == Pin) { b = (b + 1) % m; ++ba; }
      else           { a = (a + 1) % m; ++aa; }
    } else if (C >= 0) {
      if (A > 0) { if (in == Pin) R.push_back(P[a]); a = (a+1)%n; ++aa; }
      else       { if (in == Qin) R.push_back(Q[b]); b = (b+1)%m; ++ba; }
    } else {
      if (B > 0) { if (in == Qin) R.push_back(Q[b]); b = (b+1)%m; ++ba; }
      else       { if (in == Pin) R.push_back(P[a]); a = (a+1)%n; ++aa; }
    }
  } while ( (aa < n || ba < m) && aa < 2*n && ba < 2*m );
  if (in == Unknown) {
    if (convex_contains(Q, P[0])) return P;
    if (convex_contains(P, Q[0])) return Q;
  }
  return R;
}


vector<L> ls;

P projection(const L &l, const P &p) {double t = dot(p-l[0], l[0]-l[1]) / norm(l[0]-l[1]);return l[0] + t*(l[0]-l[1]);}


double PI = acos(-1);


vector<point> convex_hull(vector<point> ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  vector<point> ch(2*n);
  for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
    while (k >= 2 && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;
  for (int i = n-2, t = k+1; i >= 0; ch[k++] = ps[i--]) // upper-hull
    while (k >= t && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;
  ch.resize(k-1);
  return ch;
}

G gen(L l,double d){
	P f = l[1]-l[0];
	f /= abs(f);
	P r = f * exp(P(0,PI/2.));
	P a = l[0] + r * d;
	P b = l[0] - r * d;

	double len = 100000;
	G g;
	g.push_back(a+f*len);
	g.push_back(a-f*len);
	g.push_back(b+f*len);
	g.push_back(b-f*len);

	return convex_hull(g);
}
double ok(double d,int f=0){
	vector<P> co;

	for(int i = 0 ; i < ls.size() ; i++){
		auto v = gen(ls[i],d);
		if(i==0){
			co = v;
		}else{
			if( area2(co) < EPS ) co.clear();
			if( co.size() ) co = convex_intersect(co,v);
		}
	}
	if(f){
		printf("%.10lf %.10lf\n",co[0].real(),co[0].imag());
	}
	return area2(co);
}

