	if((state&((1<<(houses.size()-1))-1))==((1<<(houses.size()-1))-1)&&house_num==0) return 1;
	//if(memo[MP(house_num,state)]!=0) return memo[MP(house_num,state)]-1;
	int result1=0,result2=0;
	REP(i,0,G[house_num].size()){
