	//cout << result1 << ' ' << result2 << endl;
	if(house_num<=17&&memo[MP(house_num,state)]==0) memo[MP(house_num,state)]=result2+1;
	return (house_num<=17?memo[MP(house_num,state)]:result2+1)+result1-1;
}

