pii ls, lg, rs, rg;

int dx[]={0, 0, 1, -1}, dy[]={1, -1, 0, 0};

bool border(pii p){

	return 0<=p.first&&p.first<w&&0<=p.second&&p.second<h;
}

string solve(vector<string> left, vector<string> right){


	stat start = make_pair(ls, rs), goal = make_pair(lg, rg);

	set<stat> vis;
	queue<stat> qu;

	vis.insert(start);
	qu.push(start);

	while(!qu.empty()){

		pii lnx, rnx;
		stat now = qu.front();
		qu.pop();

		for(int i=0; i<4; ++i){

				lnx = make_pair(now.first.first + dx[i], 
								now.first.second + dy[i]);

				rnx = make_pair(now.second.first - dx[i], 
								now.second.second + dy[i]);

				if(!border(lnx)||left[lnx.second][lnx.first]=='#')
					lnx = now.first;

				if(!border(rnx)||right[rnx.second][rnx.first]=='#')
					rnx = now.second;

				stat nx = make_pair(lnx, rnx);

				if(nx == goal)
					return "Yes";

				if(vis.count(nx)==0){

					vis.insert(nx);
					qu.push(nx);
				}
		}
	}

	return "No";
}

