using namespace std;

static const int di[] = {-1,0,1,0};
static const int dj[] = {0,1,0,-1};

typedef pair<int,int> pi;

#define MAX 16
#define HSMAX 32
#define fr first
#define sc second 
#define UP 0
#define RIGHT 1
#define DOWN 2
#define LEFT 3
#define MAXDIR 4

int houseId[MAX][MAX];

struct Node{
  bool isCharch;
  bool isHouse;
  vector<pi> link[MAXDIR];
  bool exist[MAXDIR];
  bool cexist[MAXDIR];
  Node():isCharch(false),isHouse(false){
    for(int i=0;i<MAXDIR;++i){
      cexist[i]=exist[i]=false;
    }
  }
};

struct state{
  int ni,nj;
  int cnt;
  int vis;
  state(int si, int sj):ni(si),nj(sj){cnt=0;
    vis=0;
    vis|=(1<<houseId[si][sj]);
  }
};

inline bool isinside(int H, int W, int i, int j){
  return 0<=i&&i<H&&0<=j&&j<W;
}

void bfs(Node M[][MAX], int bi, int bj, int nhouse, int &ans){
  queue<state> qs;
  qs.push( state( bi, bj ) );

  while(!qs.empty()){
    bool bCont=false;
    state st_now = qs.front();
    int ni = st_now.ni;
    int nj = st_now.nj;
    qs.pop();

    if( st_now.cnt == nhouse ){
      for(int k = 0; k < MAXDIR; ++k){
	if( M[ni][nj].cexist[k] ){
	  ++ans;
	  bCont=true;
	}
      }
    }
    if(bCont)continue;

    for(int k = 0; k < MAXDIR; ++k){
      if( M[ni][nj].exist[k] ){
	for(int v = 0; v < M[ni][nj].link[k].size(); ++v){
	  pi next = M[ni][nj].link[k][v];
	  if( !( st_now.vis&(1<<houseId[next.fr][next.sc]) ) ){
	    state st_next(st_now);
	    st_next.ni = next.fr;
	    st_next.nj = next.sc;
	    st_next.vis|=(1<<houseId[next.fr][next.sc]);
	    st_next.cnt++;
	    qs.push( st_next );
	    break;
	  }else{
	    //break;
	  }
	}
      }
    }
  }
  return ;
}

int main()
{
  while(true){
    int ans = 0;
    int W,H;cin>>W>>H;
    if(W==0&&W==H)break;
    bool vis[MAX][MAX]={{false,},};
    int iM[MAX][MAX];
    Node M[MAX][MAX];
    pi charch;
    int nhouse=0;

    for(int i = 0; i < H; ++i){
      for(int j = 0; j < W; ++j){
	cin >> iM[i][j];
	if(iM[i][j]==1){
	  ++nhouse;
	  houseId[i][j]=nhouse;
	  M[i][j].isHouse=true;
	}else if(iM[i][j]==2){
	  M[i][j].isCharch=true;
	  charch = pi(i,j);
	}
      }
    }

    for(int i = 0; i < H; ++i){
      for(int j = 0; j < W; ++j){
	for(int k = UP; k < MAXDIR; ++k){
	  int ti=i+di[k];
	  int tj=j+dj[k];
	  while(isinside(H,W,ti,tj)){
	    if(M[ti][tj].isHouse){
	      M[i][j].link[k].push_back( pi(ti,tj) );
	      M[i][j].exist[k]=true;
	    }else if(M[ti][tj].isCharch){
	      M[i][j].cexist[k]=true;
	    }
	    ti+=di[k];tj+=dj[k];
	  }
	}
      }
    }

    vis[charch.fr][charch.sc]=true;
    bfs(M,charch.fr,charch.sc,nhouse,ans);
    cout << ans << endl;

  }
  return 0;

