using namespace std;

struct Traversal {
	vector<int> positions;
	int count;

	Traversal(vector<int> initial_position) : positions(initial_position), count(0) {}
	Traversal(vector<int> initial_position, int c) : positions(initial_position), count(c) {}

	friend bool operator <(Traversal const& lhs, Traversal const& rhs) {
		if (lhs.count != rhs.count) {
			return lhs.count < rhs.count;
		}
		assert(lhs.positions.size() == rhs.positions.size());
		for (int i = 0; i < lhs.positions.size(); i++) {
			if (lhs.positions[i] != rhs.positions[i]) {
				return lhs.positions[i] < rhs.positions[i];
			}
		}
		return false;
	}
};

int main() {
	int n, m, k;
	cin >> n >> m >> k;
	vector<bool> is_bright_room = vector<bool>(n + 1, true);
	vector<int> dark_rooms;
	for (int i = 0; i < m; i++) {
		int x;
		cin >> x;
		is_bright_room[x] = false;
		dark_rooms.push_back(x);
	}

	vector<vector<int>> edges = vector<vector<int>>(n + 1, vector<int>(k, 0));
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j < k; j++) {
			cin >> edges[i][j];
		}
	}

	queue<Traversal> queue;
	queue.emplace(dark_rooms);

	set<Traversal> visited;

	while (true) {
		auto state = queue.front();
		queue.pop();
		if (visited.find(state) != visited.end()) {
			continue;
		}
		visited.insert(state);
		bool end = true;
		for (auto p : state.positions) {
			end = end && is_bright_room[p];
		}
		if (end) {
			cout << state.count << endl;
			return 0;
		}

		for (int j = 0; j < k; j++) {
			vector<int> new_positions;
			for (auto p : state.positions) {
				if (!is_bright_room[p]) {
					new_positions.push_back(edges[p][j]);
				}
				else {
					new_positions.push_back(p);
				}
			}
			queue.emplace(new_positions, state.count + 1);
		}
	}
