int res(int N, set<int> a, vector<int> &fib, vector<bool> isok){
  if(fib.at(N) != -1) return fib.at(N);

  if(N == 1) return fib.at(N) = 1;
  if(N == 0) return fib.at(N) = 1;

  return fib.at(N) = (res(N-1, a, fib, isok) % MOD + res(N-2, a, fib, isok) %MOD) % MOD;
}

