#include <cstdio>
#include <cstring>
#include <algorithm>
#include <cmath>
using namespace std;
int n,m;
double dp[1<<16][17][17];
double dp2[1<<16][17];
double data[17][17];

double memo(int bit,int v,int c){
	if(v==n)return 1.0;
	if(bit==0)return 0.0;
	if(dp[bit][v][c]>=0.0)return dp[bit][v][c];
	double lost=0.0;
	int lbit=bit-(1<<c);
	if(dp2[lbit][v]>=0.0)lost=dp2[lbit][v];
	else{
		for(int i=0;i<m;i++){
			if(lbit>>i & 1){
				lost=max(lost,memo(lbit,v,i));
			}
		}
		dp2[lbit][v]=lost;
	}
	double res=memo(bit,v+1,c)*data[c][v]+lost*(1.0-data[c][v]);
	return dp[bit][v][c]=res;
}

int main(void){
	scanf("%d %d",&m,&n);
	for(int i=0;i<m;i++){
		for(int j=0;j<n;j++){
			scanf("%lf",&data[i][j]);
		}
	}
	memset(dp,-1,sizeof(dp));
	memset(dp2,-1,sizeof(dp2));
	double res=0.0;
	for(int i=0;i<m;i++){
		res=max(res,memo((1<<m)-1,0,i));
	}
	printf("%.10f\n",res);
	return 0;
