#include<iostream>
#include<algorithm>
using namespace std;

typedef struct trie Trie;

struct trie{
  bool flag;
  Trie* next[26];

  trie(){
    flag=false;
    fill(next,next+26,(trie*)0);
  }
};

bool str_find(string str,Trie* ptrie){
  Trie* tmp=ptrie;
  bool flag=true;
  int c;

  for(int i=0;i<(int)str.length();i++){
    c=str[i]-'A';

    if(!tmp->next[c]){
      flag=false;
      break;
    }
    tmp=tmp->next[c];
  }
  if(!tmp->flag)
    flag=false;

  return flag;
}

void str_insert(string str,Trie* ptrie){
  Trie* tmp=ptrie;
  int c;

  for(int i=0;i<(int)str.length();i++){
    c=str[i]-'A';

    if(!tmp->next[c])
      tmp->next[c]=new Trie;
    tmp=tmp->next[c];
  }
  tmp->flag=true;
}

int main(int argc,char* argv[]){
  int n;
  string str;
  Trie root;

  cin>>n;
  for(int i=0;i<n;i++){
    cin>>str;

    if(str[0]=='i'){
      cin>>str;
      str_insert(str,&root);
    }
    else{
      cin>>str;
      if(str_find(str,&root))
	cout<<"yes"<<endl;
      else
	cout<<"no"<<endl;
    }
  }
  return 0;
