using namespace std;

typedef long long LL;
typedef set <LL> SET;

const int size = 100;

int B[size];
bool U[size];
bool F[size];
int n;
SET V[size];

bool dist( int a, int v, int s );
bool solve();

bool dist( int a, int v, int s ) {
    LL S = 0, T = 1;
    for ( int i = 0; i < s; ++ i ) {
        if ( F[i] ) S += T;
        T = ( T << 1 );
    }
    if ( V[s].find( S ) != V[s].end() ) return false;
    V[s].insert( S );
    for ( int i = a-1; i >= 0; -- i ) {
        if ( U[i] ) continue;
        if ( B[i] == v ) {
            F[i] = true;
            U[i] = true;
            bool flag = true;
            for ( int j = 0; j < n; ++ j ) {
                if ( ! U[j] ) flag = false;
            }
            if ( flag ) {
                return true;
            } else {
                if ( solve() ) {
                    return true;
                } else {
                    F[i] = false;
                    U[i] = false;
                }
            }
        }
        if ( B[i] < v ) {
            F[i] = true;
            U[i] = true;
            if ( dist( i, v - B[i], s ) ) {
                return true;
            } else {
                F[i] = false;
                U[i] = false;
            }
        }
    }
    return false;
}

bool solve() {
    for ( int i = n - 1; i >= 0; -- i ) {
        if ( ! F[i] ) continue;
        F[i] = false;
        LL S = 0, T = 1;
        for ( int j = 0; j < i; ++ j ) {
            if ( F[j] ) S += T;
            T <<= 1;
        }
        if ( V[i].find( S ) != V[i].end() ) {
            F[i] = true;
            continue;
        }
        if ( dist( i, B[i], i ) ) return true;
        F[i] = true;
    }
    return false;
}

int main() {
    while ( cin >> n && n ) {
        for ( int i = 0; i < n; ++ i ) {
            U[i] = false;
            F[i] = false;
            V[i].clear();
        }

        for ( int i = 0; i < n; ++ i ) cin >> B[i];
        sort( B, B + n );
        U[n-1] = F[n-1] = true;
        if ( n == 1 ) {
            cout << "YES" << endl;
        } else {
            cout << ( solve() ? "YES" : "NO" ) << endl;
        }
    }
    return 0;
