#define mod 1000000007
#define FOR(x,to) for(int x=0;x<(to);x++)
#define FORR(x,arr) for(auto& x:arr)
#define ALL(a) (a.begin()),(a.end())
#define ZERO(a) memset(a,0,sizeof(a))
#define MINUS(a) memset(a,0xff,sizeof(a))
#define long long long
inline int rei(){int x;cin>>x;return x;}
inline long rel(){long x;cin>>x;return x;}
inline string res(){string x;cin>>x;return x;}
//------------------------------------------------------- 
namespace Fact{
	long f[20000001];
	long rf[20000001];
	long pow(long N,long K){
		if(K == 0){
			return 1;
		}
		else if(K % 2 == 0){
			long t = pow(N,K/2);
			return t*t%mod;
		}
		else{
			return N*pow(N,K-1)%mod;
		}
	}
	void Fact(int N){
		for(int i=0;i<N+1;i++){
			if(i == 0){
				f[i] = 1;
			}
			else{
				f[i] = (f[i-1]*i)%mod;
			}
		}
		for(int i=N;i>=0;i--){
			if(i == N){
				rf[i] = pow(f[N],mod-2);
			}
			else{
				rf[i] = rf[i+1]*(i+1)%mod;
			}
		}
	}
	long GetFact(int N){
		return f[N];
	}
	long GetPerm(int N,int R){
		return f[N] * rf[N-R] % mod;
	}
	long GetConv(int N,int R){
		return ((f[N]*rf[R])%mod*rf[N-R])%mod;
	}
	long GetRev(int N){
		if(N == 0){
			return 1;
		}
		else{
			return rf[N] * f[N-1] % mod;
		}
	}
}
long DP0[20000001];
long DP1[20000001];
long DP2[20000001];
long DP3[20000001];
long DP4[20000001];
long DP5[20000001];
void Calc(){
	int H = rei();
	int W = rei();
	int K = rei();
	DP0[0] = DP3[0] = DP5[0] = 1;
	Fact::Fact(H+W);
	for(int i=0;i<K;i++){
		int res = H+W-i;
		DP0[i+1] = DP0[i] * (res-2) % mod;
		DP1[i+1] = (DP0[i] * 2 + DP1[i] * (res-1)) % mod;
		DP2[i+1] = (DP1[i] + DP2[i] * res) % mod;
		DP3[i+1] = DP3[i] * (res-1) % mod;
		DP4[i+1] = (DP3[i] + DP4[i] * res) % mod;
		DP5[i+1] = DP5[i] * res % mod;
	}
	long ans = 0;
	for(int i=1;i<=K;i++){
		ans += (DP2[i]*H%mod*W%mod+DP4[i]*(H+W)%mod+DP5[i]) % mod * Fact::GetPerm(H+W-i,K-i);
		ans %= mod;
	}
	cout << ans << endl;
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
