#include<bits/stdc++.h>
using namespace std;

int N,M,S,T;
int st, ed;
int R[101][60*24+1];
int tr[1001][60*24+1];


int gettime(int t1,int t2){
  return t1*60 + t2;
}
int ghs(int a,int b){
  return a * 1100 + b;
}
void rhs(int &a,int &b,int x){
  a = x/1100, b = x%1100;
}


const int INF = (1<<29);
typedef pair<int,int> P;
int dp[60*24+1][1101];
vector<int> pr[60*24+1][1101];
void update(int nt,int ni,int t,int i,int x){
  dp[nt][ni] = max( dp[nt][ni], x );
  pr[nt][ni].emplace_back( ghs(t,i) );
}
int solve(){
  fill( dp[0], dp[ed+1], -INF );
  dp[st][S+M] = 0;
  for(int t=0;t<=ed;t++)
    for(int i=0;i<N+M;i++)
      pr[t][i].clear();

  for(int t=st;t<=ed;t++){
    for(int i=0;i<N+M;i++){
      int id = i%(N+M);
      if( dp[t][id] == -INF ) continue;

      if( id < M ) { // train
        if( R[id][t] != -1 )
          update( t, R[id][t]+M, t, id, 0 );
        update( t+1, id, t, id, dp[t][id]+1);
      } else { //station
        int x = id-M;
        if( tr[x][t] != -1 )
          update( t+1, tr[x][t], t, id, 1 );
        update( t+1, id, t, id, dp[t][id] );
      }
    }
  }

  int res = -INF;
  queue<int> q; q.emplace( ghs(ed,M+T) );
  while( !q.empty() ) {
    int p = q.front(); q.pop();
    int a,b; rhs(a,b,p);
    res = max( res, dp[a][b] );
    for( int to : pr[a][b] )
      q.emplace( to );
    pr[a][b].clear();
  }
  return res;
}


int main(){
  while( ~scanf("%d%d",&N,&M) && (N|M) ) {
    int t1,t2,t3,t4;
    scanf("%d %d:%d %d %d:%d",&S, &t1, &t2, &T, &t3, &t4);
    --S; --T;
    st = gettime( t1, t2 ), ed = gettime( t3, t4 );

    fill( tr[0], tr[N+1], -1 );
    for(int i=0;i<M;i++){
      int n; scanf("%d",&n);
      memset( R[i], -1, sizeof(R[i]) );
      for(int j=0;j<n;j++){
        int k;
        scanf("%d %d:%d",&k,&t1,&t2);
        --k;
        R[i][gettime(t1,t2)] = k;
        tr[k][gettime(t1,t2)] = i;
        //cout << i << " "<< gettime(t1,t2) << " " << R[i][gettime(t1,t2)] << endl;
        // cout << k << " "<< gettime(t1,t2) << " " << tr[k][gettime(t1,t2)] << endl;
      }            
    }

    int res = solve();
    if( res < 0 ) printf("impossible\n");
    else printf("%d\n",res);
  }
