#include <iostream>
#include <cstdio>
#include <vector>
#include <queue>
using namespace std;

typedef pair<int, int> P;
typedef pair<int, P> T;

const int MAX_N = 10005;
const int MAX_D = 1005;
const int INF = 2*MAX_N*MAX_D;
int N,M;  //N=都市の数,M=当初の道路の数
int dist[MAX_N][MAX_N];
int cost[MAX_N][MAX_N];
int addi[MAX_N];
int d[MAX_N];
//現在地を下4桁、一個前の点を上4桁
int twoToOne(int v, int pv) {
    int ret = v-1;
    ret += (pv-1) * 10000;
    return ret;
}

P oneToTwo(int n) {
    int pv = n / 10000;
    int v = n % 10000;
    pv++;
    v++;
    return P(v,pv);
}

int dijkstra(int s) {  //1~各地点間の最短の道路建設に必要な追加費用
    fill(d, d+N+1, INF);
    fill(addi, addi+N+1, INF);
    d[s] = 0;
    addi[s] = 0;
    priority_queue<P, vector<P>, greater<P> > pque;

    pque.push(P(0,0));  //距離、現在地、前の点
    while (!pque.empty()) {
        P p = pque.top(); pque.pop();
        P city = oneToTwo(p.second);
        int v = city.first;
        int pv = city.second;
        if (d[v] < p.first) continue;
        //最短経路が複数あった場合は、追加のコストが小さい方を選ぶ
        if (cost[pv][v] < addi[v]) {
            addi[v] = cost[pv][v];
        }
        for (int i = 1; i <= N; i++) {
            if (i != v && dist[v][i] != INF) {
                if (d[i] >= p.first + dist[v][i]) {  //最短距離の更新
                    d[i] = p.first + dist[v][i];
                    int nextCity = twoToOne(i, v);
                    pque.push(P(d[i],nextCity));
                }
            }
        }
    }
    int total = 0;
    for (int i = 2; i <= N; i++) {
        total += addi[i];
    }
    return total;
}

int main(int argc, const char * argv[])
{
    while (true) {
        scanf("%d %d", &N, &M);
        if (N == 0 && M == 0) break;
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= N; j++) {
                if (i == j) dist[i][j] = cost[i][j] = 0;
                else dist[i][j] = cost[i][j] = INF;
            }
        }
        for (int i = 0; i < M; i++) {
            int u,v,d,c;
            scanf("%d %d %d %d", &u, &v, &d, &c);
            dist[u][v] = dist[v][u] = d;
            cost[u][v] = cost[v][u] = c;
        }
        int ret = 0;
        ret = dijkstra(1);
        printf("%d\n",ret);

    }
    return 0;
},memory_limit_exceeded,,p01366

