int dy[4] = {0, 1, 0, -1};
int W, H, C;
int grid[10][10];
vector<int> G[100];
unordered_set<ull> used;
bool dfs(int u, ull s){
  if(s == (1ULL << C) - 1) return true;
  if(used.count(s)) return false;

  // のこりの頂点が連結かどうか
  queue<int> que;
  ull used_s = s;
  que.push(u);
  while(!que.empty()){
    int u = que.front(); que.pop();
    REP(i, G[u].size()) {
      int v = G[u][i];
      if(used_s & (1ULL << v)) continue;
      used_s |= 1ULL << v;
      que.push(v);
    }
  }
  if(used_s != (1ULL << C) - 1){
    used.insert(s);
    return false;
  }

  REP(i, G[u].size()){
    int v = G[u][i];
    if(s & (1ULL << v)) continue;
    if(dfs(v, s | (1ULL << v))) return true;
  }
  return false;
}

