    REP(i, C) G[i].clear();
    REP(y, H) REP(x, W) if(grid[y][x] == 0){
      REP(r, 4) {
        int nx = x + dx[r];
        int ny = y + dy[r];
        if(valid(nx, ny, W, H) && grid[ny][nx] == 0) G[id[y][x]].push_back(id[ny][nx]);
      }
    }

    if(C > 0 && (C == 1 || dfs(0, 0))){
      cout << "Yes" << endl;
    }else{
      cout << "No" << endl;
    }
  }
  return 0;
