using namespace std; 

const int N = 1e4 + 100, OO = 724249387, T = 6e3 + 100, M = 1e9 + 7, P = 6151, SQ = 280, lg = 30;
typedef pair <int, int> pii;
int fac[N], inv[N], dp[T][T], is[T][T], it[T][T];

int pw(int x, int y) {
	if(y == 0)
		return 1;
	int cnt = pw(x, y / 2);
	cnt = (cnt * cnt) % M;
	cnt = (cnt * (y % 2 == 1 ? x : 1)) % M;
	return cnt;
}

void prepro() {
	fac[0] = 1;
	for(int i = 1; i <= N - lg; i++) 
		fac[i] = (fac[i - 1] * i) % M;
	inv[N - lg] = pw(fac[N - lg], M - 2);
	for(int i = N - lg - 1; i > -1; i--) 
		inv[i] = (inv[i + 1] * (i + 1)) % M;
}

int c(int x, int y) {
	return ((fac[x] * inv[y] % M) * inv[x - y]) % M;
}

int32_t main() {
	use_fast;
	prepro();
	int n, cnt = 0;
	cin >> n;
	for(int i =0; i < n; i++) {
		int x, y;
		cin >> x >> y;
		cnt -= c(2 * (x + y), 2 * x);
		cnt = (cnt % M + M) % M;
		is[-x + 2500][-y + 2500]++;
		it[x + 2500][y + 2500]++;
	}
	for(int i = 1; i <= 4500; i++) {
		for(int j = 1; j <= 4500; j++) {
			dp[i][j] = (dp[i - 1][j] + dp[i][j - 1] + is[i][j]) % M;		
			cnt = (cnt + dp[i][j] * it[i][j]) % M;
		}
	}
	cnt = (cnt * pw(2, M - 2)) % M;
	cout << cnt << endl;
	return 0;
}
