int not_prime[31625];

vector<ll> factorize(ll n){
    vector<ll> ret;
    int i = 2, rt = sqrt(n);
    while(n != 1 && i <= rt){
        if(not_prime[i]){
            i++;
            continue;
        }
        int j = i;
        while(j <= rt){
            not_prime[j] = 1;
            j += i;
        }

        while(n % i == 0){
            n /= i;
            ret.push_back(i);
        }

        i++;
    }
    if(n != 1){
        ret.push_back(n);
    }
    return ret;
}

int main(){
    std::ios::sync_with_stdio(0); cin.tie(0);
    ll n;
    cin >> n;
    set<ll> fact;
    for(ll x: factorize(n)){
        fact.insert(x);
    }
    vector<ll> ans(n+1, 0);
    for(ll x: fact){
        ll i = x;
        while(i <= n){
            ans[i] = 1;
            i += x;
        }
    }
    cout << n - accumulate(all(ans), 0) << endl;

}

