	while(scanf("%d%d%d%d",&n,&m,&s,&g),n)
	{
		for(i=0;i<n;++i)for(j=0;j<n;++j)a[i][j]="|";
		while(m--)
		{
			scanf("%d%d%s",&x,&y,str);
			a[x][y]=min(a[x][y],string(str));
		}
		for(k=0;k<n;++k)for(i=0;i<n;++i)
		{
			if(a[i][k]=="|")continue;
			for(j=0;j<n;++j)
			{
				if(a[k][j]=="|"||a[i][j]<=a[i][k])continue;
				a[i][j]=min(a[i][j],a[i][k]+a[k][j]);
			}
		}
		for(i=0;i<n;++i)
		{
			b=a[s][i];
			if(b>=a[s][g])continue;
			b+=a[i][i];
			if(b>=a[s][g])continue;
			b+=a[i][g];
			if(b<a[s][g]){a[s][g]="NO";break;}
		}
		if(a[s][g]=="|")a[s][g]="NO";
		printf("%s\n",a[s][g].c_str());
	}
	return 0;
