using namespace std;

const int INF = 1 << 29;
typedef pair<int, int> P;
typedef long long LL;

int n, t, s;
vector<int> a, b;
int dp[3000][3001][2];

int dfs(int ni, int time, bool visited)
{
	if(ni == n) return 0;

	if(dp[ni][time][visited]) return dp[ni][time][visited];

	int ret = 0;
	if(time + b[ni] <= t && (time + b[ni] <= s || visited))
		ret = dfs(ni+1, time+b[ni], visited) + a[ni];
	ret = max(ret, dfs(ni+1, time, visited));
	if(!visited && time <= s)
		ret = max(ret, dfs(ni, s, true));
	return dp[ni][time][visited] = ret;
}

int main(void)
{
	while(cin >> n >> t >> s && n)
	{
		memset(dp, 0, sizeof(dp));
		a.resize(n); b.resize(n);
		for (int i = 0; i < n; i++)
		{
			cin >> a[i] >> b[i];
		}
		cout << dfs(0,0, false) << endl;
	}
	return 0;
