void build_s(vvi& g, vvi& s, l n, l m) {
  F(i, 0, n) {
    if (g[i][0]) s[i][1] = 1;
    F(j, 1, m) {
      s[i][j + 1] = s[i][j];
      if (g[i][j] and not g[i][j - 1]) s[i][j + 1]++;
    }
  }
}

void build_e(vvi& g, vvi& e, l n, l m) {
  F(i, 0, n) {
    F(j, 1, m + 1) {
      e[i][j] = e[i][j - 1];
      if (not g[i][j] and g[i][j - 1]) e[i][j]++;
    }
  }
}

void solve(istream& cin, ostream& cout) {
  l n, m, q; cin >> n >> m >> q;
  vvi grid(n, vi(m));
  F(i, 0, n) {
    string s; cin >> s;
    F(j, 0, m) grid[i][j] = s[j] - '0';
  }
  vvi sc(n, vi(m + 1)), ec(n, vi(m + 1)); // TODO: multidimentional macro?
  {
    vvi connected(n, vi(m));
    F(i, 1, n) {
      F(j, 0, m) connected[i][j] = grid[i][j] & grid[i - 1][j];
    }
    build_s(connected, sc, n, m);
    build_e(connected, ec, n, m);
  }
  l d = 0;
  while ((1 << (d + 1)) <= n) d++;
  if (d) d--;
  vvvi ss(d + 1, vvi(n, vi(m + 1)));
  vvvi ee(d + 1, vvi(n, vi(m + 1)));
  build_s(grid, ss[0], n, m);
  build_e(grid, ee[0], n, m);
  F(k, 0, d) {
    l t = 1 << k;
    F(i, 0, n - 2 * t + 1) {
      F(j, 0, m + 1) {
        ss[k + 1][i][j] = ss[k][i][j] + ss[k][i + t][j] - sc[i + t][j];
        ee[k + 1][i][j] = ee[k][i][j] + ee[k][i + t][j] - ec[i + t][j];
      }
    }
  }
  F(w, 0, q) {
    l r1, c1, r2, c2; cin >> r1 >> c1 >> r2 >> c2; r1--; c1--;
    l k = d;
    l t = r2 - r1;
    l z = 0;
    while (t) {
      while ((1 << k) > t) k--;
      z += ss[k][r1][c2] - ee[k][r1][c1];
      t -= (1 << k);
      r1 += (1 << k);
      if (t) {
        z -= sc[r1][c2];
        z += ec[r1][c1];
      }
    }
    cout << z << endl;
  }
}

