#include <stdio.h>
#include <algorithm>

using namespace std;

const long long mod = 998244353;
const long long del = 93000;
long long n;
long long a[1200];
long long dp[310][191000][4];
long long ans;
long long ksm ( long long f , long long x ) {
	long long s = 1;
	while ( x ) {
		if ( x % 2 ) s = s * f % mod;
		f = f * f % mod; x = x / 2;
	}
	return s % mod;
}
void work () {
	long long i , j , k , s;
	scanf ( "%lld" , &n );
	for ( i = 1 ; i <= n ; i++ ) {
		scanf ( "%lld" , &a[i] );
	}
	s = 0;
	dp[0][del][0] = 1;
	for ( i = 0 ; i < n ; i++ ) {
		s += a[i+1];
		for ( j = -s ; j <= s ; j++ ) {
			for ( k = 0 ; k <= 3 ; k++ ) {
				dp[i+1][del+j+a[i+1]][k] = (dp[i+1][del+j+a[i+1]][k] + dp[i][del+j][k]) % mod;
				dp[i+1][del+j-a[i+1]][k|1] = (dp[i+1][del+j-a[i+1]][k|1] + dp[i][del+j][k]) % mod;
				dp[i+1][del+j-a[i+1]][k|2] = (dp[i+1][del+j-a[i+1]][k|2] + dp[i][del+j][k]) % mod;
			}
		}
	}
	ans = ksm ( 3 , n );
	ans = (ans - ksm ( 2 , n ) * 3 + ksm ( 1 , n ) * 3 ) % mod;
	ans = (ans + mod) % mod;
	for ( i = 0 ; i <= s ; i++ ) {
		ans = (ans - dp[n][del+i][3]*3) % mod;
	}
	ans = (ans + mod) % mod;
	printf ( "%lld\n" , ans );
}
int main () {
	work ();
	return 0;
}
