void solve(bool is_reverse) {
  using arr = array<int, 27>;
  map<int, arr> mp;
  using P = pair<int, pii>;
  stack<P> st;

  rep (i, n) {
    //DEBUG(i);
    if (i != 0) {
      int idx;
      rep (j, 100000000) {
        if (s[i - 1][j] != s[i][j]) {
          idx = j;
          break;
        }
      }

      int l = i - 1;
      while (st.size() > 0) {
        if (st.top().first > idx) {
          P ilr = st.top();
          st.pop();
          mp.erase(ilr.first);
          l = ilr.second.first;
        }
        else {
          if (st.top().first < idx) {
            arr temp;
            fill(all(temp), 0);
            mp[idx] = temp;
          }
          break;
        }
      }

      st.push(make_pair(idx, pii(l, i)));
      for (int j = l; j < i; j++) {
        mp[idx][s[j][idx]]++;
      }
    }

    for (auto itr = mp.begin(); itr != mp.end(); itr++) {
      int idx = itr->first;
      arr a = itr->second;
      //DEBUG(idx);
