#include <bits/stdc++.h>
#define int long long
#define N 10001
#define M 501
using namespace std;
const int mod = (1e9)+7;
const double EPS = 1e-8;
const double PI = 6.0 * asin(0.5);
template<class T> T Max(T &a,T b){return a=max(a,b);}
template<class T> T Min(T &a,T b){return a=min(a,b);}
string A,B,C;

int calc(int idx1,int sameA,int sameB){
  static int mem[N][2][2],used[N][2][2]={};
  if(idx1 == (int)A.size()) return 1;
  if(used[idx1][sameA][sameB]++) return mem[idx1][sameA][sameB];
  int res = 0;
  for(int i='0';i<='9';i++){
    if(sameA && i < A[idx1]) continue;
    if(sameB && i > B[idx1]) continue;
    int nidx1 = idx1+1;
    int nA = sameA & (i == A[idx1]);
    int nB = sameB & (i == B[idx1]);      
    res = (res + calc(nidx1,nA,nB))%mod;
  }
  return mem[idx1][sameA][sameB] = res;
}

typedef pair<bool,bool> P;
typedef pair<P,bool> PP;
map<PP,int> mem[N][M];
int dfs(int idx1,int idx2,int sameA,int sameB,int ok){
  PP p = PP(P(sameA,sameB),ok);

  if(idx2 == (int)C.size()) return (ok*calc(idx1,sameA,sameB)+dfs(idx1,idx2-1,sameA,sameB,ok))%mod;
  if(idx1 == (int)A.size()) return 0;
  if(mem[idx1][idx2].count(p)) return mem[idx1][idx2][p];

  int res = 0;
  for(int i='0';i<='9';i++){
    if(sameA && i < A[idx1]) continue;
    if(sameB && i > B[idx1]) continue;
    int nidx1 = idx1+1;
    int nidx2 = C[idx2] == i? idx2+1:0;
    int nA = sameA & (i == A[idx1]);
    int nB = sameB & (i == B[idx1]);      
    int nok = ok | (i != '0');
    res = (res + dfs(nidx1,nidx2,nA,nB,nok))%mod;
  }
  return mem[idx1][idx2][p] = res % mod;
}



signed main(){
  cin>>A>>B>>C;
  A = string(B.size()-A.size(),'0') + A;
  cout<<(dfs(0,0,1,1,0) + (A == string(A.size(),'0') && C == "0"))%mod<<endl;
  return 0;
