#include <vector>
#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

const int MAX_C = 26;

struct TNode {
    int Next[MAX_C];
    int UpValue;
    int Count;

    int Sum[MAX_C][MAX_C];
};

const int MAX_NODE_COUNT = 4e5 + 1;

TNode nodes[MAX_NODE_COUNT];
int nodesCount;

void InitMemory() {
    nodesCount = 0;
}

void ClearNode(int index) {
    for (int i = 0; i < MAX_C; ++i) {
        nodes[index].Next[i] = -1;
    }
    nodes[index].Count = 0;
    nodes[index].UpValue = false;
}

int GetNewNode() {
    ClearNode(nodesCount);
    return nodesCount++;
}

int AddString(const string& s, int root) {
    for (int i = 0; i < (int) s.length(); ++i) {
        ++nodes[root].Count;

        int c = s[i] - 'a';

        if (nodes[root].Next[c] == -1) {
            nodes[root].Next[c] = GetNewNode();
        }

        root = nodes[root].Next[c];
    }
    ++nodes[root].Count;
    nodes[root].UpValue = true;
    return root;
}

void BuildSumDfs(int vert, int pr, int prChar) {
    if (pr != -1) {
        for (int i = 0; i < MAX_C; ++i) {
            for (int j = 0; j < MAX_C; ++j) {
                nodes[vert].Sum[i][j] = nodes[pr].Sum[i][j];
            }
        }
        for (int i = 0; i < MAX_C; ++i) {
            int nxt = nodes[pr].Next[i];
            if (nxt != -1) {
                nodes[vert].Sum[prChar][i] += nodes[nxt].Count;
            }
        }
        nodes[vert].UpValue += nodes[pr].UpValue;
    } else {
        for (int i = 0; i < MAX_C; ++i) {
            for (int j = 0; j < MAX_C; ++j) {
                nodes[vert].Sum[i][j] = 0;
            }
        }
    }
    for (int i = 0; i < MAX_C; ++i) {
        if (nodes[vert].Next[i] != -1) {
            BuildSumDfs(nodes[vert].Next[i], vert, i);
        }
    }
}

void BuildSum(int root) {
    BuildSumDfs(root, -1, -1);
}

int main() {
   // freopen("input.txt", "r", stdin);

    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    bool first = true;
    while (true) {
        InitMemory();

        int root = GetNewNode();

        int n;
        if (!(cin >> n)) {
            break;
        }

        if (!first) {
            cout << endl;
        } else {
            first = false;
        }

        vector<int> ids(n);

        vector<string> s(n);
        for (int i = 0; i < n; ++i) {
            cin >> s[i];

            ids[i] = AddString(s[i], root);
        }

        BuildSum(root);

        int tests;
        cin >> tests;
        for (int test = 0; test < tests; ++test) {
            int k;
            cin >> k;
            --k;

            int trieVertex = ids[k];

            string t;
            cin >> t;

            vector<int> charValue(MAX_C);
            for (int i = 0; i < MAX_C; ++i) {
                charValue[t[i] - 'a'] = i;
            }

            int result = 0;
            for (int i = 0; i < MAX_C; ++i) {
                for (int j = 0; j < MAX_C; ++j) {
                    if (charValue[i] > charValue[j]) {
                        result += nodes[trieVertex].Sum[i][j];
                    }
                }
            }
            result += nodes[trieVertex].UpValue;

            cout << result  << '\n';
        }
        cout.flush();
    }

    return 0;
},memory_limit_exceeded,,p03974

