  pzq.push(mp3(manpz(pz),0,pz));

  for(;!pzq.empty();){

    vvi now=pzq.top().se.se;
    int how=pzq.top().se.fi;
    int man=pzq.top().fi;
    pzq.pop();

    if(how>45 || man>45) continue;

    if(tf[now]) continue;
    tf[now]=1;

