#include "bits/stdc++.h"
using namespace std;

#define rep(i, n) for (int i = 0; i < (n); i ++)

struct Edge {
        int s;
        int d;
        int c;
};

struct State {
        int s;
        int c;
        int cost;
        int dist;
        bool operator < (const State& r) const { return cost < r.cost; }
        bool operator > (const State& r) const { return cost > r.cost; }
};

int getcost[20][20202];

int cost(int dis, int c) {
        return getcost[c][dis];
}

static const int INF = 0x3f3f3f3f;

int dp[200][20][20202];

int dijkstra(int s, int g, int c,  vector<vector<Edge> >& E) {
        rep(i, 200) rep(j, 20) rep(k, 20202) dp[i][j][k] = INF;
        //cerr << "ok" << endl;
        priority_queue<State, vector<State>, greater<State> > pq;
        rep(i, c) pq.push({s, i, 0, 0});
        while (!pq.empty()) {
                State now = pq.top(); pq.pop();
                if (now.dist > 20000) continue;
                //cout << now.s << ' ' << now.c << ' '  << now.dist << ' ' << now.cost << endl;
                if (dp[now.s][now.c][now.dist] < now.cost) continue;
                for (Edge e : E[now.s]) {
                        State next;
                        next.s = e.s;
                        next.c = e.c;
                        if (next.c == now.c) {
                                next.dist = now.dist + e.d;
                                next.cost = now.cost + cost(now.dist + e.d, now.c) - cost(now.dist, now.c);
                        } else {
                                next.dist = e.d;
                                next.cost = now.cost + cost(e.d, next.c);
                        }
                        if (dp[next.s][next.c][next.dist] > next.cost) {
                                dp[next.s][next.c][next.dist] = next.cost;
                                pq.push(next);
                        }
                }
        }
        int ans = INF;
        rep(i, c) rep(j, 20202) ans = min(ans, dp[g][i][j]);
        if (ans == INF) ans = -1;
        return ans;
}

int main() {
        while (true) {
                int n, m, c, s, g;
                cin >> n >> m >> c >> s >> g;
                if (n == 0 && m == 0 && c == 0 && s == 0 && g ==0) break;
                s --, g --;
                vector<vector<Edge>> E(n);
                rep(i, m) {
                        int x, y, d, c;
