                rep(i, c) cin >> p[i];
                vector<vector<int> > q(c);
                vector<vector<int> > r(c);
                rep(i, c) {
                        q[i].resize(p[i] - 1);
                        rep(j, p[i] - 1) {
                                cin >> q[i][j];
                        }
                        r[i].resize(p[i]);
                        rep(j, p[i]) {
                                cin >> r[i][j];
                        }
                }
                rep(i, c) {
                        int qp = 0, rp = 0;
                        int d = 0;
                        for (int j = 1; j < 20202; j ++) {
                                if (qp < p[i] -  1 && j > q[i][qp]) { 
                                        qp ++;
                                        rp ++;
                                }
                                d = d + r[i][rp];
                                getcost[i][j] = d;
                        }
                }
                cout << dijkstra(s, g, c, E) << endl;
        }
        return 0;
