#include <bits/stdc++.h>
using namespace std;

int N;

void solve() {
    vector<int> v(N);
    for (auto& i : v) cin >> i;

    vector<vector<map<int,int> > > dp(N + 1, vector<map<int,int> >(N + 1));
    dp[0][0][0] = 0;
    for (int i = 0; i < N; i++) {
        int payment = v[i];
        for (int j = 0; j <= i; j++) {
            for (auto p : dp[i][j]) {
                int coins = p.first;
                int cost = p.second;

                if (dp[i+1][j].find(coins) == dp[i+1][j].end()) dp[i+1][j][coins] = cost;
                else dp[i+1][j][coins] = min(dp[i+1][j][coins], cost);

                int sub = payment % 1000;
                if (0 < sub && sub <= 500) {
                    if (dp[i+1][j+1].find(coins + 500 - sub) != dp[i+1][j+1].end())
                        dp[i + 1][j + 1][coins + 500 - sub]
                            = min(dp[i + 1][j + 1][coins + 500 - sub], cost + payment);
                    else
                        dp[i + 1][j + 1][coins + 500 - sub] = cost + payment;
                } else {
                    if (sub == 0) sub = 500;
                    else sub = sub - 500;
                    if (sub <= coins) {
                        int coins_ = coins - sub;
                        if (dp[i+1][j+1].find(coins_) != dp[i+1][j+1].end())
                            dp[i + 1][j + 1][coins_] = min(dp[i+1][j+1][coins_], cost + payment);
                        else
                            dp[i + 1][j + 1][coins_] = cost + payment;
                    }

                    if (dp[i+1][j].find(coins + ((1000 - (payment % 1000)) % 1000)) != dp[i+1][j].end())
                        dp[i + 1][j][coins + ((1000 - (payment % 1000)) % 1000)]
                            = min(dp[i+1][j][coins + ((1000 - (payment % 1000)) % 1000)], cost + payment);
                    else
                        dp[i + 1][j][coins + ((1000 - (payment % 1000)) % 1000)] = cost + payment;
                }
            }
        }
    }
    int ans = 1 << 28, count = 0;
    for (int i = N; i > -1; i--) {
        if (count > 0) break;
        if (dp[N][i].size() == 0) continue;
        count = i;
        for (auto p : dp[N][i]) {
            ans = min(p.second, ans);
        }
    }
    cout << count << " " << ans << endl;
}

int main() {
    while (cin >> N, N) solve();

    return 0;
