template<int V>
struct SCC {
    vector<int> g[V], rg[V];
    /// i-j?????????????????????
    void add(int i, int j) {
        g[i].push_back(j);
        rg[j].push_back(i);
    }

    vector<int> vs;
    bitset<V> used;
    void dfs(int v) {
        used[v] = true;
        makeg(v);
        auto nv = nowg;
        for (int d: nv) {
            if (used[d]) continue;
            dfs(d);
        }
        vs.push_back(v);
    }
    int res[V]; /// res[i] = ??????i????±????????????£????????????ID
//    vector<int> scc[V]; /// scc[i] = i??????????????£?????????????±?????????????
    void rdfs(int v, int k) {
        used[v] = true;
        res[v] = k;
//        scc[k].push_back(v);
        for (int d: rg[v]) {
            if (used[d]) continue;
            rdfs(d, k);
        }
    }

    /**
     * ??????0..v-1????????????SCC?????????
     *
     * ???????????¨???????????£?????????????????°???????????????
     * ???????????????????????¨res[0..v-1], scc[0..v-1]????????±?????\???
     */
    int exec(int v) {
        vs.reserve(v+1);
//        fill_n(used, v, false);
        used.reset();
        for (int i = 0; i < v; i++) {
            if (used[i]) continue;
            dfs(i);
        }
//        fill_n(used, v, false);
        used.reset();
        int k = 0;
        for (int i = vs.size()-1; i >= 0; i--) {
            if (used[vs[i]]) continue;
            rdfs(vs[i], k);
            k++;
        }
        return k;
    }
};

