    for (int i = 0; i < MV; i++) {
        if (SVf[i]) {
            SVf2[scc.res[i]] = true;
        }
        if (TVf[i]) {
            TVf2[scc.res[i]] = true;
        }
        if (TV2f[i]) {
            TV2f2[scc.res[i]] = true;
        }
        makeg(i);
        for (int j: nowg) {
            scc.rg[scc.res[i]].push_back(scc.res[j]);
        }
    }

    int sre = 0;
    for (int i = MV-1; i >= 0; i--) {
        int ma = -INF;
        if (TVf2[i]) ma = -1;
        if (TV2f2[i]) ma = 0;
        bool loop = false;
        for (int j: scc.rg[i]) {
            if (i == j) {
                loop = true;
                continue;
            }
            if (scc.res[j] == -INF) continue;
            ma = max(ma, scc.res[j]+2);
        }
        if (ma < -INF/2) ma = -INF;
        if (ma == -INF) {
            scc.res[i] = -INF;
            continue;
        }
        if (loop) ma = INF;
        scc.res[i] = ma;
        if (ma == -INF) continue;
        if (SVf2[i]) {
            sre = max(sre, ma+2);
        }
    }
    if (sre > INF/2) sre = -1;
    return sre;
}

