int check(int a, int b, int c, int n, vector< vector<int> > &v){
  int _h = c, tmp = 1000;
  while(_h){
    if(tmp == 1000 && _h % 10 == 6 && n != 8) return -1;
    if(tmp == 100 && _h % 10 == 6 && n != 6) return -1;
    if(tmp == 10 && _h % 10 == 6 && n != 2) return -1;
    if(tmp == 1 && _h % 10 == 6 && n != 0) return -1;
    _h /= 10;
    tmp /= 10;
  }
  REP(i, v[a].size()){
    if(!v[a][i]) continue;
    bool f = true;
    REP(j, l[i]) if(d[i][j] == n) f = false;
    if(!f) return -1;
  }
  if(n != 0) c += 1000;
  if(n != 2) c += 100;
  if(n != 6) c += 10;
  if(n != 8) c += 1;
  if(n == 0) c %= 1000;
  if(n == 2) c = c - (c % 1000) + (c % 100);
  if(n == 6) c = c - (c % 100) + (c % 10);
  if(n == 8) c -= c % 10;
  return c;
}

int solve(){
  vector< vector<int> > v(D, vector<int>(N));
  REP(i, D) REP(j, N) cin >>v[i][j];
  memset(dp, 0, sizeof(dp));
  if(v[0][5] || v[0][6] || v[0][9] || v[0][10]) return 0;
  dp[1][4][1111] = 1;
  FOR(a, 1, D){
    REP(b, MAX_B){
      REP(c, MAX_C){
        if(!dp[a][b][c]) continue;
        REP(i, 5){
          int nb = m[b][i], nc;
          if((nc = check(a, b, c, nb, v)) == -1) continue;
          dp[a + 1][nb][nc] = true;
        }
      }
    }
  }
  bool ans = false;
  REP(b, MAX_B) REP(c, MAX_C) if(dp[D][b][c]) ans = true;
  return (ans ? 1 : 0);
}


int main() {
  while(cin >>D && D) cout <<solve() <<endl;
    return 0;
