#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

#define MAX 3000000
int n;
ll ans;

int solve(vector<int> t){
  int res=0;
  while(1){
    int index=-1;
    for(int i=0;i+1<(int)t.size();i++){
      if(t[i]>t[i+1]){
        index=i;
        break;
      }
    }
    if(index==-1)break;
    int num=t[index];
    t.erase(t.begin()+index);
    t.push_back(num);
    res++;
  }
  return res;
}


void input(){
  ans=0;
  vector<int> X, t(n*n);
  for(int i=0;i<n;i++){
    scanf("%d",&t[i]);
    X.push_back( t[i] );
  }
  sort(X.begin(),X.end());
  for(int i=0;i<n;i++){
    t[i]=lower_bound(X.begin(),X.end(),t[i])-X.begin()+1;
  }

  int K=1;
  for(int i=0;i<n;i++)if(t[i]==K)K++;

  stack<int> st;
  int cc=n;
  for(int i=0;i<cc;i++){

    while(!st.empty()&&t[ st.top() ] > t[i]){
      t[cc++]=t[ st.top() ];
      t[ st.top() ]=-1;
      ans++;
      if( t[cc-1] == K ) break;
      st.pop();
    }
    if( t[cc-1] == K ) break;
    st.push(i);
  }

  vector<int> tmp;
  for(int i=0;i<cc;i++)
    if(t[i]!=-1)tmp.push_back(t[i]);

  cout<< ans + solve( tmp ) <<endl;
}

int main(){
  while(cin>>n&&n){
    input();
  }
  return 0;
