	cout << endl;
}

// [(sx,sy),(gx,gy)] の範囲に myon をかける (0 <=> 1 の反転)
int myon(int bits, int n, int sx, int sy, int gx, int gy){
	for(int y = sy ; y <= gy ; y++ ){
		for(int x = sx ; x <= gx ; x++ ){
			int k = 1 << (x+y*n);
			(bits & k)? bits -= k : bits += k;
		}
	}
	return bits;
}

// n = 3, n = 4 のときのすべての状態からの最小の myon の回数を計算する
// n*n のすべて 0 の状態からBFS
void solve_2(int n){
	queue< pair<int,int> > q;
	q.push( pair<int,int>( 0 , 0 ) );
	map<int,bool> memo;

	while( !q.empty() ){
		int bits = q.front().first; 
		int cnt = q.front().second;
		q.pop();
		if( memo[bits] ) continue;
		memo[bits] = true;
		dp[n-1][bits] = cnt;

		for(int y = 0 ; y < n ; y++ ){
			for(int x = 0 ; x < n ; x++ ){
				for(int my = y ; my < n ; my++ ){
					for(int mx = x ; mx < n ; mx++){
						int next = myon( bits , n , x , y , mx , my );
						if( !memo[next] ){
							q.push( pair<int,int>( next , cnt+1 ) );
						}
					}
				}
			}
		}
	}
}

// n = 5 のときの一部の最小の myon の回数を計算する
// n*n のすべて 0 の状態からBFS (2手以下まで)
void solve_3(){
	queue< pair<int,int> > q;
	q.push( pair<int,int>( 0 , 0 ) );
	map<int,bool> memo;

	while( !q.empty() ){
		int bits = q.front().first; 
		int cnt = q.front().second;
		q.pop();
		if( memo[bits] ) continue;
		memo[bits] = true;
		dp_5[bits] = cnt;

		if( cnt >= 3 ) break;

		for(int y = 0 ; y < 5 ; y++ ){
			for(int x = 0 ; x < 5 ; x++ ){
				for(int my = y ; my < 5 ; my++ ){
					for(int mx = x ; mx < 5 ; mx++){
						int next = myon( bits , 5 , x , y , mx , my );
						if( !memo[next] ){
							q.push( pair<int,int>( next , cnt+1 ) );
						}
					}
				}
			}
		}
	}
}

// n <= 4 のすべての解と n = 5 の一部の解を求めておく
void solve(){
	for(int i=0 ; i < 5 ; i++ ){
		if( i == 0 ){
			vector<int> v(2);
			v[0] = 0;
			v[1] = 1;
			dp[0] = v;
		}else if( i == 1 ){
			vector<int> v(16);
			int f[16] = {0,1,1,1,1,1,2,2,1,2,1,2,1,2,2,1};
			for(int j=0 ; j < 16 ; j++ ){
				v[j] = f[j];
			}
			dp[1] = v;
		}else if( i == 2 ){
			vector<int> v(512);
			dp[2] = v;
			solve_2( 3 );
		}else if( i == 3 ){
			vector<int> v(65536);
			dp[3] = v;
			solve_2( 4 );
		}else if( i == 4 ){
			solve_3();
		}
	}
}

int main(){
	// n <= 4 のすべての解と n = 5 の一部の解を求めておく
	solve();


