const double EPS = 1e-10;

const int OPEN = 0;
const int UP_WALL = 1;
const int LEFT_WALL = 2;
const int DOWN_WALL = 4;
const int RIGHT_WALL = 8;

vvi field(32, vi(32, OPEN));
vvi cost(32, vi(32, 1000000));

int main() {
	int w, h;
	while(cin >> w >> h, w, h) {
		REP(i, 32) {
			REP(j, 32) {
				field[i][j] = OPEN;
				cost[i][j] = 1000000;
			}
		}

		FOR(i, 1, w+1) {
			field[1][i] += UP_WALL;
			field[h][i] += DOWN_WALL;
		}
		FOR(i, 1, h+1) {
			field[i][1] += LEFT_WALL;
			field[i][w] += RIGHT_WALL;
		}

		FOR(i, 1, h*2) {
			if(i%2) {
				FOR(j, 1, w) {
					int tmp;
					cin >> tmp;
					if(tmp) {
						field[i/2+1][j] += RIGHT_WALL;
						field[i/2+1][j+1] += LEFT_WALL;
					}

				}
			} else {
				FOR(j, 1, w+1) {
					int tmp;
					cin >> tmp;
					if(tmp) {
						field[i/2][j] += DOWN_WALL;
						field[i/2+1][j] += UP_WALL;
					}
				}
			}
		}

		//make cost map
		queue<pii> route;
		route.push(make_pair(1, 1));
		cost[1][1] = 1;
		while(!route.empty()) {
			pii zahyou = route.front();
			route.pop();

			int x = zahyou.first;
			int y = zahyou.second;

			if((field[y][x]&UP_WALL) == 0) {
				if(cost[y-1][x] > cost[y][x]) {
					cost[y-1][x] = cost[y][x]+1;
					route.push(make_pair(x, y-1));
				}
			}
			if((field[y][x]&LEFT_WALL) == 0) {
				if(cost[y][x-1] > cost[y][x]) {
					cost[y][x-1] = cost[y][x]+1;
					route.push(make_pair(x-1, y));
				}
			}
			if((field[y][x]&DOWN_WALL) == 0) {
				if(cost[y+1][x] > cost[y][x]) {
					cost[y+1][x] = cost[y][x]+1;
					route.push(make_pair(x, y+1));
				}
			}
			if((field[y][x]&RIGHT_WALL) == 0) {
				if(cost[y][x+1] > cost[y][x]) {
					cost[y][x+1] = cost[y][x]+1;
					route.push(make_pair(x+1, y));
				}
			}

			if(x == w && y == h) {
				break;
			}
		}

		if(cost[h][w] != 1000000) {
			cout << cost[h][w] << endl;
		} else {
			cout << -1 << endl;
		}
	}
