        if(val%d==0) return 1;
        return 0;
    }
    if(memo[pos][par][val]!=-1) return memo[pos][par][val];
    ll ans=0;
    if(par==0){
        for(ll i=0;i<10;i++){
            ans+=go(pos+1,par,(val+i)%d);
            ans%=mod;
        }
    }
    else{
        ans+=go(pos+1,par,(val+k[pos]-'0')%d);
        ans%=mod;
        for(ll i=0;i<k[pos]-'0';i++){
            ans+=go(pos+1,0,(val+i)%d);
            ans%=mod;
        }
    }
    return memo[pos][par][val]=ans;
}

