	rep(i, n)cin >> a[i];
	dpl[0][0] = 1;
	// dpl[i][j]: [0,i)
	rep(i, n) {
		rep(j, k + 1) {
			dpl[i + 1][j] |= dpl[i][j];
			if (j + a[i] <= k) {
				dpl[i + 1][j + a[i]] |= dpl[i][j];
			}
		}
	}
	dpr[n][0] = 1;
	// dpr[i][j]: [i,n)
	Rrep(i, n) {
		rep(j, k + 1) {
			dpr[i][j] |= dpr[i + 1][j];
			if (j + a[i] <= k) {
				dpr[i][j + a[i]] |= dpr[i + 1][j];
			}
		}
	}
	vector<vector<LL>>L(n + 1), R(n + 1);
	rep(i, n + 1)
		rep(j, k + 1) {
		if (dpl[i][j])
			L[i].push_back(j);
		if (dpr[i][j])
			R[i].push_back(j);
	}
	rep(i, n) {
		LL mx = 0;
		rep(j, L[i].size()) {
			if (k - L[i][j] > 0) {
				auto it = upper_bound(R[i + 1].begin(), R[i + 1].end(), k - L[i][j] - 1) - R[i + 1].begin();
				it--;
				mx = max(mx, L[i][j] + R[i + 1][it]);
			}
		}
		//cout << i << " " << mx << endl;
		if (a[i] >= k - mx)ans++;
	}
	cout << n - ans << endl;
	return 0;
