#include <bits/stdc++.h>

using namespace std;

#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)

const int MAX_N=300;

const int INF=1e8;

int N;
int p[MAX_N+1][MAX_N+1];

int dp[MAX_N+1][MAX_N+1][MAX_N+1],dp2[MAX_N+1][MAX_N+1][MAX_N+2];

int main(){
	scanf("%d",&N);
	FOR(i,1,N+1){
		FOR(j,1,N+1){
			scanf("%d",&p[i][j]);
		}
	}
	int res=-INF;
	FOR(i,1,N+1){
		FOR(j,1,N+1){
			for (int k=i;k>=1;k--){
				if (i==k){
					dp2[i][j][k]=p[i][j];
				}else{
					dp2[i][j][k]=dp2[i][j][k+1]+p[k][j];
				}
				res=max(res,dp2[i][j][k]);
			}
		}
	}
	FOR(i,1,N+1){
		FOR(j,2,N+1){
			FOR(k,1,i+1){
				if (j==2){
					dp[i][j][k]=dp2[i][j-1][k]+dp2[i][j][k];
				}else{
					dp[i][j][k]=dp2[i][j][k]+max(dp2[i][j-1][k],dp[i][j-1][k]-dp2[i-1][j-1][k+1]);
				}
				res=max(res,dp[i][j][k]);
			}
		}
	}
	printf("%d\n",res);
	return 0;
},memory_limit_exceeded,,p00305

