{
	cin >> N >> K;

	rep(i, N) {
		int x, y;
		char c;
		scanf("%lld %lld %c", &x, &y, &c);

		if (c == 'W') y += K;

		x %= 2*K, y %= 2*K;

		//imos[y][x]++;
		//printf("y = %lld, x = %lld\n", y, x);

		/*
		imos[y][x]++;
		imos[y][x - K]--;
		imos[y - K][x]--;
		imos[y - K][x - K]++;
		*/
		imos[y + OFS][x + OFS]++;
		imos[y + OFS][x - K + OFS]--;
		imos[y - K + OFS][x + OFS]--;
		imos[y - K + OFS][x - K + OFS]++;

		y -= K, x -= K;

		imos[y + OFS][x + OFS]++;
		imos[y + OFS][x - K + OFS]--;
		imos[y - K + OFS][x + OFS]--;
		imos[y - K + OFS][x - K + OFS]++;
	}

	rrange(y, 0, 6005) {
		rrange(x, 0, 6005) {
			imos[y][x] += imos[y][x + 1];
		}
	}

	rrange(y, 0, 6005) {
		rrange(x, 0, 6005) {
			imos[y][x] += imos[y + 1][x];
		}
	}

	rep(i, 6005) rep(j, 6005) sum[i%(2*K)][j%(2*K)] += imos[i][j];

	int mx = 1;

	rep(y, 2005) {
		rep(x, 2005) {
			chmax(mx, sum[y][x]);
		}
	}

	cout << mx << endl;
}


