//BASE進数
template<size_t BASE> class base_num {
    int v;
public:
    base_num(int v = 0) : v(v) {};
    int operator[](int i) { return bget(v, i, BASE); }
    void operator++() { v++; }
    void operator++(signed) { v++; }
    operator int() { return v; }
};
#define base3(mas, lim, BASE) for (base_num<BASE> mas; mas < lim; mas++)
