vector<T> sub(const vector<vector<T> >& A, int h, int w, int ah,int aw, F f){    vector<T> res;    while(0<= h && h < sz(A) && 0 <= w && w < sz(A[h]) && f(A[h][w])){        res.emplace_back(A[h][w]);        h += ah;        w += aw;    }    return res;}
