using namespace std;
using ll = long long;
using ull = unsigned long long;
constexpr int TEN(int n) {return (n==0)?1:10*TEN(n-1);}

using P = vector<int>;

bool solve() {
    int n;
    cin >> n;
    if (!n) return false;
    P a(2*n);
    for (int i = 0; i < 2*n; i++) {
        cin >> a[i]; a[i]--;
    }
    auto h = [&](const P &x) {
        int sm = 0;
        for (int i = 0; i < n; i++) {
            sm += abs(x[2*i]-i);
            sm += abs(x[2*i+1]-i);
        }
        return sm/2;
    };
    using Q = pair<int, P>;
    priority_queue<Q, vector<Q>, greater<Q>> que;
    que.push(Q(h(a), a));
    set<P> used;
    while (true) {
        P x; int dist;
        tie(dist, x) = que.top(); que.pop();
        if (used.count(x)) continue;
        used.insert(x);
        int hx = h(x);
        if (hx == 0) {
            cout << dist << endl;
            break;
        }
        for (int i = 0; i < n-1; i++) {
            for (int l = 0; l < 2; l++) {
                for (int r = 0; r < 2; r++) {
                    P y = x;
                    swap(y[2*i+l], y[2*i+2+r]);
                    que.push(Q(dist+1-hx+h(y), y));
                }
            }
        }
    }
    return true;
}

int main() {
    while (solve()) {}
    return 0;
