#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

#define INF 0xffffffff

int r;
int c;
int q;
int sizex;
int sizey;

class Seg2d {
public:
    vector<unsigned int> grid;
    int width;
    int height;

    Seg2d (int sizex, int sizey) : width(sizex), height(sizey) {
        long long int len = max(width, height);
        long long int sq = len*len;
        long long int ration = max(width, height) / min(width, height);
        long long int size = (sq*4-1)/3/ration + 1;

        grid.resize(20000000, INF);
    }

    void _update(int wishl, int wishr, int wishu, int wishd, int k, int watchl, int watchr, int watchu, int watchd, unsigned int x) {
        int midx, midy;
        unsigned int val1, val2, val3, val4;

        if (wishl == wishr || wishu == wishd) return;
        if (wishr <= watchl || watchr <= wishl || wishd <= watchu || watchd <= wishu) return;
        if (wishl <= watchl && watchr <= wishr && wishu <= watchu && watchd <= wishd) {
            grid[k] = x;
            return;
        }

        midx = (watchl+watchr)/2;
        midy = (watchu+watchd)/2;
        _update(wishl, wishr, wishu, wishd, k*4+1, watchl, midx, watchu, midy, x);
        _update(wishl, wishr, wishu, wishd, k*4+2, midx, watchr, watchu, midy, x);
        _update(wishl, wishr, wishu, wishd, k*4+3, watchl, midx, midy, watchd, x);
        _update(wishl, wishr, wishu, wishd, k*4+4, midx, watchr, midy, watchd, x);
        grid[k] = min(min(grid[k*4+1], grid[k*4+2]), min(grid[k*4+3], grid[k*4+4]));
    }

    void update(int x, int y, unsigned int t) {
        _update(x, x+1, y, y+1, 0, 0, width, 0, height, t);
    }

    unsigned int _getMin(int wishl, int wishr, int wishu, int wishd, int k, int watchl, int watchr, int watchu, int watchd) {
        int midx, midy;
        unsigned int val1, val2, val3, val4;

        if (wishl == wishr || wishu == wishd) return INF;
        if (wishr <= watchl || watchr <= wishl || wishd <= watchu || watchd <= wishu) return INF;
        if (wishl <= watchl && watchr <= wishr && wishu <= watchu && watchd <= wishd) {
            return grid[k];
        }

        midx = (watchl+watchr)/2;
        midy = (watchu+watchd)/2;
        val1 = _getMin(wishl, wishr, wishu, wishd, k*4+1, watchl, midx, watchu, midy);
        val2 = _getMin(wishl, wishr, wishu, wishd, k*4+2, midx, watchr, watchu, midy);
        val3 = _getMin(wishl, wishr, wishu, wishd, k*4+3, watchl, midx, midy, watchd);
        val4 = _getMin(wishl, wishr, wishu, wishd, k*4+4, midx, watchr, midy, watchd);
        return min(min(val1, val2), min(val3, val4));
    }

    unsigned int getMin(int x1, int x2, int y1, int y2) { // [x1, x2) [y1, y2)
        return _getMin(x1, x2, y1, y2, 0, 0, width, 0, height);
    }
};

int main() {
    while (1) {
        scanf("%d %d %d", &r, &c, &q);
        if (r == 0 && c == 0 && q == 0) return 0;

        sizex = 1;
        while (sizex < c) sizex *= 2;
        sizey = 1;
        while (sizey < r) sizey *= 2;

        Seg2d seg(sizex, sizey);
        for (int i=0; i<r; i++) {
            for (int j=0; j<c; j++) {
                unsigned int g;

                scanf("%u", &g);
                seg.update(j, i, g);
            }
        }

        for (int i=0; i<q; i++) {
            int r1, r2;
            int c1, c2;

            scanf("%d %d %d %d", &r1, &c1, &r2, &c2);
            printf("%u\n", seg.getMin(c1, c2+1, r1, r2+1));
        }
    }
