using State = tuple<int, int, int>;
using Elem  = tuple<int, State>;

inline bool check(State pre, State cur){
    int pp[3], cp[3];
    tie(pp[0], pp[1], pp[2]) = pre;
    tie(cp[0], cp[1], cp[2]) = cur;

    // exchange
    rep(i, 3){
        int j = (i + 1) % 3;
        if(i >= n or j >= n) continue;

        if(pp[i] == cp[j] and pp[j] == cp[i]){
            return false;
        }
    }

    // overlap
    rep(i, 3){
        int j = (i + 1) % 3;
        if(i >= n or j >= n) continue;

        if(cp[i] == cp[j]){
            return false;
        }
    }

    return true;
}

