const int MAX = 200011;
const ll mod = 1000000007;

//modt³
ll mypow(ll n,ll p){
  if (p == 1)return n;
  ll ret=mypow(n,p/2);
  ret=ret*ret%mod;
  if (p&1)ret=ret*n%mod;
  return ret;
}
ll getinv(ll a){
  return mypow(a,mod-2);
}

//n! mod p ðßéB
//n! = a * p^e ðvZ·éB
//a Æe@»ê¼êªàÆÜéB
//log_p(n):e[uL
//min(n,p)*log_p(n):e[uL
ll fact[MAX];
ll modFact(ll n,ll p,ll &e){
  e=0;
  if (n == 0)return 1;
  ll res = modFact(n/p,p,e);
  e+=n/p;
  ll f = 1;
  //REP(i,2,n+1)f=f*i%p;//pªe[uðìêéTCYÈçe[uðìé×«B
  f = fact[n];
  if ((n/p) % 2 != 0)return res*(p-f)%p;
  return res*f%p;
}

//p=mod
//min(n,p)log_p
//n choose k mod p ðvZ·é
map<ll,ll> Inv;
ll modComb(ll n,ll k,ll p){
  if (n < 0 || k < 0 || n < k)return 0;
  ll e1,e2,e3;
  //ll a1=modFact(n,p,e1),a2=modFact(k,p,e2),a3=modFact(n-k,p,e3);
  ll a1 = fact[n],a2=fact[k],a3=fact[n-k];
  if (e1 > e2+e3)return 0;
  return a1 * getinv(a2*a3%p)%p;
  ll tmp = a2*a3%p;
  if (Inv.find(tmp) != Inv.end())return a1*Inv[tmp]%p;
  ll req = getinv(tmp)%p;
  Inv[tmp]=req;
  return  a1*req%p;

}

void precalc(){
  fact[0]=1;
  REP(i,1,MAX)fact[i]=(fact[i-1]*i)%mod;
}

