bool isin(int y1,int x1,int y2,int x2,int y,int x){
  return 
    y1 <= y && y <= y2 &&
    x1 <= x && x <= x2 && 
    !((y1==y) && (x1 == x)) && 
    !((y2==y) && (x2 == x));
}

template <class T> int getindex(T a,map<T,int> & M){
  int index = M.size();
  if (M.find(a) == M.end())M[a]=index;
  return M[a];
}

//s©çtÜÅA[vz[Ì_ðPÇàÊçÈ¢pXÌ©¸ðvZ·éB
ll dpP[N][N];
ll solveP(int r,int c,int sy,int sx,int ty,int tx,vector<int> & iny,vector<int> &inx,
	  int sid,int tid,vector<int>&inid){
  int w = tx-sx,h=ty-sy;
  int a1=sid,a2=tid;
  if (dpP[a1][a2] != -1){return dpP[a1][a2];}
  ll all = modComb(w+h,w,mod);
  ll deg = 0;
  rep(i,inx.size()){
    if (isin(sy,sx,ty,tx,iny[i],inx[i])){
      ll a = solveP(r,c,sy,sx,iny[i],inx[i],iny,inx,sid,inid[i],inid)%mod;
      ll tw=tx-inx[i],th=ty-iny[i];
      ll b = modComb(tw+th,tw,mod)%mod;
      a =(a*b)%mod;
      deg=(deg+a)%mod;
    }
  }
  return dpP[a1][a2]=(all-deg+mod)%mod;
}

ll dp[N][N];
ll solve(int r,int c,int sy,int sx,int ty,int tx,vector<int> &iny,vector<int> &inx,
	 vector<int> &outy,vector<int> &outx,
	 int sid,int tid,
	 vector<int> &inid,vector<int> &outid){
  int a1=sid,a2=tid;
  if (dp[a1][a2] != -1){
    return dp[a1][a2];
  }
  ll sum1 = solveP(r,c,sy,sx,ty,tx,iny,inx,sid,tid,inid)%mod;
  ll sum2 = 0;
  rep(i,(int)inx.size()){
    if (isin(sy,sx,ty,tx,iny[i],inx[i]) && isin(sy,sx,ty,tx,outy[i],outx[i])){
      ll a = solveP(r,c,sy,sx,iny[i],inx[i],iny,inx,sid,inid[i],inid)%mod;
      ll b = solve(r,c,outy[i],outx[i],ty,tx,iny,inx,outy,outx,outid[i],tid,inid,outid);
      a = (a*b)%mod;
      sum2=(sum2+a)%mod;
    }
  }
  return dp[a1][a2]=(sum1+sum2)%mod;
}

