#define V vector
int kai_size = 5001;
vel kai(kai_size, 1);
vel kai2;
vel ink(kai_size, 1);
vel ink2;
vector<int> Centroid(const vector<vector<int>> &g) {
	int n = g.size();
	vector<int> centroid;
	vector<int> sz(n);
	function<void(int, int)> dfs = [&](int u, int prev) {
		sz[u] = 1;
		bool is_centroid = true;
		for (auto v : g[u]) if (v != prev) {
			dfs(v, u);
			sz[u] += sz[v];
			if (sz[v] > n / 2) is_centroid = false;
		}
		if (n - sz[u] > n / 2) is_centroid = false;
		if (is_centroid) centroid.push_back(u);
	};
	dfs(0, -1);
	return centroid;
}
int ru(int a, int r) {
	if (r == 0) { return 1; }
	int ans = ru(a, r / 2);
	ans *= ans; ans %= p;
	if (r % 2 == 1) { ans *= a; }
	return ans % p;
}
int inv(int a) {
	return ru(a, p - 2);
}
void make_kai() {
	kai2 = kai; ink2 = ink;
	rep(i, kai_size - 1) {
		kai[i + 1] = (kai[i] * (i + 1)) % p;
		kai2[i + 1] = kai[i + 1] * kai[i + 1];
		kai2[i + 1] %= p;
	}
	rep(i, kai_size) {
		ink[i] = inv(kai[i]);
		ink2[i] = ink[i] * ink[i];
		ink2[i] %= p;
	}
}
int size_tree(int back, int now, vvel way) {
	int ans = 1;
	rep(j, way[now].size()) {
		int nex = way[now][j];
		if (nex != back) {
			ans += size_tree(now, nex, way);
		}
	}
	return ans;
}
int center(vvel &way) {
	int n = way.size();
	rep(i, n) {
		int qmax = 0;
		rep(j, way[i].size()) {
			mmax(qmax, size_tree(i, way[i][j], way));
		}
		if (qmax * 2 <= n) { return i; }
	}
	return -1;
}
int RE() {
	vel v(3, 2);
	return v.at(4);
}
int comper(int n, int r) {
	int ans = kai2[n] * ink2[n - r];
	ans %= p;
	ans *= ink[r];
	return ans % p;
}
void pl(int &a, int b) {
	a += b; a %= p;
}
signed main() {
