		int nex = (i + 1) % 2;
		for (int j = 0; j <= sum; j++) {
			rep(k, sub[i] + 1) {
				int plus = dp[now][j] * comper(sub[i], k);
				pl(dp[nex][j + k], plus);
			}
			dp[now][j] = 0;
		}
		sum += sub[i];
	}
	int ans = 0;
