void initRMQ(int n)
{
    int i, j;
    for (i = 0; i <= n; i++)
    {
        st.pb(vector<int>());
        for (j = 0; (1 << j) <= n; j++)
            st[i].pb(0);
    }
    for (i = 0; i < n; i++)
        st[i][0] = a[i];
    for (j = 1; (1 << j) <= n; j++)
        for (i = 0; i + (1 << j) - 1 < n; i++)
            st[i][j] = min (st[i][j - 1], st[i + (1 << j - 1)][j - 1]);
}

int calc(int l, int r)
{
    int d = Log2[r - l + 1];
    return min (st[l][d], st[r - (1 << d) + 1][d]);
}

