#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
const int MAXN = 5007;
const int INF = 1000 * 1000 * 1000 + 7;
int a[MAXN], b[MAXN][MAXN];
ll mod[MAXN][MAXN];
int gol[MAXN], gor[MAXN];
void add(int x1, int y1, int x2, int y2, int val)
{
	mod[x1][y1] += val;
	mod[x2 + 1][y1] -= val;
	mod[x1][y2 + 1] -= val;
	mod[x2 + 1][y2 + 1] += val;
}
int main()
{
#ifdef LOCAL
	freopen("input.txt", "r", stdin);
#endif
	int n, m;
	scanf("%d %d", &n, &m);
	for (int i = 2; i <= n; i++)
	{
		scanf("%d", &a[i]);
	}
	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= m; j++)
		{
			scanf("%d", &b[i][j]);
		}
	}
	for (int i = 1; i <= m; i++)
	{
		vector<pair<int, int> > st;
		st.push_back(make_pair(0, INF));
		for (int j = 1; j <= n; j++)
		{
			while (st.back().second < b[j][i]) st.pop_back();
			gol[j] = st.back().first + 1;
			st.push_back(make_pair(j, b[j][i]));
		}
		st.clear();
		st.push_back(make_pair(n + 1, INF));
		for (int j = n; j >= 1; j--)
		{
			while (st.back().second < b[j][i]) st.pop_back();
			gor[j] = st.back().first - 1;
			st.push_back(make_pair(j, b[j][i]));
		}
		for (int j = 1; j <= n; j++)
		{
			add(gol[j], j, j, gor[j], b[j][i]);
		}
	}
	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= n; j++)
		{
			mod[i][j] = mod[i - 1][j] + mod[i][j - 1] - mod[i - 1][j - 1] + mod[i][j];
		}
	}
	ll res = 0;
	for (int i = 1; i <= n; i++)
	{
		ll dist = 0;
		for (int j = i; j <= n; j++)
		{
			if (j != i) dist += a[j];
			res = max(res, mod[i][j] - dist);
		}
	}
	printf("%lld\n", res);
}

