using namespace std;
using ulong = unsigned long;
using ll = long long;
const int M = 1e9 + 7;

struct Node;
struct pqElem{
	int cost, c;
	Node* node;
	pqElem(int cost, int c, Node* node):cost(cost), c(c), node(node){}
	bool operator < (const pqElem& p) const{
		return cost > p.cost;
	}
};

priority_queue<pqElem> pq;
set<pair<Node*, int>> decided;
int n, m;

struct Node{
	vector<pair<int, Node*>> edges;
	int id;
};

void add(int c, Node* n, int cost){
	if(decided.count({n, c})){ return; }
	decided.insert({n, c});
	if(n -> id == ::n - 1){
		cout << cost << endl;
		exit(0);
	}
	for(auto e : n -> edges){
		if(c == e.first){
			add(c, e.second, cost);
		}else{
			pq.emplace(cost + 1, e.first, e.second);
		}
	}
}

int main(){
	cin >> n >> m;
	vector<Node> nodes(n);
	for(int i=0;i<n;i++){
		nodes[i].id = i;
	}
	for(int i=0;i<m;i++){
		int p, q, c;
		cin >> p >> q >> c;
		p--;
		q--;
		nodes[p].edges.emplace_back(c, &nodes[q]);
		nodes[q].edges.emplace_back(c, &nodes[p]);
	}
	pq.emplace(0, -1, &nodes[0]);
	while(!pq.empty()){
		auto cn = pq.top();
		pq.pop();
		add(cn.c, cn.node, cn.cost);
	}
	cout << -1 << endl;
	return 0;
}

