void solve(int n){
    int d;
    vector<string> name(n);
    cin >> d;
    rep(i,0,n) cin >> name[i];

    function<set<string>(const string&,const int)> enumerate_neighborhood=[&](const string &s,int d){
        if(d==0) return set<string>({s});
        set<string> res;
        //replace
        rep(i,0,s.size()){
            string t=s;
            rep(j,0,26){
                t[i]='a'+j;
                auto tmp=enumerate_neighborhood(t,d-1);
                res.insert(tmp.begin(),tmp.end());
            }
        }
        //insert
        rep(i,0,s.size()+1){
            string x=s.substr(0,i),y=s.substr(i);
            rep(j,0,26){
                x.push_back('a'+j);
                auto t=x+y;
                auto tmp=enumerate_neighborhood(t,d-1);
                res.insert(tmp.begin(),tmp.end());
                x.pop_back();
            }
        }
        //delete
        rep(i,0,s.size()){
            string t=s.substr(0,i)+s.substr(i+1);
            auto tmp=enumerate_neighborhood(t,d-1);
            res.insert(tmp.begin(),tmp.end());
        }
        //swap adjacent
        rep(i,0,s.size()-1){
            string t=s;
            swap(t[i],t[i+1]);
            auto tmp=enumerate_neighborhood(t,d-1);
            res.insert(tmp.begin(),tmp.end());
            swap(t[i],t[i+1]);
        }
        return res;
    };

    vector<set<string>> u(n);
    rep(i,0,n) u[i]=enumerate_neighborhood(name[i],d);

    vector<pair<string,string>> ans;
    rep(i,0,n) rep(j,i+1,n){
        int i1=i,j1=j;
        if(u[i].size()>u[j].size()) swap(i1,j1);
        if(u[i1].find(name[j1])==u[i1].end()) continue;
        ans.push_back(make_pair(min(name[i],name[j]),max(name[i],name[j])));
    }

    sort(ans.begin(),ans.end());
    rep(i,0,ans.size()) cout << ans[i].first << "," << ans[i].second << endl;
    cout << ans.size() << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    for(;;){
        int n;
        cin >> n;
        if(!n) break;
        solve(n);
    }
    return 0;
