int dfs(vector<char> v,int cy,int cx,int pos){
  if(dp[cy][cx][pos].count(v)>0)return dp[cy][cx][pos][v];
  int res=-INF;
  if(cy==R)return 0;
  if(cx==(int)v.size()){
    if(pos!=(int)ss[cy].size())return res;
    return dfs(v,cy+1,0,0);
  }
  // 今回の所に割り当てる場合
  if(pos!=(int)ss[cy].size()){
    vector<char> nv=v;
    int add=0;
    nv[cx]=pos;
    if(cx-1>=0&&ss[cy][v[cx-1]]==ss[cy][pos])add+=2;
    if(v[cx]!=-1&&cy!=0&&ss[cy-1][v[cx]]==ss[cy][pos])add+=2;
    res=max(res,add+dfs(nv,cy,cx+1,pos+1));
  }
  // 今回の所に割り当てない場合
  {
    vector<char> nv=v;
    nv[cx]=-1;
    res=max(res,dfs(nv,cy,cx+1,pos));
  }
  return dp[cy][cx][pos][v]=res;
}

