/* Dijkstra O(NlogM)*/

struct Dijkstra{

  typedef int Type;

  int V;
  vector<vector<pair<int,Type> > > G;
  vector<int> cost;

  Dijkstra(int n):
    V(n),G(n,vector<pair<int,Type> >()){}

  void add_edge(int u, int v, Type c){
    G[u].push_back({v,c});
  }

  void init(int n){
    V = n;
    G.assign(n,vector<pair<int,Type> >());
  }

  Type solve(int s, int g = -1){
    cost.assign(V,-1);
    priority_queue<pair<Type,int> > pq;
    Type max_cost = INF;

    pq.push({0,s});

    while(pq.size()){
      Type now_cost = pq.top().first;
      int now = pq.top().second;
      pq.pop();

      if(cost[now] >= 0) continue;

      cost[now] = -now_cost;
      max_cost = max(max_cost, -now_cost);

      if(now == g) return -now_cost;

      for(int i=0;i<(int)G[now].size();i++){
        pq.push({now_cost-G[now][i].second, G[now][i].first});
      }
    }

    return max_cost;
  }

};

Dijkstra dijk(5*1000 + 20);
char c[SIZE][SIZE];

bool solve(){
  int h,w;
  int sy,sx,gy,gx;
  vector<pair<int,int> > vec[6];

