      }
      if(c[i][j] == 'S'){
        sy = i; sx = j;
      }
      if(c[i][j] == 'G'){
        gy = i; gx = j;
      }
    }
  }

  dijk.init(5020);

  for(int i=0;i<5;i++){
    for(int j=0;j<vec[i].size();j++){
      for(int k=0;k<vec[(i+1)%5].size();k++){
        dijk.add_edge(i*1000 + j, ((i+1)%5)*1000 + k,
                      abs(vec[i][j].first - vec[(i+1)%5][k].first)+abs(vec[i][j].second - vec[(i+1)%5][k].second));
