      dijk.add_edge(5000 + i, i*1000 + j,abs(sy-vec[i][j].first)+abs(sx-vec[i][j].second));
      dijk.add_edge(i*1000 + j, 5010 + i,abs(gy-vec[i][j].first)+abs(gx-vec[i][j].second));
