struct state
{
    vector<int> v;

    int dist1;
    int dist2;

    state(vector<int> v1, int d1, int d2) : v(v1), dist1(d1), dist2(d2) { }
};

bool operator<(const state& s1, const state& s2) { return s1.dist1 * n + s1.dist2 * 3 < s2.dist1 * n + s2.dist2 * 3; }
bool operator>(const state& s1, const state& s2) { return s1.dist1 * n + s1.dist2 * 3 > s2.dist1 * n + s2.dist2 * 3; }

inline int getdistance(vector<int> v)
{
    int ret = 0;

    for(int i = 0; i < n; i++)
    {
        if(v[i] != i + 1)
        {
            ret++;
        }
    }

    return ret;
}

