struct state {
    int v, l, c;
};

bool operator<(const state &a, const state &b) {
    if (a.l != b.l) return a.l > b.l;
    return a.c > b.c;
}

int main(){
    cin.sync_with_stdio(false);
    int n, m;
    while(cin >> n >> m, n | m) {
        rep(i, n)rep(j, n) d[i][j].fi = d[i][j].se = INF;
        rep(i, n) cost[i] = INF;
        rep(i, m) {
            int u, v, l, c;
            cin >> u >> v >> l >> c; u--, v--;
            d[u][v].fi = d[v][u].fi = l;
            d[u][v].se = d[v][u].se = c;
        }

        priority_queue<state> q;
        q.push(state{0, 0, 0});
        while(!q.empty()) {
            state s = q.top(); q.pop();

            if (cost[s.v] < INF) continue;
            else cost[s.v] = s.c;

            rep(i, n) {
                if (d[s.v][i].fi < INF && cost[i] == INF) {
                    q.push(state{i, s.l + d[s.v][i].fi, d[s.v][i].se});
                }
            }
        }

        int ans = 0;
        repl(i, 1, n) ans += cost[i];
        cout << ans << endl;
    }

    return 0;
