struct D{
	vector<int> d;
	int de;
	D(){
		d.clear();de = 0;
	}
	bool operator <(const D& b) const{ 
		int len1=d.size();
		int len2 = b.d.size();
		if(len1 != len2) return len1<len2;//深度 
		else{
			for(int i=0;i<len1;++i){
				if(d[i]==b.d[i]) continue;
				return d[i] < b.d[i];
			}
			return false;
		}
	}
}dep[maxn];
