void dfs(int cur){
	if(son[cur].empty()){
		yz ++;
		return;
	}
	int i,j;
	int len = son[cur].size();
	dep[cur].d.push_back(len);//把儿子这一层加入
	dep[cur].de = 1; 
	for(i = 0; i <len ;++ i){
		int s=son[cur][i];
		dfs(s); //操作儿子 

		if(dep[cur].de <= dep[s].de + 1){
