const int R = 130;
const int C = 16;
const int INF = 19191919;
int dp[R][C][1<<C];

int main(){
    int r,c;
    cin >>r >>c;
    vector<string> s(r);
    vector<int> L(r);
    rep(i,r){
        cin >>s[i];
        L[i] = s[i].size();
    }

    int U = (1<<c)-1;
    vector<int> cm(c), pm(c);
    rep(i,c){
        rep(j,i) cm[i] |= (1<<j);
        pm[i] = cm[i]^U;
    }

    rep(i,R)rep(j,C)rep(k,1<<C) dp[i][j][k] = -INF;
    dp[0][0][0] = 0;
    rep(i,r)rep(j,c){
        int nr = i;
        int nc = j+1;
        if(nc == c){
            ++nr;
            nc = 0;
        }

        rep(mask,1<<c)if(dp[i][j][mask]>=0){
            // printf(" %d %d %d\n",i,j,mask);
            int idx = __builtin_popcount(mask&cm[j]);
            if(idx<=L[i]){
                // not put
                int nmask = (mask<<1)&U;
                if( !(i!=nr && idx<L[i]) ) dp[nr][nc][nmask] = max(dp[nr][nc][nmask], dp[i][j][mask]);

                // put
                if(idx<L[i]){
                    nmask |= 1;

                    int add = 0;
                    // left
                    if(idx>0) add += (s[i][idx]==s[i][idx-1]);
                    // up
                    if( (mask>>(c-1))&1 ){
                        int ct = __builtin_popcount(mask&pm[j]);
                        int pre_idx = L[i-1]-ct;
                        if(pre_idx<0) continue;

                        add += (s[i][idx]==s[i-1][pre_idx]);
                    }

                    if( !(i!=nr && idx<L[i]-1) ) dp[nr][nc][nmask] = max(dp[nr][nc][nmask], dp[i][j][mask]+add);
                }
            }
        }
    }

    int ans = 0;
    rep(i,1<<c) ans = max(ans, dp[r][0][i]);
    cout << ans*2 << endl;
    return 0;
}

