void solve(){
  mint dp[N+1][N+1][N+1];
  dp[0][0][0] = 1;
  ll s = 0;
  rep(i, N){//最大がi
    if(i == 0){
      dp[1][0][0] = 1;
      dp[0][1][0] = 1;
      dp[0][0][1] = 1;
    }
    //Rを塗る
    rep(r, i)rep(g, i){
      dp[i+1][g][i] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[i+1][i][b] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i+1][g][b] += dp[i][g][b];
    }
    //Gを塗る
    rep(r, i)rep(g, i){
      dp[r][i+1][i] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[r][i+1][b] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i][i+1][b] += dp[i][g][b];
    }
    //Bを塗る
    rep(r, i)rep(g, i){
      dp[r][g][i+1] += dp[r][g][i];
    }
    rep(r, i)rep(b, i){
      dp[r][i][i+1] += dp[r][i][b];
    }
    rep(g, i)rep(b, i){
      dp[i][g][i+1] += dp[i][g][b];
    }


    //r == i+1 の時
    while(rlx[s].f.f == i+1){
      ll left = rlx[s].f.s, right = rlx[s].f.f, x = rlx[s].s;
      if(x == 1){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left <= g || left <= b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left <= r || left <= b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left <= r || left <= g) dp[r][g][right] = 0;
        }
      }
      if(x == 2){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left <= g && left <= b) dp[right][g][b] = 0;
          if(left > g && left > b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left <= r && left <= b) dp[r][right][b] = 0;
          if(left > r && left > b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left <= r && left <= g) dp[r][g][right] = 0;
          if(left > r && left > g) dp[r][g][right] = 0;
        }
      }
      if(x == 3){
        //Rを最後に塗った
        rep(g, right)rep(b, right){
          if(left > g || left > b) dp[right][g][b] = 0;
        }
        //Gを最後に塗った
        rep(r, right)rep(b, right){
          if(left > r || left > b) dp[r][right][b] = 0;
        }
        //Bを最後に塗った
        rep(r, right)rep(g, right){
          if(left > r || left > g) dp[r][g][right] = 0;
        }
      }
      s++;
    }
  }
  mint ans = 0;
  //最後にRを塗った
  rep(g, N)rep(b, N){
    ans += dp[N][g][b];
  }
  //最後にGを塗った
  rep(r, N)rep(b, N){
    ans += dp[r][N][b];
  }
  //最後にBを塗った
  rep(r, N)rep(g, N){
    ans += dp[r][g][N];
  }

  ans.get();
}
int main(){
  cin >> N >> M;
  rlx.resize(M);
  rep(i, M){
    cin >> rlx[i].f.s >> rlx[i].f.f >> rlx[i].s;
  }
  sort(rlx.begin(), rlx.end());
  solve();
}
