	void push(T x) { arr[r] = x; r = (r + 1) & ((1 << 21) - 1); }
	T front() { return arr[l]; }
	void pop() { l = (l + 1) & ((1 << 21) - 1); }
	bool empty() { return l == r; }
};

const int maxn = 1 << 21;
