unordered_map <int, vector <int> > g1[maxn];

int main() {
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= m; i ++) {
		int u, v, c;
		scanf("%d%d%d", &u, &v, &c);
		u --; v --;
		g1[u][c].push_back(v);
		g1[v][c].push_back(u);
		all[c].push_back(u);
		all[c].push_back(v);
	}
	int cc = n;
	for (int c = 1; c <= 1000000; c ++) {
		sort(all[c].begin(), all[c].end());
		all[c].erase(unique(all[c].begin(), all[c].end()), all[c].end());
		for (int i = 0; i < (int) all[c].size(); i ++) {
			if (dis[all[c][i]] == c) continue;
			que.push(all[c][i]);
