				g[cc].push_back(u);
				for (int i = 0; i < (int) g1[u][c].size(); i ++) {
					int v = g1[u][c][i];
					if (dis[v] != c) {
						dis[v] = c;
						que.push(v);
					}
				}
			}
			cc ++;
		}
	}
	memset(dis, -1, sizeof dis);
	dis[0] = 0;
	que.push(0);
	while (!que.empty()) {
		int u = que.front();
		que.pop();
		for (int i = 0; i < (int) g[u].size(); i ++) {
			int v = g[u][i];
			if (!~dis[v]) {
				dis[v] = dis[u] + 1;
				que.push(v);
			}
		}
	}
	printf("%d\n", !~dis[n - 1] ? -1 : dis[n - 1] / 2);
	return 0;
}

