            c0.s = c0.s+c2.s;
            c2 = {node,F(0,0)};
        }
        if(d2.f!=node) {
            d0.s = d0.s+d2.s;
            d2 = {node,F(0,0)};
        }

        e0.s = d0.s*c0.s;
        e1.s = c0.s*d1.s + c1.s*d0.s;

        e2.s = (c1.s+c2.s) * (d1.s+d2.s) + c2.s*d0.s+d2.s*c0.s ;

        e0.f = e1.f = e2.f = node;

        S.push(e0);
        S.push(e1); 
        S.push(e2);
    }
    while(!S.empty()) {
        Q[r1].push_front(S.top());
        S.pop();
    }
}
