#include <iostream>
#include <string>
#include <utility>

constexpr int defaultValue = 0;

class DLLNode{
public:
    DLLNode( int key ) : key(key), prev(this), next(this){}

    DLLNode() : key(defaultValue), prev(this), next(this){}

    DLLNode* Prev(){
        return prev;
    }

    DLLNode* Next(){
        return next; 
    }

    int Key(){
        return key;
    }

    void SetPrev( DLLNode* p ){
        prev = p;
    }

    void SetNext( DLLNode* n ){
        next = n;
    }

private:
    int key;
    DLLNode* prev;
    DLLNode* next;
};

class DoublyLinkedList{
public:
    DoublyLinkedList(){
        head = new DLLNode();
    }

    // ~DoublyLinkedList(){
    //     for( DLLNode* ptr = head->Next(); ptr != head; ptr = head->Next() ){
    //         DeleteFirst();
    //     }
    // }

    void DoCommand( std::string cmd, int x ){
        if( cmd == "insert" ){
            Insert(x);
        }else if( cmd == "delete" ){
            Delete(x);
        }
    }
    void DoCommand( std::string cmd ){
        if( cmd == "deleteFirst" ){
            DeleteFirst();
        }else if( cmd == "deleteLast" ){
            DeleteLast();
        }
    }

    void Print(){
        for( DLLNode* itr = head->Next(); itr != head; itr = itr->Next() ){
            std::cout << itr->Key() << ( ( itr != head->Prev() )? " " : "" );
        }
        std::cout << "\n";
    }

private:
    DLLNode* SearchByKey( int key ){
        for( DLLNode* itr = head->Next(); itr != head; itr = itr->Next() ){
            if( itr->Key() == key ){
                return itr;
            }
        }
        return nullptr;
    }

    bool IsEmpty(){
        bool check = ( head == head->Next() );
        return check;
    }

    void Insert( int x ){
        DLLNode* newNode = new DLLNode(x);
        newNode->SetNext( head->Next() );
        head->Next()->SetPrev( newNode );
        head->SetNext( newNode );
        newNode->SetPrev( head );
    }

    void Delete( int x ){
        if( !IsEmpty() ){
            DLLNode* deleteNode = SearchByKey(x);
            if( deleteNode != nullptr ){
                deleteNode->Prev()->SetNext( deleteNode->Next() );
                deleteNode->Next()->SetPrev( deleteNode->Prev() );
                delete deleteNode;
            }
        }
    }

    void DeleteFirst(){
        if( !IsEmpty() ){
            //DLLNode* deleteNode = head->Next();
            head->SetNext( head->Next()->Next() );
            delete head->Next()->Prev();
            head->Next()->SetPrev( head );
        }
    }

    void DeleteLast(){
        if( !IsEmpty() ){
            //DLLNode* deleteNode = head->Prev();
            head->SetPrev( head->Prev()->Prev() );
            delete head->Prev()->Next();
            head->Prev()->SetNext( head );
        }
    }

    DLLNode* head;
};

class StringSplitter{
public:
    StringSplitter( std::string& str ){
        std::string tmp("");
        for( int i = 0; i < str.size(); ++i ){
            if( str[i] == ' ' ){
                cmd = std::make_pair( tmp, std::stoi( &str[i+1] ) );
                return;
            }
            tmp += str[i];
        }
        cmdOnly = str;
        isStrOnly = true;
    }

    std::pair<std::string, int> GetPair(){
        return cmd;
    }

    std::string& GetStr(){
        return cmdOnly;
    }

    bool IsStringOnly(){
        return isStrOnly;
    }

private:
    std::pair<std::string, int> cmd;
    std::string cmdOnly;
    bool isStrOnly = false;
};

int main(){
    std::cin.tie(0);
    int n;
    std::cin >> n;

    DoublyLinkedList* list = new DoublyLinkedList();
    std::string command;
    StringSplitter* splt = nullptr;
