        std::getline( std::cin, command );
        if( !splt ){ delete splt; }
        splt = new StringSplitter(command);
        if( splt->IsStringOnly() ){
            list->DoCommand( splt->GetStr() );
        }else{
            list->DoCommand( splt->GetPair().first, splt->GetPair().second );
        }
    //list->Print();
    }

    list->Print();
}
