    if(x == 0) {
      int v = rbt.query(root, z, z + 1);
      rbt.erase(root, z);
      rbt.insert(root, y, v);
    } else if(x == 1) {
      printf("%d\n", rbt.query(root, y, z + 1));
    } else if(x == 2) {
      rbt.set_element(root, y, z);
    }
    if(rbt.pool.ptr < 50) root = rbt.build(rbt.dump(root));
  }
}
