#include <iostream>
#include <string>
#include <algorithm>
#include <boost/tokenizer.hpp>
#include <boost/lexical_cast.hpp>
#include <vector>
#include <map>

using namespace std;
using namespace boost;

static vector<vector<int>> mat0;
static map<tuple<int,int,int,int>,int> memo;

void clearPartial(int sh, vector<vector<int>>& mat)
{
	int h = 0;
	for( auto row : mat0 ) {
		if( sh < h ) {
			mat[h] = row;
		}
		h++;
	}
}		

int solve(int sh, int sw, int H, int W, vector<vector<int>>& mat, int f, int m, int o)
{
	auto tp = make_tuple(sh,sw,f,o);
	auto it = memo.find(tp);
	if( it != memo.end() ) {
		return it->second;
	}

	if( sw < 0 || sw == W || o <= 0 ) {
		//memo.insert(make_pair(tp,-1));		
		return -1;
	}

	int& v = mat[sh][sw];

	if( v < 0 ) {

		f += v;
		if( f < 0 ) {
			//memo.insert(make_pair(tp,-1));
			return -1;
		}

	} else if ( o < v ) {

		o = min(m, o + v);
	}

	v = 0;

	if( sh == H-1 ) {
		//memo.insert(make_pair(tp,f));
		return f;
	}

	int p;	
	int mf = -1;

	p = solve(sh, sw-1, H, W, mat, f, m, o-1);
	clearPartial(sh, mat);
	if( mf < p ){
		mf = p;
	}

	p = solve(sh, sw+1, H, W, mat, f, m, o-1);
	clearPartial(sh, mat);	
	if( mf < p ){
		mf = p;
	}		

	p = solve(sh+1, sw, H, W, mat, f, m, o-1);
	clearPartial(sh, mat);		
	if( mf < p ){
		mf = p;
	}

	memo.insert(make_pair(tp,mf));
	return mf;
}

int main(int argc, char* argv[])
{
	using sprtr = char_separator<char>;
	using tknzr = tokenizer<sprtr>;
	sprtr sep(" ", "", keep_empty_tokens);

	int f, mf, mo;

	string line;
	while( getline(cin, line) ) {

		tknzr tkns(line, sep);
		auto it = tkns.begin();
		auto W = lexical_cast<int>(*it++);
		auto H = lexical_cast<int>(*it);

		if( H == 0 && W == 0 ) {
			break;
		}

		int m, o;
		{
			getline(cin, line);
			tknzr tkns(line, sep);
			auto it = tkns.begin();
			f = lexical_cast<int>(*it++);
			m = lexical_cast<int>(*it++);
			o = lexical_cast<int>(*it);
		}

		mat0.clear();
		{
			for( int i = 0; i < H; i++ ) {
				vector<int> row;
				getline(cin, line);
				tknzr tkns(line, sep);
				for( auto xs : tkns ) {
					row.push_back(lexical_cast<int>(xs));
				}
				mat0.push_back(row);
			}
		}

		mf = -1;
		for( int sw = 0; sw < W; sw++ ) {
			auto mat = mat0;
			int p = solve(0, sw, H, W, mat, f, m, o-1);
			if( mf < p ){
				mf = p;
			}
			memo.clear();			
		}

		if( 0 <= f - mf && mf != -1 ) {
			cout << f - mf << endl;
		} else {
			cout << "NA" << endl;		
		}
	}

    return 0;
