#define F first
#define S second
const long long mod = 1000000007;

int N;
string s;
vector<pair<int, int> > vp; // 0--F  1--T
vector<int> hor, ver;
int xf, yf, xin = 0, yin = 0, abx, aby;

int dp[8005][18000];
void initialize() {
    for(int i = 0;i < 8005;i++) {
        for(int j = 0;j < 18000;j++) {
            dp[i][j] = -1;
        }
    }
}

bool possible(int i, vector<int> &A, int sum) {
    if(i == -1 and sum == 0) {
        return true;
    }
    if(i == -1) {
        return false;
    }

    if(dp[i][sum+8000] != -1) {
        return dp[i][sum+8000];
    }

    bool ans = possible(i-1, A, sum+A[i]) || 
               possible(i-1, A, sum-A[i]);

    return dp[i][sum+8000] = ans;
}

int main() {
    cin >> s;
    N = s.size();
    cin >> xf >> yf;
    int i = 0, j = 0;
    while(j < N) {
        if(s[j] == s[i]) {j++;continue;}
        vp.push_back({s[i] == 'T', j-i});
        i = j;
    }
    vp.push_back({s[i] == 'T', j-i});

    if(vp[0].F == 0) {
        xin = vp[0].S;
        vp.erase(vp.begin());
    }
    abx = abs(xf-xin);
    aby = abs(yf-yin);

    if(vp.size() != 0 && vp[vp.size()-1].F) {
        vp.pop_back();
    }

    if(vp.size() == 0) {
        if(abx == 0 and aby == 0) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
        return 0;
    }

    bool hori = 1;
    for(int i = 0;i < vp.size();i += 2) {
        if(vp[i].S % 2 != 0) hori = !hori;
        if(hori) hor.push_back(vp[i+1].S);
        else ver.push_back(vp[i+1].S);
    }

    initialize();
    bool ans = possible(hor.size()-1, hor, abx);
    initialize();
    ans = ans && possible(ver.size()-1, ver, aby);

    if(ans) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }


    return 0;
}
