class tree{
public:
  int node;
  int parent = -1;
  vector<int> child;
  tree(int n, int c){
    node = n;
    child.resize(c);
    for(int i=0; i<c; i++) cin >> child[i];
  }
};

int getdepth(vector<tree> t, int pos, int depth){
  if( t[pos].parent == -1 ){
    return depth;
  }else{
    return getdepth(t, t[pos].parent, depth+1);
  }
}

string gettype(tree t){
  if( t.parent == -1 ) return "root";
  else if( t.child.size() == 0 ) return "leaf";
  else return "internal node";
}

