queue<Pox> Q;

void init()
{
  while(!Q.empty())Q.pop();
  ice_number = 0;
  rep(i,h)rep(j,w)ice[j+i*w] = ice_cnt[j+i*w] = inf;
  //rep(i,h*w)rep(j,h*w)ev[i][j] = inf;
  mincost.clear();
}

void getInput()
{
  rep(i,h)
    {
      getchar();
      rep(j,w)
	{
	  scanf("%c",&g[i][j]);
	  if(g[i][j] == 'S')
	    {
	      st[1] = j + i * w;
	      g[i][j] = '.';
	    }
	  if(g[i][j] == 'G')
	    {
	      st[0] = j + i * w;
	      g[i][j] = '.';
	    }
	}
    }
}
