#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int N=1500;

struct info
{
    int x,y;
};
info nu[2*N*2*N+5];
int nr_nu;

int n,d1,d2;

bool viz[2*N+5][2*N+5];
info sol[2*N*2*N+5];
int cnt=0;

bool valid(int x,int y)
{
    if(0<=x && 0<=y && x<2*n && y<2*n)
        return 1;
    return  0;
}

bool verif(int x,int y)
{
    if(valid(x,y)==1 && viz[x][y]==1)
        return 1;
    return 0;
}

info tri[2*N*2*N+5];

bool cmp(info a,info b)
{
    int d1=a.x;
    int d2=a.y;
    int d3=2*n-1-a.x;
    int d4=2*n-1-a.y;
    int val_a=min(min(d1,d2),min(d3,d4));
    d1=b.x;
    d2=b.y;
    d3=2*n-1-b.x;
    d4=2*n-1-b.y;
    int val_b=min(min(d1,d2),min(d3,d4));
    return val_a<val_b;
}


int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin>>n>>d1>>d2;
    for(int i=0;i<=2*n;i++)
        for(int j=0;j<=2*n;j++)
        {
            int s=i*i+j*j;
            if(s==d1 || s==d2)
                nu[++nr_nu]={i,j};
        }
    int pozition=0;
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
            tri[++pozition]={i,j};
    sort(tri+1,tri+pozition+1,cmp);
    for(int p=1;p<=pozition;p++)
        {
            int i=tri[p].x;
            int j=tri[p].y;
            bool ok=1;
            for(int k=1;k<=nr_nu;k++)
            {
                int dx=nu[k].x;
                int dy=nu[k].y;
                if(verif(i-dx,j-dy)==1)
                {
                    ok=0;
                    break;
                }
                if(verif(i-dx,j+dy)==1)
                {
                    ok=0;
                    break;
                }
                if(verif(i+dx,j-dy)==1)
                {
                    ok=0;
                    break;
                }
                if(verif(i+dx,j+dy)==1)
                {
                    ok=0;
                    break;
                }
            }
            if(ok==0)
                continue;
            sol[++cnt]={i,j};
            viz[i][j]=1;
            if(cnt==n*n)
            {
                for(int i=1;i<=cnt;i++)
                {
                    cout<<sol[i].x<<" "<<sol[i].y<<"\n";
                }
                return 0;
            }
        }
    while(1)
    {
        cout<<"ERROR\n";
    }
    return 0;
}
