void input() {
	cin >> n >> k;
	vec.resize(n);
	for (auto &cur : vec) cin >> cur;

	ll cur = 1;
	if (n % 2 == 0) cur = 0;
	need.resize(n);
	for (int i = 0; i < vec.size(); i++) {
		if (cur) {
			need[i] = 'A';
		}
		else {
			need[i] = 'B';
		}
		cur = !cur;
	}
}

void play2() {
	if (vec[0] == 'A') {
		vec[0] = 'B';
		return;
	}

	if (vec.back() == 'B') {
		vec.back() = 'A';
	}
	for (int i = 1; i < vec.size(); i++) {
		if (vec[i - 1] == vec[i]) {
			if (vec[i - 1] == 'A') {
				vec[i - 1] = 'B';
			}
			else {
				vec[i - 1] = 'A';
			}
		}
	}
}

void play() {
	if (vec[0] == 'A') {
		vec[0] = 'B';
		return;
	}
	ll x = 0, side = 1;
	while (x >= 0 && x < vec.size()) {
		if (side == 1) {
			if (vec[x] == 'A') {
				side = 0;
				vec[x] = 'B';
				x--;
			}
			else {
				side = 1;
				vec[x] = 'A';
				x++;
			}

		}
		else {
			if (vec[x] == 'A') {
				side = 1;
				vec[x] = 'B';
				x++;
			}
			else {
				side = 0;
				vec[x] = 'A';
				x--;
			}
		}
	}

	for (auto cur : vec) cout << cur;
	if (x < 0) {
		cout << " front";
	}
	else {
		cout << " back";
	}
	cout << "\n";
}

void rand_test() {
	n = rand() % 1000 + 1, k = rand() % 10000;
	vec.resize(n);
	for (int i = 0; i < n; i++) {
		vec[i] = ('A' + rand() % 2);
	}

	ll cur = 1;
	if (n % 2 == 0) cur = 0;
	need.resize(n);
	for (int i = 0; i < vec.size(); i++) {
		if (cur) {
			need[i] = 'A';
		}
		else {
			need[i] = 'B';
		}
		cur = !cur;
	}
}

ll find_k() {
	ll cnt = 0;
	while (need != vec) {
		cnt++;
		play();
	}

	return cnt;
}

