		lst = vec.back();
		vec.pop_back();
		add.push_back(pr);
		if (pr == 'A') {
			pr = 'B';
		}
		else {
			pr = 'A';
		}
	}
	if (add.size() > 0 && add.back() == 'A') {
		add.pop_back();
		vec.push_back(lst);
	}
	reverse(add.begin(), add.end());
	if (vec.size() > 0) {
		while (k > 0) {
