#include<stdio.h>
int d[3][16];
int x;
int i,j,k;
int m,n;
int ans=0;
int goal;
int now[3];
int p,q;

int other(int a,int b){
	if(a==0&&b==1)return 2;
	if(b==0&&a==1)return 2;
	if(a==0&&b==2)return 1;
	if(b==0&&a==2)return 1;
	if(a==1&&b==2)return 0;
	if(b==1&&a==2)return 0;
}

void move(int n,int a,int b,int to){
start:
	if(ans>m)return;
	if(n!=d[a][b])return;
	printf("%d %d %d\n",a,b,to);
	for(int k=0;k<3;k++){
		for(int l=0;l<16;l++)if(d[k][l]>0)printf("%d ",d[k][l]);
		printf("\n");
	}
	if(to-a==2||a-to==2){
		printf("1\n");
		move(d[a][b],a,b,1);
		move(d[1][now[1]-1],1,now[1]-1,to);
		if(now[a]==0)return;
		if(d[a][b]==-1)b=now[a]-1;
		goto start;
	}
	if(d[a][b+1]>0){
		printf("2\n");
		move(d[a][b+1],a,b+1,other(a,to));
		if(now[a]==0)return;
		if(d[a][b]==-1)b=now[a]-1;
		goto start;
	}
	if(now[to]>=1&&d[to][now[to]-1]>d[a][b]){
		printf("3\n");
		move(d[to][now[to]-1],to,now[to]-1,other(a,to));
		if(now[a]==0)return;
		if(d[a][b]==-1)b=now[a]-1;
		goto start;
	}
	d[to][now[to]++]=d[a][b];
	d[a][b]=-1;
	now[a]--;
	ans++;
}

int main(){
	while(1){
		scanf("%d %d",&n,&m);
		if(n==0&&m==0)break;
		ans=0;
		for(i=0;i<3;i++)for(j=0;j<16;j++)d[i][j]=-1;
		for(i=0;i<3;i++){
			scanf("%d",&x);
			for(j=0;j<x;j++){
				scanf("%d",&d[i][j]);
			}
			now[i]=x;
		}
		for(i=0;i<n;i++){
			if(i==0){
				if(d[1][0]==1){
					if(d[2][0]>d[0][0]){
						if(now[0]==0)goal=0;
						else goal=2;
					}
					else{
						if(now[2]==0)goal=2;
						else goal=0;
					}
				}
				else if(d[0][0]==1)goal=0;
				else goal=2;
			}
			p=-1;q=-1;
			for(j=0;j<3;j++)for(k=0;k<16;k++)if(d[j][k]==i+1){p=j;q=k;}
			if(p!=-1&&q!=-1)if(p!=goal)move(i+1,p,q,goal);
			if(ans>m)break;
		}
		if(ans<=m)printf("%d\n",ans);
		else printf("-1\n");
	}
},output_limit_exceeded,,p00426

