#include <iostream>
#include <vector>
#include <math.h>
#include <stdio.h>
#include <algorithm>
#include <string>
#include <map>
#include <queue>
#include <memory.h>
using namespace std;
int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

int W, H, N;
int X1[1000], X2[1000], Y1[1000], Y2[1000];

bool fld[1000 * 6][1000 * 6];

int compress(int *x1, int *x2, int w) {
  vector<int> xs;

  for(int i = 0; i < N; i++) {
    for(int d = -1; d <= 1; d++) {
      int tx1 = x1[i] + d, tx2 = x2[i] + d;
      if(0 <= tx1 && tx1 < w) xs.push_back(tx1);
      if(0 <= tx2 && tx2 < w) xs.push_back(tx2);
    }
  }
  sort(xs.begin(),xs.end());
  xs.erase(unique(xs.begin(),xs.end()),xs.end());

  for(int i = 0; i < N; i++) {
    x1[i] = find(xs.begin(),xs.end(),x1[i]) - xs.begin();
    x2[i] = find(xs.begin(),xs.end(),x2[i]) - xs.begin();
  }
  return xs.size();
}

void solve() {
  W = compress(X1,X2,W);
  H = compress(Y1,Y2,H);

  memset(fld,0,sizeof(fld));

  for(int i = 0; i < N; i++) {
    for(int y = Y1[i]; y <= Y2[i]; y++) {
      for(int x = X1[i]; x <= X2[i]; x++) {
        printf("%d %d",y,x);
        fld[y][x] = true;
      }
    }
  }


  int ans = 0;
  for(int y = 0; y < H; y++) {
    for(int x = 0; x < W; x++) {
      if(fld[y][x]) continue;
      ans++;

      queue<pair<int,int> > que;
      que.push(make_pair(x,y));
      while(!que.empty()) {
        int sx = que.front().first, sy = que.front().second;
        que.pop();

        for(int i = 0; i < 4; i++) {
          int tx = sx + dx[i], ty = sy + dy[i];
          if(tx < 0 || ty < 0 || tx >= W || ty >= H) continue;
          if(fld[ty][tx]) continue;
          que.push(make_pair(tx,ty));
          fld[ty][tx] = true;
        }
      }
    }
  }
  printf("%d\n",ans-1);
}


int main() {
  while(1) {
    scanf("%d %d",&W,&H);
    if(W == 0 && H == 0) break;
    scanf("%d",&N);
    for(int i = 0; i < N; i++) {
      scanf("%d %d %d %d",&X1[i],&Y1[i],&X2[i],&Y2[i]);
    }
    solve();
  }
},output_limit_exceeded,,p00454

#include <cstdio>
#include <vector>
#include <map>
#include <utility>
#include <algorithm>
#include <queue>

using namespace std;

int h,w,n;
int ww,hh;
vector< pair< pair<int,int>,pair<int,int> > > tp;
map<int,int> xx;
map<int,int> yy;

bool** d;

bool** newd(int w,int h){
	bool** r = new bool*[w];
	for(int i=0;i<w;i++){
		r[i] = new bool[h];
	}
	return r;
}

void deld(bool** r,int w,int h){
	for(int i=0;i<w;i++){
		delete[] r[i];
	}
	delete[] r;
}

void paint(int x,int y,int w,int h,bool c){
	//printf("paint:(%d,%d),%dx%d\n",x,y,w,h);
	for(int i=0;i<w;i++){
		for(int j=0;j<h;j++){
			//printf("%d+%d,%d+%d\n",x,i,y,j);
			d[x + i][y + j] = c;
		}
	}
}
void paint(pair< pair<int,int>,pair<int,int> > p,bool c){
	int x,y,w,h;
	x = xx[p.first.first];
	y = yy[p.first.second];
	w = xx[p.second.first] - x;
	h = yy[p.second.second] - y;
	paint(x,y,w,h,c);
}

void solve(int x,int y){
	queue< pair<int,int> > que;
	que.push( pair<int,int>(x,y) );
	pair<int,int> v[4] = {
		pair<int,int>(1,0),
		pair<int,int>(-1,0),
		pair<int,int>(0,1),
		pair<int,int>(0,-1)
	};
	pair<int,int> p,pp;
	while(que.size()>0){
		p = que.front();
		//printf("%d,%d\n",p.first,p.second);
		que.pop();
		for(int i=0;i<4;i++){
			pp.first = p.first + v[i].first;
			pp.second = p.second + v[i].second;
			if(pp.first < 0 || pp.first >= w || pp.second < 0 || pp.second >= h){continue;}
			if(d[pp.first][pp.second] == false){
				d[pp.first][pp.second] = true;
				que.push(pp);
			}
		}
	}
}

void dep(){
	for(int j=0;j<h;j++){
		for(int i=0;i<w;i++){
			if(d[i][j] == false){
				printf(".");
			}else{
				printf("#");
			}
		}
		printf("\n");
	}
	printf("\n");
}

int main(){
	int a,b,c,dd;
	while(scanf("%d %d",&ww,&hh) && (ww || hh)){
		tp.clear();
		scanf("%d",&n);
		vector<int> vx;
		vector<int> vy;
		for(int i=0;i<n;i++){
			scanf("%d %d %d %d",&a,&b,&c,&dd);
			tp.push_back(
				pair< pair<int,int>,pair<int,int> >(
					pair<int,int>(a,b),
					pair<int,int>(c,dd)
				)
			);
			vx.push_back(a);
			vx.push_back(c);
			vy.push_back(b);
			vy.push_back(dd);
		}
		sort(vx.begin(),vx.end());
		sort(vy.begin(),vy.end());
		vx.erase(unique(vx.begin(),vx.end()),vx.end());
		vy.erase(unique(vy.begin(),vy.end()),vy.end());
		xx.clear();
		yy.clear();
		for(int i=0;i<vx.size();i++){
			xx[vx[i]] = i;
		}
		for(int i=0;i<vy.size();i++){
			yy[vy[i]] = i;
		}
		w = vx.size() - 1;
		h = vy.size() - 1;

		d = newd(w,h);
		//printf("%dx%d\n",w,h);
		paint(0,0,w,h,false);

		for(int i=0;i<n;i++){
			paint(tp[i],true);
		}
		//puts("A");
		int ans = 0;
		dep();
		for(int j=0;j<h;j++){
			for(int i=0;i<w;i++){
				if(d[i][j] == false){
					solve(i,j);
					ans++;
					dep();
				}
			}
		}
		printf("%d\n",ans);
		deld(d,w,h);
	}
},output_limit_exceeded,,p00454

