#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <algorithm>
#include <cmath>
using namespace std;

int tree[16450000];

void build(int x,int y,int num,int lx,int rx,int ly,int ry,int pos)
{
    if(lx==rx&&ly==ry)
    {
        tree[pos]=num;
        return;
    }
    int midx=(lx+rx)/2,midy=(ly+ry)/2;
    if(x<=midx&&y<=midy)
    {
        build(x,y,num,lx,midx,ly,midy,pos*4);
        if(tree[pos]==-1||tree[pos*4]<tree[pos])
            tree[pos]=tree[pos*4];
    }
    if(x<=midx&&y>midy&&ly!=ry)
    {
        build(x,y,num,lx,midx,midy+1,ry,pos*4+1);
        if(tree[pos]==-1||tree[pos*4+1]<tree[pos])
            tree[pos]=tree[pos*4+1];
    }
    if(x>midx&&y<=midy&&lx!=rx)
    {
        build(x,y,num,midx+1,rx,ly,midy,pos*4+2);
        if(tree[pos]==-1||tree[pos*4+2]<tree[pos])
            tree[pos]=tree[pos*4+2];
    }
    if(x>midx&&y>midy&&lx!=rx&&ly!=ry)
    {
        build(x,y,num,midx+1,rx,midy+1,ry,pos*4+3);
        if(tree[pos]==-1||tree[pos*4+3]<tree[pos])
            tree[pos]=tree[pos*4+3];
    }
    return;
}

int query(int x,int y,int xx,int yy,int lx,int rx,int ly,int ry,int pos)
{
    if(x<=lx&&xx>=rx&&y<=ly&&yy>=ry)
        return tree[pos];
    if(lx==rx&&ly==ry)
        return tree[pos];
    int midx=(lx+rx)/2,midy=(ly+ry)/2;
    int now=-1,temp;
    if(x<=midx&&y<=midy)
    {
        temp=query(x,y,xx,yy,lx,midx,ly,midy,pos*4);
        if((temp!=-1)&&(now==-1||temp<now))
            now=temp;
    }
    if(x<=midx&&yy>midy&&ly!=ry)
    {
        temp=query(x,y,xx,yy,lx,midx,midy+1,ry,pos*4+1);
        if((temp!=-1)&&(now==-1||temp<now))
            now=temp;
    }
    if(xx>midx&&y<=midy&&lx!=rx)
    {
        temp=query(x,y,xx,yy,midx+1,rx,ly,midy,pos*4+2);
        if((temp!=-1)&&(now==-1||temp<now))
            now=temp;
    }
    if(xx>midx&&yy>midy&&lx!=rx&&ly!=ry)
    {
        temp=query(x,y,xx,yy,midx+1,rx,midy+1,ry,pos*4+3);
        if((temp!=-1)&&(now==-1||temp<now))
            now=temp;
    }
    printf("%d %d %d %d %d %d %d %d %d\n",x,y,xx,yy,lx,rx,ly,ry,now);
    return now;
}

int main()
{
    //freopen("in.txt","r",stdin);
    //freopen("out1.txt","w",stdout);
    int n,m,q,i,j,x,y,xx,yy;
    while(scanf("%d%d%d",&n,&m,&q)==3)
    {
        if(!n&&!m&&!q)
            break;
        memset(tree,-1,sizeof(tree));
        for(i=1;i<=n;i++)
            for(j=1;j<=m;j++)
            {
                scanf("%d",&x);
                build(i,j,x,1,n,1,m,1);
            }
        while(q--)
        {
            scanf("%d%d%d%d",&x,&y,&xx,&yy);
            printf("%d\n",query(x+1,y+1,xx+1,yy+1,1,n,1,m,1));
        }
    }
    return 0;
