using namespace std;
typedef pair<double, double> pt;
const double EPS = 1e-4;
#define x first
#define y second

double sq(double a) { return a * a; }

double dist(pt p, pt q) {
  return sqrt(sq(p.x - q.x) + sq(p.y - q.y));
}

bool lessthan(double a, double b) {
    if (a - b <= EPS)
        return true;
    return false;
}

pt midpoint(pt a, pt b) {
    return pt((a.x + b.x)/2, (a.y + b.y)/2);
}

pt operator+(pt a, pt b) {
    return pt(a.x + b.x, a.y + b.y);
}

pt operator-(pt a, pt b) {
  return pt(a.x - b.x, a.y - b.y);
}

pt operator*(pt a, double b) {
    return pt(a.x * b, a.y * b);
}

pt rotate(pt p, double a) {
  pt res;
  res.x = p.x * cos(a) - p.y * sin(a);
  res.y = p.x * sin(a) + p.y * cos(a);
  return res;
}



const int maxn = 300;
pt pts[maxn + 1];

int main() {
    int N;

    cin >> N;

    int maxcount = -1;
    while (N != 0) {
        if (maxcount != -1)
            cout << maxcount << endl;
        for (int i = 0; i < N; ++i) {
            double x, y;
            cin >> x >> y;
            pts[i] = pt(x, y);
        }
        maxcount = 0;
        for (int i = 0; i < N ; i++){
            for (int j = 0; j < N; j++) {
                if (j == i) continue;
                // for every pair of points
                if (dist(pts[i], pts[j]) > 2) continue;
                pt A = pts[i];
                pt B = pts[j];
                cout << "for points " << A.x << " " << A.y << " b: " << B.x << " "<< B.y << endl;
                pt M = midpoint(A, B);
                //cout << " M is " << M.x << " " << M.y << endl;
                pt BM = M - B;
                double distBM = dist(B,M);
                //cout << "dist BM " << distBM << endl; 
                double alpha = acos(distBM);
                pt BK = rotate(BM, alpha);
                pt BC = BK * (1 / distBM);
                pt C = B + BC;
                cout << "C is  "<< C.x << " " << C.y << endl;
                int count = 2;
                for (int k = 0; k < N; k++) {
                    if (k == i || k == j) continue;
                    if (lessthan(dist(C, pts[k]), 1)) count++; 
                }
                maxcount = max(count, maxcount);
            }
        }

        cin >> N;
    }
    cout << maxcount;

    return 0;
}
