					vx[i]=ivx;vy[i]=ivy;
				}
				else V.push_back(info(i,beftime,ivx,ivy));
				if(time==T) break;
				beftime=time;
			}
		}
		sort(V.begin(),V.end());

		ok[0]=true;
		for(int i=0;i<N;i++){//最初から通信しているところを列挙
			if(!ok[i]) continue;
			for(int j=0;j<N;j++){
				if(i==j) continue;
