#include <bits/stdc++.h>
using namespace std;
const int N = 200000;

inline int read()
{
	char c = getchar(); int f = 1, x = 0;
	while( c < '0' || c>'9' ) { if(c == '-') f = -1;  c = getchar(); }
	while( c >= '0'&&c<='9' ) { x = x * 10 + c - '0'; c = getchar(); }
	return f * x;
}

int n, tot = 0, front[N];

struct tEdge {
    int v, next;
    inline void init( int _u, int _v ) {
        v = _v; 
        next = front[_u];
        front[_u] = tot;
    }
} e[N<<1];

inline void add_edge( int u, int v ) {
    e[++tot].init( u, v );
    e[++tot].init( v, u );
}

int top_dep = 0, top_id = 0, dep[N], size[N];

void dfs( int u, int fa )
{
    size[u] = 1; dep[u] = dep[fa] + 1; 
    if( dep[u] > top_dep ) 
        top_dep = dep[u], top_id = u; 

    for( int i = front[u]; i; i = e[i].next ) 
        if( e[i].v != fa ) dfs( e[i].v, u ), size[u] += size[e[i].v];
}

bool check( int u, int fa )
{
    bool flag = false;
    for( int i = front[u]; i; i = e[i].next )
    {
        int v = e[i].v;
        if( v == fa ) continue;  

        if( size[v] > 1 && flag ) return false;
        if( size[v] > 1 ) flag = true;
        if( !check( v, u ) ) return false; 
    } 
    return true;
}

int calc_len( int u, int fa )
{
	int ret = 0;
    for( int i = front[u]; i; i = e[i].next )
    {
        int v = e[i].v;
        if( v == fa ) continue;

        if( size[v] <= 1 ) return 0; 
        ret = calc_len( v, u ) + 1;
    } 
    return ret;
}

int top, tail, top_len, tail_len;

void print( int u, int fa, int now )
{
    int next, sum;
    for( int i = front[u]; i; i = e[i].next )
    {
        int v = e[i].v;
        if( v == fa ) continue;

        if( size[v] >= 2 ) next = v;
        else sum ++;
    }

	if( !next ) 
	{
		for( int i = 1; i <= sum-1; i ++ )
			printf( "%d ", now+i );
		if( !sum )printf( "%d\n", now );
		else printf( "%d %d\n", now, now+sum );
		return;
	}

    for( int i = 1; i <= sum; i ++ )    
        printf( "%d ", now + i );
    printf( "%d ", now );

    print( next, u, now+sum+1 );
}

int main()
{
    n = read();
    for( int i = 1; i < n; i ++ )
        add_edge( read(), read() );

    dfs( 1, 0 ); top = top_id; 
    memset( size, 0, sizeof( size ) ); 
    memset( dep, 0, sizeof( dep ) );

    dfs( top, 0 ); tail = top_id;

    if( !check( top, 0 ) ) {
        printf( "-1\n" ); return 0;
    }

    top_len = calc_len( top, 0 ); 
    tail_len = calc_len( tail, 0 );

    top = top_len >= tail_len ? top : tail;
    print( top, 0, 1 );

    return 0;
},output_limit_exceeded,,p03384

