	return sum[x2][y2] + sum[x1 - 1][y1 - 1] - sum[x1 - 1][y2] - sum[x2][y1 - 1];
}

P dp[40][40][40][40];

P rec(int x1,int y1,int x2,int y2){
	if(dp[x1][y1][x2][y2].first != -1) return dp[x1][y1][x2][y2];
	cout << x1 << " " << y1 << " " << x2 << " " << y2 << " " << get_sum(x1,y1,x2,y2) << endl;
	P res = {1 , s - (sum_all - get_sum(x1,y1,x2,y2))};
	for(int i = x1;i < x2;i++){
		if(sum_all - get_sum(x1, y1, i, y2) > s) continue;
		if(sum_all - get_sum(i + 1,y1,x2,y2) > s) continue;
		P l = rec(x1, y1, i, y2);
		P r = rec(i + 1,y1,x2,y2);
		P ans = {l.first + r.first,min(l.second,r.second)};
		res = max(res,ans);
	}
	for(int i =  y1;i < y2;i++){
		if(sum_all - get_sum(x1,y1,x2,i) > s) continue;
		if(sum_all - get_sum(x1,i + 1,x2,y2) > s) continue;
		P l = rec(x1,y1,x2,i);
		P r = rec(x1,i + 1,x2,y2);
		P ans = {l.first + r.first , min(l.second , r.second)};
		res = max(res,ans);
	}

	return dp[x1][y1][x2][y2] = res;
}


int main(){
	while(cin >> h >> w >> s,h || w || s){
		sum_all = 0;
		rep(i,1,h)rep(j,1,w) cin >> c[i][j];
		rep(i,1,h)rep(j,1,w) sum_all += c[i][j];
		rep(i,1,h)rep(j,1,w) sum[i][j] = sum[i - 1][j] + c[i][j];
		rep(i,1,h)rep(j,1,w) sum[i][j] += sum[i][j - 1];
		rep(i,1,h)rep(j,1,w)rep(k,1,h)rep(l,1,h) dp[i][j][k][l].first = dp[i][j][k][l].second = -1;
		cout << rec(1,1,h,w).first << " " << rec(1,1,h,w).second << endl;;
	}
}

