#include <fstream>
#include <sstream>
class svg {
	ofstream f;
	stringstream s;
	double x1 = 1e9, y1 = 1e9, x2 = -1e9, y2 = -1e9;
public:
	svg(string path) :f(path, ios::trunc) {
	}
	~svg(){
		f << "<?xml version=\"1.0\" standalone=\"no\"?><svg viewBox='"<<x1*1.1-x2*0.1<<" "<<y1*1.1-y2*0.1<<" "<<(x2-x1)*1.2<<" "<<(y2-y1)*1.2<<"' xmlns = \"http://www.w3.org/2000/svg\" xmlns:xlink = \"http://www.w3.org/1999/xlink\" >\n";
		f << s.str();
		f << "</svg>";
	}
	void circle(C c) {
		s << fixed << "<circle cx = \"" << c.p.real() << "\" cy = \"" << c.p.imag() << "\" r = \"" << c.r << "\" stroke=\"black\" stroke-width=\"0.01\" fill = \"none\"/>\n";
		cmin(x1, c.p.real() - c.r);
		cmin(y1, c.p.imag() - c.r);
		cmax(x2, c.p.real() + c.r);
		cmax(y2, c.p.imag() + c.r);
	}
	void line(L l) {
		s << fixed << "<line x1=\"" << l.a.real() << "\" y1=\"" << l.a.imag() << "\" x2=\"" << l.b.real() << "\" y2=\"" << l.b.imag() << "\" stroke=\"black\" stroke-width=\"0.01\"/>\n";
		cmin(x1, l.a.real());
		cmin(y1, l.a.imag());
		cmax(x2, l.a.real());
		cmax(y2, l.a.imag());
		cmin(x1, l.b.real());
		cmin(y1, l.b.imag());
		cmax(x2, l.b.real());
		cmax(y2, l.b.imag());
	}
};
