int dx[] = {0, 1, 0, -1};
int dy[] = {1, 0, -1, 0};

void compress(int n)
{
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  x.erase(unique(x.begin(), x.end()), x.end());
  y.erase(unique(y.begin(), y.end()), y.end());
  for(int i = 0; i < n; i++){
    l[i] = find(x.begin(), x.end(), l[i]) - x.begin();
    t[i] = find(y.begin(), y.end(), t[i]) - y.begin();
    r[i] = find(x.begin(), x.end(), r[i]) - x.begin();
    b[i] = find(y.begin(), y.end(), b[i]) - y.begin();    
  }
}

void dfs(int yy, int xx)
{
  int c = sum[yy][xx];
  sum[yy][xx] = 0;
  for(int i = 0; i < 4; i++){
    int nx = xx + dx[i], ny = yy + dy[i];
    if(0 <= nx && nx < x.size() && 0 <= ny && ny < y.size() && sum[ny][nx] == c) dfs(ny, nx);
  }
}

