      sum[t[i]][l[i]] += 1;
      sum[b[i]+1][l[i]] -= 1;
      sum[t[i]][r[i]+1] -= 1;
      sum[b[i]+1][r[i]+1] += 1;
    }
    for(int i = 0; i < y.size(); i++){
      for(int j = 1; j < x.size(); j++){
	sum[i][j] += sum[i][j-1];
      }
