#include<iostream>
#include<string>
#include<algorithm>
#include<map>
using namespace std;
#define rep(i,a,b) for(auto (i)=(a);(i)<(b);(i)++)
#define rev(i,a,b) for(auto (i)=(b)-1;(i)>=(a);(i)--)
#define num_check(x) '0'<=(x)&&(x)<='9'


struct Siki{
	int num;
	int depth;
	char type;
	int left, right;

};

int pri[10];//各演算子の計算順序
int min_pri[6];//各演算子のdepthごとの計算順序の最低値、これを破るとNG
Siki siki[12];
Siki temp[12];//作業用配列
int s_size;
string input;
map<int, int> data;

bool check_pri(){
	rep(i, 0, s_size){
		if (min_pri[siki[pri[i]].depth] > i)
			return(false);
	}
	return(true);
}

void init(){
	//初期化
	data.clear();
	rep(i, 0, 12)siki[i].num = 0;
	rep(i, 0, 6)min_pri[i] = 0;
	int d = 0; 
	s_size = 0;

	//入力を作業用に変換
	rep(i, 0u, input.length()){
		if (num_check(input[i])){
			siki[s_size].num *= 10;
			siki[s_size].num += input[i] - '0';
		}
		else if (input[i] == '(')d++;//()の中に入るので深さを増加
		else if (input[i] == ')')d--;//深さを減少
		else
		{
			siki[s_size].type = input[i];
			siki[s_size].depth = d;
			pri[s_size] = s_size;
			rep(j, d + 1, 6)
				min_pri[j]++;
			s_size++;
		}
	}
	siki[s_size].type = '\0';//終端記号
	rep(i, 0, s_size){
		//連結リスト構造の作成
		siki[i].right = i+1;
		siki[i + 1].left = i;
	}
	siki[0].left = siki[s_size].right = -1;//左端、右端の保護

}

//2項計算する関数
int calc(int l, char op, int r){
	switch (op){
	case '+':return(l + r);
	case '-':return(l - r);
	case '*':return(l * r);
	case '/':return(l / r);
	}
	return(0);
}


void parse(){
	Siki *p,*r,*l;
	rep(i, 0, s_size+1)temp[i] = siki[i];//作業用配列にコピー
	rev(i, 0, s_size){
		p = &temp[pri[i]];
		l = &temp[p->left];
		r = &temp[p->right];

		if (r->num == 0 && p->type == '/')return;//0除算を省く
		printf("%d%c%d=", p->num, p->type, r->num);
		r->num = calc(p->num, p->type, r->num);
		printf("%d\n", r->num);
		r->left = p->left;
		if (l->left >=0 )l->right = p->right;

	}
	cout << temp[s_size].num << endl;
	data[temp[s_size].num]++;
}

//順列を効率的に列挙するための関数
void p(int d, int dm){
	if (d == dm){
		if (check_pri()){
			parse();
		}
	}
	rep(i, d, dm){
		swap(pri[d], pri[i]);
		p(d + 1, dm);
		swap(pri[d], pri[i]);
	}
}

int main(void){
	while (true){
		cin >> input;
		if (input[0] == '#')break;
		init();
		/*	
		rep(i, 0, siki_size)if (siki[i].type == 'c')printf("%d", siki[i].num); else printf("%c", siki[i].type); cout << endl;
		rep(i, 0, op_size)printf("%c", siki[index[i]].type); cout << endl;
		rep(i, 0, op_size)printf("%d", min_pri[siki[index[i]].num]); cout << endl;
		*/
		p(0, s_size);
		cout << data.size() << endl;
	}
	return(0);
},output_limit_exceeded,,p01372

