#include<bits/stdc++.h>
using namespace std;
typedef long double D;
typedef pair<D,int> pdi;

const D EPS = 1e-10;
D px[220],py[220],pz[220],vx[220],vy[220],vz[220],r[220],vr[220];

vector<D> cal(int a, int b){
  vector<D> res;

  D dpx = px[a]-px[b], dpy = py[a]-py[b], dpz = pz[a]-pz[b], dpv = r[a]+r[b];
  D dtx = vx[a]-vx[b], dty = vy[a]-vy[b], dtz = vz[a]-vz[b], dtv = vr[a]+vr[b];
  cout << dpx << " " << dpv << endl;
  D A = dtx*dtx + dty*dty + dtz*dtz - dtv*dtv;
  D B = 2*dtx*dpx + 2*dty*dpy + 2*dtz*dpz + 2*dtv*dpv;
  D C = dpx*dpx + dpy*dpy + dpz*dpz - dpv*dpv;

  if(abs(A)<EPS){
    if(abs(B)<EPS)return res;
    else{
      D t = -C/B;
      if(t>-EPS)res.push_back(t);
      return res;
    }
  }

  D d = B*B-4*A*C;
  if(d<-EPS)return res;
  if(abs(d)<EPS){
    D t = -B/2/A;
    if(t>-EPS)res.push_back(t);
    return res;
  }

  D t1 = (-B-sqrt(d))/(2*A);
  D t2 = (-B+sqrt(d))/(2*A);
  if(t1>-EPS){
    res.push_back(t1); 
    return res;
  }else if(t2>-EPS){
    res.push_back(t2); 
    return res;
  }
  return res;
}

int main(){
  int n;
  while(cin >> n, n){
    priority_queue<pdi> q;

    for(int i=0;i<n;i++){
      cin >> px[i] >> py[i] >> pz[i] >> vx[i] >> vy[i] >> vz[i] >> r[i] >> vr[i];
      q.push( pdi(-r[i]/vr[i], i) );
    }

    for(int i=0;i<n;i++){
      for(int j=0;j<i;j++){
	vector<D> tmp = cal(i,j);
	for(D t : tmp){
	  q.push( pdi(-t, (i+1)*n + j) );
	}
      }
    }

    vector<D> ans(n);
    vector<int> del(n,0);
    while(q.size()){
      D t = -q.top().first;
      int id = q.top().second;
      q.pop();

      int id1 = id%n, id2 = id/n-1;
      if(id2<0){
	if(!del[id1]){
	  ans[id1] = t;
	  del[id1] = 1;
	}
      }else{
	if(!del[id1] && !del[id2]){
	  ans[id1] = t; ans[id2] = t;
	  del[id1] = 1; del[id2] = 1;
	}
      }
    }

    for(int i=0;i<n;i++){
      cout << fixed << setprecision(10) << ans[i] << endl;
    }
  }
