int a[N];
int f[N];
int c[N];
int fact[N];
int ifact[N];
int dp[1000][1000];

int comb(int n, int k)
{
    return mul(fact[n], mul(ifact[k], ifact[n - k]));
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    fact[0] = 1;
    for (int i = 1; i < N; i++)
    {
        fact[i] = mul(fact[i - 1], i);
    }
    ifact[N - 1] = dv(1, fact[N - 1]);
    for (int i = N - 2; i >= 0; i--)
    {
        ifact[i] = mul(ifact[i + 1], i + 1);
    }

    cin >> n;
    map<int, int> f;
    for (int i = 1; i <= 2 * n; i++)
