int connect(int n, list<pair<pair<int,int>, int> > cord, vector<int> &linked, int current, int res, list<pair<pair<int,int>, int> >::iterator it)
{
    linked.pb(current);
    res++;
    int x = (*it).fi.fi, y = (*it).fi.se;
    for (list<pair<pair<int,int>, int> >::iterator it1 = cord.begin(); it1 != cord.end(); it1++)
        cout << (*it1).se << ' ' << (*it1).fi.fi << ' ' << (*it1).fi.se << '\n';
    cout << '\n';
    cord.erase(it);
    for (list<pair<pair<int,int>, int> >::iterator it1 = cord.begin(); it1 != cord.end(); it1++)
        cout << (*it1).se << ' ' << (*it1).fi.fi << ' ' << (*it1).fi.se << '\n';
    cout << '\n';
    system("PAUSE");
    for (it = cord.begin(); it != cord.end(); it++)
    {
        //printf("%d ", (*it).se);
        if ((*it).fi.fi > x && (*it).fi.se > y || (*it).fi.fi < x && (*it).fi.se < y)
            connect (n, cord, linked, (*it).se, res, it);
    }
    return res;
}

void solve(int n, list<pair<pair<int,int>, int> > cord, int solution[])
{
    for (list<pair<pair<int,int>, int> >::iterator it = cord.begin(); it != cord.end();)
    {
        vector<int> linked;
        int res = connect(n, cord, linked, (*it).se, 0, it);
        it = cord.begin();
        for (int i = 0; i < res; i++)
        {
            solution[linked[i]] = res;
        }
        printf("%dsmh",(*it).se);
        system("PAUSE");
    }
    return ;
}

