const int N=300005;

struct node{
    int a=0;
    node (int val=0){
        a=val;
    }
    void merge(node &n1,node &n2){
        this->a=n1.a+n2.a;
    }
};
struct update{
  int val=0;
  update(int t=0){
     val=t;
  }
  void combine(update &par,int tl,int tr){
      val=par.val;
  }
  void apply(node &node){
      node.a=val;
      val=0;
  }
};
template<typename node,typename update>
struct segtree{
  node t[4*N];
  bool lazy[4*N];
  update zaker[4*N];
  int tl[4*N];
  int tr[4*N];
  node nul;
  inline void pushdown(int v){
     if(lazy[v]){    
       apply(zaker[v],v);
       lazy[v]=0;
       zaker[v].apply(t[v]);
     }
  }
  inline void apply(update &u,int v){
      if(tl[v]!=tr[v]){
          lazy[2*v]=lazy[2*v+1]=1;
          zaker[2*v].combine(u,tl[2*v],tr[2*v]);
          zaker[2*v+1].combine(u,tl[2*v+1],tr[2*v+1]);
      }
  }
  void build(int v,int start,int end){
      tl[v]=start;
      tr[v]=end;
      if(start==end){
          t[v].a=1;
      }
      else{
          int m=(start+end)/2;
          build(2*v,start,m);
          build(2*v+1,m+1,end);
          t[v].merge(t[2*v],t[2*v+1]);
     }
  }
  void zeno(int v,int l,int r,update val){
      pushdown(v);
      if(tr[v]<l || tl[v]>r)return;
      if(l<=tl[v] && tr[v]<=r){
            t[v].a=val.val;
            apply(val,v); 
            return;
      }
      zeno(2*v,l,r,val);
      zeno(2*v+1,l,r,val);
      t[v].merge(t[2*v],t[2*v+1]);
  }
  node query(int v,int l,int r){
      if(tr[v]<l || tl[v]>r)return nul;
      pushdown(v);
      if(l<=tl[v] && tr[v]<=r){
         return t[v];
      }
      node a=query(2*v,l,r);
      node b=query(2*v+1,l,r);
      node ans;
      ans.merge(a,b);
      return ans;
  }
public:
  node query(int l,int r){
      return query(1,l,r);
  }
  void upd(int l,int r,update val){
      return zeno(1,l,r,val);
  }   
};

segtree<node,update>seg;
int a[N],b[N];
int f1[N],f2[N];
int solve(){
	int n;cin>>n;
	rep(i,1,n+1){
		cin>>a[i];
		f1[i]=n+1;
		f2[i]=0;
	}
	rep(i,1,n+1){
		cin>>b[i];
		f1[b[i]]=min(f1[b[i]],i);
		f2[b[i]]=i;
	}
	seg.build(1,0,n);
	update upd;upd.val=0;
	for(int i=1;i<=n;i++){
		if(f2[a[i]]==0){
			continue;
		}
		int j1=f1[a[i]];
		int j2=f2[a[i]];
		if(j2<=i){
			seg.upd((i-j2),i-j1,upd);

		}
		else if(j1<=i && i<=j2){
			seg.upd(0,i-j1,upd);
			seg.upd(n-j2+i,min(n,n-j1+i),upd);
		}
		else{
			seg.upd(n-j2+i,min(n,n-j1+i),upd);
		}
	}
	int j=n;
	for(int i=0;i<=n-1;i++){
		int x=seg.query(i,i).a;
		if(x){
			j=i;break;
		}
	}
	//cerr<<j<<endl;
	if(j==n){
		cout<<"No"<<endl;return 0;
	}
	cout<<"Yes"<<endl;
	rep(i,1,n+1){
		int val=((i-j-1+2*n)%n);
		cout<<b[val+1]<<" ";
	}cout<<endl;
}
