vector<pair<long long, long long> > prime_factorize(long long N) {
    vector<pair<long long, long long> > res;
    for (long long a = 2; a * a <= N; ++a) {
        if (N % a != 0) continue;
        long long ex = 0; // 指数

        // 割れる限り割り続ける
        while (N % a == 0) {
            ++ex;
            N /= a;
        }

        // その結果を push
        res.push_back({a, ex});
    }

    // 最後に残った数について
    if (N != 1) res.push_back({N, 1});
    return res;
}

int vector_finder(vector<ll> vec, ll number) {
  auto itr = find(vec.begin(), vec.end(), number);
  int index = distance( vec.begin(), itr );
  if (index != vec.size()) { // 発見できたとき
    return index+1;
  }
  else { // 発見できなかったとき
    return 0;
  }
}

int main() {
	int N, max=1;	cin>>N;
	vector<ll> number={1};
	vector<pair<ll, ll>> count={make_pair(1,1)};
	FOR(k,0,N){
    	long long A;
    	cin >> A;
    	const auto &res = prime_factorize(A);
		vector<ll>	s;
    	for (auto p : res) {
        	for (int i = 0; i < p.second; ++i) {
				s.push_back(p.first);
			}
    	}
		s.erase(unique(s.begin(), s.end()), s.end());
		FOR(i,0,s.size()){

			cout<<"number:";
			FOR(i,0,number.size()) cout<<number.at(i)<<" ";
			cout<<endl;
			FOR(i,0,count.size()) cout<<"count:"<<count.at(i).first<<"/"<<count.at(i).second<<endl;
			cout<<s.at(i)<<":"<<vector_finder(number,s.at(i))<<endl;
			cout<<endl;

			if(vector_finder(number,s.at(i))!=0){
				count.at(vector_finder(number,s.at(i))-1).second++;
				if(count.at(vector_finder(number,s.at(i))-1).second>max) max=count.at(vector_finder(number,s.at(i))-1).second;
			}else{
				count.push_back(make_pair(s.at(i),1));
				number.push_back(s.at(i));
			}
		}
	}
	FOR(i,0,count.size()) cout<<"count:"<<count.at(i).first<<"/"<<count.at(i).second<<endl;
	//cout<<max<<endl;
	if(max==1)	cout<<"pairwise coprime"<<endl;
	else if(max==N)	cout<<"not coprime"<<endl;
	else cout<<"setwise coprime"<<endl;

	return 0;
}



