template <class T>
class SegTreeLazy {
    int n;// 葉の数
    vector<T> data;// データを格納するvector
    vector<T> lazy;//
    T ex; // 初期値かつ単位元
    T em;//更新の単位元
    function<T(T, T)> fx; // 区間クエリで使う処理
    function<T(T, T)> fa;// 区間更新で使う処理、要素←遅延
    function<T(T, T)> fm;

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    void eval(int k) {
        if (lazy[k] == em) return;  // 更新するものが無ければ終了
        if (k < n - 1) {            // 葉でなければ子に伝搬
            lazy[k * 2 + 1] = fm(lazy[k * 2 + 1], lazy[k]);
            lazy[k * 2 + 2] = fm(lazy[k * 2 + 2], lazy[k]);
        }
        // 自身を更新
        data[k] = fa(data[k], lazy[k]);
        lazy[k] = em;
    }

    T _query(int a, int b, int k, int l, int r) {
        eval(k);
        if (r <= a || b <= l) return ex; // 交差しない
        if (a <= l && r <= b)
            return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return fx(c1, c2);
        }
    }
    void _update(int a, int b, T x, int k, int l, int r) {
        eval(k);
        if (a <= l && r <= b){
            lazy[k]= fm(lazy[k], x);
            eval(k);
        }
        else if( a < r &&l < b ){
            _update(a, b, x, 2 * k + 1, l, (l + r) / 2); // 左の子
            _update(a, b, x, 2 * k + 2, (l + r) / 2, r); // 右の子
            data[k]=fx(data[k*2+1],data[k*2+2]);
        }
    }   
    using FT=function<T(T, T)>;
    public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTreeLazy(int n_, FT fx_, FT fa_, FT fm_, T ex_, T em_)
        : n(), fx(fx_), fa(fa_), fm(fm_), ex(ex_), em(em_) {
        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
        data = vector<T>(2 * n - 1, ex);
        lazy = vector<T>(2 * n - 1, em);
    }

    // 場所i(0-indexed)の値をxで更新
    void update(int a, int b, T x) {
        _update(a,b,x,0,0,n);
    }

    // [a, b)の区間クエリを実行
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }
};


int main(){
