const int bfy[]={-2,-1,0,1,2,-2,-1,1,2,-2,2,-2,-1,1,2,-2,-1,0,1,2};
int h,w,cx,cy,dx,dy,qx[INF*INF+25],qy[INF*INF+25],l,r,dis_[INF][INF];
bool vis[INF][INF];
char Map[INF][INF];
void DFS(int x,int y) {
        for (int i=0; i<4; i++) {
                int gx=x+dfx[i],gy=y+dfy[i];
                if (gx<1 || gy<1 || gx>h || gy>w || vis[gx][gy] || Map[gx][gy]=='#') continue;
                vis[gx][gy]=true;
                dis_[gx][gy]=dis_[x][y];
                qx[++r]=gx;
                qy[r]=gy;
                DFS(gx,gy);
        }
        return;
}
