        memset(dis_,63,sizeof dis_);
        vis[cx][cy]=true;
        dis_[cx][cy]=0;
        bool flag=false;
        while (l<=r) {
                int x=qx[l],y=qy[l]; l++;
                DFS(x,y);
                if (vis[dx][dy]) flag=true;
                if (flag) break;
                for (int i=0; i<20; i++) {
                        int gx=x+bfx[i],gy=y+bfy[i];
                        if (gx<1 || gy<1 || gx>h || gy>w || vis[gx][gy] || Map[gx][gy]=='#') continue;
                        dis_[gx][gy]=dis_[x][y]+1;
                        vis[gx][gy]=true;
                        if (vis[dx][dy]) flag=true;
                        if (flag) break;
                        qx[++r]=gx;
                        qy[r]=gy;
                }
                if (flag) break;
                for (int i=1; i<=h; i++) {
                        for (int j=1; j<=w; j++)
                                cout<<dis_[i][j]<<" ";
                        cout<<endl;
                }
        }
        return;
}
signed main()
{
        scanf("%lld %lld",&h,&w); scanf("%lld %lld %lld %lld ",&cx,&cy,&dx,&dy);
        for (int i=1; i<=h; i++) {
                for (int j=1; j<=w; j++)
                        scanf("%c",&Map[i][j]);
                scanf(" ");
        }
        l=1;
        qx[++r]=cx;
        qy[r]=cy;
        BFS();
        if (vis[dx][dy]) cout<<dis_[dx][dy]<<"\n";
        else cout<<"-1\n";
        return 0;
}
