using namespace std;

int main() {
    int n, l;
    scanf("%d %d", &n, &l);
    vector<int> len(n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &len[i]);
    }

    int pick = -1;
    for (int i = 0; i + 1 < n; ++i) {
        if (len[i] + len[i + 1] >= l) {
            pick = i;
            break;
        }
    }
    if (pick == -1) {
        printf("Impossible\n");
        return 0;
    }

    printf("Possible\n");
    for (int i = 0; i < pick; ++i) {
        printf("%d\n", i + 1);
    }
    for (int i = n - 2; i > pick; ++i) {
        printf("%d\n", i + 1);
    }
    printf("%d\n", pick + 1);
    return 0;
