#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll dp[3030][3030][4];
ll grid[3030][3030];

int main() {
    int r, c, k;
    cin >> r >> c >> k;
    for (int i = 0; i < k; ++i) {
        int ri, ci;
        ll vi;
        cin >> ri >> ci >> vi;
        ri--, ci--;
        grid[ri][ci] = vi;
    }

    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            for (int t = 0; t < 4; ++t) {
                // move vertically by 1, w/o taking anything
                dp[i+1][j+1][0] = max(dp[i+1][j+1][0], dp[i][j+1][t]);

                // move vertically by 1, w/ taking item at (i, j)
                dp[i+1][j+1][1] = max(dp[i+1][j+1][1], dp[i][j+1][t] + grid[i][j]);

                // move horizontally by 1, w/o taking anything
                dp[i+1][j+1][t] = max(dp[i+1][j+1][t], dp[i+1][j][t]);

                // move horizontally by 1, w/ taking item at (i, j)
                // whilst incrementing the count by 1
                if(t+1 < 4) {
                    dp[i+1][j+1][t+1] = max(dp[i+1][j+1][t+1], dp[i+1][j][t] + grid[i][j]);
                }
            }
        }
    }

    for (int t = 0; t < 4; ++t) {
        cout << t << endl;
        for (int i = 0; i <= r; ++i) {
            for (int j = 0; j <= c; ++j) {
                cout << dp[i][j][t] << " ";
            }
            cout << endl;
        }
        cout << endl;
    }


    ll ans = 0;
    for (int i = 0; i < 4; ++i) {
        ans = max(ans, dp[r][c][i]);
    }
    cout << ans << endl;
}
