#define MIN(a,b) ((a) < (b) ? (a) : (b))

int R,C,K;
int DP[3001][3001];
int Arr[3001][3001];


int* minUpd(int arr[3])
{
    int min = 3000000;
    int* ret;
    for (int i = 0; i < 3; i++)
    {
        if(arr[i] < min){
            ret = &arr[i];
            min =  arr[i];
        }
    }
    return ret;

}    
void update(int i, int J, int plus){

        int last[] = {0,0,0};
        int* low;
        for (int j = J; j < C+1; j++)
        {
            low = minUpd(last);

            if(*low < Arr[i][j])
                *low = Arr[i][j];

            DP[i][j] = last[0] + last[1] + last[2] + plus;
        }


}




void solve(){
    cin >> R >> C >> K;

    for (int i = 0; i < 3000; i++)
    {
        for (int j = 0; j < 3000; j++)
        {
         DP[i][j] = 0;
         Arr[i][j] = 0;
        }
    }

    int r, c, v;
    for (int i = 0; i < K; i++)
    {
        cin >> r  >> c >> v ;

        Arr[r][c] = v;
        DP[r][c] = v;
    }


    for (int i = 1; i < C+1; i++)
    {
        update(i, 1, 0);
    }


    for (int i = 0; i < R+1; i++)
    {
        for (int j = 0; j < C+1; j++)
        {
            cout << DP[i][j] << " ";
        }
        cout << endl;
    }


    for (int i = 1; i < R+1; i++)
    {
        for (int j = 1; j < C+1; j++)
        {
            if(DP[i][j] < DP[i-1][j] + Arr[i][j]){
                update(i,j, DP[i-1][j]);
            }
        }

    }

    for (int i = 0; i < R+1; i++)
    {
        for (int j = 0; j < C+1; j++)
        {
            cout << DP[i][j] << " ";
        }
        cout << endl;
    }

    cout << DP[R][C]<< endl;
}





int main(){

    ios::sync_with_stdio(false);
    cin.tie(0);

    solve();

