void solve() {
    LCIN(R, C, K);
    Fill(score, -1);
    REP(i, K) {
        LCIN(r, c, v);
        r--, c--;
        score[r][c] = v;
    }
    REP(r, R) REP(c, C) {
        ll bias = (r ? dp[r - 1][c][3] : 0LL);
        REP(k, 4) {
            chmax(dp[r][c][k], (c ? dp[r][c - 1][k] : 0LL));
            if(k && ~score[r][c]) {
                chmax(dp[r][c][k], (c ? dp[r][c - 1][k - 1] : 0LL) +
                                       (k == 1 ? bias : 0LL) + score[r][c]);
            }
            if(score[r][c] == -1) {
                chmax(dp[r][c][k], bias);
            }
        }
        REP(k, 3) { chmax(dp[r][c][k + 1], dp[r][c][k]); }
    }
    REP(r, R) REP(c, C) { cout << dp[r][c][3] << (c == C - 1 ? "\n" : " "); }
    COUT(dp[R - 1][C - 1][3]);
}

