string convertSumdigit(string x) {
    int cnt = 0;
    for(auto ix:x) if(ix=='1') cnt++;

    string ans;
    while(cnt!=0) {
        if(cnt%2==0) ans.push_back('0');
        else ans.push_back('1');
        cnt /= 2;
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

int main(void) {
    int n;
    cin >> n;

    string x;
    cin >> x;

    string xnow;
    for(int in=0;in<n;in++) {
        xnow = x;
        if(xnow[in]=='1') xnow[in] = '0';
        else xnow[in] = '1';

        int xpoint = 0, ans = 0;
        while(1) {
            string xdiv = convertSumdigit(xnow);
            cout << xnow << endl;
            cout << xdiv << endl;
            for(int ix=0;ix<=xnow.size()-xdiv.size();ix++) {
                if(xnow.substr(ix, xdiv.size())==xdiv) xpoint = ix;
            }
            if(xpoint+1>=xnow.size()) { 
                ans++;
                break;
            }
            xnow = xnow.substr(xpoint+1, xnow.size()-xpoint);
            ans++;
            cout << ans << endl;
        }
        if(xnow.empty()) ans--;
        cout << ans << endl;
    }
    return 0;
}
