		int cnt = 0;

		string tmp = x;
		if (tmp[i] == '0')
			tmp[i] = '1';
		else
			tmp[i] = '0';

		while (1) {

			cnt++;

			cout << "tmp1:" << tmp << endl;

			int popcount = 0;
			for (int i = 0; i < n; i++) {
				if (tmp[i] == '1') popcount++;
			}

			int popcount_ = popcount;
			vector<bool> flag;
			while (popcount_) {
				flag.push_back(popcount_ % 2);
				popcount_ >>= 1;
			}
			reverse(flag.begin(), flag.end());

			for (int j = 0; j < n - flag.size(); j++) {

				if (tmp[j] == '0') continue;

				for (int k = 0; k < flag.size(); k++) {

					if (flag[k]) {
						if (tmp[j + k] == '0')
							tmp[j + k] = '1';
						else
							tmp[j + k] = '0';
					}
				}
			}

