			//cout << "popcount" << popcount << endl;

			bool ok = true;
			for (int j = 0; j < flag.size(); j++) {

				if (flag[j]) {
					if (tmp[n - flag.size() + j] != '1') {
						ok = false;
						break;
					}
				}
				else {
					if (tmp[n - flag.size() + j] == '1') {
						break;
					}
				}
			}
			if (ok) {
				for (int k = 0; k < flag.size(); k++) {
					tmp[n - k - 1] = '0';
				}
			}

			bool end = false;
			for (int j = 0; j < flag.size(); j++) {
				if (tmp[n - j - 1] != '0') break;
				if (j == flag.size() - 1) end = true;
			}
			if (end) break;
		}


		cout << cnt << endl;// << endl << endl;
	}






	return 0;
}
