/*
 * 定数
 */
const long double PI = (acos(-1));
const long double EPS = 1e-10;
const long long INF = 1e18;

/*
 * データ変換 
 */
/* char -> int */
int ctoi(char c) { return (int)(c - '0'); }

/*
 * 数学的な計算
 */
/* 階乗 */
int factorial(int n) {
  int ret = 1;
  for (int i = 1; i < n + 1; ++i) {
    ret = ret * i;
  }
  return ret;
}

/* 最大公約数 */
template <typename T>
T gcd(T x, T y) { return x % y == 0 ? y : gcd(y, x % y); }

/* 最小公倍数 */
template <typename T>
T lcm(T a, T b) { return a * b / gcd(a, b); }

/* n個の整数の最小公倍数 */
template <typename T>
T lcm_n(vector<T> &numbers) {
  T l;
  l = numbers[0];
  for (int i = 1; i < numbers.size(); ++i) {
    l = lcm(l, numbers[i]);
  }
  return l;
}

/*
 * DP向け
 */
template <class T>
bool chmax(T &a, const T &b) {
  if (a < b) {
    a = b;
    return 1;
  }
  return 0;
}
template <class T>
bool chmin(T &a, const T &b) {
  if (b < a) {
    a = b;
    return 1;
  }
  return 0;
}

/*
 * グラフ
 */
class Graph {
 public:
  vector<vector<int>> G;
  vector<int> Trans;
  vector<int> inDeg;
  int numV;

  Graph(int numV) {
    this->numV = numV;
    inDeg.assign(numV, 0);
    Trans.assign(numV, 0);
    G.assign(numV, vector<int>());
  }

  int topologicalSort(int v, vector<int> &dp) {
    if (dp[v] != -1) {
      return dp[v];
    }

    int res = 0;

    for (auto to : G[v]) {
      chmax(res, topologicalSort(to, dp) + 1);
    }

    return dp[v] = res;
  }
};

bool isPrime(ll n) {
  switch (n) {
    case 0:  // fall-through
    case 1:
      return false;
    case 2:  // fall-through
    case 3:
      return true;
  }  // n > 3 が保証された

  if (n % 2 == 0 || n % 3 == 0) return false;
  // n は 2 と 3 のいずれの倍数でもないことが保証された
  // これより n は (6の倍数)-1 か (6の倍数)+1 である

  // 6の倍数前後の数を使って試し割りをする
  for (ll i = 5; i * i <= n; i += 6) {
    if (n % i == 0) return false;        // (6の倍数)-1
    if (n % (i + 2) == 0) return false;  // (6の倍数)+1
  }

  return true;
}

int main() {
  ll N;
  cin >> N;
  vector<ll> A(N);

  for (auto &v : A) {
    cin >> v;
  }

  sort(A.begin(), A.end());

  if (A[0] == A[N - 1]) {
    cout << 0 << endl;
    return 0;
  }

  if (A[0] == 1) {
    cout << 0 << endl;
    return 0;
  }

  vector<ll> memory;
  ll ans = 0;
  map<ll, ll> B;
  B[A[0]] = 1;

  for (ll i = 1; i < N; ++i) {
    if (A[i - 1] == A[i]) {
      B[A[i]]++;
    } else {
      B[A[i]] = 1;
    }
  }

  for (auto itr = B.begin(); itr != B.end(); ++itr) {
    if (isPrime(itr->first)) {
      memory.emplace_back(itr->first);
      if (itr->second == 1) {
        ++ans;
      }
      continue;
    }
    bool check = false;
    cout << endl;
    for (auto m : memory) {
      cout << m << ", ";
      if (itr->first % m == 0) {
        check = true;
        break;
      }
    }
    if (!check) {
      memory.emplace_back(itr->first);
      if (itr->second == 1) {
        ++ans;
      }
    }
  }

  cout << ans << endl;

  return 0;
}
