struct State{
	State(int arg_row,int arg_col,int arg_num_turn,int arg_num_move,Type arg_dir){
		row = arg_row;
		col = arg_col;
		num_turn = arg_num_turn;
		num_move = arg_num_move;
		dir = arg_dir;
	}
	bool operator<(const struct State &arg) const{

		if(num_turn != arg.num_turn){

			return num_turn > arg.num_turn;
		}else{

			return num_move > arg.num_move;
		}
	}
	int row,col,num_turn,num_move;
	Type dir;
};

