	start_col--;
	start_row--;
	goal_col--;
	goal_row--;

	for(int row = 0; row < H; row++){

		scanf("%s",table[row]);
	}

	priority_queue<State> Q;

	for(int i = 0; i < 4; i++){

		info[start_row][start_col][i].num_turn = 1;
		info[start_row][start_col][i].num_move = 0;

		Q.push(State(start_row,start_col,1,0,type_dir[i]));
	}

