// exgcd:
//   For given x>0 and y>0, solve a, b, c such that ax+by=c (=gcd(x,y))

void exgcd(int x, int y, int &a, int &b, int &c) {
  int r0 = x, r1 = y;
  int a0 = 1, a1 = 0;
  int b0 = 0, b1 = 1;

  while (r1 > 0) {
    int q1 = r0 / r1;
    int r2 = r0 % r1;
    int a2 = a0 - q1 * a1;
    int b2 = b0 - q1 * b1;
    r0 = r1, r1 = r2;
    a0 = a1, a1 = a2;
    b0 = b1, b1 = b2;
  }
  c = r0;
  a = a0;
  b = b0;
}

/* main */

int main() {
  int l;
  string s, t;
  cin >> l >> s >> t;

  int sn = s.size(), tn = t.size();
  int a, b, c;
  exgcd(sn, tn, a, b, c);
  int da = tn / c, db = sn / c;
  //printf("%d,%d -> a,b,c=%d,%d,%d\n", sn, tn, a, b, c);
  a *= l / c, b *= l / c;
  //printf("-> %d,%d,%d (%d,%d)\n", a, b, l, da, db);

  if (s + t < t + s) {
    if (b < 0) {
      int d = (-b + db - 1) / db;
      b += db * d;
      a -= da * d;
    }
    else if (b > 0) {
      int d = b / db;
      b -= db * d;
      a += da * d;
    }
    for (int i = 0; i < a; i++) cout << s;
    for (int i = 0; i < b; i++) cout << t;
    cout << endl;
  }
  else {
    if (a < 0) {
      int d = (-a + da - 1) / da;
      a += da * d;
      b -= db * d;
    }
    else if (a > 0) {
      int d = a / da;
      a -= da * d;
      b += db * d;
    }
    for (int i = 0; i < b; i++) cout << t;
    for (int i = 0; i < a; i++) cout << s;
    cout << endl;
  }
  //printf("a=%d, b=%d\n", a, b);

  return 0;
}
