        rer(i, a - 1) A.pb(N - i);
        rep(i, N - a) A.pb(i + 1);
        int l = a, r = a + b - 1;
        while (l < N) {
            auto lb = A.begin() + l;
            auto rb = A.begin() + min(r, N);
