void make()
{
    for(int i=1 ;i<=n*n ;i++ ){
        x = (i-1) / n , y = (i-1) % n;

        path[x][y] = emp[x][y] = false;
    }   

    for(int i=0 ;i<=n+1 ;i++ ){
        path[0][i] = path[n+1][i] = path[i][n+1] = path[i][n+1] = emp[0][i] = emp[n+1][i] = emp[i][0] = emp[i][n+1] = true;
    }
