void painfulReading() {
  cin >> n;
  int yacklen = 0;
  for (int i = 1; i <= n; i++) {
    ll x, y;
    cin >> x >> y;
    if (x == 0 && y == 0) {
      ans = add(ans, 1);
      continue;
    }
    if (x == 0) {
      y = 1;
      yacklen++;
      a[yacklen] = 0;
      b[yacklen] = 1;
      continue;
    }
    if (y == 0) {
      x = 1;
      yacklen++;
      a[yacklen] = 1;
      b[yacklen] = 0;
      continue;
    }
    ll g = __gcd(abs(x), abs(y));
    x /= g;
    y /= g;
    if (x < 0 && y < 0) {
      x *= -1;
      y *= -1;
    }
    if (x < 0 && y > 0) {
      x *= -1;
      y *= -1;
    }
    yacklen++;
    a[yacklen] = x;
    b[yacklen] = y;
  }
  n = yacklen;
  for (int i = 1; i <= n; i++) {
    p[i] = {a[i], b[i]};
    if (b[i] > 0) {
      ip[i] = {b[i], -a[i]};
    } else {
      ip[i] = {-b[i], a[i]};
    }
  }
  ans = add(ans, -1);
  return;
  for (int i = 1; i <= n; i++) {
    cout << " : " << p[i].first << " " << p[i].second << ", " << ip[i].first << " " << ip[i].second << "\n";
  }
}

bool okMask(int mask) {
  vector<int> active;
  for (int i = 0; i < n; i++) {
    if (mask & (1 << i)) {
      active.push_back(i + 1);
    }
  }
  for (auto &i : active) {
    for (auto &j : active) {
      if (p[i] == ip[j]) {
        return 0;
      }
    }
  }
  return 1;
}

