int ai[1003];
int bi[1003];
int ci[1003];
int di[1003];
int ei[1003];
int fi[1003];

bool used[4096][4096];

bool dis[4096][4096][4];

int main() {
	int n, m;

	cin >> n >> m;

	map<int, int> xzip;
	map<int, int> yzip;

	xzip[0] = 0;
	yzip[0] = 0;
	xzip[INF] = 0;
	yzip[INF] = 0;
	xzip[-INF] = 0;
	yzip[-INF] = 0;
	xzip[INF+1] = 0;
	yzip[INF+1] = 0;
	xzip[-INF-1] = 0;
	yzip[-INF-1] = 0;

	rep(i, n) {
		cin >> ai[i] >> bi[i] >> ci[i];
		xzip[ai[i]] = 0;
		xzip[bi[i]] = 0;
		yzip[ci[i]] = 0;
	}
	rep(i, m) {
		cin >> di[i] >> ei[i] >> fi[i];
		xzip[di[i]] = 0;
		yzip[ei[i]] = 0;
		yzip[fi[i]] = 0;
	}
	vector<int> xunzip;
	vector<int> yunzip;
	int xc = -1;
	for (auto& p : xzip) {
		p.second = ++xc;
		xunzip.push_back(p.first);
	}
	int yc = -1;
	for (auto& p : yzip) {
		p.second = ++yc;
		yunzip.push_back(p.first);
	}
	++xc; ++yc;

	assert(xc < 4000);
	assert(yc < 4000);

	const int dx[4] = { 1,-1,0,0 };
	const int dy[4] = { 0,0,1,-1 };
	const int RR = 0;
	const int LL = 1;
	const int DD = 2;
	const int UU = 3;

	using PP = pair<Pi, Pi>;
	//set<PP> dis;
	rep(i, n) {
		int a = xzip[ai[i]];
		int b = xzip[bi[i]];
		int c = yzip[ci[i]];
		for (int y = a; y < b; ++y) {
			dis[c - 1][y][LL] = true;
			dis[c][y][RR] = true;;
		}
	}
	rep(i, m) {
		int d = xzip[di[i]];
		int e = yzip[ei[i]];
		int f = yzip[fi[i]];
		for (int x = e; x < f; ++x) {
			dis[x][d - 1][UU] = true;
			dis[x][d][DD] = true;
		}
	}

	queue<Pi> q;
	used[xzip[0]][yzip[0]] = true;
	q.push({ xzip[0], yzip[0] });
	while (!q.empty()) {
		auto p = q.front(); q.pop();
		rep(d, 4) {
			int x = p.first  + dx[d];
			int y = p.second + dy[d];
			if (y < 0 || y >= yc-1) continue;
			if (x < 0 || x >= xc-1) continue;
			if (used[x][y]) continue;
			//if (dis.count({ p, {x,y} })) continue;
			if (dis[x][y][d]) continue;
			used[x][y] = true;
			q.push({y, x});
		}
	}
	ll ret = 0;
	bool isinf = false;

	rep(i, yc-1) {
		rep(j, xc-1) {
			ll v = !used[j][i] ? 0LL : ll(xunzip[j + 1] - xunzip[j]) * ll(yunzip[i + 1] - yunzip[i]);
			//printe((v > 0 ? v > 99 ? " #" : "%2lld" : " ."), v);
			ret += v;
			if (v > 0 && (i == 0 || j == 0 || i == yc - 2 || j == xc - 2)) {
				isinf = true;
			}
		}
		//printe("\n");
	}
	if (isinf) {
		cout << "INF" << endl;
	} else {
		assert(ret > 0);
		if (ret < 4) {
			for (;;) puts("aaaaaaaaaaaaaaaaaaaaaa");
		}
		cout << ret << endl;
	}


}


