using namespace std;
const int M = 1e5+50;
const int N = 1e5+50;
const int MAXN = 1e5+50;
int n;
char s[N];
pii ct[N];

bool cmp1( pii p1, pii p2 ){
    if( p1.fi == p2.fi )
        return p1.se > p2.se;
    return p1.fi < p2.fi;
}

bool cmp2( pii p1, pii p2 ){
    if( p1.se == p2.se )
        return p1.fi < p2.fi;
    return p1.se > p2.se;
}

int main( ){
    while( scanf( "%d", &n ) != EOF ){

        int ans = 0;
        for( int i = 1; i <= n; i++ ){

            scanf( "%s", s );
            int len = strlen( s );
            int st = 0, ed = len-1;
            ct[i].fi = ct[i].se = 0;
            while( s[st] == ')' && st < len ){
                ct[i].fi++;
                st++;
            }
            while( s[ed] == '(' && ed ){
                ct[i].se++;
                ed--;
            }
            int tmp = 0;
            for( int j = st; j <= ed; j++ ){
                if( s[j] == '(' )
                   tmp++;
                else
                    tmp--;
            }
            if( tmp > 0 )
                ct[i].se += tmp; //缺多少右, 即多出多少左
            else
                ct[i].fi -= tmp; //缺多少左，即多出多少右
        }
        /*for( int i = 1; i <= n; i++ ){
            cout << "i: " << i << "    R: " << ct[i].fi << "    L: " << ct[i].se << endl;
        }
        cout << "\n\n";*/
        sort( ct+1, ct+n+1, cmp1 );
        /*for( int i = 1; i <= n; i++ ){
            cout << "i: " << i << "    R: " << ct[i].fi << "    L: " << ct[i].se << endl;
        }*/
        int L = ct[1].se, R = ct[1].fi;
        bool flag = 0;

        for( int i = 2; i <= n; i++ ){
            if( R > 0 ){
                flag = 1;
                break;
            }
            L -= ct[i].fi;
            if( L < 0 ){
                flag = 1;
                break;
            }
            L += ct[i].se;
        }
        if( L || R )
            flag = 1;

        sort( ct+1, ct+n+1, cmp2 );
        L = ct[1].se, R = ct[1].fi;
        for( int i = 2; i <= n; i++ ){
            if( R > 0 ){
                flag = 1;
                break;
            }
            L -= ct[i].fi;
            if( L < 0 ){
                flag = 1;
                break;
            }
            L += ct[i].se;
        }
        if( L || R )
            flag = 1;
        if( flag )
            printf( "No\n" );
        else
            printf( "Yes\n" );
    }
    return 0;
}
