            while( s[st] == ')' && st < len ){
                ct[i].fi++;
                st++;
            }
            while( s[ed] == '(' && ed ){
                ct[i].se++;
                ed--;
            }
            for( int j = st; j <= ed; j++ ){
                if( s[j] == '(' )
                   tmp++;
                else
                    tmp--;
            }
            if( tmp > 0 )
                ct[i].se += tmp; //缺多少右, 即多出多少左
            else
                ct[i].fi -= tmp; //缺多少左，即多出多少右
        }
        sort( ct+1, ct+n+1, cmp );
        /*for( int i = 1; i <= n; i++ ){
            cout << "i: " << i << "    R: " << ct[i].fi << "    L: " << ct[i].se << endl;
        }*/
        int L = ct[1].se, R = ct[1].fi;
        bool flag = 0;

        for( int i = 2; i <= n; i++ ){
            if( R > 0 ){
                flag = 1;
                break;
            }
            L -= ct[i].fi;
            if( L < 0 ){
                flag = 1;
                break;
            }
            L += ct[i].se;
        }
        if( L > 0 )
            flag = 1;
        if( flag )
            printf( "No\n" );
        else
            printf( "Yes\n" );
    }
    return 0;
}
