void printa(int a){
  printf("%c\n",a+'A');
}

void hand(vector<int>& v,const vector<int>& q,int& i){
  int n=q.size();
  int k=q[i],a1=(k+1)%3,a2=(k+2)%3;
  if(v[a1] < v[a2])swap(a1,a2);  // v[a1] >= v[a2]
  if(not (v[a1]>=v[a2])) while(1) print("TLE");
  if(i==n-1) v[k]++;
  if(v[k]>0){
    printa(a2);
    v[a1]--; v[a2]++;
    return;
  }
  // v[k]==0, i!=n-1
  if(not (v[k]==0 and i!=n-1)) while(1) print("TLE");
  if(q[i]==q[i+1]){
    printa(a1);
    printa(a2);
    i++;
    return;
  }
  int a=3-k-q[i+1];
  printa(a);
  printa(k);
  v[k]++;
  v[q[i+1]]--;
  i++;
  return;
}

int main(){
  vector<int> v(3);
  li n; cin >>n;
  rep(i,3){
    cin >>v[i]; chmin(v[i],2);
  }
  vector<int>  q(n);
  rep(i,n){
    string s; cin >>s;
    q[i]=3-(s[0]-'A')-(s[1]-'A');
  }

  int f=(!v[0])+(!v[1])+(!v[2]);  // 0の数
  if(f==3){  // all 0
    if(not (v[0]==0 and v[1]==0 and v[2] == 0)) while(1) print("TLE");
    print("No");
    return 0;
  }
  if(f==2 and v[q[0]]>0){
    print("No");
    return 0;
  }
  if(f<2 or v[0]+v[1]+v[2]>=2){
    print("Yes");
    rep(i,n){
      hand(v,q,i);
    }
    return 0;
  }

  // 0が2つ v[0]+v[1]+v[2]==1
  if(not (v[0]+v[1]+v[2]==1)) while(1) print("TLE");
  vector<int> ans;
  rep(i,n){
    int k=q[i],a1=(k+1)%3,a2=(k+2)%3;    
    if(v[a1] < v[a2])swap(a1,a2);  // v[a1] >= v[a2]
    if(v[a1]==0){
      print("No");
      return 0;
    } 
    ans.push_back(a2);
    v[a1]--; v[a2]++;
  }
  print("Yes");
  rep(i,n) printa(ans[i]);


}
