void printSubSeqRec(string str, int n, vector<string>& vec, int index = -1, string curr = "")
{
    // base case
    if (index == n)
        return;

    vec.push_back(curr);
    for (int i = index + 1; i < n; i++) {

        curr += str[i];
        printSubSeqRec(str, n, vec, i, curr);

        // backtracking
        curr = curr.erase(curr.size() - 1);
    }
    return;
}
