using Bits = bitset<50000>;
int N, M, T;
int X[100000], Y[100000];
Bits bits[50000];
bool used[50000];

void sub(int from) {
	string s(M, 'v');
	used[from] = true;
	REM(j, 0, M) {
		int a = X[j];
		int b = Y[j];

		if (used[a]) {
			s[j] = '^';
			used[b] = true;
		} else if (used[b]) {
			used[a] = true;
		}
	}
	cout << s << endl;
}

int main() {
	cin >> N >> M >> T;
	REP(j, 0, M) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		X[j] = a;
		Y[j] = b;
	}

	if (T == 2) OLE();
	REP(i, 0, N) {
		bits[i][i] = true;
	}

	REP(j, 0, M) {
		int a = X[j];
		int b = Y[j];
		bits[a] |= bits[b];
		bits[b] |= bits[a];
	}

	REP(i, 0, N) {
		if (bits[i].count() == N) {
			sub(i);
			return 0;
		}
	}

	cout << -1 << endl;
	return 0;
