using namespace std;

const int MAX_N = 1e3 + 5;
const int INF = 1e9 + 5;

typedef long long ll;

int arr [MAX_N];

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  int mx = -INF;
  ll odds = 0;
  ll evens = 0;
  for (int i = 1; i <= n; i++) {
    cin >> arr[i];
    mx = max(mx, arr[i]);

    if (arr[i] > 0) {
      if (i % 2 == 1) {
        odds += arr[i];
      } else {
        evens += arr[i];
      }
    }
  }

  if (mx <= 0) {
    int pos = 0;
    for (int i = 1; i <= n; i++) {
      if (arr[i] == mx) {
        pos = i;
        break;
      }
    }

    cout << mx << '\n';
    cout << n - 1 << '\n';
    for (int i = n; i > pos; i++) {
      cout << i << '\n';
    }
    for (int i = 1; i < pos; i++) {
      cout << 1 << '\n';
    }
    return 0;
  }

  vector<int> ops;
  if (evens > odds) {
    ops.push_back(1);
    for (int i = 1; i < n; i++) {
      arr[i] = arr[i + 1];
    }
    n--;
    odds = evens;
  }

  vector<int> to_keep;
  for (int i = 1; i <= n; i++) {
    if (arr[i] > 0 && i % 2 == 1) {
      to_keep.push_back(i);
    }
  }

  while (n > to_keep.back()) {
    ops.push_back(n);
    n--;
  }

  while ((int) to_keep.size() >= 2) {
    int v = to_keep.back();
    int u = *next(to_keep.rbegin());

    while (v > u + 2) {
      v -= 2;
      n -= 2;
      ops.push_back(u + 2);
    }

    n -= 2;
    ops.push_back(u + 1);
    to_keep.pop_back();
  }

  for (int i = 1; i < to_keep[0]; i++) {
    ops.push_back(1);
  }

  cout << odds << '\n';
  cout << (int) ops.size() << '\n';
  for (int u : ops) {
    cout << u << '\n';
  }
}
