#include <bits/stdc++.h>

using namespace std;

int N;
int ans[504][504];

void sol(vector < int > arr, int gap){
    if((int)arr.size() % 2){
        while(1) puts("1");
        for(auto&i:arr){
            ans[i][arr.back()] = ans[arr.back()][i] = gap;
        }
        arr.pop_back();
        ++gap;
    }
    for(int i = 0; i < (int)arr.size(); ++i){
        int j = (i + 1) % (int)arr.size();
        int x = j;
        while(1){
            ans[arr[i]][arr[j]] = gap;
            j = (j + 1) % (int)arr.size();
            j = (j + 1) % (int)arr.size();
            if(j == x) break;
        }
    }
    if((int)arr.size() > 3){
        vector < int > A, B;
        for(int i = 0; i < (int)arr.size(); ++i){
            if(i % 2) A.push_back(arr[i]);
            else B.push_back(arr[i]);
        }
        sol(A, gap + 1), sol(B, gap + 1);
    }
}

int main(){
    scanf("%d", &N);
    vector < int > vc;
    for(int i = 1; i <= N; ++i) vc.push_back(i);
    sol(vc, 1);
    for(int i = 1; i <= N; ++i){
        for(int j = i + 1; j <= N; ++j){
            printf("%d ", ans[i][j]);
        }
        puts("");
    }
    return 0;
}
