            g[v2].insert({new_w + x[v1], v1});
            g[v1].insert({new_w + x[v2], v2});

            operations.erase({w + x[i], i, v2});
            operations.insert({new_w + x[v1], v1, v2});
            operations.insert({new_w + x[v2], v2, v1});
