        g[i].clear();
        g[i].insert({w1, v1});
     }

    for(int i = 1; i <= n; ++i)
        for(auto [w, v] : g[i]) {
            //cout << i << " " << v << "\n";
            answer += (w + x[i]);
        }

    cout << answer / 2;
}

