  if(abs(x - nowx) >= k) {
    if(x > nowx) {
      nowx += k;
    } else {
      nowx -= k;
    }
  } else {
    if(y > nowy) {
      nowy += k - abs(x - nowx);
    } else {
      nowy -= k - abs(x - nowx);
    }
    nowx = x;
  }
}
