inline void prt(ll x, ll y) {
  if(swp) {
      if(minusx && minusy) {
        printf("%lld %lld\n", -y, -x);
      } else if(minusx) {
        printf("%lld %lld\n", -y, x);
      } else if(minusy) {
        printf("%lld %lld\n", y, -x);
      } else {
        printf("%lld %lld\n", y, x);
      }
    } else {
      if(minusx && minusy) {
        printf("%lld %lld\n", -x, -y);
      } else if(minusx) {
        printf("%lld %lld\n", -x, y);
      } else if(minusy) {
        printf("%lld %lld\n", x, -y);
      } else {
        printf("%lld %lld\n", x, y);
      }
    }
}
