void print_zeroes(int n) {
  char s[100000];
  memset(s, '0', sizeof s);
  for (int i = 0; i < (n / 10000); ++i) {
    fwrite(s, 1, sizeof s, stdout);
  }

  fwrite(s, (n % 10000), sizeof s, stdout);
}

