#include<bits/stdc++.h>
#define f(i,a,b) for(int i=a; i<b; i++)
#define F first;
#define S second;
using namespace std;
typedef long long ll;

int fun(int i,int n,int l_c,short int a[][3],int dp[][3])
{
    if(i>=n) return 0;
    int x,y;
    if(l_c==0){
        x=1;
        y=2;
    }
    else if(l_c==1){
        x=0;
        y=2;
    }
    else{
        x=0,y=1;
    }
    if(i==n-1){
        return max(a[n-1][x],a[n-1][y]);
    }
    if(dp[i][l_c]!=-1){
        return dp[i][l_c];
    }
    return dp[i][l_c]=max(a[i][x]+fun(i+1,n,x,a,dp),a[i][y]+fun(i+1,n,y,a,dp));
}
int solve()
{
    int n;
    cin>>n;
    short int a[100000][3];
    int dp[100000][3];
    for(int i=0; i<n; i++){
        cin>>a[i][0]>>a[i][1]>>a[i][2];
        dp[i][0]=dp[i][1]=dp[i][2]=-1;
    }
    int ans=max(a[0][0]+fun(1,n,0,a,dp),max(a[0][1]+fun(1,n,1,a,dp),a[0][2]+fun(1,n,2,a,dp)));
    cout<<ans;
}
int main()
{
    ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
    int t,c=0;
    t=1;
    while(t--){
        solve();
        cout<<endl;
    }
}
