struct pUF{
    vector<ll> r, par;
    pUF(int n):r(n),par(n,-1){};

    int find(int x){
       if(par[x]<0)
           return x;
       int y = find(par[x]);
       r[x] += r[par[x]];
       return par[x] = y;
    }

    bool same(int x,int y){
        return find(x)==find(y);
    }

    ll weight(int x){
       find(x);
       return r[x];
    }

    ll diff(int x,int y){//weigth(y)-weight(x)を出力
        return weight(y)-weight(x);
    }

    bool unite(ll c,int x, int y){//weight(y)-weight(x)=cとなるようにつなぐ
        c -= weight(y);
        c += weight(x);
        x = find(x);
        y = find(y);
        if(x!=y){
           par[y] = x;
           r[y] = c;
           return true;
       }
       return false;
    }
};
int main(){
    int n;
    cin>>n;
    pUF uf(n);
    int q;
    cin>>q;
    rep(i,q){
        int t;
        cin>>t;
        if(t){
            int x,y;
            cin>>x>>y;
            cout<<endl;
            if(uf.same(x,y))cout<<uf.diff(x,y)<<endl;
            else cout<<"?"<<endl;
        }
        else {
            int x,y,z;
            cin>>x>>y>>z;
            uf.unite(z,x,y);
        }
    }


   return 0;
}
