#include<stdio.h>
int main() {
	int Max(int *p, int N);
	int Min(int *p, int N);
	int Sum(int *p, int N);
	int data[10000], m, n, i = 0;
	int ans_max, ans_min, ans_sum;

	scanf("%d", &n);
	do {
		scanf("%d", &m);
		data[i] = m;
		i++;
	} while (i < n);


	ans_max = Max(data,n);
	ans_min = Min(data,n);
	ans_sum = Sum(data,n);

	printf("%d %d %d",ans_min ,ans_max ,ans_sum);

	return 0;
}

int Max(int *p,int N) {
	int i, j, tmp;
	for (i = 0; i < N - 1; i++) {
		for (j = i + 1; j < N; j++) {
			if (p[j] > p[i]) {
				tmp = p[i];
				p[i] = p[j];
				p[j] = tmp;
			}
		}
	}
	return p[0];
}

int Min(int *p,int N) {
	int i, j, tmp;
	for (i = 0; i < N - 1; i++) {
		for (j = i + 1; j < N; j++) {
			if (p[j] > p[i]) {
				tmp = p[i];
				p[i] = p[j];
				p[j] = tmp;
			}
		}
	}
	return p[N - 1];
}

int Sum(int *p, int N){
	int i, ans = 0;
	for (i = 0; i < N; i++) {
		ans = ans + p[i];
	}
	return ans;
}
