std::vector<std::string> split(std::string source, char ch) {
	std::vector<std::string> res;
	std::string temp = "";
	int i = 0;

	while (i < source.size()) {
		if (source[i] == ch) {
			res.push_back(temp);
			temp = "";
		} else {
			temp += source[i];
		}
		i++;
	}

	return res;
}


