    for (int i = 0; i < r; ++i) {
        matrix[i] = new int[c];
        for (int j = 0; j < c; ++j) {
            cin >> matrix[i][j];
        }
    }
    return matrix;
}

int cij(int i, int j, int m, int **a, int **b) {
    int tmp = 0;
    for (int k = 0; k < m; ++k) {
        tmp += a[i][k] * b[k][j];
    }
    return tmp;
}

void print(int n, int m, int l, int **a, int **b) {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < l; ++j) {
            cout << cij(i, j, m, a, b) << " ";
        }
        cout << endl;
    }
}

void delete_matrix(int r, int** matrix) {
    for (int i = 0; i < r; ++i) {
        delete[] matrix[i];
    }
    delete[] matrix;
}

