#include <iostream>
#include<malloc.h>

using namespace std;
struct Node{
 long int data;
struct Node *next;
}*head,*temp;
int ins(long int x){
    temp=(Node*)malloc(sizeof(Node));
    temp->data=x;
    temp->next=head;
    head=temp;
}
void del(Node **head_ref, long int y){
    struct Node* temp=*head_ref, *prev;
    while(temp!=NULL){
        while(temp!=NULL && temp->data!=y){
                prev=temp;
        temp=temp->next;}
        if(temp==NULL)return;
        prev->next=temp->next;
        free(temp);
        temp=prev->next;

    }

}
void delfirst(){
    temp=head;
    head=head->next;
    free(temp);
}
void dellast(){
    temp=head;
    Node* curr;
    while(temp->next!=NULL){
        curr=temp;
        temp=temp->next;
    }
    curr->next=NULL;
    free(temp);
}

void display(){
    temp=head;
    while(temp!=NULL){
        cout<<temp->data<<" ";
        temp=temp->next;
    }cout<<endl;
    }
int main()
{
    long int t,x;
    head=NULL;
    cin>>t;
    while(t--){
    string c;
    cin>>c;
    if(c=="insert"){
    cin>>x;
    ins(x);}
    if(c=="delete"){
    long int y;
     cin>>y;
    del(&head, y);}
    if(c=="deleteFirst"){
        delfirst();
    }
    if(c=="deleteLast"){
        dellast();
    }
    }
    display();
    return 0;
}


