using namespace std;

int main()
{
	int a[3]; // 正解の数字
	int b[3]; // 回答者の数字

	while(cin >> a[0] >> a[1] >> a[2] >> a[3]){ // 正解の数字を入力
	  int hit  =0; // 初期値
	  int blow =0; // 初期値

	for(int i=0; i<4; i++) // 回答者の数字を入力
		cin >> b[i];

	for(int i=0; i<4; i++)
		for(int j=0; j<4; j++)
			if(a[i]==b[j])	// もし数字が一致しているなら
				if(i==j)	// もし同じ桁数が同じなら
					hit++;	// ヒットの数を増やす
				else
					blow++;	// ブロウの数を増やす
	cout<< hit << "" << blow << endl; // 結果を出力
	}
