#include <bits/stdc++.h>

using namespace std;

#define pb push_back
#define mp make_pair
#define L first
#define R second

const int maxn=1e5+10;

int n,m;
vector <int> adj[maxn], ans;
bool mark[maxn];
int h[maxn], up[maxn];

void input()
{
    cin>>n>>m;
    for(int i=0; i<m; i++)
    {
        int fi,se;
        cin>>fi>>se;
        adj[fi].pb(se);
        adj[se].pb(fi);
    }
}

void dfs(int x, int par)
{
    int t=h[x], ch=0;
    up[x]=h[x];
    mark[x]++;
    for(int i=0; i<adj[x].size(); i++)
    {
        int child=adj[x][i];
        if(!mark[child])
        {
            ch++;
            h[child]=h[x]+1;
            dfs(child, x);
            t=min(t,up[child]);
            up[x]=min(up[x],up[child]);
        }
        else if(child!=par)
            up[x]=min(up[x],h[child]);
    }
    if(t>=h[x] && ch>0 && x!=0)
        ans.pb(x);
    if(x==0 && ch>1)
        ans.pb(0);

}

void debug()
{
    cerr<<"debug starts"<<endl;
    for(int i=0; i<n; i++)
        cerr<<up[i]<<" ";
    cerr<<endl;
    cerr<<" debug ends"<<endl;
}

void output()
{
    sort(ans.begin(), ans.end());
    for(int i=0; i<ans.size(); i++)
        cout<<ans[i]<<" ";
    cout<<endl;
}

int main()
{
    input();
    dfs(0,0);
    //debug();
    output();
    return 0;
