using namespace std;

vector<bool> is_exist[6];

int encode(string s) {
	int ret = 0;
	int mul = 1;

	for (int i = 0; i < s.length(); i++) {
		ret += (s[i] - 'a') * mul;
		mul *= 26;
	}
	return ret;
}

string decode(int id, int length) {
	string ret;
	int mul = 1;

	for (int i = 0; i < length; i++) {
		int val = (id / mul) % 26;
		ret += (char)(val + 'a');
		mul *= 26;
	}
	return ret;
}

void input() {
	int n;

	cin >> n;

	is_exist[1].resize(26);
	is_exist[2].resize(26 * 26);
	is_exist[3].resize(26 * 26 * 26);
	is_exist[4].resize(26 * 26 * 26 * 26);
	is_exist[5].resize(26 * 26 * 26 * 26 * 26);
	for (int i = 1; i <= 5; i++) {
		for (int j = 0; j < is_exist[i].size(); j++) {
			is_exist[i][j] = false;
		}
	}

	for (int i = 0; i < n; i++) {
		string s;
		cin >> s;
		for (int j = 0; j < s.length(); j++) {
			string t;
			for (int k = j; k < min((int)s.length(), j + 5); k++) {
				t += s[k];
				is_exist[t.length()][encode(t)] = true;
			}
		}
	}
}

int main() {
