const long long int L_INF = 9223372036854775807;

typedef vector<int> Weight;
const Weight INF = vector<int>(100, 1);
const Weight ZERO = vector<int>(100, 0);
struct Edge {
	int src, dst;
	Weight weight;
	Edge(int src, int dst, Weight weight) :
		src(src), dst(dst), weight(weight) { }
};
bool operator <(const Weight&l, const Weight&r) {
	for (int i = 99; i >=0; --i) {
		if (l[i] != r[i])return l[i] < r[i];
	}
	return false;
}
bool operator >(const Weight&l, const Weight&r) {
	for (int i = 99; i >= 0; --i) {
		if (l[i] != r[i])return l[i] > r[i];
	}
	return false;
}
bool operator < (const Edge &e, const Edge &f) {
	return e.weight != f.weight ? e.weight > f.weight : // !!INVERSE!!
	e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
Weight operator+(const Weight&l, const Weight&r) {
	vector<int>ans(100);
	for (int i = 0; i < 100; ++i) {
		ans[i] = l[i] + r[i];
	}
	return ans;
}
Weight operator-(const Weight&l, const Weight&r) {
	vector<int>ans(100);
	for (int i = 0; i < 100; ++i) {
		ans[i] = l[i] - r[i];
	}
	return ans;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef vector<Weight> Array;
typedef vector<Array> Matrix;
#define RESIDUE(s,t) (capacity[s][t]-flow[s][t])

//??????0??????????????????????????¨??£???????±??????????????????§??¨???
Weight maximumFlow(const Graph &ag, int s, int t) {

	Graph g(ag);
	for (int i = 0; i < ag.size(); ++i) {
		for (int j = 0; j < ag[i].size(); ++j) {
			int d = ag[i][j].dst;
			int s = ag[i][j].src;

			bool ok = false;
			for (int k = 0; k < ag[d].size(); ++k) {
				if (ag[d][k].src == s) {
					ok = true;
					break;
				}
			}
			if (!ok) {
				g[d].push_back(Edge(d, s, ag[i][j].weight));
			}
		}
	}
	int n = g.size();
	Matrix flow(n, Array(n,ZERO)), capacity(n, Array(n, ZERO));
	REP(u, n) FOR(e, g[u]) capacity[e->src][e->dst] =capacity[e->src][e->dst]+ e->weight;


	Weight total = ZERO;
	while (1) {
		queue<int> Q; Q.push(s);
		vector<int> prev(n, -1); prev[s] = s;
		while (!Q.empty() && prev[t] < 0) {
			int u = Q.front(); Q.pop();
			FOR(e, g[u]) if (prev[e->dst] < 0 && RESIDUE(u, e->dst) > ZERO) {
				prev[e->dst] = u;
				Q.push(e->dst);
			}
		}
		if (prev[t] < 0)break; // prev[x] == -1 <=> t-side
		Weight inc = INF;
		for (int j = t; prev[j] != j; j = prev[j]) {
			auto v(RESIDUE(prev[j], j));
			if (inc > v) {
				inc =v;
			}
		}
		for (int j = t; prev[j] != j; j = prev[j])
			flow[prev[j]][j] =flow[prev[j]][j]+inc, flow[j][prev[j]] =flow[j][prev[j]]- inc;
		total =total+ inc;
	}

	return total;
}
