#include <stdio.h>

int bubbleSort(int A[], int N) {
  int flag, j, num;
  flag = 1;
  num = 0;
  while ( flag ) {
    flag = 0;
    for ( j = N - 1; j >= 1; j-- ) {
      if ( A[j] < A[j - 1]) {
        int v = A[j];
        A[j] = A[j - 1];
        A[j - 1] = v;
        num++;
        flag = 1;
      }
    }
  }
  return num;
}

int main() {
  int N, i, j, num;
  int A[100];

  scanf("%d", &N);
  for ( i = 0; i < N; i++ ) scanf("%d", &A[i]);

  num = bubbleSort(A, N);
  for ( i = 0; i < N; i++ ) printf("%d", A[i]);
  printf("\n");
