#include <iostream>
#include <string>

using namespace std;

struct Node{
	int key;
	struct Node* prev;
	struct Node* next;
};

typedef struct Node Node;

Node* nil;

// Inirialize the list
void initialize()
{
	nil = new Node;
	nil->key = -999999;
	nil->next = nil;
	nil->prev = nil;
}

// Insert the key
void insert(int key)
{
	// Make new node
	Node* x = new Node;
	x->key = key;

	// Insert the new node
	x->next = nil->next;
	nil->next->prev = x;
	nil->next = x;
	x->prev = nil;
}

// Search the node by given key
Node* search(int key)
{
	Node* current;
	current = nil->next;
	while (current != nil && current->key != key) {
		current = current->next;
	}
	return current;
}

// Delete the node
void delete_node(Node* node)
{
	node->prev->next = node->next;
	node->next->prev = node->prev;
	delete node;
}

// Delete x
void delete_x(int x)
{
	Node* n = search(x);
	delete_node(n);
}

// Delete first
void delete_first()
{
	delete_node(nil->next);
}

// Delete last
void delete_last()
{
	delete_node(nil->prev);
}


int main()
{
	initialize();
	int n;
	cin >> n;

	int x;
	for (int i = 0; i < n; i++) {
		string operation;
		cin >> operation;
		if (operation == "insert") {
			cin >> x;
			insert(x);
		}
		else if (operation == "delete") {
			cin >> x;
			delete_x(x);
		}
		else if (operation == "deleteFirst") {
			delete_first();
		}
		else {
			delete_last();
		}
	}

	// Print all keys of lists
	Node* current;
	current = nil->next;
	while (current != nil) {
		cout << current->key;
		current = current->next;
	}
	while (current != nil) {
		cout << " " << current->key;
		current = current->next;
	}
	return 0;
},presentation_error,,p02265

