#include <cstdio>
#include <algorithm>
#include <cmath>
using namespace std;
int t[1000001];
int s[100001];


		//Slozenost O(log n)

int binarna(int a[], int n, int k){
	int low = 0, high = n - 1; 
	bool b = 0;

	int mid;
	while(low <= high){
		mid = (low + high) / 2;

		if (a[mid] == k){
			b = true;
			break;
		}

		if (k < a[mid])
			high = mid - 1;
		else
			low = mid + 1;
	}

	if (b)
		return mid;
	else
		return -1;
}

int main()
{
    int n, q, br = 0;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
    {
        scanf("%d", &s[i]);
    }
    scanf("%d", &q);
    for (int i = 1; i <= q; i++)
    {
        scanf("%d", &t[i]);
    }
    sort(s + 1, s + n + 1);
    sort(t + 1, t + q + 1);
    if (n <= q)
    {
        for (int i = 1; i <= n; i++)
        {
            if (binarna(t, q, s[i]) != -1)
            {
                br++;
            }
        }
    }
    else
    {
        for (int i = 1; i <= q; i++)
        {
            if (binarna(s, n, t[i]) != -1)
            {
                br++;
            }
        }
    }
    printf("%d", br);
    return 0;
}
