using namespace std;


void factorize(int n){
	vector<int> fac;
	cout << n <<": ";
	int k = sqrt(n);

	while(n % 2 ==0){
		n /= 2;
		fac.push_back(2);
	}
	for(int i=3; i<=k; i = i+2){
		if(n % i == 0){
			n /= i;
			//cout << i << " ";
			fac.push_back(i);
			i -= 2;
		}
	}


	//cout << endl;
	int m = fac.size();
	if(m == 0) cout << n;
	else{
		for(int i=0; i<m-1; i++){
			cout << fac[i] << " ";
		}
		cout << fac[m-1] << endl;
	}
}


int main(){
	int n;
	cin >> n;
	factorize(n);
	return 0;
