using namespace std;

const int INF = 0x3f3f3f3f;
const int NBDR = -2e7;
const int BDR = 2e7;
const int MAXN = 130;
int G[MAXN][MAXN];

int n, k, u, v, w;


void init()
{
	for(int i = 0; i < n; i++)
		for(int j = 0; j < n; j++)
			G[i][j] = i == j ? 0 : INF;
}

void floyd()
{
	for(int k = 0; k < n; k++)
		for(int i = 0; i < n; i++)
			for(int j = 0; j < n; j++)
				if(min(G[i][j], G[i][k] + G[k][j]) >= NBDR && min(G[i][j], G[i][k] + G[k][j]) <= BDR)
					G[i][j] = min(G[i][j], G[i][k] + G[k][j]);
}


int main()
{
	while(scanf("%d %d", &n, &k) != EOF)
	{
		init();
		int flag = 0;
		while(k--)
		{
			scanf("%d %d %d", &u, &v, &w);
			G[u][v] = w;
		}

		floyd();

		for(int i = 0; i < n; i++)
			if(G[i][i] < 0)
			{
				printf("NEGATIVE CYCLE\n");
				flag = 1;
				break;
			}

		if( flag == 1)
			continue;		

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < n; j++)
			{
				if(G[i][j] == INF)
					printf("INF ");
				else
					printf("%d ", G[i][j]);
			}
			printf("\n");
		}
	}


	return  0;
}

