#include <cstdio>
#include <cstdlib>
#include <cstring>

struct Node {
    int key;
    Node *next, *prev;
};


Node *nil;

void insert(int key) {
    Node *x = (Node*)malloc(sizeof(Node));
    x->key = key;
    x->next = nil->next;
    nil->next->prev = x;
    x->prev = nil;
    nil->next = x;
}

Node* listsearch(int key) {
    Node* cur = (Node*)malloc(sizeof(Node));
    cur = nil->next;
    while ( cur != nil && cur->key != key ) {
        cur = cur->next;
    }
    return cur;
}

void init() {
    nil = (Node*)malloc(sizeof(Node));
    nil->next = nil;
    nil->prev = nil;
}


void printlist() {
    Node* cur;
    cur = nil->next;
    for ( int i = 0; cur != nil; i++ ) {
        if ( i != 0 ) printf(" ");
        printf("%d", cur->key);
        cur = cur->next;
    }
}


void deleteNode(Node* t) {
    if ( t == nil ) return;
    t->prev->next = t->next;
    t->next->prev = t->prev;
    free(t);
}


void deleteFirst() {
    deleteNode(nil->next);
}

void deleteLast() {
    deleteNode(nil->prev);
}

void deleteKey(int key) {
    deleteNode(listsearch(key));
}

int main() {
    int key;
    int n;
    int count = 0;
    char name[20];
    init();
    scanf("%d", &n);
    for ( int i = 0; i < n; i++ ) {
        scanf("%s%d", name, &key);
        if ( name[0] == 'i' ) {insert(key); count++;}
        else if ( name[0] == 'd' ) {
            if ( strlen(name) > 6 ) {
                if ( name[6] == 'F' ) 
                    deleteFirst();
                else if ( name[6] == 'L' ) 
                    deleteLast();
            }
            else 
               deleteKey(key);
            }
        }

    printlist();

    return 0;
}
