#include<iostream>

#define MAX 10000
using namespace std;
int l[MAX / 2 + 2], r[MAX / 2 + 2];
int cnt_sum;

void merge(int a[], int left, int mid, int right) {
	int n1 = mid - left;
	int n2 = right - mid;

	for (int i = 0; i < n1; i++) {
		l[i] = a[left + i];
	}
	l[n1] = MAX;
	for (int i = 0; i < n2; i++) {
		r[i] = a[mid + i];
	}
	r[n2] = MAX;

	int p = 0, q = 0;
	for (int i = left; i < right; i++) {
		cnt_sum++;
		if (l[p] < r[q]) {
			a[i] = l[p++];
		}
		else {
			a[i] = r[q++];
		}
	}
}
void mergeSort(int a[], int left, int right) {
	if (left + 1 == right) return;
	int mid = (left + right) / 2;
	mergeSort(a, left, mid);
	mergeSort(a, mid, right);
	merge(a, left, mid, right);
}


int main(void) {

	int n;
	int s[50000];

	cin >> n;

	for (int i = 0; i < n; i++) {
		cin >> s[i];
	}

	mergeSort(s, 0, n);

	for (int i = 0; i < n; i++) {
		cout << s[i]<<" ";
	}
	cout << endl;
	cout << cnt_sum<<endl;

	return 0;


}
