#include <iostream>
using namespace std;
#define NIL -1

//二分木の節点
struct Node { int parent, left, right; };

Node T[1000000];
int n, D[1000000], H[1000000];

//二分木の節点の深さ
void setDepth ( int u, int d ) {
  if ( u == NIL ) return;
  D[u] = d;
  setDepth(T[u].left, d+1);
  setDepth(T[u].right, d+1);
}

//二分木の節点の高さ
int setHeight ( int u ) {

  int h1,h2;
  h1 = h2 = 0;

  if ( T[u].right != NIL ) {
    h2 = setHeight( T[u].right ) + 1;
  }

  if ( T[u].left != NIL ) {
    h1 = setHeight( T[u].left ) + 1;
  }

  if ( h1 > h2 ) return H[u] = h1;
  else return H[u] = h2;
}

//兄弟の番号を求める
//兄弟を持たない場合は-1
int getSibling ( int u ) {
  if ( T[u].parent == NIL ) return NIL;
  if ( T[T[u].parent].left != u && T[T[u].parent].left != NIL ) {
    return T[T[u].parent].left;
  }
  if ( T[T[u].parent].right != u && T[T[u].parent].right != NIL ) {
    return T[T[u].parent].right;
  }
  return NIL;
}

//出力
void print ( int u ) {
  cout << "node " << u << ": ";
  cout << "parent = " << T[u].parent << ", ";
  cout << "sibling = " << getSibling(u) << ", ";
  int deg = 0;
  if ( T[u].left != NIL ) deg++;
  if ( T[u].right != NIL ) deg++;
  cout << "degree = " << deg << ", ";
  cout << "depth = " << D[u] << ", ";
  cout << "height = " << H[u] << ", ";

  if ( T[u].parent == NIL ) {
    cout << "root " << endl;
  } else if ( T[u].left == NIL && T[u].right == NIL ) {
    cout << "leaf " << endl;
  } else {
    cout << "internal node" << endl;
  }
}

int main() {
  int id, left, right, root = 0;



  //入力
  cin >> n;
  for ( int i = 0; i < n; i++ ) T[i].parent = NIL; //初期化
  for ( int i = 0; i < n; i++ ) {
    cin >> id >> left >> right;
    T[id].left = left;
    T[id].right = right;
    if ( left != NIL ) T[left].parent = id;
    if ( right != NIL ) T[right].parent = id;
  }

  for ( int i = 0; i < n; i++ ) {
    if ( T[i].parent == NIL ) root = i;
  }

  setDepth(root, 0);

  setHeight(root);

  //出力
  for ( int i = 0; i < n; i++ ) print(i);

  return 0;
