void proc() {
	LOAD(int, N);
	LOADVEC2(int, x, y, N);
	unordered_multimap<int, int>X, Y;
	for (int i = 0; i < N; ++i) {
		X.insert({ x[i], i });
		Y.insert({ y[i], i });
	}
	//
	int res = 0;
	while (!X.empty()) {
		unordered_set<int> xs, ys;
		auto id = X.begin()->second;
		xs.insert(x[id]);
		ys.insert(y[id]);
		int nErase = 0;
		while (true) {
			bool erased = false;
			for (auto oneX : xs) {
				auto itr = X.find(oneX);
				if (itr != X.end()) {
					auto id = X.begin()->second;
					xs.insert(x[id]);
					ys.insert(y[id]);
					X.erase(itr);
					++nErase;
					erased = true;
				}
			}
			for (auto oneY : ys) {
				auto itr = Y.find(oneY);
				if (itr != Y.end()) {
					auto id = Y.begin()->second;
					xs.insert(x[id]);
					ys.insert(y[id]);
					Y.erase(itr);
					++nErase;
					erased = true;
				}
			}
			if (!erased)break;
		}
		res += xs.size() * ys.size() - nErase / 2;
		assert(X.size() == Y.size());
	}
	cout << res << endl;
}


