int atcoder(){
    int h,w,ans=0;
    cin>>h>>w;
    vector<string> s(h);
    REP(i,0,h) cin>>s[i];

    while(1){
        REP(i,0,w){
            REP(j,0,h){
                if(s[i][j]=='.') goto out;
            }
        }
        break;
    out:
        REP(i,0,w){
            REP(j,0,h){
                if(i>0) if(s[i-1][j]=='#') s[i][j]='a';
                if(i<w-1) if(s[i+1][j]=='#') s[i][j]='a';
                if(j>0) if(s[i][j-1]=='#') s[i][j]='a';
                if(j<h-1) if(s[i][j+1]=='#') s[i][j]='a';
            }
        }
        REP(i,0,w) REP(j,0,h) if(s[i][j]=='a') s[i][j]='#';
        ans++;
    }
    cout<<ans<<ENT;
    return 0;
}

signed main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    atcoder();
    return 0;
}
