				}
				l=i;r=j-1;z[i]=r-l+1;
			}
		}
	}
}
long long query(long long p,long long a)
{
	if (p%g==0) return cnt[a][g-1]*(p/g);
	return cnt[a][g-1]*(p/g)+cnt[a][(p-1)%g];
}
long long calc(long long pos,long long a)
{
	if (!pos) return 0;
	if (pos<=sq) return q[a][pos-1];
	len[1]=sp;len[2]=sq;num[1]=p[a][sp-1];num[2]=q[a][sq-1];re=pos-sq;res=num[2];
