			break;
		}
		len[i]=len[i-1]+len[i-2];
		num[i]=num[i-1]+num[i-2];
		res+=num[i-2];
		re-=len[i-2];
	}
	while(cur>2)
	{
		if (re>=len[cur-1])
		{
			res+=num[cur-1];
			re-=len[cur-1];
			cur-=2;
		}
		else cur--;
	}
	if (!re) return res;
	if (cur==2) return res+q[a][re-1];
	return res+p[a][re-1];
}
