#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = 100000000000000;

int n;
vector<ll> a(5000);
vector<vector<ll> > adj(5000, vector<ll>());
//vector<vector<vector<ll> > > dp(5000, vector<vector<ll> >(5000, vector<ll>(2, INF)));
ll dp[5000][5000][2];
vector<int> edges(5000, 0);

void chmin(ll& before, ll after) {
	if (before > after) before = after;
	return;
}

int dfs_pre(int x, int p) {
	if (x != 0 && adj[x].size() == 1) return 0;
	for (auto v : adj[x]) {
		if (v == p) continue;
		else edges[x] += dfs_pre(v, x) + 1;
	}
	return edges[x];
}

void dfs(int x, int p) {
	for (auto v : adj[x]) {
		if (v != p) dfs(v, x);
	}

	//vector<vector<vector<ll> > > sub(n, vector<vector<ll> >(n, vector<ll>(2, INF)));
	ll sub[n][n][2];
	for (int i = 0; i < adj[x].size()+1; ++i)
	{
		for (int j = 0; j < edges[x]+1; ++j)
		{
			sub[i][j][0] = INF;
			sub[i][j][1] = INF;
		}
	}
	sub[0][0][1] = a[x];
	if (a[x] > 0) sub[0][0][0] = a[x];
	int i = 0;
	int e_cnt = 0;

	for (auto v : adj[x]) {
		if (v == p) continue;
		for (int j1 = 0; j1 < e_cnt+1; ++j1)
		{
			for (int j2 = 0; j2 < edges[v]+1; ++j2)
			{
				chmin(sub[i+1][j1+j2][1], sub[i][j1][0] + dp[v][j2][1]);
				chmin(sub[i+1][j1+j2][1], sub[i][j1][1] + dp[v][j2][0]);
				chmin(sub[i+1][j1+j2][1], sub[i][j1][1] + dp[v][j2][1]);
				if (a[x] > 0) chmin(sub[i+1][j1+j2][0], sub[i][j1][0] + dp[v][j2][0]);

				if (dp[v][j2][0] < INF/2 || dp[v][j2][1] < 0) {
					chmin(sub[i+1][j1+j2+1][1], sub[i][j1][1]);
					if (a[x] > 0) chmin(sub[i+1][j1+j2+1][0], sub[i][j1][0]);
				}
			}
		}
		e_cnt += edges[v] + 1;
		i++;
	}
	for (int j = 0; j < edges[x]+1; ++j)
	{
		dp[x][j][0] = sub[i][j][0];
		dp[x][j][1] = sub[i][j][1];
	}

	return;
}

int main() {
	for (int i = 0; i < 5000; ++i)
	{
		for (int j = 0; j < 5000; ++j)
		{
			for (int k = 0; k < 2; ++k)
			{
				dp[i][j][k] = INF;
			}
		}
	}

	cin >> n;
	for (int i = 0; i < n; ++i) cin >> a[i];
	for (int i = 0; i < n-1; ++i)
	{
		int u, v; cin >> u >> v;
		adj[u-1].push_back(v-1);
		adj[v-1].push_back(u-1);
	}

	dfs_pre(0, -1);

	dfs(0, -1);

	int ans;
	for (int j = 0; j < n; ++j)
	{
		if (dp[0][j][0] < INF/2 || dp[0][j][1] < 0) {
			ans = j;
			break;
		}
	}

	cout << ans << endl;
	return 0;
}
