int N, W;
int w[10000];
int v[10000];
int dp[10001][10001];

int rec(int i, int j) {
  if (dp[i][j] >= 0) {
    return dp[i][j];
  }
  int val;
  if (i == N) {
    val = 0;
  } else if (j < w[i]) {
    val = rec(i+1, j);
  } else {
    val = std::max(rec(i+1, j), rec(i+1, j-w[i])+v[i]);
  }
  dp[i][j] = val;
  return val;
}

