using namespace std;

using ll = long long;
using ull = unsigned long long;
using pii = pair<int, int>;
template <class T>
using max_priority_queue = priority_queue<T>;
template <class T>
using min_priority_queue = priority_queue<T, std::vector<T>, std::greater<T>>;

const int INF = 1 << 29;
const ll LL_INF = 1LL << 60;
const double EPS = 1e-9;
const ll MOD = 1000000007;

const int dx[] = {1, 0, -1, 0}, dy[] = {0, -1, 0, 1};
int N;
vector<int> A;
const int MAX_V = 4000001;
pii dp[MAX_V];
void init()
{
  for (int i = 0; i < MAX_V; i++)
  {
    dp[i] = mp(-1, -1);
  }
}

void add(int a, int b)
{
  dp[a] = max(dp[a], mp(0, 0));
  dp[a].first += dp[b].first;
  dp[a].second += dp[b].second;

  if (dp[a].second > 1)
  {
    int idx = 1;
    int res = 2;

    while (true)
    {
      if (res * 2 > dp[a].second)
      {
        break;
      }
      res *= 2;
      idx++;
    }
    dp[a].first += idx;
    dp[a].second -= res;
  }
}
int main()
{
  init();
  cin >> N;
  A.resize(N);
  for (auto &val : A)
  {
    cin >> val;
  }
  sort(A.begin(), A.end());

  dp[0] = mp(0, 1);
  for (int i = 0; i < MAX_V; i++)
  {
    if (dp[i].first == -1 || dp[i].second == -1)
    {
      continue;
    }

    for (int j = 0; j < N; j++)
    {
      add(i + A[j], i);
    }
  }
  int bit = 0;
  int mod = 0;
  for (int i = 1; i < MAX_V; i++)
  {
    if (dp[i].first == -1 || dp[i].second == -1)
    {
      continue;
    }
    bit += dp[i].first;
    mod += dp[i].second;

    if (mod > 1)
    {
      int idx = 1;
      int res = 2;
      while (true)
      {
        if (res * 2 > mod)
        {
          break;
        }
