	//			//func(h, w, data[h][w]);
	//		}
	//	}
	//}

	template <class INDEX>
	vector<T>& operator[](INDEX indx){
		return data[indx];
	}

	bool IsValid(const Array2DAccessor& indx) {
		return 0LL <= indx.h && indx.h < data.size() && 0LL <= indx.w && indx.w < data.front().size();
	}

public:
	vector<vector<T>> data;
};

template<class T>
const initializer_list<typename Array2D<T>::Array2DAccessor> Array2D<T>::Array2DAccessor::UpDownLeftRight = { { 0LL, 1LL },{ 0LL, -1LL },{ -1LL, 0LL },{ 1LL, 0LL } };

