//深さ優先探索
//template <template<class T, class Allocator = StdAlloc<T>> class Container, class T>
template<class ACCESSOR, class WORK, class SEARCH>
tuple<ULL> DepthFirstSearch(Array2D<unsigned>& field, const ACCESSOR& accessor, const initializer_list<ACCESSOR>& list, const WORK& Work, const SEARCH& IsSearch)
{
	Work(accessor);

	tuple<ULL> info = make_tuple(1ULL);

	for (auto df : list) {
		if (IsSearch(accessor + df, field)) {
			tuple<ULL> nowInfo = DepthFirstSearch(field, accessor + df, list, Work, IsSearch);
			get<0>(info) = max(get<0>(info), get<0>(nowInfo) + 1ULL);
		}
	}

	return info;
}

