	for (auto h = 0; h < H; h++) {
		for (auto w = 0; w < W; w++) {
			if (board[h][w] == 0) {
				continue;
			}

			tuple<ULL> info = DepthFirstSearch(
				board,
				Array2D<unsigned>::Array2DAccessor{ h, w },
				Array2D<unsigned>::Array2DAccessor::UpDownLeftRight,
				[&board](auto a) {	board[a.h][a.w] = 0;	},
				[](auto indx, auto board) {	return board.IsValid(indx) && board[indx.h][indx.w] == 1;	}
			);

			if (get<0>(info) <= 1) {
				cout << "No" << endl;
				return 0;
			}
		}
	}

