ll mod = 1000000007;
bool cmp(int a, int b) { return a > b; }
void solve(int T)
{
	cin >> n >> k;
	vint b, c;
	ll zero = 0;
	ll ans = 1;
	for (int i = 1; i <= n; i++)
	{
		cin >> a[i];
		if (a[i] > 0)b.pb(a[i]);
		else if (a[i] < 0)c.pb(a[i]);
		else zero++;
	}
	sort(b.begin(), b.end());
	sort(c.begin(), c.end(), cmp);
	sort(a + 1, a + n + 1);
	if (k > (ll)b.size() + (ll)c.size())
	{
		cout << "0\n";
		return;
	}
	int i = b.size() - 1, j = c.size() - 1, l;
	if ((k & 1) && b.size() == 0)
	{
		for (l = 0; l < k; l++)
			ans = ans * c[l] % mod;
		cout << (ans + mod) % mod << endl;
		return;
	}
	if (b.size() == 0)
	{
		for (j, l = 0; l < k && j >= 0; l++, j--)
			ans = ans * c[j] % mod;
		cout << (ans + mod) % mod << endl;
		return;
	}
	if (k & 1)
	{
		ans = b[b.size() - 1];
		i--; k--;
	}
	while (k > 0)
	{
		if (i >= 1 && j >= 1)
		{
			if (1ll * b[i] * b[i - 1] > 1ll * c[i] * c[i - 1])
			{
				ans = ans * (1ll * b[i] * b[i - 1] % mod) % mod;
				i -= 2;
			}
			else
			{
				ans = ans * (1ll * c[i] * c[i - 1] % mod) % mod;
				j -= 2;
			}
		}
		else 
		{
			if (i >= 1)
			{
				for (i, l = 0; l < k && i >= 0; l++, i--)
					ans = ans * b[i] % mod;
				cout << (ans + mod) % mod << endl;
				return;
			}
			else if (j >= 1)
			{
				for (j, l = 0; l < k && j >= 0; l++, j--)
					ans = ans * c[j] % mod;
				cout << (ans + mod) % mod << endl;
				return;
			}
		}
		k -= 2;
	}
	cout << (ans + mod) % mod << endl;
}
int main()
{
	std::ios::sync_with_stdio(false);
	cin.tie(NULL);
	int numoftest = 1;

	//cin >> numoftest;


	for (int siven = 1; siven <= numoftest; ++siven)
		solve(siven);
	return 0;
}

