#include<bits/stdc++.h>

using namespace std;

#define H_MAX 100000


//top down approach
int minimumCost(vector<int> height, size_t stone, int dp[]){
    //base case
    if(stone==height.size()-1){
        return 0;
    }

    //memory or soul of dynamic program
    int oneStep = INT_MAX;

    if(dp[stone+1]!=0){
        oneStep = dp[stone+1] + abs(height[stone]-height[stone+1]);
    }
    else{
        oneStep = minimumCost(height, stone+1, dp) + abs(height[stone]-height[stone+1]);
    }

    int twoStep = INT_MAX;

    if(stone+2<=height.size()-1){
        if(dp[stone+2]!=0){
            twoStep = dp[stone+2] + abs(height[stone]-height[stone+2]);
        }
        else{
            twoStep = minimumCost(height, stone+2, dp) + abs(height[stone]-height[stone+2]);
        }
    }

    return min(oneStep, twoStep);
}

int main(){
    int n;
    cin >> n;

    vector<int> height(n+1);
    height[0] = 0;

    for(int i=1; i<=n; i++){
        cin >> height[i];
    }

    int dp[H_MAX] = {0};

    cout << minimumCost(height, 1, dp);

    return 0;
