using namespace std;

int calclcm(int a, int t){
  int A = a, T = t;
  int gcd = 0;
  //euclid;
  if(a > t){
    int tmp = t;
    t = a;
    a = tmp;
  }
  int d = 0;
  int r = -1;
  while(r != 0){
    d = t / a;
    r = t % a;
    t = r;
    a = d;
  }
  gcd = a;
//  cout << gcd << " ";
  return (A * T) / gcd;
}

int main(){
  int N;
  cin >> N;
  vector<int> A(N), T(N), L(N);
  for(int i = 0; i < N; i++) cin >> A[i] >> T[i];
  for(int i = 0; i < N; i++){
    L[i] = calclcm(A[i], T[i]);
 //   cout << L[i] << endl;
  }
  //A'[i] T'[i] = 最小公倍数のlcm[i]の倍数で、A[i-1], T[i-1] 以上で最小なA'[i] T'[i]
  for(int i = 1; i < N; i++){
    int preA = A[i-1], preT = T[i-1];
    for(int j = 1; j < 10000; j++){
      int nowA = L[i] * j / T[i];
      int nowT = L[i] * j / A[i];
      if(nowA < preA || nowT < preT) continue;
      else{
        A[i] = nowA, T[i] = nowT;
        break;
      }
    }
  }
  int ans = A[N-1] + T[N-1];
  //cout << A[N-1] << " " << T[N-1] << endl;
  cout << ans;
}
