void fin(T const& t){ std::cout << t << std::endl; exit(0); }

struct line {
  int64_t p, q, r;
  line() {}
  line(int64_t a, int64_t b, int64_t c): p(a), q(b), r(c) {}
};

int main() {
  int N, M; std::cin >> N >> M;
  std::vector<int> xs(M), ys(N);
  std::vector<line> hL(N), vL(M);
  // (p,r)-(q,r)
  for(int i = 0; i < N; ++i) { std::cin >> hL[i].p >> hL[i].q >> hL[i].r; ys[i]=hL[i].r; }
  // (p,q)-(p,r)
  for(int i = 0; i < M; ++i) { std::cin >> vL[i].p >> vL[i].q >> vL[i].r; xs[i]=vL[i].p; }
  // compress
  std::sort(xs.begin(), xs.end()); xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
  std::sort(ys.begin(), ys.end()); ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
  // walls
  int XS = xs.size(), YS = ys.size();
  std::vector<std::vector<int>> hW(YS, std::vector<int>(XS, 0)), vW(YS, std::vector<int>(YS, 0));
  for(int i = 0; i < N; ++i) {
    line& w = hL[i]; // w.p < w.q : given
    int x1 = std::max(0, (int)(std::lower_bound(xs.begin(), xs.end(), w.p) - xs.begin()));
    int x2 = std::min(XS-1, (int)(std::upper_bound(xs.begin(), xs.end(), w.q) - xs.begin()-1));
    int y  = std::lower_bound(ys.begin(), ys.end(), w.r) - ys.begin();
    ++hW[y][x1];
    --hW[y][x2];
  }
  for(int y = 0; y < YS; ++y) for(int x = 1; x < XS; ++x) hW[y][x] += hW[y][x-1];
  for(int i = 0; i < M; ++i) {
    line& w = vL[i]; // w.q < w.r : given
    int x  = std::lower_bound(xs.begin(), xs.end(), w.p) - xs.begin();
    int y1 = std::max(0, (int)(std::lower_bound(ys.begin(), ys.end(), w.q) - ys.begin()));
    int y2 = std::min(YS-1, (int)(std::upper_bound(ys.begin(), ys.end(), w.r) - ys.begin()-1));
    ++vW[y1][x];
    --vW[y2][x];
  }
  for(int x = 0; x < XS; ++x) for(int y = 1; y < YS; ++y) vW[y][x] += vW[y-1][x];
  // bfs
  std::vector<std::vector<bool>> visited(YS-1, std::vector<bool>(XS-1, false));
  std::queue<std::pair<int,int>> q;
  int x = std::lower_bound(xs.begin(), xs.end(), 0) - xs.begin() - 1;
  int y = std::lower_bound(ys.begin(), ys.end(), 0) - ys.begin() - 1;
  if(x < 0 || x > XS-2 || y < 0 || y > YS-2) fin("INF");
  q.push(std::make_pair(x, y));
  while(!q.empty()) {
    auto const& p = q.front(); x = p.first; y = p.second; q.pop();
    visited[y][x] = true;
    // ydec
    if(hW[y][x] < 1) {
      if(y <= 0) fin("INF");
      if(!visited[y-1][x]) q.push(std::make_pair(x, y-1));
    }
    // yinc
    if(hW[y+1][x] < 1) {
      if(y >= YS-2) fin("INF");
      if(!visited[y+1][x]) q.push(std::make_pair(x, y+1));
    }
    // xdec
    if(vW[y][x] < 1) {
      if(x <= 0) fin("INF");
      if(!visited[y][x-1]) q.push(std::make_pair(x-1, y));
    }
    // xinc
    if(vW[y][x+1] < 1) {
      if(x >= XS-2) fin("INF");
      if(!visited[y][x+1]) q.push(std::make_pair(x+1, y));
    }
  }
  // calc area
  int64_t ans = 0;
  for(int y = 0; y < YS-1; ++y) for(int x = 0; x < XS-1; ++x) if(visited[y][x]) {
    ans += (xs[x+1] - xs[x])*(ys[y+1] - ys[y]);
  }
  fin(ans);
  return 0;
}
