	// sz[x] := xを含む集合のサイズ
	vector<int> sz;
	UnionFind(const int V) :
		V(V),
		par(vector<int>(V)),
		sz(vector<int>(V, 1))
		{
			for(int i = 0; i < V; ++i) par[i] = i;
		}
	bool unite(int x, int y) {
		x = root(x), y = root(y);
		if(same(x, y)) return false;
		if(y < x) swap(x, y);
		par[y] = x;
		sz[x] += sz[y];
		return true;
	}
	int root(int x) {
		if(par[x] == x) return x;
		return (par[x] = root(par[x]));
	}
	bool same(int x, int y) {
		return (root(x) == root(y));
	}
	int size(int x) {
		return sz[root(x)];
	}
};

int main() {
	int64_t n, m; cin >> n >> m;
	UnionFind uf(n);
	int64_t a[m], b[m], ans[m];
	for(int i = 0; i < n; ++i) {
		cin >> a[i] >> b[i];
		a[i]--; b[i]--;
	}
	ans[m - 1] = n * (n - 1) / 2;
	for(int q = m - 2; q >= 0; --q) {
		ans[q] = ans[q + 1];
		if(not uf.same(a[q+1], b[q+1])) ans[q] -= (int64_t)uf.size(a[q + 1]) * (int64_t)uf.size(b[q + 1]);
		uf.unite(a[q + 1], b[q + 1]);
	}
	for(int i = 0; i < m; ++i) cout << ans[i] << "\n";
	return 0;
