void dfs_r(int p) {

    queue<int> que;
    bitset<100000> f; f[p] = 1;
    rep(i, rg[p].size()) {
        que.push(rg[p][i]);
        f[rg[p][i]] = 1;
    }

    while (que.size()) {
        int pp = que.front(); que.pop();
        rep(i, rg[pp].size()) {
            if (!f[rg[pp][i]]) {
                rg[p].push_back(rg[pp][i]);
                que.push(rg[pp][i]);
                f[rg[pp][i]] = 1;
            }
        }
    }

}

void dfs_k(int r) {

    queue<int> que;
    bitset<100000> f; f[r] = 1;
    rep(i, lg[r].size()) {
        que.push(lg[r][i]);
        f[lg[r][i]] = 1;
    }

    while (que.size()) {
        int rr = que.front(); que.pop();
        rep(i, lg[rr].size()) {
            if (!f[lg[rr][i]]) {
                lg[r].push_back(lg[rr][i]);
                que.push(lg[rr][i]);
                f[lg[rr][i]] = 1;
            }
        }
    }

}

