int check(vector<int> &a, int lstart, int rstart, ll m, int p, int v) {
    int n = a.size(), res = 0;
    ll have = (rstart - p) * m;
    for(int i = lstart, j = rstart; i < p && j < n; i++, j++) {
        if(a[j] + m - a[i] >= 0) {
            have -= (a[j] + m - a[i]);
            res++;
        }
    }
    return have > 0 ? max(0LL, res - have) : res;
}

