void Insertion_sort(int g){
  int v,j;
  for(int i = g;i < n;i++){
    v = data[i];
    j = i - g;
    while(v < data[j] && j >= 0){
      data[j + g] = data[j];
      j -= g;
      cnt++;
    }
    data[j + g] = v;
  }
  return;
