using namespace std;

int main(){
    int32_t N, M;
    std::cin >> N >> M;
    string S;
    cin >> S;
    struct step {
        int pos;
        int num_step;
        vector<int>* path;
        step (int pos, int ns, vector<int>* p) : pos(pos), num_step(ns), path(p) {}
    };
    queue<step> q;
    q.push(step(N, 0, new vector<int>));
    vector<bool> visited(N+1, false);
    vector<int> res_path;
    int min_step = INT_MAX;
    while (!q.empty()) {
        step cur_s = q.front();
        q.pop();
        if (cur_s.pos == 0) {
            if (cur_s.num_step < min_step) {
                res_path = *(cur_s.path);
                min_step = cur_s.num_step;
            } else if (cur_s.num_step == min_step) {
                auto cur_it = cur_s.path->rbegin();
                auto pre_it = res_path.rbegin();
                while(cur_it != cur_s.path->rend()) {
                    if (*cur_it < *pre_it) {
                        res_path = *(cur_s.path);
                        break;
                    } else if (*cur_it > *pre_it) {
                        break;
                    }
                    cur_it++;
                    pre_it++;
                }
            }
            continue;
        }
        if (visited[cur_s.pos] == true) {
            continue;
        } else {
            visited[cur_s.pos] = true;
            for (int i = 1; i <= M; i++) {
                if (cur_s.pos < i || visited[cur_s.pos - i] == true || S[cur_s.pos - i] == '1') {
                    continue;
                } else {
                    vector<int>* new_path = new vector<int>;
                    *new_path = *cur_s.path;
                    new_path->push_back(i);
                    q.push(step(cur_s.pos - i, cur_s.num_step + 1, new_path));
                }
            }
        }
    }

    if (min_step == INT_MAX) {
        cout << "-1" << endl;
        return 0;
    }
    for (auto it = res_path.rbegin(); it != res_path.rend(); it++) {
        cout << *it << " ";
    }
    cout << endl;

    return 0;
}
