using namespace std;

vector<lli> a,b,p;

lli calc(lli level,lli num){
	lli right = 0;
	lli left = a[level]-1;
	lli middle = (right+left)/2;
	if(DEBUG)cout<<"level="<<level<<" num= "<<num<<endl;

	if(level == 0)return 1;

	if(num == 0)return 0;
	else if(num < middle){
		return calc(level-1,num-1);
	}
	else if(num == middle){
		return p[level-1] + 1;
	}
	else if(middle < num){
		return p[level-1] + 1 + calc(level-1,num-middle-1);
	}
	else{
		return p[level];
	}
}


