#include <bits/stdc++.h>
using namespace std;

void solve(int N, string c) {
    int i = 0, j = N - 1;
    int ans = 0;
    // WR をなくす
    // →左から W を探して、右から R を探して、入れ替える
    while (1) {
        while (i < N - 1 && c[i] == 'R') {
            i++;
        }
        if (i == N - 1) {
            break;
        }
        if (j > 0 && c[j] == 'W') {
            j--;
        }
        if (j == 0) {
            break;
        }
        if (i < j) {
            assert(c[i] == 'W');
            assert(c[j] == 'R');
            ans++;
            i++;
            j--;
        } else {
            break;
        }
    }
    cout << ans << endl;
}


