#include <cstdio>
#include <cstring>
#include <algorithm>
#define N 500100
typedef long long ll;
using namespace std;

int head[N*2],cnt;
ll dep[N*2],sum[N*2],son[N*2];
ll dp[N*2][2];
struct Edge{
	int v,next;
}edge[N*2*2];

void init(){
	memset(head,-1,sizeof(head));
	cnt=0;
}

void addedge(int u,int v){
	edge[cnt].v=v;
	edge[cnt].next=head[u];
	head[u]=cnt++;
	edge[cnt].v=u;
	edge[cnt].next=head[v];
	head[v]=cnt++;
}

void dfs(int u,int fa){
	sum[u]=0;
	if(fa==-1) dep[u]=0;
	else dep[u]=dep[fa]+1;
	bool flag=0;
	int l,r;
	int cou=0;
	son[u]=1;
	for(int i=head[u];i!=-1;i=edge[i].next){
		int v=edge[i].v;
		if(v==fa) continue;
		dfs(v,u);
		sum[u]+=son[v]+sum[v];
		flag=1;
		if(cou==0) l=v;
		else r=v;
		cou++;
	}
	if(!flag){
		dp[u][1]=0;
		dp[u][0]=0;
	}
	else{
		son[u]=son[l]+son[r];
		dp[u][1]=min(sum[l]+son[l]+min(dp[r][1]+1,dp[r][0]+1),sum[r]+son[r]+min(dp[l][1]+1,dp[l][0]+1));
		dp[u][0]=min(dp[l][1]+1,dp[l][0]+1)+min(dp[r][1]+1,dp[r][0]+1)+dep[u];
	}
}

int main(){
	init();
	int n;
	scanf("%d",&n);
	int cou=n-1;
	for(int i=0;i<n-1;i++){
		int u,v;
		scanf("%d %d",&u,&v);
		u--;v--;
		if(u==n-1){
			addedge(i,cou);
			cou++;
		}
		else addedge(i,u);
		if(v==n-1){
			addedge(i,cou);
			cou++;
		}
		else addedge(i,v);
	}
	dfs(0,-1);
	printf("%lld\n",min(dp[0][0],dp[0][1]));
    return 0;
},runtime_error,,p01461

