int fact(int n) {
    if (n == 0) return 1;
    if (n > 0) return n * fact(n - 1);
}

int NCR(int n, int r) {
    if (n == r) return 1;
    if (r == 0 && n != 0)
        return 1;
    else
        return (n * fact(n - 1)) / fact(n - 1) * fact(n - r);
}

