#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<LL, LL> pii;

int N, K;
int A[505050];
int T[2020202];
bool chk[505050];
vector<int> ans;

void update(int id, int s, int e, int t){
    if (e < t || t < s) return;
    if (s == e) {
        T[id] = t;
        return;
    }
    int mid = (s+e)/2;
    update(id*2, s, mid, t);
    update(id*2+1, mid+1, e, t);
    if (A[T[id*2]] > A[T[id*2+1]]) T[id] = T[id*2];
    else T[id] = T[id*2+1];
}

int query(int id, int s, int e, int ts, int te){
    if (e < ts || te < s) return N+1;
    if (ts <= s && e <= te) return T[id];
    int mid = (s+e)/2;
    int lret=query(id*2, s, mid, ts, te);
    int rret=query(id*2+1, mid+1, e, ts, te);
    if (A[lret] > A[rret]) return lret;
    return rret;
}

priority_queue<int> PQ;

int main(){
    scanf("%d %d", &N, &K);
    for (int i=0; i<N; i++){
        scanf("%d", &A[i]);
        update(1, 0, N-1, i);
    }
    for (int i=0; i<N; i+=K){
        int k = query(1, 0, N-1, i, min(N, i+K-1));
        if (k == query(1, 0, N-1, max(1, k-K+1), min(N, k+K-1))){
            PQ.push(k);
            chk[k] = true;
        }
    }
    while (!PQ.empty()){
        int t = PQ.top();
        PQ.pop();
        A[t] = 0;
        update(1, 0, N-1, t);
        ans.push_back(t);
        int k = query(1, 0, N-1, t/K*K, min(N-1, (t/K+1)*K-1));
        if (A[k] && !chk[k] && k == query(1, 0, N-1, max(0, k-K+1), min(N-1, k+K-1))){
            PQ.push(k);
            chk[k] = true;
        }
        k = query(1, 0, N-1, max(0, (t/K-1)*K), max(0, t/K*K-1));
        if (A[k] && !chk[k] && k == query(1, 0, N-1, max(0, k-K+1), min(N-1, k+K-1))){
            PQ.push(k);
            chk[k] = true;
        }
        k = query(1, 0, N-1, min(N, (t/K+1)*K), min(N-1, (t/K+2)*K-1));
        if (A[k] && !chk[k] && k == query(1, 0, N-1, max(0, k-K+1), min(N-1, k+K-1))){
            PQ.push(k);
            chk[k] = true;
        }
    }
    for (int i=N-1; i>=0; i--) printf("%d\n", ans[i]+1);
    return 0;
}
