void RandomJump(ll pos, ll X, ll cur, ll cnt)
{
    if (pos == X or cnt > X) {
        if (ans > cnt) {
            ans = cnt;
        }
    } else if(pos > X){
        RandomJump(pos - cur, X, cur + 1, cnt + 1);
        RandomJump(pos, X, cur + 1, cnt + 1);
    } else {
        RandomJump(pos + cur, X, cur + 1, cnt + 1);
        RandomJump(pos, X, cur + 1, cnt + 1);
    }
}
