int dp[100001];

int minCost(vector<int> ar,int i){
    if(i >= ar.size()-1){
        return 0;
    }
    if(dp[i]!=-1){
        return dp[i];
    }
    int minC = LLONG_MAX;
    minC=min(minC,minCost(ar,i+1)+abs(ar[i]-ar[i+1]));
    minC=min(minC,minCost(ar,i+2)+abs(ar[i]-ar[i+2]));
    return dp[i]=minC;
}


int goEasy( int i, vector<int> &v ){
    int n = v.size();
    if( i == n-1 )return 0;
    if( dp[i] != -1 )return dp[i];
    int ans = LLONG_MAX;
    for( int j = i+1; j <= n-1 && j <= i+2; j++ ){
        ans = min(ans, goEasy(j,v) + abs(v[i] - v[j]));
    }
    return dp[i] = ans;
}

