#include <unordered_map>

using namespace std;

typedef long long ll;
//unordered_map<int, vector<int>> edges;
int edges[10001][10001] = {0};
ll dp[10002] = {0};
bool visited[10002] = {false};

ll helper(int i) {
    if (visited[i]) return dp[i]; // 访问过的节点，直接返回i节点的Longest Path
    else {
        dp[i] = 0;
        visited[i] = true; // 访问过当前这个节点
        for(int j=0;j<10001;j++){
            if(edges[i][j]==1){
                dp[i] = max(dp[i],helper(j)+1);
            }
        }
        return dp[i];
    }
}

int main(int argc, char *argv[]) {
    int N, M;
    cin >> N >> M;
    int a,b;
    for (int i = 0; i < M; i++) {
        cin >> a >> b;
        edges[a][b] = 1;
    }
    ll res = 0;
    for (int i = 1; i <= N; i++) {
