template <typename T> vector<T> table(int n, T v) { return vector<T>(n, v); }

template <class... Args> auto table(int n, Args... args) {
  auto val = table(args...);
  return vector<decltype(val)>(n, move(val));
}

priority_queue<int, vector<int>, greater<int>> que;
int res[128000];

bool solve(long long N, const std::vector<long long> &a, int p) {
  // REP(i,N) cout << res[i] << " \n"[i == N - 1];
  if (p == N) {
    REP(i,N) cout << res[i] << " \n"[i == N - 1];
    return true;
  }
  int top = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != top) {
    res[p] = top;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
  }

  if (que.empty()) return false;
  int sec = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != sec) {
    que.push(top);
    res[p] = sec;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
    que.pop();
  }

  if (que.empty()) return false;
  int thi = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != thi) {
    que.push(top);
    que.push(sec);
    res[p] = sec;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
    que.pop();
    que.pop();
  }

  que.push(top);
  que.push(sec);
  que.push(thi);
  return false;
}

int main() {
  long long N;
  scanf("%lld", &N);
  std::vector<long long> a(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &a[i]);
  }
  REP(i,N) que.push(i + 1);
  bool ok = solve(N, a, 0);
  if (!ok) cout << -1 << endl;
  return 0;
}

