#include <bits/stdc++.h>
using namespace std;

#define int long long

using pii = pair<int, int>;

int H, W, N;
int sy, sx;
string s, t;
string g;
// それぞれの文字に対応する差分を格納
map<char, pii> mp = {
  {'U', {-1, 0}},
  {'D', {1, 0}},
  {'R', {0, 1}},
  {'L', {0, -1}},
};
int dp[111][111][111];

// 範囲内かをチェック
bool check(int y, int x) {
  return y >= 1 and y <= H and x >= 1 and x <= W;
}

bool dfs(int idx, int y, int x) {
  if (dp[idx][y][x] != -1) {
    return dp[idx][y][x];
  }

  // 範囲外に出たら終了
  if (check(y, x) == false) {
    return dp[idx][y][x] = false;
  }

  // 最後まで探索し終える
  if (idx >= g.size()) {
    return dp[idx][y][x] = true;
  }

  if (idx % 2 == 0) { // 高橋くんの手番。1つでもfalseがあってほしい
    bool ret = true;

    // no
    ret &= dfs(idx + 1, y, x);

    // yes
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret &= dfs(idx + 1, ny, nx);

    return dp[idx][y][x] = ret;
  } else { // 青木くんの手番。1つでもtrueがあってほしい
    bool ret = false;

    // no
    ret |= dfs(idx + 1, y, x);

    // yes
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret |= dfs(idx + 1, ny, nx);

    return dp[idx][y][x] = ret;
  }
}

signed main() {
  cin >> H >> W >> N;
  cin >> sy >> sx;
  cin >> s >> t;

  assert(H < 110);
  assert(W < 110);
  assert(N < 110);

  for (int i = 0; i < 111; i++) {
    for (int j = 0; j < 111; j++) {
      for (int k = 0; k < 111; k++) {
        dp[i][j][k] = -1;
      }
    }
  }

  // 探索に使うための配列を用意。高橋→青木→高橋...といった順番になる
  for (int i = 0; i < N; i++) {
    g.push_back(s[i]);
    g.push_back(t[i]);
  }

  bool ans = dfs(0, sy, sx);

  puts(ans ? "YES" : "NO");

  return 0;
},runtime_error,,p03054

