int N, X[10000], Y[10000];
bool graph[10000][10000];

bool used[10000];
int cmp[10000];
int order[10000];
int ptr;

void dfs(int idx)
{
  if(used[idx]++) return;
  for(int i = 0; i < N * 2; i++) if(graph[idx][i]) dfs(i);
  order[ptr++] = idx;
}

void rdfs(int idx, const int cnt)
{
  if(~cmp[idx]) return;
  cmp[idx] = cnt;
  for(int i = 0; i < N * 2; i++) if(graph[i][idx]) rdfs(i, cnt);
}

bool cross(int s, int t, int g)
{
  if(s > t) swap(t, s);
  return (t - s < g);
}

