const ll MOD=998244353;
const ll INF=1e18;
const double pi=acos(-1);
const double eps=1e-10;

int dx[]={1, 0, -1, 0};
int dy[]={0, -1, 0, 1};

const int MAX_N = 300010;

ll modpow(ll a, ll b){
    if(b==0) return 1;
    else if(b%2==0){
        ll d=modpow(a, b/2)%MOD;
        return (d*d)%MOD;
    }
    else{
        return (a*modpow(a, b-1))%MOD;
    }
}

int fact[MAX_N], finv[MAX_N];
ll comb(int n, int r){
    if(n<r || r<0) return 0;
    return fact[n]*finv[n-r]%MOD*finv[r]%MOD;
}

ll comb2(int n, int a, int b, int c){
    return fact[n]*finv[a]%MOD*finv[b]%MOD*finv[c]%MOD;
}

ll calc(int n){
    fact[0]=finv[0]=1;
    for(int i=1; i<=n; i++){
        fact[i]=(fact[i-1]*i)%MOD;
        finv[i]=modpow(fact[i], MOD-2);
    }
}

int main(){
    ll n, R, B, k; cin>>n>>R>>B>>k;
    vector<P> usecnt;

    calc(300005);

    int cnt=0;
    for(ll i=0; i<=n; i++){
        ll sum=k;
        sum -= i*R;
        if(sum % B == 0){
            usecnt.eb(P(i, sum/B));
        }
    }

    ll ans=0;

    for(auto i:usecnt){
        ll redcnt=i.fs;
        ll bluecnt=i.sc;
        ll greencnt=0;
        ll sumcnt=redcnt+bluecnt;

        if(sumcnt > n){
            redcnt -= (sumcnt - n);
            bluecnt -= (sumcnt - n);
            greencnt += (sumcnt - n);
        }

        int cnt=1;
        while(1){
            if(redcnt == -1 || bluecnt == -1){
                break;
            }

            ans += comb2(redcnt + bluecnt + greencnt, redcnt, bluecnt, greencnt) * comb(n, n - redcnt - bluecnt - greencnt);
            ans %= MOD;

            //cout << redcnt << " " << bluecnt << " " << greencnt << endl;
            //cout << comb2(redcnt + bluecnt + greencnt, redcnt, bluecnt, greencnt) * comb(n, n - redcnt - bluecnt - greencnt) << endl;

            cnt++;
            redcnt--;
            bluecnt--;
            greencnt++;
        }
    }

    cout << ans << endl;
