string make_str(int v){
	ostringstream os;
	os << v;
	return os.str();
}

vector<int> s[400001];

int calc(int t,int v){
	calced[v]=true;
	s[v].clear();
	for(int i=0;i<(int)G[t][v].size();i++){
		int nv=G[t][v][i];
		if(nv>=300000 || nv<0)return -1;
		if(!calced[nv]){
			int val=calc(t,nv);
			if(val==-1)return -1;
			s[v].push_back(val);
		}
	}
	if(s[v].size()>0)sort(s[v].begin(),s[v].end());
	string str="";
	for(int i=0;i<s[v].size();i++){
		if(i>0)str+=';';
		str+=make_str(s[v][i]);
	}
	s[v].clear();
	if(str.size()==0){
		str+='0';
	}
	if(mp.find(str)!=mp.end()){
		return mp[str];
	}else{
		if(t==0)return -1;
		int siz=mp.size();
		mp[str]=siz+1;
		return siz+1;
	}
	return -1;
}

void bfs(int t,int s){
	queue<int> que;
	memset(dist,-1,sizeof(dist));
	vs.clear();
	que.push(s);
	dist[s]=0;
	while(que.size()){
		int v=que.front();
		que.pop();
		vs.push_back(v);
		for(int i=0;i<G[t][v].size();i++){
			if(dist[G[t][v][i]]==-1){
				dist[G[t][v][i]]=dist[v]+1;
				que.push(G[t][v][i]);
			}
		}
	}
}

