  int my_label = (cw_ids[0] + num_bumps) % n;
  ll my_position = (cw[0] + T) % L;
  int ee = upper_bound(final_positions.begin(), final_positions.end(), my_position) - final_positions.begin() - 1;
  for(int l = my_label; ; l = (l + 1) % n, ee = (ee + 1) % n){
