    sum += ABC[i].f - ABC[i].s.s;
    sum -= pque.top();
    pque.pop();
    ans[i] = sum;
  }
  priority_queue<ll, vector<ll>, greater<ll>> pque2;
  sum = 0;
  for(int i = N-1; i >= N-Y; i--){
    pque2.push(ABC[i].s.f - ABC[i].s.s);
    sum += ABC[i].s.f - ABC[i].s.s;
  }
  ans[N-Y-1] += sum;
  for(int i = N-Y-1; i >= 0; i--){
    pque2.push(ABC[i].s.f - ABC[i].s.s);
    sum += ABC[i].s.f - ABC[i].s.s;
    sum -= pque2.top();
    pque2.pop();
    ans[i-1] += sum;
  }
  ll answer = 0;

  for(int i = X-1; i < N-Y; i++){
    answer = max(answer, Csum + ans[i]);
  }
  cout << answer << endl;



}
