#include <bits/stdc++.h>

using vi = std::vector<int>;
using pi = std::pair<int, int>;
vi a;
std::vector<vi> edges;
std::vector<bool> isConnected;
std::priority_queue<pi, std::vector<pi>, std::greater<pi>> connectedPQ, disconnectedPQ;

void dfs(int, int);
int64_t solve();

int main()
{
	int64_t ans{solve()};
	if (ans < 0) puts("Impossible");
	else printf("%lld\n", ans);

	return 0;
}

int64_t solve()
{
	int N, M;
	scanf("%d%d", &N, &M);
	a.resize(N);
	for (int i{}; i < N; i++)
	{
		scanf("%d", &a[i]);
		disconnectedPQ.push({a[i], i});
	}
	edges.resize(N);
	for (int i{}; i < M; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		edges[x].push_back(y);
		edges[y].push_back(x);
	}
	isConnected.resize(N);
	int64_t sum{};
	dfs(0, -1);
	while (!disconnectedPQ.empty())
	{
		auto dis{disconnectedPQ.top()};
		disconnectedPQ.pop();
		if (isConnected[dis.second]) continue;
		if (connectedPQ.empty()) return -1;
		auto con{connectedPQ.top()};
		connectedPQ.pop();
		sum += (int64_t)dis.first + con.first;
		dfs(dis.second, dis.second);
	}
	return sum;
}

void dfs(int index, int ignore)
{
	if (isConnected[index]) return;
	isConnected[index] = true;
	if (index != ignore)
		connectedPQ.push({a[index], index});
	for (auto& e: edges[index])
		dfs(e, ignore);
	return;
