#include<bits/stdc++.h>
using namespace std;

typedef long long ll;

const int N = 2e5;
const ll INF = 1e18;

int n;
ll k;

vector<ll> pos, neg;

ll cek(ll x){
	ll id = 0ll;
	if(x >= 0){
		id += (ll)(pos.size()) * (ll)(neg.size());
		int r = pos.size()-1;
		for(int i=0;i<pos.size();i++){
			while(pos[i] * pos[r] > x) r--;
			if(r-i <= 0) break;
			id+=(ll)(r-i);
		}
		r = 0;
		for(int i=neg.size()-1;i>=0;i--){
			while(neg[i] * neg[r] > x) r++;
			if(i-r <= 0) break;
			id+=(ll)(i-r);
		}
	} else {
		int r = neg.size()-1;
		for(int i=pos.size()-1;i>=0;i--){
			while(pos[i] * neg[r] > x) r--;
			id+=(ll)(r+1);
		}
		/*
		3 3
		-4 -2
		*/
	}
	return id;
}

int main(){
	scanf("%d %lld",&n,&k);
	for(int i=1;i<=n;i++){
