ll f(ll a, ll b){
    ll ans = a;
    if((b-a)<bin[16]){
        for(ll i=a; i<b; i++){
            ans ^= (i+1);
        }
        return ans;
    }

    decltype(bin)::iterator it = lower_bound(bin.begin(), bin.end(), a);
    for(int i=0; *(it-i)>=4; i++){
        if(*(it-i)+(*it)<=b){
            return f(a,(*it)-1LL) ^ f(*(it-i)+(*it), b);
            break;
        }
        if((*it)-(*(it-i))>=a){
            return f(a,(*it)-(*(it-i))) ^ f((*it),b);
            break;
        }
    }
    return 0LL;
}

