void merge(v &ls,v &rs,v& u){
	int sl=ls.size(),sr=rs.size();if(sl>sr)swap(ls,rs);
	sort(ls.begin(),ls.end(),cmpy),sort(rs.begin(),rs.end(),cmpx),mn[0]=rs[0].Y;
	for(int i=1;i<sr;++i)mn[i]=min(mn[i-1],rs[i].Y);
