#include<bits/stdc++.h>
using namespace std;

typedef long long ll;

int N,N_,A,B,Q;
int X[200010];
ll INF = 1001001001001001001;
ll seg[2][400010];

void init()
{
    N_ = 1;
    while(N_ <= N)N_ *= 2;
    for(int i = 0; i < N_ * 2 - 1; i++)seg[0][i] = seg[1][i] = INF;
    return;
}

void update(int t,int p,ll x)
{
    p += N_ - 1;
    seg[t][p] = min(seg[t][p],x);
    while(p)
    {
        p = (p - 1) / 2;
        seg[t][p] = min(seg[t][p * 2 + 1],seg[t][p * 2 + 2]);
    }
    return;
}

ll get_min(int t,int a,int b,int k = 0,int l = 0,int r = N_)
{
    if(b <= l || r <= a)return INF;
    if(a <= l && r <= b)return seg[t][k];
    ll L = get_min(t,a,b,k * 2 + 1,l,(l + r) / 2);
    ll R = get_min(t,a,b,k * 2 + 2,(l + r) / 2,r);
    return min(L,R);
}

ll unit()
{
    ll ans = INF,mem = 0;
    for(int i = 1; i <= Q; i++)
    {
        ll L = get_min(0,0,X[i]) + X[i],R = get_min(1,X[i],N) - X[i];
        ll res = min(L,R) - abs(X[i] - X[i - 1]);
        update(0,X[i - 1],res - X[i - 1]);
        update(1,X[i - 1],res + X[i - 1]);
        mem += abs(X[i] - X[i - 1]);
    }
    for(int i = 0; i < N; i++)ans = min(ans,get_min(0,i,i + 1) + i);
    return ans + mem;
}

int main()
{
    scanf("%d%d%d%d",&N,&Q,&A,&B);
    A--;B--;
    for(int i = 1; i <= Q; i++)scanf("%d",X + i),X[i]--;
    ll ans = INF;

    init();
    X[0] = B;
    update(0,A,-A);
    update(1,A,A);
    ans = unit();

    init();
    X[0] = A;
    update(0,B,-B);
    update(1,B,B);
    ans = min(ans,unit());

    printf("%lld\n",ans);
    return 0;
}
