vector<int> prime;

void prime_search(int x) {
    for(int i = 0;i < x;i++) prime[i] = i;
    prime[1]=0;
    for(int j = 2;j < x;j++) {
        for(int n = 2;j*n < x;n++) {
            prime[j*n] = 0;
        }
    }
}

int main() {
    int n,ans;
    while(1) {
        cin >> n;
        if(n==0) break;
        prime_search(n);
        ans = 0;
        for(int p = 2;p < n;p++) {
            if(prime[p] != 0) {
                for(int pp = 2;pp < n;pp++) {
                    if(prime[pp] == n-p) {
                        ans++;
                        pp=n;
                    }
                }
            }
        }
        cout << ans << endl;
    }
    return 0;
}
