    vector <pair<ll,ll>> v;
    rep(i,n)
    {
        ll c;
        cin>>c;
        if(c<0)
        {
            v.pb(mp(-c,-1));
            neg++;
        }
        else if(c>0)
        {
            v.pb(mp(c,1));
            pos++;
        }
    }
