    if(v.size()<k)
    {
        cout<<0<<'\n';
        return;
    }
    if(k%2==1 && neg==n)
    {
        ll ans=1;
        for(int i=0;i<k;i++)
        {
            ans*=(-v[i].first);
            ans%=mod;
        }
        ans+=mod;
        ans%=mod;
        cout<<ans<<'\n';
        return;
    }
    if(k%2==1 && neg==v.size())
    {
        cout<<0<<'\n';
        return;
    }
    reverse(all(v));
    ll sign=1;
    ll ans=1;
    vl negs,poss;
    for(int i=0;i<k;i++)
    {
        if(v[i].second==1)
        {
            ans*=v[i].first;
            ans%=mod;
            poss.pb(v[i].first);
        }
        else
        {
            ans*=(-v[i].first);
            ans%=mod;
            ans+=mod;
            ans%=mod;
            negs.pb(v[i].first);
            sign*=-1;
        }
    }
    sort(all(poss));
    sort(all(negs));
    if(sign==1)
    {
        cout<<ans<<'\n';
        return;
    }
    else
    {
        ll option1=-473,option2=-473;
        int flagneg=0,flagpos=0;
        ll addneg=0,addpos=0;
        for(int i=k;i<v.size();i++)
        {
            if(v[i].second<0)
            {
                if(flagneg==1)
                    continue;
                flagneg=1;
                addneg=v[i].first;
            }
            if(v[i].second>0)
            {
                if(flagpos==1)
                    continue;
                flagpos=1;
                addpos=v[i].first;
            }
        }
        if(negs.size()!=0 && addneg!=0)
        {
            option1=negs[0]*addneg;
        }
        if(poss.size()!=0 && addpos!=0)
        {
            option2=poss[0]*addpos;
        }
        if(option2==-473 && option1==-473)
        {
            cout<<0<<'\n';
            return;
        }
        if(option1>=option2)
        {
            ans*=modInverse(poss[0]);
            ans%=mod;
            ans*=(-addneg);
            ans%=mod;
            ans+=mod;
            ans%=mod;
        }
