            ans%=mod;
            ans*=(-negs[0]);
            ans%=mod;
            ans+=mod;
            ans%=mod;
            ans*=modInverse((negs[0]*negs[0])%mod);
            ans%=mod;
        }
        cout<<ans<<'\n';
    }
}
