int popcount32(unsigned int x) {
	x = x - ((x >> 1) & 0x55555555);
	x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
	x = (x + (x >> 4)) & 0x0F0F0F0F;
	x = x + (x >> 8);
	x = x + (x >> 16);
	return x & 0x0000003F;
}

long long pow_mod(long long x, long long y, int mod) {
	int res = 1;
	while (y) {
		if (y & 1)res = (res * x) % mod;
		y >>= 1;
		x = (x * x) % mod;
	}
	return res;
}


