const int MAX_N = 250005;
// セグメント木を持つグローバル配列(n2は要素数を2のべき乗にするから)
int n2, dat[2*MAX_N - 1];
void init(int n_) {
  n2 = 1;
  while (n2 < n_) n2 *= 2;
  for (int i = 0; i < 2*n2-1; i++) dat[i] = -INFLL;
}
// k番目の値(0-indexed)をaに変更
void update(int k, int a) {
  // 葉の節点
  k += n2 - 1;
  dat[k] = a;
  // 登りながら更新
  while (k > 0) {
    k = (k-1)/2;
    dat[k] = max(dat[k*2+1], dat[k*2+2]);
  }
}
// 区間max: [a,b)の最大値を求める(k: 節点の番号、l、rはその節点が[l,r)に対応づいていることを表す
// query(a,b,0,0,n2)と呼ぶ
int query(int a, int b, int k=0, int l=0, int r=n2) {
  if (r <= a || b <= l) return -INFLL;
  if (a <= l && r <= b) return dat[k];
  else {
    int vl = query(a,b,k*2+1,l,(l+r)/2);
    int vr = query(a,b,k*2+2,(l+r)/2,r);
    return max(vl, vr);
  }
}

