const int dx[] = {-1, 0, 1, 0}, dy[] = {0, -1, 0, 1};

struct STATE
{
	int grid[10][10];
	int x, y;
	int num;
};

int main()
{
	int m, n;
	while (cin >> m >> n, m + n){
		STATE start;
		memset(&start, 0, sizeof(STATE));
		for (int i = 0; i < n; i++){
			for (int j = 0; j < m; j++){
				scanf("%d", &start.grid[i][j]);
				if (start.grid[i][j] == 2){
					start.x = i;
					start.y = j;
				}
				start.num += !!start.grid[i][j];
			}
		}

		int res = 0;
		queue<STATE> que;
		que.push(start);
		while (!que.empty()){
			STATE st = que.front(); que.pop();
			if (st.num == 0){
				res++;
				continue;
			}

			for (int dir = 0; dir < 4; dir++){
				int i = 1;
				while (true){
					int tx = st.x + dx[dir] * i;
					int ty = st.y + dy[dir] * i;

					if (tx < 0 || tx >= n || ty < 0 || ty >= m) break;
					if (st.grid[tx][ty] == 3) break;

					if (st.grid[tx][ty] == (1 + (st.num == 1))){
						STATE tmp = st;
						tmp.grid[tx][ty] = 3;
						tmp.x = tx;
						tmp.y = ty;
						tmp.num--;
						que.push(tmp);
					}
					i++;
				}
			}
		}

		printf("%d\n", res);
	}

	return 0;
