    long long xi = a;
    long long res = 1;
    while(x != 0){
        if(x & 1){
            res = res*xi%MOD;
        }
        xi = xi*xi%MOD;                                        
        x >>= 1;
    }
    return res;
}

void treedp(int i, int depth, int max_depth){
    if(depth == max_depth){
        dp[i][0] = 1;
        dp[i][1] = 1;
        return;
    }
    long long all = 1;
    long long zeroall = 1;
    for(int c : child[i]){
      treedp(c, depth + 1, max_depth);
        all = all * (dp[c][0] + dp[c][1] + MOD) % MOD;
