bool dfs(int now,int type_a,int type_b,int cost){

    if(memo[now][type_a][type_b][cost] >= 0)return memo[now][type_a][type_b][cost];

    //now番目の商品について、現在のコスト

    //printf("%d %d %d %d %d\n",now,type_a,type_b,cost,mini_cost);

    bool flag = false;

    if(now == n){
        //最後の薬品まで調べた時
        if(type_a*mb != type_b*ma){
            //混合比を満たす組み合わせがなかった
            return false;
        }else{
            //組み合わせがあった
            if(type_a != 0 && type_b != 0){
                //初期状態を除く
                mini_cost = min(mini_cost,cost);
                //コストの最小値を更新
                return true;
            }else{
                return false;
            }
        }
    }

    if(type_a*mb == type_b*ma){
        //混合比を満たす状態になった場合
        if(type_a != 0 && type_b != 0){
            //初期状態を除く
            mini_cost = min(mini_cost,cost);
            //コストの最小値を更新
            return true;
        }
    }


    if(dfs(now+1,type_a+a[now],type_b+b[now],cost+c[now])){
        //now番目を使って薬品ができたらtrueを返す
        flag = true;
    }
    if(dfs(now+1,type_a,type_b,cost)){
        //now番目を使わずに薬品ができたらtrueを返す
        flag = true;
    }
    if(flag){
        return memo[now][type_a][type_b][cost] = true;
    }else{
        return memo[now][type_a][type_b][cost] = false;
    }
}


int main(){

    fill(memo[0][0][0], memo[50][20][20], -1);

    cin >> n >> ma >> mb;
    REP(i,n){
        cin >> a[i] >> b[i] >> c[i];
    }


    if(dfs(0,0,0,0)){
        cout << mini_cost << endl;
    }else{
        cout << "-1" << endl;
    }



    return 0;
}
