bool solve(string c){
  stack<char> st;
  rep(i,c.size()){
    if(c[i] == '(') st.push(c[i]);
    else if(c[i] == '[' ) st.push(c[i]);
    else if(c[i] == ')'){
      if(st.top() != '(') return false;
      if(st.empty()) return false;
      st.pop();
    }
    else if(c[i] == ']'){
      if(st.top() != '[') return false;
      if(st.empty()) return false;
      st.pop();
    }
    return st.empty();
  }
}
