	sort(x.begin(), x.end());
	sort(y.begin(), y.end());

	for (int i = 0; i < N - 1; i++)
	{
		es[i].u = x[i].second;
		es[i].v = x[i + 1].second;
		es[i].cost = x[i + 1].first - x[i].first;
