	for (int i = 0; i < N - 1; i++)
	{
		es[i + N - 1].u = y[i].second;
		es[i + N - 1].v = y[i + 1].second;
		es[i + N - 1].cost = y[i + 1].first - y[i].first;
	}

	int cost;

	cost = kruskal(2*N, 2*N - 2, es);

	cout << cost << endl;

	return 0;
