int a[16],b[16],n,f[16],c[100];
int lowbit(int x)
{
	return x&(-x);
}
int add(int x)
{
	while(x<=n)
	{
		c[x]+=1;
		x+=lowbit(x);
	}
}
int pre(int x)
{
	int sum=0;
	while(x)
	{
		sum+=c[x];
		x-=lowbit(x);
	}
	return sum;
}
void init()
{
	f[0]=1;
	for(int i=1;i<=8;++i)
	{
		f[i]=f[i-1]*i;
	}
}
int cantor_exp(int *p,int len)
{
	int sum=0;
	for(int i=n;i>=1;--i)
	{
		int a=pre(p[i]);
		sum+=a*f[n-i];
		add(p[i]);
	}
	return sum;
}
int main()
{
	ios;
	cin>>n;
	init();
	for(int i=1;i<=n;++i)
