int ldx[]={1,0,-1,0};
int rdy[]={0,-1,0,1};
int rdx[]={-1,0,1,0};

void dfs(int ly,int lx, int ry, int rx){
  visited[ly][lx][ry][rx] = true;

  int nly,nlx,nry,nrx;
  for(int i=0; i<4; i++){
    nly = ly + ldy[i];
    nlx = lx + ldx[i];
    nry = ry + rdy[i];
    nrx = rx + rdx[i];

    if(!visited[nly][nlx][nry][nrx] &&
       0<=nly && nly<h && 0<=nlx && nlx<w && 0<=nry && nry<h && 0<=nrx && nrx<w){
      if(L[nly][nlx]=='%' && R[nry][nrx]=='%'){
	f = true;
	return ;
      }
      if(L[nly][nlx]=='%' || R[nry][nrx]=='%') visited[nly][nlx][nry][nrx] = true;
      if(L[nly][nlx]=='#' && R[nry][nrx]=='.') dfs(ly,lx,nry,nrx);
      if(L[nly][nlx]=='.' && R[nry][nrx]=='#') dfs(nly,nlx,ry,rx);
      if(L[nly][nlx]='.' && R[nry][nrx]=='.')  dfs(nly,nlx,nry,nrx);
    }
    if((nlx<0 || w<=nlx) && (0<=nrx && nrx<w) && R[nry][nrx]=='.')    dfs(ly,lx,nry,nrx);
    if((nrx<0 || w<=nrx) && (0<=nlx && nlx<w) && L[nly][nlx]=='.')    dfs(nly,nlx,ry,rx);
    if((nry<0 || w<=nry) && (0<=nly && nly<w) && L[nly][nlx]=='.')    dfs(nly,nlx,ry,rx);
    if((nly<0 || w<=nly) && (0<=nry && nry<w) && L[nly][nlx]=='.')    dfs(ly,lx,nry,nrx);

  }
}


