    while(i!=1){
        //cout<<i<<" "<<lprime[i]<<endl;
        int lp=lprime[i];
        if(ar[lp])  return true;
        while((i%lp)==0) i=i/lp;
    }
    return false;
}
void adddiv(int i){
    while(i!=1){
        int lp=lprime[i];
        ar[lp]=1;
        while((i%lp)==0) i=i/lp;
    }
