#include <bits/stdc++.h>
using namespace std;
#define INF 0x3f3f3f3fLL
#define endl '\n'
typedef long long ll;
int num[505];
ll cal(int num, int base){
    //int num2 = num;
    if (num % base == 0) num /= base;
    else num = num / base + 1;
    ll ans = 0;
    while (num > 1) {
        ans++;
        num = (num + 1) / 2;
    }
    //cout << num2 << ' ' << base << ' ' << ans << endl;
    return ans;
}
ll solve(int l, int r, int base){
    if (l == r) return cal(num[l], base);
    vector<int>ans;
    for (int i = l; i <= r; i++){
        if (num[i] <= base) {ans.push_back(i);}
    }
    if (ans.empty()){
        return solve(l, r, base * 2) + 1;
    }
    ll ret = 0;
    if (ans[0] - 1 >= l) ret += solve(l, ans[0] - 1, base * 2) + 1;
    for (int i = 0; i < ans.size() - 1; i++){
        int nowl = ans[i] + 1;
        int nowr = ans[i + 1] - 1;
        //cout << nowl << ' ' << nowr << endl;
        if (nowl <= nowr) ret += solve(nowl, nowr, base * 2) + 1;
    }
    if (ans[ans.size() - 1] + 1 <= r) ret += solve(ans[ans.size() - 1] + 1, r, base * 2) + 1;
    return ret;
}
int main(){
    //ios::sync_with_stdio(0);
    int n; cin >> n;
    for (int i = 0; i < n; i++){
        cin >> num[i];
    }
    cout << solve(0, n - 1, 1) << endl;
    return 0;
}
