void solve(long long N, std::vector<long long> H){
  vector< vector<int> > array(N, vector<int>(2, 0));

  array[0][0] = 1; // 下げない場合
  array[0][1] = 1; // 下げた場合

  for(ll i=0; i<N-1; i++){
    array[i+1][0] = 0;
    array[i+1][1] = 0;

    if(H[i]-array[i][i] <= H[i+1]){
      array[i+1][0] = 1;
    }
    if(H[i]-array[i][i] <= H[i+1]-1){
      array[i+1][1] = 1;
    }
  }

  if(array[N-1][0] || array[N-1][1] ){
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
}

