using namespace std;
typedef long long ll;
typedef pair<int, int> pii;
const ll INF = 1000000007;
ll gcd(ll a, ll b) {
	if (b == 0) return a;
	return gcd(b, a % b);
}
int pr[100010];
void uini(int n) {
	for (size_t i = 0; i <= n; i++)
	{
		pr[i] = i;
	}
}

int parent(int x) {
	if (x == pr[x]) return x;
	return pr[x] = parent(pr[x]);
}

bool unit(int x, int y) {
	int px = parent(x);
	int py = parent(y);

	if (px == py) return false;
	if (px < py) {
		pr[py] = px;
	}
	else {
		pr[px] = py;
	}
	return true;
}

map<int, map<int, int>> mp;
map<int, map<int,vector<int>>> armp;

int parent(int x, int c) {
	if (mp[c][x] == 0) {
		armp[c][x].push_back(x);
		mp[c][x] = x;
		return x;
	}
	if (mp[c][x] == x) return x;
	int pi = parent(mp[c][x], c);
	vector<int> my = armp[c][x];
	std::copy(my.begin(),my.end(),std::back_inserter(armp[c][pi]));
	armp[c][x].clear();
	return mp[c][x] = pi;
}
void unite(int p, int q, int c) {
	int pp = parent(p, c);
	int qp = parent(q, c);

	if (pp < qp) {
		mp[c][qp] = pp;
		std::copy(armp[c][qp].begin(), armp[c][qp].end(), std::back_inserter(armp[c][pp]));
		armp[c][qp].clear();
	}
	else if (pp > qp) {
		mp[c][pp] = qp;
		std::copy(armp[c][pp].begin(), armp[c][pp].end(), std::back_inserter(armp[c][qp]));
		armp[c][pp].clear();
	}
}
int n, m;
map<int, map<int, int>> memo;
bool use[100010];
set<int> inner[100010];

int calc(int f,int cf) {

	if (n == f) return 0;
	if (memo[f][cf] != 0) return memo[f][cf];
	int res = INF;
	for (auto com : inner[f]) {

		int p = parent(com, f);
		vector<int> nexv = armp[com][p];
		for (auto nex : nexv)
		{
			if (use[nex]) continue;
			use[nex] = true;
			res = min(res, calc(nex,com) + 1);
			use[nex] = false;
		}
	}
	return memo[f][cf] = res;
}
void solv() {

	cin >> n >> m;
	for (size_t i = 0; i < m; i++)
	{
		int p, q, c;
		cin >> p >> q >> c;
		if (p > q) {
			swap(p, q);
		}
		unite(p, q, c);
		inner[p].insert(c);
		inner[q].insert(c);
	}
	for (size_t i = 1; i <= n; i++)
	{
		parent(i);
	}
	use[1] = true;

	int res = calc(1,0);
	cout << (res == INF ? -1 : res) << endl;
}




int main() {
	solv();

	return 0;
}
