#include<bits/stdc++.h>
using namespace std;
typedef long long int ll;
ll power(ll a,ll b,ll mod)
{
	a%=mod;
	ll res=1;
	while(b>0)
	{
		if(b%2) res=(res*a)%mod;
		a=(a*a)%mod;
		b/=2;
	}
	return res;
}
ll getop(ll x,ll mod)
{
	if(x!=0) return 1+getop(x%mod,__builtin_popcountll(x%mod));
	else return 0;
}
void solve()
{
	ll n;
	cin>>n;
	string s;
	cin>>s;
	ll mod=0;
	for(ll i=n-1;i>=0;i--)
	{
		if(s[i]=='1') mod++;
	}
	ll umod=0,lmod=0;
	ll um=mod+1,lm=mod-1;
	for(ll i=0,j=n-1;i<n;i++,j--)
	{
		if(s[i]=='1')
		{
			umod=(umod+power(2,j,um))%um;
			if(mod!=0) lmod=(lmod+power(2,j,lm))%lm;
		}
	}
	//cout<<um<<" "<<lm<<"\n";
	//cout<<umod<<" "<<lmod<<"\n";
	for(ll i=0,j=n-1;i<n;i++,j--)
	{
		if(s[i]=='1')
		{
			ll x=(lmod-power(2,j,lm)+lm)%lm;
			cout<<1+getop(x,__builtin_popcountll(x))<<"\n";
		}
		else
		{
			ll x=(umod+power(2,j,um)+um)%um;
			cout<<1+getop(x,__builtin_popcountll(x))<<"\n";
		}
	}

}
int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	ll T=1;
	//cin>>T;
	while(T--)
	{
		solve();
	}
	return 0;
