inline char nc(){
	static char buf[100000],*p1=buf,*p2=buf;
	return p1==p2&&(p2=(p1=buf)+fread(buf,1,100000,stdin),p1==p2)?EOF:*p1++;
}
inline int read(){
	int ret=0;bool f=0;char ch=nc();
	while(ch>'9'||ch<'0') f^=ch=='-',ch=nc();
	while(ch<='9'&&ch>='0') ret=ret*10+ch-'0',ch=nc();
	return f?-ret:ret;
}
int getfa(int x){return fa[x]==x?x:fa[x]=getfa(fa[x]);}
inline void add_e(int x,int y){son[++e]=y;nxt[e]=lnk[x];lnk[x]=e;}
inline int abs(int x){return x<0?-x:x;}
inline long long solve(int x){
	w[U]+=x,w[V]+=x*flg;
	memset(s,0,sizeof s);ans=0;
	for (int i=n;i;i--) s[Q[i]]+=w[Q[i]],ans+=abs(s[Q[i]]),s[fa[Q[i]]]+=s[Q[i]];
	w[U]-=x,w[V]-=x*flg;
	return s[1]==0?ans+abs(x):1e18;
}
