	solve(0);
	if(s[1]&&((s[1]&1)==1||!U||w[U]!=w[V])){puts("-1");return 0;}
	if(U){
		flg=w[U]==w[V]?1:-1;
		int L=-n,R=n;
		while(L<R){
			int _L=L,_R=R;
			int midl=(L+L+R)/3,midr=(L+R+R+2)/3;
			if(solve(midl)<solve(midr)) R=midr-1;else L=midl+1;
			if(_L==L&&_R==R) return -1;
		}
		printf("%lld\n",solve(L));
	}else printf("%lld\n",solve(0));
	return 0;
