class UnionFind {
public:
	vector<int> Parent;

	UnionFind(int N) {
		Parent = vector<int>(N, -1);
	}

	int root(int A) {
		if (Parent[A] < 0)return A;
		return Parent[A] = root(Parent[A]);
	}

	int size(int A) {
		return -Parent[root(A)];
	}

	bool unite(int A, int B) {
		A = root(A);
		B = root(B);
		if (A == B)
			return false;

		if (size(A) < size(B))
			swap(A, B);

		Parent[A] += Parent[B];
		Parent[B] = A;

		return true;
	}

	bool same(int A, int B) {
		if (root(A) == root(B))
			return true;
		else
			return false;
	}
};

signed main(){
cin.tie(0);
ios::sync_with_stdio(false);

	int N,M;
	cin >> N >> M;
	vector<vector<int> >L(M);
	UnionFind uni(N);
	int q;
	REP(i, N) {
		int K;
		cin >> K;
		REP(j, K) {
			int a;
			cin >> a;
			a--;
			q = a;
			L[a].push_back(i);
		}
	}
	REP(i, M) {
		if (L[i].empty())
			continue;
		REP(j, L[i].size() - 1) {
			if(!uni.same(L[i][j], L[i][j + 1]))
				uni.unite(L[i][j], L[i][j + 1]);
		}
	}
	if (uni.size(q) == N)
		cout << "YES" << endl;
	else
		cout << "NO" << endl;
	return 0;
}

