    if ( a.r == b.r ) {
        return a.t < b.t;
    }
    return a.r < b.r;
}

int bit[ 30001 ];

void add( int y, int val ) {
    while ( y <= 30000 ) {
        bit[ y ] += val;
        y += ( y & -y );
    }
}

int sum( int y ) {
    int res = 0;
    while ( y > 0 ) {
        res += bit[ y ];
        y -= ( y & -y );
    }
    return res;
}

