four c_four(int a, int b, int c, int d) {
  return four(two(a, b), two(c, d));
}

int main(int argc, char** argv){
  int h, w;

  while(cin >> h >> w) {
    vector< two > odds;

    for (int ih = 0; ih < h; ih++) {
      for (int jw = 0; jw < w; jw++) {
	int tmp;
	cin >> tmp;

	if (tmp % 2 == 1)
	  odds.push_back(two(ih, jw));
      }
    }

    vector<four> moves;

    for (int i = 0; i < odds.size() - 1; i+=2) {
      pair<int, int> from = odds[i];
      pair<int, int> dest = odds[i+1];

      // move h
      if (from.first > dest.first) {
	int dif = from.first - dest.first;

	for (int j = 0; j < dif; j++) {
	  moves.push_back(c_four(from.first - j, from.second, from.first - (j + 1), from.second));
	}
      } else if (from.first < dest.first) {
	int dif = dest.first - from.first;

	for (int j = 0; j < dif; j++) {
	  moves.push_back(c_four(from.first + j, from.second, from.first + (j + 1), from.second));
	}
      }

      // move w
      if (from.second > dest.second) {
	int dif = from.second - dest.second;

	for (int j = 0; j < dif; j++) {
	  moves.push_back(c_four(dest.first, from.second -j, dest.first, from.second - (j + 1)));
	}
      } else if (from.second < dest.second) {
	int dif = dest.second - from.second;

	for (int j = 0; j < dif; j++) {
	  moves.push_back(c_four(dest.first, from.second + j, dest.first, from.second + (j + 1)));
	}
      }
    }

    int size = moves.size();
    cout << size << endl;
    for (int i = 0; i < size; i++) {
      four m = moves[i];
      cout << m.first.first + 1 << " " << m.first.second + 1 << " " << m.second.first + 1 << " " << m.second.second + 1 << endl;
    }
  }

  return 0;
}
