#include<bits/stdc++.h>
using namespace std;
long knapSack(int W, int wt[], int val[], int n) 
{ 
   int i, w; 
   long K[n+1][W+1]; 

   // Build table K[][] in bottom up manner 
   for (i = 0; i <= n; i++) 
   { 
       for (w = 0; w <= W; w++) 
       { 
           if (i==0 || w==0) 
               K[i][w] = 0; 
           else if (wt[i-1] <= w) 
                 K[i][w] = max(val[i-1] + K[i-1][w-wt[i-1]],  K[i-1][w]); 
           else
                 K[i][w] = K[i-1][w]; 
       } 
   } 

   return K[n][W]; 
} 

int main(){
  int N=0;
  int W=0;
  cin>>N;
  cin>>W;
  int weight[N];
  int value[W];


  for(int i=0;i<N;i++){
    cin>>weight[i];
    cin>>value[i];
  }
  cout<<knapSack(W,weight,value,N);
}
