		if (p[i]) {
			for (ll j = i * i; j < N; j += i) {
				p[i] = 0;
			}
			primes.pb(i);
		}
	}
}

template<typename T> T gcd(T a, T b) {
	if (a == 0) return b;
	return gcd(b % a, a);
}

template<typename T> T lcm(T a, T b) {
	return (a * b) / gcd(a, b);
}

void solve() {

	sieve();
	int n;
	cin >> n;
	int a[n];
	int G;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		if (i) {
			G = gcd(G, a[i]);
		} else {
			G = a[i];
		}
	}

	if (G != 1) {
		cout << "not coprime" << endl;
		return;
	}

	vi cnt(N, 0);

	for (int i = 0; i < n; i++) {
		int x = a[i];
		for (int k = 0; k < (int)primes.size() && primes[k]*primes[k] <= x; k++) {
			if (x % primes[k] == 0) {
				if (cnt[primes[k]]) {
					cout << "setwise coprime" << endl;
					return;
				}

				while (x % primes[k] == 0) {
					x = x / primes[k];
				}
				cnt[primes[k]]++;
			}
		}
		if (x > 1) {
			if (cnt[x]) {
				cout << "setwise coprime" << endl;
				return;
			}
			cnt[x]++;
		}
	}

	cout << "pairwise coprime" << endl;

}

int32_t main()
{
	IOS
	// int T; cin >> T; while (T--)
	solve();
	return 0;
}
