    bool single;
    int f, t;
  };
  Cond conds[Q];
  for (int q = 0; q < Q; q++) {
    int a, b, c; cin>>a>>b>>c;
    conds[q] = {c == 0, a, b};
  }
  int c_graph = N;
  for (auto cond : conds) {
    if (not cond.single)
      continue;
    if (unite(cond.f, cond.t))
      c_graph--;
  }
  bool is_tree = true;
  for (auto cond : conds) {
    if (cond.single)
      continue;
    is_tree = false;
    if (root(cond.f) == root(cond.t)) {
      cout << "No" << endl;
      return 0;
    }
  }
  int c_min = is_tree ? N-1 : N;
  bool ans = (M >= c_min) and (M <= N-c_graph + c_graph*(c_graph-1)/2);
  cout << (ans ? "Yes" : "No") << endl;

  return 0;
}
