const ll MOD = 1000000007;


class UnionFind{
public:
    vector<int> par;
    vector<int> rank;
    UnionFind(int n){
        init(n);
    }
    void init(int n){
        par.resize(n);
        for(int i=0;i<n;i++){
            par[i] = i;
        }
        rank.assign(n, 0);
    }
    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }
    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }
    bool same(int x,int y){
        return find(x)==find(y);
    }
};

int main(){
    int N, M;
    cin >> N >> M;

    vector<int> A(M), B(M);
    for(int i=0;i<M;i++){
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
    }

    vector<ll> size(N, 1);
    UnionFind uf(N);

    vector<ll> ans(N);
    for(int i=M-1;i>=0;i--){
        if(uf.same(A[i], B[i])) {
            ans[i] = 0;
        }else{
            ll a_size = size[uf.find(A[i])], b_size = size[uf.find(B[i])];
            ans[i] = a_size * b_size;
            uf.unite(A[i], B[i]);
            size[uf.find(A[i])] = a_size + b_size;
        }
    }
    ll cumsum = 0;
    for(int i=0;i<M;i++){
        cumsum += ans[i];
        cout << cumsum << endl;
    }

    return 0;
