constexpr double PI = M_PI;

template<class RandomAccessIterator>
auto medianOfMedians(RandomAccessIterator first, RandomAccessIterator last, int k) {
    auto _first = *first;
    using T = decltype(_first);

    int len = last - first;
    if (len == 1 || k == 0) return *first;

    int ms = (len + 4) / 5;
    std::vector<T> medians(ms);
    for (int i=0; i<ms; ++i) {
        auto iter = first + 5*i;
        if (5*i + 4 < len) {
            for (int j=0; j<3; ++j) {
                int minInd = j;
                for (int k=j+1; k<5; ++k) {
                    if (*(iter+k) < *(iter+minInd)) minInd = k;
                }
                swap(*(iter+j), *(iter+minInd));
            }
            medians[i] = *(iter+2);
        } else {
            medians[i] = *iter;
        }
    }

    T pivot = medianOfMedians(medians.begin(), medians.end(), ms/2);

    for (int i=0; i<len; ++i) {
        if (*(first+i) == pivot) {
            swap(*(first+i), *(first+len-1));
            break;
        }
    }

    int store = 0, same = 0;
    for (int i=0; i<len; ++i) {
        if (*(first+i) < pivot) {
            swap(*(first+i), *(first+store));
            ++store;
        } else if (*(first+i) == pivot) {
            ++same;
        }
    }
    swap(*(first+store), *(first+len-1));

    if (store <= k && k <= store + same - 1) {
        return pivot;
    } else if (k < store) {
        return medianOfMedians(first, first+k, k);
    } else {
        return medianOfMedians(first+k+1, last, k-store-1);
    }
}

void solve() {
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i=0; i<N; ++i) cin >> a[i];

    int maxi = -INF;
    for (int x : a) chmax(maxi, x);
    int medi = medianOfMedians(a.begin(), a.end(), N/2);
    ll res = 0;
    int cnt = -1;
    for (int x : a) {
        if (medi < x) {
            res += 2 * x;
            cnt += 2;
        }
    }
    res -= maxi;
    res += (ll)medi * (N - 1 - cnt);
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}
