int n; //n個
vector<int> a;

int comb_culc(int *x, int *y) {
	int ans,up,down = 0;
	if (*y != 0 && *x != 0) {
		for (int i = 0; i < *y; ++i) {
			if (i == 0) {
				up = *x;
				down = *y;
			}
			else {
				up = up * (*x - i);
				down = down * (*y - i);
			}
		}
		ans = up / down;
	}
	else {
			ans = 1;
	}	
	return ans;
}

int main() {

	cin >> n;
	for (int i = 0; i < n; ++i) {
