class SegTree{
public:
    int size;
    const static int N = 500100;
    vector<bitset<N>> values;

    SegTree(int n){
        size = 1;
        while(size<n) size*=2;
        values.resize(size*3);
    }

    bitset<N> NEUTRAL_ELEMENT = bitset<N>(); // CHANGE
    bitset<N> single(int val) { // CHANGE
        bitset<N> ret;
        ret[val] = 1;
        return ret;
    }

    bitset<N> merge(bitset<N> aa, bitset<N> bb){ // CHANGE
        aa |= bb;
        return aa;
    }


    void build(vector<int>& a){
        build(a,0,0,size);
    };
    void build(vector<int>& a, int node, int nodeL, int nodeR){
        if (nodeR-nodeL == 1) {
            if(nodeL<(int) a.size()) values[node] = single(a[nodeL]); // SINGLE
            return;
        }
        int m = (nodeL+nodeR)/2;
        build(a,node*2+1,nodeL,m);
        build(a,node*2+2,m,nodeR);
        values[node] = merge(values[node*2+1],values[node*2+2]);
    }


    bitset<N> calc(int l, int r){
        return calc(l,r,0,0,size); 
    }
    bitset<N> calc(int l,int r, int node, int nodeL, int nodeR){
        if (r<=nodeL || l>=nodeR) return NEUTRAL_ELEMENT;
        if (l<=nodeL && nodeR<=r) return values[node];
        int m = (nodeL+nodeR)/2;
        return merge(calc(l,r,node*2+1,nodeL,m),calc(l,r,node*2+2,m,nodeR));
    }



};



void solve(){
    int n,q;
    cin >> n >> q;
    vector<int> C(n);
    for(int i = 0; i < n; i++) {
        cin >> C[i];
    }
    SegTree st(n+1);
    st.build(C);

    for(int i = 0; i < q; i++){
        int l,r;
        cin >> l >> r;
        l--;
        cout << st.calc(l,r).count() << endl;
    }
}


int main(){
    int T;
    //cin >> T;
    T = 1;
    while(T--){
        solve();
        cout << endl;
    }
}









