int sum(int l1,int r1,int l2,int r2) {
	ll s = 0;
	for(auto x : v) {
		if(l1 <= x.fi.fi && x.fi.fi <= r1 && l2 <= x.fi.se && x.fi.se <= r2) s += x.se;
	}
