int H, W, h, w;
const int M = 1e8;
vector<pair<pii,int>> vv;
int dx[4] = {1, 1, -1, -1};
int dy[4] = {-1, 1, -1, 1};
ll s = 0;

ll pre[N][N];

void dfs(int u,int v,int val) {
	if(val == 1) {
		s += M;
		a[u][v] = M;
		vv.pb({{u, v}, M});
	}
	else {
		a[u][v] = -(M + 1);
		s -= (M + 1);
		vv.pb({{u, v}, -(M + 1)});
	}
	fr(k, 0, 3) {
		int uu = u + (h - 1) * dx[k];
		int vv = v + (w - 1) * dy[k];
		if(uu >= 1 && u <= H && vv >= 1 && vv <= W && !a[uu][vv]) {
			dfs(uu, vv, val ^ 1);
			break;
		}
	}
}

void solve() {
	cin >> H >> W >> h >> w;
	if(h == H || w == W) {
		cout << "No";
		return;
	}
	dfs(1, 1, 1);
	if(s < 0) {
		auto x = vv.back();
		vv.pop_back();
		s -= x.se;
		a[x.fi.fi][x.fi.se] = 0;
	}
	if(s <= 0) {
		cout << "No";
		return;
	}
	fr(i, 1, H) {
		fr(j, 1, W) {
			if(!a[i][j]) { a[i][j] = -1; s--; }
		}
	}
	fr(i, 1, H) {
		fr(j, 1, W) {
			pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + a[i][j];
		}
	}
	fr(i, h, H) {
		fr(j, w, W) {
			ll s = pre[i][j] - pre[i - h][j] - pre[i][j - w] + pre[i - h][j - w];
			if(s >= 0) {
				cout << "No";
				exit(0);
			}
		}
	}
	cout << "Yes" << endl;
	fr(i, 1, H) {
		fr(j, 1, W) {
			cout << a[i][j] << " ";
		}
		cout << endl;
	}
}

