bool is_able(ll sum, vector<ll> v){
    bitset<20001> b(0); // b[i] = (i-8000)が作れるかどうか
    b[10000] = true;
    bitset<20001> b_old(b);
    for (auto &&i: v){
        for (auto &&j: boost::irange(0LL, 20001LL)){
            if (b_old[j]){
                if (j-i >= 0) b[j-i] = true;
                if (j+i <= 20000) b[j+i] = true;
            }
        }
        b_old = b;
    }
    cout << endl;
    return b[sum+10000];
}



