#include <iostream>
using namespace std;

const int MAX = 52;
const int ldy[4] = { 0,1,0,-1 };
const int ldx[4] = { 1,0,-1,0 };
const int rdy[4] = { 0,1,0,-1 };
const int rdx[4] = { -1,0,1,0 };

char l_grid[MAX][MAX];
int l_visited[MAX][MAX];
char r_grid[MAX][MAX];
int r_visited[MAX][MAX];
bool goal;

void dfs(int ly, int lx, int ry, int rx, int deep)
{
	if (goal == true) {
		return;
	}

	if (l_grid[ly][lx] == '%'&&r_grid[ry][rx] == '%') {
		goal = true;
		return;
	}
	else if (l_grid[ly][lx] == '%' || r_grid[ry][rx] == '%') {
		return;
	}


	for (int i = 0; i < 4; i++) {
		int nly, nlx, nry, nrx;
		if (l_grid[ly + ldy[i]][lx + ldx[i]] == '#') {
			nly = ly;
			nlx = lx;
		}
		else {
			nly = ly + ldy[i];
			nlx = lx + ldx[i];
		}
		if (r_grid[ry + rdy[i]][rx + rdx[i]] == '#') {
			nry = ry;
			nrx = rx;
		}
		else {
			nry = ry + rdy[i];
			nrx = rx + rdx[i];
		}

		if (nly == ly&&nlx == lx&&nry == ry&&nrx == rx) {
			continue;
		}

		if (l_visited[nly][nlx] != -1 && r_visited[nry][nrx] != -1 && l_visited[nly][nlx] == r_visited[nry][nrx]) {
			continue;
		}

		l_visited[ly][lx] = deep + 1;
		r_visited[ry][rx] = deep + 1;

		dfs(nly, nlx, nry, nrx, deep + 1);
	}
}

int main()
{
	while (true) {
		int W, H;
		cin >> W >> H;

		if (W == 0 && H == 0) {
			break;
		}

		goal = false;

		for (int i = 0; i < MAX; i++) {
			for (int j = 0; j < MAX; j++) {
				l_grid[i][j] = '#';
				l_visited[i][j] = -1;
				r_grid[i][j] = '#';
				r_visited[i][j] = -1;
			}
		}

		int ly, lx, ry, rx;

		for (int y = 1; y <= H; y++) {
			for (int x = 1; x <= W; x++) {
				cin >> l_grid[y][x];

				if (l_grid[y][x] == 'L') {
					ly = y;
					lx = x;
					l_grid[y][x] = '.';
				}
			}

			for (int x = 1; x <= W; x++) {
				cin >> r_grid[y][x];

				if (r_grid[y][x] == 'R') {
					ry = y;
					rx = x;
					r_grid[y][x] = '.';
				}
			}
		}

		dfs(ly, lx, ry, rx, 0);

		if (goal == true) {
			cout << "Yes" << endl;
		}
		else {
			cout << "No" << endl;
		}

	}

	return 0;
