#include <iostream>
#include <vector>
#define MAX 100000
using namespace std;

using edge = struct{int node; int w;};
int d[MAX];
vector<edge> tree[MAX];

void dfs(int n, int p, int v) {
    d[n] = v;
    for (auto k : tree[n]) {
        if (k.node == p) {
            continue;
        }
        dfs(k.node, n, v + k.w);
    }
}

int main(int argc, const char * argv[]) {
    int N, a, b, c;
    cin >> N;
    for (int i = 0; i < N-1; i++) {
        cin >> a >> b >> c;
        tree[a].push_back({b,c});
        tree[b].push_back({a,c});
    }

    int Q, K;
    cin >> Q >> K;
    dfs(K, -1, 0);

    for (int i = 0; i < Q; i++) {
        int x,y;
        cin >> x >> y;
        cout << d[x--] + d[y--] << endl;
    }
    return 0;
}
