        else {
            if (x < 0) {
                trace(1);
                x = (nearest + d);
            }
            else {
                trace(2, x, d);
                x = (nearest - d);
            }
        }
        trace(nearest);
    } else {
        if (x > 0ll) x -= k * d;
        else x += k * d;
    }
