};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<P> p(n);
    for (int i = 0; i < n; i++) {
        int l, r;
        cin >> l >> r;
        r++;

        p[i] = { l, r };
    }
    sort(p.begin(), p.end());

    if (n == 2) {
        int s = 0;
        for (int i = 0; i < n; i++) {
            int w = p[i].r - p[i].l;
            s += w;
        }
        cout << s << endl;
        exit(0);
    }

    int il = n - 1, l_max = p[il].l;
    int ir = -1, r_min = 1 << 30;
    for (int i = 0; i < n; i++) {
        if (p[i].r < r_min) {
            r_min = p[i].r;
            ir = i;
        }
    }

    int w_max = 0;
    for (int i = 0; i < n; i++) {
        if (i == il || i == ir) continue;
        int w = p[i].r - p[i].l;
        if (w > w_max) {
            w_max = w;
        }
    }

    int s0;
    {
        int w = max(p[ir].r - p[il].l, 0);
        s0 = w + w_max;//同じグループにした場合のスコア
    }

    if (il == ir) {
        cout << s0 << endl;
        exit(0);
    }

    int s1 = 0, r = p[il].r;
    for (int i = n - 1; i > 0; i--) {//il側に属するのが[i,n-1]とする
        r = min(r, p[i].r);
        int s = max(p[ir].r - p[i - 1].l, 0) + max(r - p[il].l, 0);
        s1 = max(s1, s);
    }

    cout << max(s0, s1) << endl;

    //左右に分けてしまいたくなる 片方を1問だけにするのも有効そう 同じ区間を2回に分けて使うこともある
    //バラバラだったら、一番長い1個を使うことになる
    //Lが最大のやつは、他のどれと組んでもLが悪化しない つまりそれを含むほうの左端はその最大のL
    //あくまでもそいつから見ればだが自分以上のRと組んでも悪化しない 引き受けることができる
    //3個以上残っててLが最大のとRが最小のやつが同じだったら除ける 何を加えても悪化しないので全部引き受ける
    //その2つ、同じグループだと最小の区間が出来上がる 何を加えても悪化しないので一番長い1個をもう片方にする N=2ならばらすだけ
    //違うグループとするとこれはO(N)でわかるんじゃ？ Rが最小のやつはLしか悪化しないから、全部取るところから始めて
    //そもそも片方を0問にするメリットはない

    return 0;
