ll rek(int pos, int d, int ter) {
	//cout << pos << ' ' << d << ' ' << ter << '\n';
	if (pos == n) {
		if (ter == 2) return 0;
		if (d == 0) return 1;
		else return 0;
	}
	ll &ret = DP[pos][d][ter];
	if (ret != -1) {
		//cout << pos << ' ' << d << ' ' << ter << ' ' << ret << " EAKU\n";
		return ret;
	}
	ret = 0;
	if (d == 0) ret += 1;
	if (pos != 0) {
		if (ter == 0 || ter == 2) ret = (ret + rek(pos + 1, d, ter)) % MOD;
		else if (ter == 1){
			if (k[pos] - '0' == 0) ret = (ret + rek(pos + 1, d, 1)) % MOD;
			else ret = (ret + rek(pos + 1, d, 0)) % MOD;
		}
	}
