using namespace std;
int read()
{
    int d = 0, w = 1;
    char ch = getchar();
    while (ch != '-' && (ch < '0' || ch > '9'))
        ch = getchar();
    if (ch == '-')
        w = -1, ch = getchar();
    while (ch >= '0' && ch <= '9')
        d = d * 10 + ch - '0', ch = getchar();
    return d * w;
}
void write_(int x)
{
    if (x < 0)
        x = -x, putchar('-');
    if (x > 9)
        write_(x / 10);
    putchar(x % 10 + '0');
}
void writeln(int x)
{
    write_(x);
    putchar('\n');
}
void writesp(int x)
{
    write_(x);
    putchar(' ');
}
