const int mod = 1000000007;
struct mint {
  ll x;  // typedef long long ll;
  mint(ll x = 0) : x((x % mod + mod) % mod) {}
  mint operator-() const { return mint(-x); }
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod - a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res += a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod - 2); }
  mint& operator/=(const mint a) { return (*this) *= a.inv(); }
  mint operator/(const mint a) const {
    mint res(*this);
    return res /= a;
  }
};
mint comb(int n, int r) {
  if (n - r < r) r = n - r;
  if (r == 0) return 1;
  if (r == 1) return n;

  vector<mint> numerator(r, 0), denominator(r, 0);
  for (int k = 0; k < r; k++) {
    numerator[k] = n - r + k + 1;
    denominator[k] = k + 1;
  }

  for (int p = 2; p < r + 1; p++) {
    mint pivot = denominator[p - 1];
    if (pivot.x > 1) {
      int offset = (n - r) % p;
      for (int k = p - 1; k < r; k += p) {
        numerator[k - offset] /= pivot;
        denominator[k] /= pivot;
      }
    }
  }

  mint res = 1;
  for (int k = 0; k < r; k++) {
    if (numerator[k].x > 1) {
      res *= numerator[k];
    }
  }
  return res;
}

int main() {
  ll x,y;
  cin >> x >> y;
  ll b = (2*x -y)/3;
  ll a = x-2*b;
  mint ans = comb(a+b,a);
  if((a+2*b !=x)|(2*a+b!=y))ans=0;
  cout<<ans.x<<endl;
  return 0;
