const int N = 1e6 + 60; 
char s[N];
int n, ans, mc;
vector<int> a;

void solve() {
	lop(i, n) if (!i || s[i] != s[i - 1]) a.pb(s[i] - 'A');
	{
		int c[3] = {}; 
		for (int x : a) ++c[x];
		mc = min_element(c, c + 3) - c;		
		ans = c[mc];
		for (int &x : a) x = x == mc ? 0 : (x == 0 ? mc : x);
	}
	//for (int x : a) Pr("%d ", x); Pr("\n"); 
	if (ans) {
		int x[2] = {}, y[2] = {}, cur[2] = {};
		vector<array<int, 3>> w;
		int f = 1, h = -1;
		auto upd = [&]() {
			lop(k, 2) if (cur[k]) { 
				++x[k];
				y[k] += cur[k ^ 1] == 0 && !f;
			}
			f = 0; 
			w.pb({ cur[0], cur[1], h });
			cur[0] = cur[1] = 0;
			h = -1;
		}; 
		for (int x : a) {
			if (x == 0) upd(); 
			else {
				++cur[x - 1];
				if (h == -1) h = x - 1;
			}
		}
		f = 1, upd(); 

		lop(k, 2) if (x[k ^ 1] < y[k]) ans -= y[k] - x[k ^ 1];

		lop(k, 2) {
			vector<array<int, 3>> t;
			lop(i, w.size()) {
				if (x[k ^ 1] < y[k]) {
					if (i && i + 1 < w.size() && !w[i][k ^ 1]) {
						--x[k], --y[k]; 
						continue;
					}
				}
				t.pb(w[i]); 
			}
			w = t;
		}

		int len = w.size(), c[2] = {}; 
		for (auto e : w) lop(k, 2) c[k] += e[k];
		lop(k, 2) lop(i, len) {
			if (i && i + 1 < len && w[i][k ^ 1] == 0) continue;
			if (c[k] > c[k ^ 1]) {
				if (w[i][k] && w[i][k] >= w[i][k ^ 1]) {
					--w[i][k], --c[k];
				}
			}
		}
		assert(c[0] == c[1]); 
		vector<int> res;	
		lop(i, len) {
			while (c[0] >= len) {
				int g = w[i][0] + w[i][1]; 
				if (g <= 1) break;
				if (0 < i && i < len - 1 && g == 2) break;
				lop(k, 2) --c[k], --w[i][k]; 
			}
			int of = w[i][2];
			lop(k, 2) if (w[i][k] > w[i][k ^ 1]) of = k;
			lop(j, w[i][0] + w[i][1]) res.pb((j + of)% 2 + 1);
			if (i + 1 < len) res.pb(0); 
		}
		for (int v : res) {
			v = v == 0 ? mc : (v == mc ? 0 : v);
			putchar(v + 'A'); 
		}
	}
	puts(""); 
}

int main(int argc,char *argv[]){
#ifdef CURIOUSCAT
