using namespace std;
int n , z;

pair < int , int > st[4*100000];

int op(int iz , int der)
{
	return st[iz].first + st[der].first;
}
void push(int v , int l , int r)
{
	int m = (r+l)/2;
	st[2*v].second += st[v].second;
	st[2*v].first += st[v].second*(m-l);
	st[2*v+1].second += st[v].second;
	st[2*v+1].first += st[v].second*(r-m);
	st[v].second = 0;
}

void u(int v , int l , int r, int i , int j, int x)
{
	push(v , l , r);
	if(j < l || i >= r)
	{
		return;
	}else if(i <= l && r-1 <= j)
	{
		st[v].second += x;
		st[v].first += (r-l)*x;
	}else
	{
		int m = (r+l)/2;
		u(2*v , l , m , i , j , x);
		u(2*v+1 , m , r , i , j , x );
		st[v].first = op(2*v , 2*v+1);
	}
}



int q(int v , int l , int r , int x)
{
	push(v , l , r);
	if(x < l || x >= r)
	{
		return 0;
	}else
	{
		if(r - l == 1)
		{
			return st[v].first;
		}else
		{
			int m = (r+l)/2;
			return max(q(2*v , l , m , x) , q(2*v+1 , m , r , x ));
		}
	}
}


