long long c(long long n, long long r) {
	if (n == r) dp[n][r] = 1;
	if (r == 0)dp[n][r] = 1;
	if (r == 1)dp[n][r] = n;
	if (dp[n][r])return dp[n][r];
	return dp[n][r] = c(n - 1, r) + c(n - 1, r - 1);
}
