int Pow(int x, int y) {
    if(y < 0) return 0;
    int res = 1;
    for(; y > 0; y >>= 1) {
        if(y & 1) res = 1ll * res * x % mod;
        x = 1ll * x * x % mod;
    }
    return res;
}

int nCk(int n, int k) {
    if(c[n][k] != -1) return c[n][k];
    if(n * k == 0 || k == n) return 1;
    if(k > n) return c[n][k] = 0;
    if(n < 0 || k < 0) return 0;
    return c[n][k] = nCk(n - 1, k - 1) + nCk(n - 1, k);
}

