    for(int i = 0; i <= k; ++i) f[0][i] = 1;
    for(int i = 1; i <= n; ++i) {
        for(int j = 1; j <= k; ++j) {
            f[i][j] = f[i - 1][j] + f[i][j - 1];
            if(f[i][j] >= mod) f[i][j] -= mod;
        }
