    for(int i = 2; i <= 2 * k; ++i) {
        int rem = k - 2 * cnt[i];
        if(i % 2 == 0) --rem; res = ans = 0;
        for(int j = 0; j <= cnt[i]; ++j) {
            if(n - j >= 0) {
            res += 1ll * nCk(cnt[i], j) * p[j] % mod * f[n - j][j + rem] % mod;
            if(res >= mod) res -= mod;
