const int inf=0x3f3f3f3f;
const int MOD=1e9+7;
int par[100005],ranks[100005],ans[100005];
void init(int n)
{
	for(int i=0;i<n;i++)
	{
		par[i]=i;
		ranks[i]=1;
	}
}
int find(int x)
{
	if(par[x]==x)
	return x;
	else
	return par[x]=find(par[x]);
}
void Union(int x,int y)
{
	x=find(x);y=find(y);
	if(x==y) return ;
	if(ranks[x]<ranks[y])
	swap(x,y);
	par[y]=x;
	ranks[x]+=ranks[y];
}
int size(int x)
{
	return ranks[find(x)];
}
int main()
{
	int n,m,k;cin>>n>>m>>k;
	vector<int> friends[n];
	vector<int> block[n];
