	memset(ans,0,sizeof(ans));
	init(n);
	for(int i=0;i<n;i++)
	{
		cin>>x>>y;
		x--;y--;
		Union(x,y);
		friends[x].push_back(y);
		friends[y].push_back(x);
	}
	for(int i=0;i<n;i++)
	{
		cin>>x>>y;
		x--,y--;
