int adiv(int a) {
	map<int,int>mp;
	int num(a);
	for (int i = 2; i <= a; ++i) {
		while (num%i == 0) {
			mp[i]++;
			num/=i;
		}
	}
	int anum=0;
	for (auto m : mp) {
		anum-=m.first;
	}
	anum+=2*prev(mp.end())->first;
	return anum;
}

double dis(pair<int, int>l, pair<int, int>r) {
	int dx=l.first-r.first;
	int dy=l.second-r.second;
	return sqrt(double(dx)*dx+double(dy)*dy);
}

double get_x(pair<int, int>f, pair<int, int>t, int y) {
	if(f.second>t.second)return get_x(t,f,y);

	double a=y-f.second;
	double b=t.second-y;

	return (f.first*b+f.second*a)/(a+b);
}

