			int a,b;cin>>a>>b;
			points[i]=make_pair(a,b);
		}

		vector<vector<pair<int,double>>>edges(N);
		for (int i = 0; i < N - 1; ++i) {
			edges[i].push_back(make_pair(i+1,dis(points[i],points[i+1])/vw));
		}

		int nid=N;

		for (int i = 0; i < N - 1; ++i) {
			int ny=points[i].second;
			if (points[i + 1].second > ny) {
				for (int j = i + 1; j < N-1; ++j) {
					int fy=points[j].second;
					int ty=points[j+1].second;

					if (ny < fy&&ty <= ny) {
						double tunnel_x=get_x(points[j],points[j+1],ny);

						double adis=abs(tunnel_x-points[i].first)/vc+dis(make_pair(tunnel_x,ny),points[j+1])/vw;

						edges[i].push_back(make_pair(j+1,adis));
						break;
					}
				}
			}
		}
		for (int i = 1; i < N; ++i) {
			int ny = points[i].second;
			if (points[i - 1].second > ny) {
				for (int j = i - 1; j >0; ++j) {
					int fy = points[j].second;
					int ty = points[j - 1].second;

					if (ny < fy&&ty <= ny) {
						double tunnel_x = get_x(points[j], points[j - 1], ny);

						double adis = abs(tunnel_x - points[i].first)/vc + dis(make_pair(tunnel_x, ny), points[j - 1])/vw;

						edges[j-1].push_back(make_pair(i, adis));
