				}
			}
		}

		vector<double>memo(N,1e9);
		memo[0]=0;
		for (int i = 0; i < N; ++i) {
			for (auto e : edges[i]) {
				int to=e.first;
				double cost=e.second;
				memo[to]=min(memo[to],memo[i]+cost);
			}
		}
		cout<<memo[N-1]<<endl;
	}
	return 0;
}
