ll power(ll a, ll b){ // to calculate a^b %mod
    if(b == 0)
        return 1;
    ll temp = power(a,b>>1)%mod;
    temp = (temp*temp)%mod;
    if(b&1)
        temp = temp*a%mod;
    return temp;
}

void buildtable(void){
    ll count=1;
    for(ll i=1;i<=100001;i++){
        count*=i;
        if(count>mod){
            count=count%mod;
        }
        arr[i].fi=count;
        ll invmod=power(count,mod-2);
        arr[i].se=invmod;
    }
}

