//(x>y) ll -> ll -> ll
ll gcd(ll x,ll y){
    if (y==0){ 
        return x;
    }else {
      return gcd(y,x%y);
    }
}

//素因数を求める
set<int> soinnsuu(ll x){
    ll tmp=x;
    set<int> s;
    for (int a=2;a*a<=x;a++){
        while (tmp%a==0){
            s.insert(a);
            tmp/=a;
        }
    } s.insert(tmp);
    s.insert(1);
    return s;
}


