struct C{
  double x, y, r;
  C(double x=0,double y=0, double r=0):x(x),y(y),r(r)
  {}
};

double dist(C& c1, C& c2){
  double dx = c1.x - c2.x;
  double dy = c1.y - c2.y;
  if(dx*dx + dy*dy <= (c1.r+c2.r)*(c1.r+c2.r))
	return 0.;
  return sqrt((dx*dx + dy*dy)) - sqrt((c1.r+c2.r)*(c1.r+c2.r));
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  C s, t;
  cin >> s.x >> s.y >> t.x >> t.y;
  int N; cin >> N;
