  cs.PB(s);
  REP(i,N){
	C c;
	cin >> c.x >> c.y >> c.r;
	cs.EB(c);
  }
  cs.PB(t);

  vector<vector<double>> ds(N+2, vector<double>(N+2));
  REP(i,N+2) REP(j,i+1){
	ds[i][j] = ds[j][i] = dist(cs[i], cs[j]);
  }

  using Type = pair<double,int>;
  vector<double> d(N+2, INF);
  fill(d.begin(), d.end(), INF);
  d[0] = 0;
  queue<Type> q;
  q.push(MP(0,0));

  while(!q.empty()){
	Type pii = q.front(); q.pop();
	int v = pii.second;
	if(d[v] < pii.first) continue;
	REP(i,N+2){
