bool check(int x)
{
	bool flag[3];
	rep(i, 3) flag[i] = false;
	while(x)
	{
		int y = x % 10;
		if (y == 3)
			flag[0] = true;
		else if (y == 5)
			flag[1] = true;
		else if (y == 7) 
			flag[2] = true;
		x /= 10;
	}
	rep(i, 3)
	{
		if (!flag[i])
			return false;
	}
	return true;
}
void dfs(int x)
{
	if (x <= n)
	{
		if (check(x)) ans++;
		dfs(10 * x + 3);
		dfs(10 * x + 5);
		dfs(10 * x + 7);
	}
}

