int main()
{
    cin >> n >> k;
    for (int i = 0; i < n; i++)
        scanf("%lld", &a[i]);

    for (int i = n - 1; i >= 0; i--)
        idx[a[i]] = i;
    for (int i = n - 1; i >= 0; i--)
    {
        if (idx[a[i]] <= i)
            add[0][i] = idx[a[i]] + n - i + 1;
        else
            add[0][i] = idx[a[i]] - i + 1;
        idx[a[i]] = i;
    }

    for (int i = 1; i < LOG; i++)
        for (int j = 0; j < n; j++)
        {
            add[i][j] = add[i - 1][(add[i - 1][j] + j) % n] + add[i - 1][j];
            if (add[i][j] > LLONG_MAX / 3)
                add[i][j] = LLONG_MAX / 3;
        }

    ll now = 0;
    for (int i = LOG - 1; i >= 0; i--)
    {
        while (now + add[i][now % n] <= k * n)
            now += add[i][now % n];
    }
    //printf("%lld\n", add[LOG - 1][0]);
    //printf("%lld\n", now);
    if (now == k * n)
        return 0;
    memset(idx, -1, sizeof(idx));
    top = 0;
    for (ll i = now; i <= n * k - 1; i++)
    {
        ll now = i % n;
        if (idx[a[now]] >= top || idx[a[now]] == -1)
        {
            idx[a[now]] = top;
            ans[top++] = a[now];
        }
        else
            top = idx[a[now]];
    }
    for (int i = 0; i < top; i++)
        printf("%lld ", ans[i]);
    return 0;
}
