#include <stdio.h>
#include <iostream>
#include <vector>
using namespace std;

long recurse(vector<vector<long>> dp, vector<int> arr, int l, int r) {
    if (l == r) {
        return arr[l];
    }

    if (dp[l][r] != -69) {
        return dp[l][r];
    }

    dp[l][r] = max(arr[l] - recurse(dp, arr, l + 1, r), arr[r] - recurse(dp, arr, l, r - 1));
    return dp[l][r];
}

int main() {
    int N;
    cin >> N;

    vector<int> arr(N);
    vector<vector<long>> dp(arr.size(), vector<long>(arr.size(), -69));

    for (int i = 0; i < N; i++) {
        cin >> arr[i];
    }

    printf("%ld\n", recurse(dp, arr, 0, arr.size() - 1));
