const int nmax = 100005;
std::array<std::vector<int>, nmax> fr;
std::array<std::vector<int>, nmax> block;
std::array<int, nmax> ans;
std::array<int, nmax> color;

int N, M, K;

void find_path(int u, int v)
{
  if (u == v) return;
  color.fill(0);
  std::queue<int> q;
  q.push(u);

  while (!q.empty())
    {
      auto f = q.front();
      q.pop();
      color[f] = 1;

      if (f == v)
        {
          ans[u]++;
          break;
        }

      for (int i=0; i<fr[f].size(); ++i)
        {
          if (color[fr[f][i]] == 0)
            q.push(fr[f][i]);
        }
    }
}

void find_fr(int u)
{
  for (int v=1; v<=N; ++v){
    if ((std::find(fr[u].begin(), fr[u].end(), v) == fr[u].end()) &&
        (std::find(block[u].begin(), block[u].end(), v) == block[u].end()))
      {
        // std::cout << "find path = " << u << " " << v << std::endl;
        find_path(u, v);
      }
  }
}

void solve()
{
  for (int i=1; i<=N; ++i)
    find_fr(i);
}

int main ()
{
  std::cin >> N >> M >> K;

  int a, b;
  for (int i=0; i<M; ++i){
    std::cin >> a >> b;
