int n;
long long int rec(long long int a[], long long int b[], long long int c[], long long int index, long long int prev_val){
    long long int x, y, z;
    if(index==0){
        x=a[0]+rec(a, b, c, 1, 0);
        y=b[0]+rec(a, b, c, 1, 1);
        z=c[0]+rec(a, b, c, 1, 2);
        return max(x, max(y, z));
    }
    if(index==n){
        return 0;
    }
    else{
        if(prev_val==0){
            y=b[index]+rec(a, b, c, index+1, 1);
            z=c[index]+rec(a, b, c, index+1, 2);
            return max(y, z);
        }
        if(prev_val==1){
            x=a[index]+rec(a, b, c, index+1, 0);
            z=c[index]+rec(a, b, c, index+1, 2);
            return max(x, z);
        }
        if(prev_val==2){
            x=a[index]+rec(a, b, c, index+1, 0);
            y=b[index]+rec(a, b, c, index+1, 1);
            return max(x, y);
        }
    }
}

