#include <queue>
#include <cstdio>
#include <algorithm>
using namespace std;

typedef long long ll;
const int Maxn = 2e5;

int N;
long long K;

int A[Maxn + 5], F[Maxn + 5];

bool cmp(int lhs, int rhs) {
	return lhs > rhs;
}

bool check(ll mx) {
	ll cnt = 0;
	for(int i = 1; i <= N; i++)
		if(mx <= 1LL * A[i] * F[i]) {
			ll t = A[i] - (mx) / F[i];
			cnt += t;
		}
	return cnt <= K;
}

int main() {
#ifdef LOACL
	freopen("in.txt", "r", stdin);
	freopen("out.txt", "w", stdout);
#endif
	scanf("%d %lld", &N, &K);
	for(int i = 1; i <= N; i++)
		scanf("%d", &A[i]);
	for(int i = 1; i <= N; i++)
		scanf("%d", &F[i]);
	sort(A + 1, A + N + 1, cmp);
	sort(F + 1, F + N + 1);
	ll lb = 0, ub = 0, ans;
	for(int i = 1; i <= N; i++)
		ub = max(ub, 1LL * A[i] * F[i]);
	while(lb <= ub) {
		int mid = (lb + ub) >> 1;
		if(check(mid)) ub = mid - 1, ans = mid;
