int count(int pos)
{
	int w_side_count = 0;
	int e_side_count = 0;

	for ( int i = 0; i < n; i++ )
	{
		if ( i < pos )	// w side
		{
			if ( s[i] == 'W' ) w_side_count++;
		}
		else
		if ( i > pos )	// e side
		{
			if ( s[i] == 'E' ) e_side_count++;
		}
	}

	return w_side_count + e_side_count;
}

int main()
{
	cin >> n >> s;

	int ans = 3 * 100000 + 1;

	for ( int i = 0; i < n; i++ )
	{
		int c = count(i);
		if ( c < ans ) ans = c;
	}

	cout << ans << endl;

	return 0;
}
