bool solve(int N, int M, string& s, vi& a, vi& b) {
    vector<set<int>> a_side(N), b_side(N);

    rep(i,M){
        int u = a[i], v = b[i];
        int cu = s[u], cv = s[v];

        if (cv == 'A')
            a_side[u].insert(v);
        else
            b_side[u].insert(v);

        if (cu == 'A')
            a_side[v].insert(u);
        else
            b_side[v].insert(u);
    }

    set<int> killed;
    int newly_killed = 0;

    do {
        newly_killed = 0;
        rep(i,N){
            if (found(killed, i)) continue;
            if (a_side[i].empty() || b_side[i].empty()) {
                ++newly_killed;
                killed.insert(i);

                vector<ii> _a, _b;
                for (int a: a_side[i]) {
                    if (s[i] == 'A') {
                        _a.pb(ii(a,i));
                        // a_side[a].erase(i);
                    }
                    if (s[i] == 'B') {
                        _b.pb(ii(a,i));
                        // b_side[a].erase(i);
                    }
                }
                for (int b: b_side[i]) {
                    if (s[i] == 'A') {
                        _a.pb(ii(b,i));
                        // a_side[b].erase(i);
                    }
                    if (s[i] == 'B') {
                        _b.pb(ii(b,i));
                        // b_side[b].erase(i);
                    }
                }
                for (ii p: _a){
                    a_side[p.first].erase(p.second);
                }
                for (ii p: _b){
                    b_side[p.first].erase(p.second);
                }
            }
        }
    } while (newly_killed > 0);

    return killed.size() < N;
}

