				if (cmp(a[i], a[j]) && cmp(a[j], a[k]) && !cmp(a[i], a[k])) assert(0);
				if (!cmp(a[i], a[j]) && !cmp(a[j], a[k]) && cmp(a[i], a[k])) assert(0);
