			long long tmp = dp[i][j - 1];
			tmp++, tmp += tmp * a[i].fi + a[i].se;
			tmp = min(tmp, (long long)T + 1);
			dp[i + 1][j] = min(dp[i][j], tmp);
			int pos = upper_bound(sum + mid, sum + n, T - dp[i][j]) - sum;
			if (dp[i][j] <= T) ans = max(ans, j + pos - mid);
		}
	}
	for (int j = 0; j <= N; j++) {
