const int INF = 1e8;
using namespace std;

class Edge{
    public:
        int to, com;
        Edge(int to, int com) : to(to) ,com(com) {}
};

class Node{
    public:
        int dis;
        bool isUsed;
        Node(){
            this->dis = INF;
            this->isUsed = 0;
        }
};

typedef vector<vector<Edge>> AdjList;


unordered_map<int,Node> node[100005];
typedef pair<int,pair<int,int>> ppi;
int dijkstra(AdjList g, int start, int n){
    priority_queue<ppi, vector<ppi>, greater<ppi>> q;

    q.push(make_pair(0, make_pair(start, -1)));
    node[start][-1].dis = 0;

    ppi u;
    while(not q.empty()){
        u = q.top(); q.pop();
        int current = u.second.first;
        int pre_com = u.second.second;
        node[current][pre_com].isUsed = 1;

        rep(i,g[current].size()){
            int next = g[current][i].to;
            int next_com = g[current][i].com;
            if(node[next][pre_com].isUsed == 0){
                if(pre_com == next_com){
                    if(node[next][next_com].dis > node[current][pre_com].dis){
                        node[next][next_com].dis = node[current][pre_com].dis;
                        q.push(make_pair(node[next][next_com].dis, make_pair(next, next_com)));
                    }
                }else{
                    if(node[next][next_com].dis > node[current][pre_com].dis + 1){
                        node[next][next_com].dis = node[current][pre_com].dis + 1;
                        q.push(make_pair(node[next][next_com].dis, make_pair(next, next_com)));
                    }

                }
            }
        }
    }

    int mini = INF;
    for(auto it : node[n - 1]){
        mini = min(mini, it.second.dis);
    }
    return mini;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;

    AdjList g(n);
    rep(i,m){
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        g[a].emplace_back(Edge{b,c});
        g[b].emplace_back(Edge{a,c});
    }

    int ans = dijkstra(g,0,n);
    cout << (ans == INF ? -1 : ans) << endl;
}
