#include <bits/stdc++.h>
#pragma GCC optimize("Ofast")

using namespace std;
using ll = long long;

const long long MOD = 1000000007;

long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

map< int64_t, int > prime_factor(int64_t n) {
  map< int64_t, int > ret;
  for(int64_t i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return ret;
}

void solve(long long N, std::vector<long long> A){
    map<ll, int> lcm;
    vector<map<int64_t, int>> www;
    for(int i = 0;i < N;i++){
        auto a = prime_factor(A[i]);
        www.push_back(a);
        for(auto b : a)lcm[b.first] = max(lcm[b.first], b.second);
    }
    ll ans = 0;
    map<int, vector<ll>> po;
    for(auto a : lcm){
        ll s = 1;
        vector<ll> v(a.second+1);
        v[0] = 1;
        for(int i = 0;i < a.second;i++){
            s *= a.first;
            if(s > MOD)s %= MOD;
            v[i+1] = s;
        }
        po[a.first] = v;
    }
    vector<pair<int, int>> _lcm;
    for(auto a : lcm)_lcm.push_back(a);
    for(int i = 0;i < N;i++){
        ll usi = 1;
        for(auto b : _lcm){
            int s = b.second - www[i][b.first];
            usi *= po[b.first][s];
            if(usi > MOD)usi %= MOD;
        }
        ans += usi;
        if(ans > MOD)ans %= MOD;
    }
    cout<<ans<<endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, std::move(A));
    return 0;
}
