        tree[k] += x;
        k += k&-k;
    }
}

int table[MX] = {0};

void solve() {
    vi prime1001;

    for (int i = 2; i < 1001; ++i) if (table[i] == 0) {
        prime1001.pb(i);
        for (int j = i; j < MX; j+=i)
            table[j] = 1;
    }
    for (int i = 1001; i < MX; ++i) if (table[i] == 0)
        prime1001.pb(i);

    int n;
    cin >> n;
    vi A(n);
    F0R(i, n)
        cin >> A[i];

    int gcdall = A[0];
    bool flag = 0;
    set<int> st;
    F0R(i, n) {
        gcdall = gcd(gcdall, A[i]);
        //cout << gcdall << endl;
        for (auto p: prime1001) if (A[i] % p == 0) {
            if (st.find(p) != st.end())
                flag = 1;
            else {
                st.insert(p);
            }
        }
    }
    if (gcdall != 1) {
        cout << "not coprime\n";
    } else if (flag) {
        cout << "setwise coprime\n";
    } else {
        cout << "pairwise coprime\n";
    }
}


