//Prime Factorization O(sqrt(N))
vector<long long> Prime_Factorization(long long N) {
    vector<long long> ret;
    if (N == 1) ret.push_back(1);
    for (long long i = 2,M = N; i*i <= M; ++i) {
        if (N%i == 0) ret.push_back(i);
        while (N%i == 0) N /= i;
    }
    if (N != 1) ret.push_back(N);
    return ret;
}

//Greatest Common Divisor
long long GCD(long long a, long long b) {
    return ((b == 0) ? a : GCD(b, a % b));
}


int main() {
	int N; cin >> N;
	V<ll> a(N); REP(i,N) cin >> a[i];
	V<V<ll>> b(N);
	for(int i  = 0; i < N; ++i) b[i] = Prime_Factorization(a[i]);
	map<ll,ll> mp;
	V<map<ll,ll>> vmp(N);

	for(int i = 0; i < N; ++i){
		ll c = a[i];
		for(auto e: b[i]){
			if(e == 1) continue;
			if(!mp.count(e)) mp[e] = (ll)1e10;
			ll cnt = 0;
			while(c%e==0){
				cnt++;
				c /= e;
			}
			vmp[i][e] = cnt;
			chmin(mp[e],cnt);
		}
	}

	ll ans = a[0];
	for(int i = 0; i < N; ++i) ans = GCD(ans,a[i]);

	for(auto pp:mp){
		ll e = pp.first;		
		V<P<ll,ll>> v;

		for(int i = 0; i < N; ++i){
			if(!vmp[i].count(e)) v.push_back({0,i});
			else v.push_back({vmp[i][e],i});
		}

		sort(ALL(v));
		if(v[0].first == v[1].first) continue;
		int idx = v[0].second;
		ll cnt = (idx==0?a[1]:a[0]);
		for(int i = 0; i < N; ++i){
			if(idx == i) continue;
			cnt = GCD(cnt,a[i]);
		}
		chmax(ans,cnt);
	}
	cout << ans << endl;
	return 0;
}
