const int nm = (1 << 18) + 2;

int n, m;
int v[nm], w[nm];
int na, a[nm];
int nb, nc;
pair<int, int> b[nm], c[nm];

void doit(int i, int sv, int sw, int l) {
	if (i > na / 2) {
		b[++nb] = {sw, sv};
		return;
	}
	doit(i + 1, sv, sw, l);
	if (sw + w[a[i]] <= l) {
		doit(i + 1, sv + v[a[i]], sw + w[a[i]], l);
	}
}

void doit2(int i, int sv, int sw, int l) {
	if (i > na) {
		c[++nc] = {sw, sv};
		return;
	}
	doit2(i + 1, sv, sw, l);
	if (sw + w[a[i]] <= l) {
		doit2(i + 1, sv + v[a[i]], sw + w[a[i]], l);
	}
}

int calc(int vv, int l) {
	na = 0;
	while (vv) {
		a[++na] = vv;
		vv >>= 1;
	}
	nb = 0;
	doit(1, 0, 0, l);
	sort(b + 1, b + nb + 1);
	nc = 0;
	doit2(na / 2 + 1, 0, 0, l);
	sort(c + 1, c + nc + 1);
	for (int i = 1; i <= nc; ++i) {
		c[i].se = max(c[i - 1].se, c[i].se);
	}
	int res = 0;
	for (int i = 1, j = nc; i <= nb && j > 0; ++i) {
		while (j > 0 && b[i].fi + c[j].fi > l) {
			j--;
		}
		if (j > 0) {
			res = max(res, b[i].se + c[j].se);
		}
	}
	return res;
}

