template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< mod >;


/**
 * @brief Binary-Indexed-Tree(BIT)
 * @docs docs/binary-indexed-tree.md
 */
template< typename T >
struct BinaryIndexedTree {
  vector< T > data;

  BinaryIndexedTree() = default;

  explicit BinaryIndexedTree(size_t sz) : data(sz + 1, 0) {}

  void add(int k, const T &x) {
    for(++k; k < (int) data.size(); k += k & -k) data[k] += x;
  }

  T query(int k) const {
    T ret = T();
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return ret;
  }

  int lower_bound(T x) const {
    int i = 0;
    for(int k = 1 << (__lg(data.size() - 1) + 1); k > 0; k >>= 1) {
      if(i + k < data.size() && data[i + k] < x) {
        x -= data[i + k];
        i += k;
      }
    }
    return i;
  }

  int upper_bound(T x) const {
    int i = 0;
    for(int k = 1 << (__lg(data.size() - 1) + 1); k > 0; k >>= 1) {
      if(i + k < data.size() && data[i + k] <= x) {
        x -= data[i + k];
        i += k;
      }
    }
    return i;
  }
};

int main() {
  int H;
  cin >> H;
  vector< int > P(1 << (H - 1));
  cin >> P;
  for(auto &p : P) --p;

  // 多分LCAを固定するべきじゃないでしょうか

  int64 s = 1 << (H - 1);

  vector< int > left((1 << H) + 1), right((1 << H) + 1);
  for(int i = 0; i < 1 << (H - 1); i++) {
    left[i + s] = i + s;
    right[i + s] = i + s + 1;
  }
  for(int i = s - 1; i >= 1; i--) {
    left[i] = left[i * 2 + 0];
    right[i] = right[i * 2 + 1];
  }

  vector< BinaryIndexedTree< modint > > bits;
  for(int i = 0; i + 1 < H; i++) bits.emplace_back((1 << H) + 1);

  modint ret = 0;

  auto dfs = MFP([&](auto dfs, int idx) -> pair< int, int > {
    if(idx >= s) {
      return {idx, idx + 1};
    }
    int l = idx * 2 + 0;
    int r = idx * 2 + 1;
    auto x = dfs(l);
    auto y = dfs(r);


    for(int i = x.first; i < x.second; i++) {
      int to = i;
      modint mul = to;
      while(to > idx) {
        to /= 2;
        mul *= to;
      }


      to = P[i - s] + s;
      mul *= to;
      int dep = H - 2;
      while(dep >= 0) {
        to /= 2;
        mul *= to;
        bits[dep].add(P[i - s] + s, mul);
        --dep;
      }
    }
    modint rev = modint(1) / idx;

    for(int i = y.first; i < y.second; i++) {
      int to = i;
      modint mul = to;
      while(to > idx) {
        to /= 2;
        mul *= to;
      }
      mul *= rev;

      to = P[i - s] + s;
      mul *= to;

      int dep = H - 2;

      while(dep >= 0) {
        int latte = -1, malta = -1;

        if(to % 2 == 0) {
          latte = left[(to / 2) * 2 + 1];
          malta = right[(to / 2) * 2 + 1];
        } else {
          latte = left[(to / 2) * 2 + 0];
          malta = right[(to / 2) * 2 + 0];
        }
        to /= 2;
        ret += (bits[dep].query(malta - 1) - bits[dep].query(latte - 1)) * mul;
        mul *= to;
        --dep;
