class UnionFind {
    vector<int> parent;

    public:
        UnionFind(int size) {
            parent = vector<int>(size, -1);
        }

        int find(int x) {
            if (parent[x] < 0) {
                // parent itself
                return x;
            } else {
                return parent[x] = find(parent[x]);
            }
        }

        bool unite(int x, int y) {
            int rX, rY;
            if ((rX = find(x)) == (rY = find(y))) {
                // already united
                return false;
            }
            if (size(rX) < size(rY)) {
                int tmp = rX;
                rX = rY;
                rY = tmp;
            }
            parent[rX] += parent[rY];
            parent[rY] = rX;
            return true;
        }

        int size(int x) {
            return -parent[find(x)];
        }

        bool is_same(int x, int y) {
            return find(x) == find(y);
        }

        // CAUTION!! : This method is heavy due to scanning linearly.
        int component_count() {
            int c = 0;
            for (const int x : parent) {
                if (x < 0) {
                    c++;
                }
            }
            return c;
        }
};

void solve() {
    int n, m, k;
    cin >> n >> m >> k;
    UnionFind fr(n);
    vector<vector<bool>> g(n, vector<bool>(n, false));

    int a, b;
    REP(i, m) {
        cin >> a >> b;
        a--; b--;
        fr.unite(a, b);
        g[a][b] = true;
        g[b][a] = true;
    }
    REP(i, k) {
        cin >> a >> b;
        a--; b--;
        g[a][b] = true;
        g[b][a] = true;
    }

    vi ans(n);

    REP(i, n - 1) FOR(j, i + 1, n) {
        if (g[i][j]) continue;
        if (fr.is_same(i, j)) {
            ans[i]++;
            ans[j]++;
        }
    }
    printv(ans);
}
