typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> P;
typedef pair<ll, ll> LP;
typedef pair<int, P> IP;
typedef pair<ll, LP> LLP;

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

constexpr int INF = 100000000;
constexpr ll LINF = 10000000000000000ll;
constexpr int MOD = static_cast<int>(1e9 + 7);
constexpr double EPS = 1e-9;

static inline ll mod(ll x, ll m)
{
    ll y = x % m;
    return (y >= 0 ? y : y+m);
}

// print floating-point number
// cout << fixed << setprecision(12) <<

// }}}

int H, W;
char s[20][20];

struct phash{
    inline size_t operator()(const P & p) const {
        const auto h1 = hash<int>()(p.first);
        const auto h2 = hash<int>()(p.second);
        return h1 ^ (h2 << 1);
    }
};

int bfs(P start, P destination)
{
    unordered_set<P, phash> visited;
    queue<pair<P, int> > q;
    q.push(mp(start, 0));
    while (!q.empty()) {
        auto p = q.front();
        q.pop();
        if (visited.find(p.fi) != visited.end()) continue;
        visited.insert(p.fi);
        if (s[p.fi.fi][p.fi.se] == '#') continue;
        if (p.fi == destination) return p.se;
        REP (i, 4) {
            int ni = p.fi.fi + dx[i];
            int nj = p.fi.se + dy[i];
            if (ni < 0 || H <= ni || nj < 0 || W <= nj) continue;
            if (s[ni][nj] == '#') continue;
            P np = mp(ni, nj);
            q.emplace(np, p.se+1);
        }
    }
    return -1;
}

void solve()
{
    int ans = 0;
    REP (si, H) {
        REP (sj, W) {
            if (s[si][sj] == '#') continue;
            REP (ti, H) {
                REP (tj, W) {
                    if (s[ti][tj] == '#') continue;
                    ans = max(ans, bfs(mp(si, sj), mp(ti, tj)));
                }
            }
        }
    }
    cout << ans << endl;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W;
    REP (i, H) REP (j, W) cin >> s[i][j];
    solve();
    return 0;
}

