bool C(ll d, ll S[], ll base) {
  ll last = base;
  for(int i=0; i<M; i++) {
    ll p = upper_bound(S, S+N, d+last) - S;
    if(N <= p) return false;
    last = S[p-1];
  }
  return true;
}

