    sum[i] = arr[i];
    if(i) sum[i] += sum[i-1];
  }
  for(int i=N; i<2*N; i++) {
    sum[i] = arr[i-N]+sum[i-1];
  }

  ll ans = INF;
  for(midx=0; midx<N; midx++) {
    ll lb = 0, ub = INF;
    while(ub-lb>1) {
      ll mid = (lb+ub)/2;
      ll c;
      if(midx>0) c = sum[midx-1];
      else c = 0;

      if(C(mid, sum+midx, c)) {
        lb = mid;
      } else {
        ub = mid;
      }
    }
    ans = min(ans, ub);
  }

