int solve(int H, int W, int K, int x1, int y1, int x2, int y2, vs& c) {
  vvi d(H, vi(W, INT_MAX));

  using P = pair<ii, int>;
  queue<P> q;
  q.emplace(ii(x1, y1), 0);

  while (!q.empty()) {
    P top = q.front();
    q.pop();
    int x = top.first.first, y = top.first.second, dp = top.second;
    assert(c[x][y] != '@');

    if (d[x][y] != INT_MAX) continue;
    d[x][y] = dp;

    auto visited = [&](int x, int y) -> bool {
      if (d[x][y] != INT_MAX) return true;
      if (c[x][y] == '@') return true;
      return false;
    };

    rep1(i, K) {
      int xi = x - i;
      if (xi < 0) break;
      if (visited(xi, y)) break;
      q.emplace(ii(xi, y), dp + 1);
    }
    rep1(i, K) {
      int xi = x + i;
      if (xi == H) break;
      if (visited(xi, y)) break;
      q.emplace(ii(xi, y), dp + 1);
    }
    rep1(i, K) {
      int yi = y - i;
      if (yi < 0) break;
      if (visited(x, yi)) break;
      q.emplace(ii(x, yi), dp + 1);
    }
    rep1(i, K) {
      int yi = y + i;
      if (yi == W) break;
      if (visited(x, yi)) break;
      q.emplace(ii(x, yi), dp + 1);
    }
  }


  return (d[x2][y2] == INT_MAX) ? -1 : d[x2][y2];
}

int main() {
  ios_base::sync_with_stdio(
      false);
  cin.tie(NULL);
  int H, W, K;
  cin >> H >> W >> K;
  int x1, y1, x2, y2;
  cin >> x1 >> y1 >> x2 >> y2;
  --x1;
  --y1;
  --x2;
  --y2;
  vs c(H);
  rep(i, H) cin >> c[i];
  cout << solve(H, W, K, x1, y1, x2, y2, c) << endl;
  return 0;
}
