#include<bits/stdc++.h>
using namespace std;

#define MAX_V 100005
#define INF 10000000000
typedef long long ll;
typedef pair<ll,ll> P;
int vn;
P vs[MAX_V];
ll total_cost=0;
ll min_costs[MAX_V];
bool used[MAX_V];

ll cost(P a,P b){
	return min(abs(a.first-b.first),abs(a.second-b.second));
}


void prim(){
	for(int i=0;i<vn;i++){
		min_costs[i] = INF;
		used[i]=false;
	}
	min_costs[0] = 0;
	while(true){
		ll cmin = INF+1;
		int cmin_i = -1;
		for(int i=0;i<vn;i++){
			if(!used[i] && min_costs[i]<cmin){
				cmin = min_costs[i];
				cmin_i = i;
			}
		}
		if(cmin_i==-1) break;
		used[cmin_i] = true;

		total_cost += min_costs[cmin_i];
		for(int i=0;i<vn;i++){
			min_costs[i] = min(min_costs[i],cost(vs[cmin_i],vs[i]));
		}
	}

	return;
}

int main() {
	cin >> vn;

	for(int i=0;i<vn;i++){
		ll a,b;
		cin >> a >> b;
		vs[i] = P(a,b);
	}
	prim();
	cout << total_cost << endl;
    return 0;
}

