#include <bits/stdc++.h>

using namespace std;

const int N = 88;
int A[N][N], B[N][N];
bool memo[N][N][4 * N];
int h, w, ans;
void solve(int i, int j, int sum) {
    if (i == h || j == w)
        return;
    if (i == h - 1 && j == w - 1) {
        ans = min({ans, abs(sum + A[i][j]), abs(sum + B[i][j])});
        return;
    }
    int s = sum * (sum >= 0 ? 1 : -2);
    bool &ret = memo[i][j][s];
    if (ret)
        return;
    solve(i + 1, j, sum + A[i][j]);
    solve(i + 1, j, sum + B[i][j]);
    solve(i, j + 1, sum + A[i][j]);
    solve(i, j + 1, sum + B[i][j]);
}

