class state {
  public:
  int h, w, r, b;
  state() {}
  state(int h, int w, int r, int b): h(h), w(w), r(r), b(b) {}
  bool operator < (const state &st) const {
    if (h == st.h) {
      if (w == st.w) {
        if (r == st.r) {
          return b < st.b;
        } else {
          return r < st.r;
        }
      } else {
        return w < st.w;
      }
    } else {
      return h < st.h;
    }
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int h, w;
  cin >> h >> w;
  vector<vector<PI>> grid(h, vector<PI> (w));
  int a;
  rep(i, 0, h) {
    rep(j, 0, w) {
      cin >> grid[i][j].first;
    }
  }
  rep(i, 0, h) {
    rep(j, 0, w) {
      cin >> grid[i][j].second;
    }
  }

  set<state> s;
  queue<state> q;
  state init1 = state(0, 0, grid[0][0].first, grid[0][0].second);
  state init2 = state(0, 0, grid[0][0].second, grid[0][0].first);
  q.push(init1);
  q.push(init2);
  while (!q.empty()) {
    auto st = q.front(); q.pop();
    if (Find(s, st)) continue;
    s.insert(st);
    { // right
      if (st.w < w - 1) {
        state nxt1 = st;
        state nxt2 = st;
        nxt1.w++;
        nxt2.w++;
        nxt1.r += grid[nxt1.h][nxt1.w].first;
        nxt1.b += grid[nxt1.h][nxt1.w].second;
        nxt2.r += grid[nxt2.h][nxt2.w].second;
        nxt2.b += grid[nxt2.h][nxt2.w].first;
        if (!(Find(s, nxt1))) {
          q.push(nxt1);
        }
        if (!(Find(s, nxt2))) {
          q.push(nxt2);
        }
      }
    }
    { // down
      if (st.h < h - 1) {
        state nxt1 = st;
        state nxt2 = st;
        nxt1.h++;
        nxt2.h++;
        nxt1.r += grid[nxt1.h][nxt1.w].first;
        nxt1.b += grid[nxt1.h][nxt1.w].second;
        nxt2.r += grid[nxt2.h][nxt2.w].second;
        nxt2.b += grid[nxt2.h][nxt2.w].first;
        if (!(Find(s, nxt1))) {
          q.push(nxt1);
        }
        if (!(Find(s, nxt2))) {
          q.push(nxt2);
        }
      }
    }
  }

  int ans = INT_MAX;
  for (auto it: s) {
    if (it.h == h-1 && it.w == w-1) {
      ans = min(ans, abs(it.r - it.b));
    }
  }

  cout << ans << endl;


  return 0;
};
