using namespace std;
struct node{
	int x;
	node* pre;
	node* next;
};
void init(node *x) {
	x->pre = x->next = NULL;
}
void Insert(node* head,int x) {
	node *n = new node;
	init(n);
	n->x = x;
	if (head->next == NULL) {
		n->pre = head;
		head->next = n;
	}
	else {
		node* nn = new node;
		nn = head->next;
		n->pre = head;
		head->next = n;
		n->next = nn;
		nn->pre = n;
	}
}
int DeleteFirst(node* head) {
	if (head->next == NULL)
		return 0;
	else {
		head->next = head->next->next;
	}
	return 1;
}
int Delete(node* head, int x) {
	node* n = new node;
	n = head->next;
	if (n->x == x) {
		DeleteFirst(head);
		return 0;
	}
	for (; n->next != NULL; n = n->next) {
		if (n->x == x) {
			n->pre->next = n->next;
			n->next->pre = n->pre;
			delete n;
			return 0;
		}
	}
	if (n->x == x) {
		n->pre->next = NULL;
		delete n;
		return 0;
	}
	return 1;
}

int DeleteLast(node* head) {
	node* n = new node;
	n = head->next;
	if (n->next == NULL) {
		head->next = NULL;
		return 0;
	}
	while (n->next != NULL) {
		n = n->next;
	}
	n->pre->next = NULL;
	delete n;
	return 1;
}
int Print(node *head) {
	if (head->next == NULL) {
		cout << endl;
		return 0;
	}
	node *n = new node;
	n = head->next;
	node *pre = new node;
	pre = n;
	while (n->next != NULL) {
		cout << n->x << " ";
		n = n->next;
		pre = n;
	}
	cout << pre->x << endl;
	return 1;
}
int main() {
	node* head=new node;
	init(head);
	char s[30];
	int x,a;
	scanf("%d",&x);
	for (int i = 0; i < x; i++) {
		scanf("%s", s);
		if (s[0] == 'i'&&s[2]=='s') {
			scanf("%d", &a);
			Insert(head, a);
		}
		else if (s[0] == 'd'&&s[6]=='L') {
			DeleteLast(head);
		}
		else if (s[0] == 'd'&&s[6] == 'F'){
			DeleteFirst(head);
		}
		else {
			scanf("%d", &a);
			Delete(head, a);
		}
	}
	Print(head);
}
