int sieve(int n)
{
	int p=0;
	for(int i=0;i<=n;i++)
	{
		isprime[i]=true;
	}
	isprime[0]=false;
	isprime[1]=false;

	for(int i=2;i<=n;i++)
	{
		if(isprime[i])
		{
			prime[p++]=i;
			for(int j=2*i;j<=n;j+=i)
			{
				isprime[j]=false;
			}
		}
	}
	return p;
}

