#include <bits/stdc++.h>

using namespace std;

using ll = long long;

string solve(const string &s, const string &t, int n, int m) {
  if (n == 0 || m == 0) {
    return "";
  }
  if (s[n - 1] == t[m - 1]) {
    auto ret = solve(s, t, n - 1, m - 1);
    return ret += {s[n - 1]};
  } else {
    auto ret1 = solve(s, t, n, m - 1);
    auto ret2 = solve(s, t, n - 1, m);
    return (ret1.length() < ret2.length()) ? ret2 : ret1;
  }
}

int main() {
  string s, t;
  cin >> s >> t;
  cout << solve(s, t, s.length(), t.length()) << endl;
