#include <cassert>
#include <cstdio>
#include <functional>
#include <tuple>
#include <vector>
#define repeat(i, n) for (int i = 0; (i) < int(n); ++(i))
using namespace std;
template <class T> inline void setmax(T & a, T const & b) { a = max(a, b); }

inline int singleton(int i) { return 1 << i; }
inline int setminus(int s, int t) { return s & ~ t; }
inline int complement(int s, int n) { return setminus((1 << n) - 1, s); }
inline bool is_a(int i, int s) { return s & (1 << i); }
inline bool is_subset(int s, int t) { return (s | t) == t; }
inline bool is_disjoint(int s, int t) { return (s & t) == 0; }

vector<int> calculate_component_wieghts(int n, vector<tuple<int, int, int> > const & edges) {
    vector<int> component_wieght(1 << n);
    repeat (x, 1 << n) {
        for (auto edge : edges) {
            int a, b, c; tie(a, b, c) = edge;
            if (is_a(a, x) and is_a(b, x)) {
                component_wieght[x] += c;
            }
        }
    }
    return component_wieght;
}

int use_remaining_edges(int used, int n, vector<tuple<int, int, int> > const & edges, vector<int> const & component_wieght, vector<int> & memo) {
    if (memo[used] != -1) return memo[used];
    vector<int> cur(1 << n, -1), prv;
    cur[0] = 0;
    int acc = 0;
    int result = 0;
    repeat (i, n) if (is_a(i, used)) {
        cur.swap(prv);
        cur.assign(1 << n, -1);
        int z = complement(acc | used, n);
        for (int x = 0; ; x = (x - z) & z) { // x \subseteq z
            if (prv[x | acc] != -1 and result < prv[x | acc] + component_wieght[complement(x | acc, n)] - component_wieght[used]) {
                int zx = z ^ x; // z \setminus x
                for (int y = 0; ; y = (y - zx) & zx) { // y \subseteq zx
                    setmax(cur[x | acc | y | singleton(i)], prv[x | acc] + component_wieght[y | singleton(i)]);
                    setmax(result, cur[x | acc | y | singleton(i)]);
                    if (y == zx) break;
                }
            }
            if (x == z) break;
        }
        acc  ^= singleton(i);
        used ^= singleton(i);
    }
    // return memo[used] = cur[(1 << n) - 1];
    return memo[used] = result;
}


int solve(int n, vector<vector<pair<int, int> > > const & g, vector<tuple<int, int, int> > const & edges) {
    auto component_wieght = calculate_component_wieghts(n, edges);
    int result = 0;
    int acc = 0;
    int used = 0;
    const int start = 0;
    const int goal = n - 1;
    vector<int> path_dp(1 << n, -1);
    vector<int> memo(1 << n, -1);
    function<void (int)> go = [&](int i) {
        if (acc < path_dp[used | (1 << i)]) return;
        path_dp[used | (1 << i)] = acc;
        used ^= 1 << i;
        if (i == goal) {
            setmax(result, acc + use_remaining_edges(used, n, edges, component_wieght, memo));
        } else {
            for (auto edge : g[i]) {
                int j, cost; tie(j, cost) = edge;
                if (used & (1 << j)) continue;
                acc += cost;
                go(j);
                acc -= cost;
            }
        }
        used ^= 1 << i;
    };
    go(start);
    int total_cost = 0;
    for (auto edge : edges) {
        total_cost += get<2>(edge);
    }
    return total_cost - result;
}

int main() {
    // input
    int n, m; scanf("%d%d", &n, &m);
    vector<vector<pair<int, int> > > g(n);
    vector<tuple<int, int, int> > edges(m);
    repeat (i, m) {
        int a, b, c; scanf("%d%d%d", &a, &b, &c); -- a; -- b;
        edges[i] = { a, b , c };
        g[a].emplace_back(b, c);
        g[b].emplace_back(a, c);
    }
    // solve
    int result = solve(n, g, edges);
    // output
    printf("%d\n", result);
    return 0;
}
