long long int ans = 0;

void calc(const vector<long long int>& v, int cnt, int t_i, long long int now)
{
    if (v[t_i] < ans) return;
    if (cnt == 0){
        if (now > ans) ans = now;
        return;
    }

    long long int next;
    if (now == 0) next = v[t_i];
    else next = now & v[t_i];

    calc(v, cnt - 1, t_i + 1, next);
    calc(v, cnt, t_i + 1, now);
}

