using namespace std;

string X;
string Y;

int calc(int x, int y){
    if (X[x] == '\0') return 0;
    if (y == string::npos) return 0;

    int unuse = calc(x + 1, y);
    int use = 0;
    int y_target = Y.find(X[x], y);
    if (y_target == string::npos) {
        use = 0;
    } else {
        use = calc(x + 1, y_target + 1) + 1;
    }
    return max(unuse, use);
}

int main(){
    int q;
    cin >> q;
