using vc = vector<char>; using vvc = vector<vc>;
using vb = vector<bool>; using vvb = vector<vb>;
using vl = vector<ll>; using vvl = vector<vl>;
using vd = vector<double>; using vs = vector<string>;
using pii = pair<int, int>; using pll = pair<ll, ll>; using psl = pair<string, ll>;

struct ModComb {
    int Size;
    ll Mod;
    vl fact;
    vl inv_fact;

    ll pow(ll a, ll n) {
        ll res = 1;
        while (n > 0) {
            if (n & 0b01) { 
                res *= a;
                res %= Mod;
            }
            a = a*a;
            a %= Mod;
            n >>= 1;
        }
        return res;
    }

    ll inv(ll num) {
        return pow(num, Mod - 2);
    }

    void init(const int SIZE, const ll MOD){
        Size = SIZE;
        Mod = MOD;

        fact = vl(Size);
        fact[0] = 1;
        FOR (i,1,Size) {
            fact[i] = fact[i - 1] * i % Mod;
        }

        inv_fact = vl(Size);
        inv_fact[0] = 1;
        inv_fact[Size-1] = inv(fact[Size-1]);
        for (int i = Size - 1; i > 0; i--) {
            inv_fact[i - 1] = inv_fact[i] * i % Mod;
        }
    }

    ModComb(){}

    ModComb(const int SIZE, const ll MOD) {
        init(SIZE, MOD);
    }

    ll C(ll n, ll r) {
        if (n < 0 || r < 0 || n < r) return 0;
        return fact[n] * inv_fact[r] % Mod * inv_fact[n - r] % Mod;
    }

    ll P(ll n, ll r) {
        if (n < 0 || r < 0 || n < r) return 0;
        return fact[n] * inv_fact[n - r] % Mod;
    }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  const ll MOD = 1e9+7;
  int N,K; cin>>N>>K;
  vi A(N); REP(i,N) cin>>A[i];

  if (K==1) {
    cout << 0 << endl;
    return 0;
  }

  sort(A.begin(), A.end());

  ModComb comb(N, MOD);

  ll ans = 0;
  REP(i,N-K+1) {
    FOR(j,i+K-1,N) {
      ll cb = comb.C(j-i-1, K-2);
      ans += cb * (A[j] - A[i]) % MOD;
    }
  }
  ans %= MOD;

  cout << ans << endl;

  return 0;
}
