					LL y=vec[i][j];
					node c1=findans(1,1,n,1,y-1);
					node c2=findans(1,1,n,y+1,n);
					LL C1=c1.c2+y*d+a[y],C2=c2.c1-y*d+a[y];
					if(C1<C2) e[++len].x=i,e[len].y=c1.k2,e[len].c=C1;
					else e[++len].x=i,e[len].y=c2.k1,e[len].c=C2;
				}
				for(LL j=0;j<vec[i].size();j++)
