using namespace std;

const int MAX = 10;
char data[MAX][MAX];

int H,W;
int dy[] = {1,0,-1,0};
int dx[] = {0,1,0,-1};


typedef pair<int,int>P;

class S{
public:
  vector<P>v1;
  vector<P>v2;
  S(){};
  S(vector<P>_v1,vector<P>_v2){
    v1 = _v1;
    v2 = _v2;
    sort(v1.begin(),v1.end());
    sort(v2.begin(),v2.end());
  }
  bool operator < (const S& s)const{
    if(v1 == s.v1)return v2 < s.v2;
    return v1 < s.v1;
  }
};


class T{
public:
  int cost;
  P p;  
  S s;
  T(int _cost,P _p,vector<P>_v1,vector<P>_v2){
    cost = _cost;
    p = _p;
    s = S(_v1,_v2);
  }
};

set<S> st[MAX][MAX];

void input(vector<P>& w_vec,vector<P>& c_vec,P& s,P& g){
  for(int i = 0 ; i < H ; i++){
    for(int j = 0 ; j < W ; j++){
      cin >> data[i][j];
      if(data[i][j] == '#')continue;
      if(data[i][j] == '@')s = P(i,j);
      if(data[i][j] == 'w')w_vec.push_back(P(i,j));
      if(data[i][j] == 'E')g = P(i,j);
      if(data[i][j] == 'c')c_vec.push_back(P(i,j));
      data[i][j] = '.';
    }
  }
}

void init(){
  for(int i = 0 ; i < MAX ; i++){
    for(int j = 0 ; j < MAX ; j++){
      st[i][j].clear();
    }
  }
}

bool move(P& p,vector<P>& w_vec,int dir){
  P pre = p;

  p = P(p.first + dy[dir],p.second + dx[dir]);
  if(data[p.first][p.second] == '#' || data[p.first][p.second] == 'c')return false;

  while(1){
    char c = data[p.first][p.second];
    if(c == 'c' || c == '#'){
      p = pre;
      return true;
    }
    for(int i = 0 ; i < w_vec.size() ; i++){
      if(w_vec[i] == p){
	p = w_vec[i] = P(MAX,MAX);
	return true;
      }
    }
  }
  return true;
}

int bfs(T t,P g){
  S s;
  st[t.p.first][t.p.second].insert(t.s);
  queue<T>que;
  que.push(t);
  while(que.size()){
    t = que.front(); que.pop();
    P p = t.p;

    //cout << "p : " << p.first << ' ' << p.second << " cost = " << t.cost << endl; 

    for(int i = 0 ; i < 4 ; i++){
      vector<P>w_vec = t.s.v1,c_vec = t.s.v2;
      P np = P(p.first + dy[i],p.second + dx[i]);

      bool f = false;

      //cout <<  data[np.first][np.second]  << endl;
      if(data[np.first][np.second] == '#')f = true;

      for(int j = 0 ; j < w_vec.size() ; j++)if(w_vec[j] == np){f = true;break;};      

      for(int j = 0 ; j < c_vec.size() ; j++){

	if(np != c_vec[j])continue;
	// change c_vec,w_vec
	//cout << np.first << ' ' << np.second << ' ' << c_vec[j].first << ' ' << c_vec[j].second << endl;
	if(!move(c_vec[j],w_vec,i)) f = true;
      }


      /*
      if(i == 0){
	cout << "np : " << np.first << ' ' << np.second << " f = " << f << endl;
      }
      */

      if(f)continue;

      if(st[np.first][np.second].count(S(w_vec,c_vec)))continue;
      st[np.first][np.second].insert(S(w_vec,c_vec));
      if(np == g)return t.cost + 1;
      que.push(T(t.cost+1,np,w_vec,c_vec));
    }
  }
  return -1;
}

void solve(){  
  vector<P>w_vec,c_vec;
  P s,g;
  input(w_vec,c_vec,s,g);
  init();
  T t(0,s,w_vec,c_vec);
  cout << bfs(t,g) << endl;
}

int main(){  
  while(cin >> H >> W,H||W){
    solve();
  }
  return 0;
