int pollock(int i, int u) {
	int count = 0;

	if (u == 0) {
		return 0;
	}
	if (u>=pol[i]) {
		if (u - pol[i] == pol[i]) {
			return 2;
		}
		else count =1+ std::min(pollock(i + 1, u - pol[i]), pollock(i + 1, u));
	}
	else return 0;
	return mem1[u - pol[i]] = count;
}
