int POS(int k,int value){
    int mid;
    int left = 0;
    int len = G[k].size();
    int right = len - 1;
    //cout<<" "<<k<<"A"<<value<<endl;
    while(left <= right){

        // 确保中点靠近区间的起点
        mid = left + (right-left)/2;
        //cout<<mid<<endl;
        //cout<<"mid= "<<mid<<" "<<left<<" "<<right<<endl;
        // 如果找到则返回
        if(G[k][mid] == value) return mid;
        // 将中点赋给终点
        else if(G[k][mid] > value) right = mid;
        // 将中点加一赋给起点
        else left = mid + 1;
    }
    return -1;
}
