void upd(node *root, int l, int r, int x, ll v) {
    if(l == r) {
        root->mx = max(root->mx, v);
        return;
    }
    int m = (l + r) >> 1;
    if(l <= x && x <= m) {
        upd(root->l, l, m, x, v);
    } else {
        upd(root->r, m + 1, r, x, v);
    }
    root->mx = max(root->l->mx, root->r->mx);
}

void make(node *root, int l, int r) {
    if(l == r) {
        return;
    }
    int m = (l + r) >> 1;
    root->l = new node();
    root->r = new node();
    make(root->l, l, m);
    make(root->r, m + 1, r);
}

ll get(node *root, int l, int r, int gl, int gr) {
    if(l > gr || r < gl) {
        return 0;
    }
    if(l == r) {
        return root->mx;
    }
    int m = (l + r) >> 1;
    return max(get(root->l, l, m, gl, gr), get(root->r, m + 1, r, gl, gr));
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
