    a2[i]=dftn[i];

    for (int i=0; i<dwa.size(); i++)
    dftn[i]=dwa[i]%M;
    for (int i=dwa.size(); i<n1; i++)
    dftn[i]=0;
    dft(n1, 1);
    for (int i=0; i<n1; i++)
    b2[i]=dftn[i];

    vector <long long> ret;
    for (int i=0; i<n1; i++)
    ret.push_back(0);

    for (int i=0; i<n1; i++)
    dftn[i]=a1[i]*a2[i];
    dft(n1, 0);
    for (int i=0; i<n1; i++)
    ret[i]+=(llround(dftn[i].real()/n1)%1000000007)*M*M;

    for (int i=0; i<n1; i++)
    dftn[i]=a1[i]*b2[i]+b1[i]*a2[i];
    dft(n1, 0);
    for (int i=0; i<n1; i++)
    ret[i]+=llround(dftn[i].real()/n1)*M;

    for (int i=0; i<n1; i++)
    dftn[i]=b1[i]*b2[i];
    dft(n1, 0);
    for (int i=0; i<n1; i++)
    ret[i]+=llround(dftn[i].real()/n1);

    for (int i=0; i<ret.size(); i++)
        ret[i]%=1000000007;

    return ret;
}

