    sil[0]=1;
    odw[0]=1;
    do3[0]=1;
    for (int i=1; i<=s; i++)
        sil[i]=(sil[i-1]*i)%mod;
    odw[s]=dziel(1, sil[s]);
    for (int i=s-1; i; i--)
        odw[i]=(odw[i+1]*(i+1))%mod;
    for (int i=1; i<=s; i++)
        do3[i]=(do3[i-1]*3)%mod;
    for (int i=0; i<=m; i++)
        d1.push_back((komz(n, i)*odw[n+i-1])%mod);
    for (int i=0; i<=k; i++)
        d2.push_back(odw[i]);
    d3=fft_dokladne(d1, d2);
    for (int i=0; i<=m+k; i++)
        wyn+=(d3[i]*((sil[n+i-1]*do3[m+k-i])%mod))%mod;
    printf("%lld\n", wyn%mod);
    return 0;
}
