struct UnionFind {
	UnionFind(sint size) {
		for (sint i = 0; i < size; ++i) {
			parents.push_back(i);
		}
	}

	void unite(sint x, sint y) {
		sint rx = root(x);
		sint ry = root(y);
		if (rx == ry) {
			return;
		}
		parents[ry] = rx;
	}

	bool same(sint x, sint y) {
		return root(x) == root(y);
	}

	sint root(sint x) {
		if (parents[x] == x) {
			return x;
		}
		parents[x] = root(parents[x]);
		return parents[x];
	}

	vector<sint> parents;
};

