#include <iostream>
#include <deque>

using namespace std;

typedef long long LL;
#define PB push_back
#define TARO 0
#define JIRO 1

LL solve(int turn, deque<LL>& A) {
  if (A.size() == 0)
    return 0;
  if (A.size() == 1)
    return (turn == TARO ? 1 : -1) * A.front();
  LL front = A.front(),
    back = A.back();
  A.pop_front();
  LL res = solve(1 - turn, A) + (turn == TARO ? 1 : -1) * front;
  A.push_front(front);
  A.pop_back();
  LL res2 = solve(1 - turn, A) + (turn == TARO ? 1 : -1) * back;
  A.push_back(back);
  if (turn == TARO)
    return res > res2 ? res : res2;
  return res < res2 ? res : res2;
}

int main() {
  int N;
  cin >> N;

  deque<LL> A;
  for (int i = 0; i < N; ++i) {
    LL a;
    cin >> a;
    A.PB(a);
  }
  cout << solve(TARO, A) << endl;
  return 0;
}
