void solve(int cs){
    scanf("%d %lld" , &n , &k);

    for(int i = 0 ; i < n ; i ++){
            scanf("%lld" , &a[i]);
    }

    for(int i = 0 ; i < n ; i ++){
            scanf("%lld" , &f[i]);
    }

    sort(a , a + n);
    sort(f , f + n);
    reverse(f , f + n);

    priority_queue < pair < ll , pair < ll , ll > > > pq;
    for(int i = 0 ; i < n ; i ++){
            pq.push({a[i] * f[i] , {a[i] , f[i]} });
    }

    while( !pq.empty() ){
            ll z = pq.top().first;
            ll x = pq.top().second.first;
            ll y = pq.top().second.second;
            pq.pop();

            ll c = pq.top().first;

            ll x2 = c / y - (c%y == 0);

            ll diff = x - x2;
            if(k <= diff){
                    x -= k;
                    if(x > 0){
                            pq.push({x*y , {x , y} });
                    }
                    break;
            }

            k -= diff;
            x = x2;
            if(x > 0){
                    pq.push({x*y , {x , y} });
            }
    }

    ll ans = 0;
    while( !pq.empty() ){
            ans = max(ans , pq.top().first);

            pq.pop();
    }

    printf("%lld\n" , ans);
}

