		vector<int> vec(a, a + 8);
		queue<vector<int> > que;
		visited.clear();
		step = 0;
		endsearch = 0;
		que.push(vec);
		while (que.size() != 0) {
			que = bfs(que);
			if (endsearch) {
				cout << step << endl;
				break;
			}
