#include <algorithm>
#include <map>
#include <unordered_map>

using namespace std;


int lcs(string s, string t, int n, int m, vector<int> &when, int time = 0) {
	if (n < 0 || m < 0) return 0;
	if (s[n] == t[m]) {
		when[n] = max(when[n], time);
		return 1 + lcs(s, t, n - 1, m - 1, when, time + 1);
	}
	else {
		return max(lcs(s, t, n - 1, m, when, time), lcs(s, t, n, m - 1, when, time));
	}
}

int main() {
	string s, t;
	cin >> s >> t;
	int n;
	if (s.size() > t.size()) swap(t, s);
	vector<int> when(s.size(), -1);
	lcs(s, t, s.size() - 1, t.size() - 1, when);
	int l = -1;
	vector<pair<int, int>> q(s.size());
	for (int i = 0; i < s.size(); ++i) {
		q[i].first = when[i];
		q[i].second = i;
	}
	sort(begin(q), end(q));
	string ans = "";
	for (pair<int, int> i : q) {
		if (i.first > l) {
			l = i.first;
			ans += s[i.second];
		}
	}

	reverse(begin(ans), end(ans));
	cout << ans << endl;
	cin >> n;
