	for (int i = 0; i < 2 * n; i++) {
		int h;
		cin >> h;
		a[h]++;
		max_h = max(max_h, h);
	}

	f[0] = 1;
	for (int i = 1; i <= 2 * n; i++) {
		f[i] = (ll)f[i - 1] * i % MOD;
	}
	inv_f[2 * n] = power(f[2 * n], MOD - 2);
	for (int i = 2 * n - 1; i >= 0; i--) {
		inv_f[i] = (ll)inv_f[i + 1] * (i + 1) % MOD;
	}

	dp[0] = 1;
	for (int i = 1; i <= max_h; i++) {
		for (int j = 0; j <= 2 * n; j++) {
			new_dp[j] = 0;
			for (int k = 0; k <= min(a[i], j); k++) {
