};
Edge::Edge(int t,int w)
{
	this->to = t;
	this->weight = w;
}
using Graph = vector<vector<Edge>>;
vector<bool> seen;
int weight(Graph G,int x,int y)
{
	int i;
	for(i=0;i<G[x].size();i++)
	{
		if(G[x][i].to == y) return G[x][i].weight;
	}
}
void dfs(Graph G,int v,int sumweight[])
{
	seen[v] = true;
	int i;
	int count = 0;
	for(i=0;i<G[v].size();i++)
	{
		int nextv = G[v][i].to;
		//cout << nextv;
		if(seen[nextv]) continue;
		sumweight[nextv] = sumweight[v] + G[v][i].weight;
		dfs(G,nextv,sumweight);
	}
}
int main()
{
	int N;
	cin >> N;
	Graph G(N);
	int sumweight[N];
	seen.assign(N,false);
	int i;
	for(i = 0;i < (N-1);i++)
	{
		int x,y,weight;
		cin >> x >> y >> weight;
		G[x-1].push_back(Edge(y-1,weight));
		G[y-1].push_back(Edge(x-1,weight));
	}
	//cout << weight(G,0,1) << endl;
	sumweight[0] = 0;
	dfs(G,0,sumweight);
	for(i=0;i<N;i++)
	{
		//cout << sumweight[i] << endl;
		if((sumweight[i] % 2) == 0) cout << '0' << endl;
