using namespace std;

vector<int> memo(300000, -1);

class Mod
{
    static const int MOD = 1000000007;
    long long a;
public:
    Mod(){
        a = 0;
    }
    Mod(long long x){
        a = x % MOD;
    }
    const Mod operator+(const Mod& x) const{
        return Mod(a + x.a);
    }
    Mod& operator+=(const Mod& x){
        *this = Mod(a + x.a);
        return *this;
    }
    const Mod operator*(const Mod& x) const{
        return Mod(a * x.a);
    }
    Mod& operator*=(const Mod& x){
        *this = Mod(a * x.a);
        return *this;
    }
    const Mod operator/(const Mod& x) const{ // フェルマーの小定理、x.aがMODと互いに素な場合のみ有効
        if(memo[x.a] != -1)
            return Mod(a * memo[x.a]);

        int b = MOD - 2;
        long long c = x.a;
        long long ret = 1;
        while(b > 0){
            if(b & 1){
                ret *= c;
                ret %= MOD;
            }
            c *= c;
            c %= MOD;
            b >>= 1;
        }

        memo[x.a] = ret;
        return Mod(a * ret);
    }
    Mod operator/=(const Mod& x){
        *this = *this / x;
        return *this;
    }
    long long getValue(){
        return a;
    }
};

vector<Mod> solve(int len, int n)
{
    if(len < n){
        vector<Mod> ret;
        vector<Mod> curr(2*n+1, 0);
        curr[0] = 1;
        for(int i=0; i<=n; ++i){
            vector<Mod> next(2*n+1, 0);
            for(int j=0; j<2*n; ++j){
                curr[j+1] += curr[j];
                if(j - 1 >= 0)
                    next[j-1] += curr[j];
            }
            ret.push_back(curr[len]);
            curr.swap(next);
        }
        return ret;
    }

    vector<Mod> dp;
    vector<Mod> curr(n+1, 0);
    curr[0] = 1;
    for(int i=0; i<=n; ++i){
        vector<Mod> next(n+1, 0);
        for(int j=0; j<n; ++j){
            curr[j+1] += curr[j];
            if(j-1 >= 0)
                next[j-1] += curr[j];
        }
        dp.push_back(curr[n]);
        curr.swap(next);
    }

    vector<Mod> ret(n+1, 0);
    for(int i=0; i<=n; ++i){
        Mod tmp = 1;
        for(int j=0; j<i; ++j){
            tmp *= len - n + 2 * i - j;
            tmp /= j + 1;
        }

        for(int j=0; j<=n-i; ++j){
            ret[i+j] += dp[j] * tmp;
        }
    }
    return ret;
}

int main()
{
    int w, h, n; // ゴールのx座標、y座標、寄り道回数
    cin >> w >> h >> n;

    vector<Mod> s = solve(w, n);
    vector<Mod> t = solve(h, n);

    Mod tmp = 1;
    for(int i=0; i<h; ++i){
        tmp *= w + h + 2 * n - i;
        tmp /= i + 1;
    }

    Mod ret = 0;
    for(int i=0; i<=n; ++i){
        ret += s[n-i] * t[i] * tmp;

        for(int j=0; j<2; ++j){
            tmp *= w + 2 * n - 2 * i - j;
            tmp /= h+1+2*i+j;
        }
    }
    cout << ret.getValue() << endl;

    return 0;
},time_limit_exceeded,,p01452

