ll minCost(ll n,ll h[],ll dp[])
{
	if(n==1)
	return 0;

	if(dp[n]!=0)
	return dp[n];

   ll ans1,ans2;
   ans1=ans2=INT_MAX;

   if(n>1)
   ans1=minCost(n-1,h,dp)+abs(h[n]-h[n-1]);
   if(n>2)
   ans2=minCost(n-2,h,dp)+abs(h[n]-h[n-2]);

	return dp[n]=min(ans1,ans2);
}

