			}
		}
		yoko=0;
		tate=0;
		round=0;
	}
public:
	// _CXÌñ]
	void rotate(){
		if(round<4){
            int tmp = face[2][1];
			face[2][1]=face[1][2];
			face[1][2]=face[0][1];
			face[0][1]=face[1][0];
			face[1][0]=tmp;
			round++;
		}
		if(round>=4){
			round=0;
			// àÇÁÄ«½çA¡ÌXbgðñ]³¹é
			if(yoko<4){
                int tmp = face[1][3];
				for(int i = 2; i >= 0; i--){
					face[1][i+1]=face[1][i];
				}
				face[1][0]=tmp;
				yoko++;
			}
			// àÇÁÄ«½çAcÌXbgðñ]³¹é
			if(yoko>=4){
				if(tate<4){
					tate++;
					int tmp = face[1][3];
					face[1][3]=face[0][1];
					for(int i = 0; i < 2; i++){
						face[i][1]=face[i+1][1];
					}
					face[2][1]=tmp;
				}
				if(tate>=4){
					round=0;
					tate=0;
					yoko=0;
				}
			}
		}
	};
};

