		else anum = nums[i];

		if (anum >= 10)anum = anum / 10 + anum % 10;
		sum += anum;
	}
	return sum % 10 == 0;
}

int getnum( int num, const bool iseven) {
	if (!iseven)return num;
	else {
		num *= 2;
		return num % 10 + num / 10;
	}
}

