            int len1 = ind - i;
            int len2 = N - ind;
            if(len1 <= 0 || len1 < ans || len2 < ans) { continue; }
            int cand = rh.Lcp(rh, i, ind, ind, N);
            ans = max(ans, cand);
        }
    }
    printf("%lld\n", ans);
