#define ABS(a) ((a) < 0 ? -(a) : (a))

int N;
int64_t table[300][300];
int64_t table2[300][300];

class Path {
 public:
  Path(int from, int to, int dist) : from(from), to(to), dist(dist) {}

  friend int operator<(const Path &a, const Path &b) { return a.dist < b.dist; }
  friend std::ostream &operator<<(std::ostream &os, const Path &a) {
    os << a.from << " -> " << a.to << " : " << a.dist;
    return os;
  }

  int getFrom() { return from; }
  int getTo() { return to; }
  int getDist() { return dist; }

 private:
  int from, to, dist;
};

int havePath(int u, int v, int lessThan) {
  if (lessThan <= 0) return 0;
  if (u == v) return 1;
  for (int i = 0; i < N; i++) {
    if (i != u && table[u][i] < lessThan) {
      if (havePath(i, v, lessThan - table[u][i])) return 1;
    }
  }
  return 0;
}

int havePath2(int u, int v, int len, int cLen) {
  // std::cout << u << " " << v << std::endl;
  if (u == v && len == cLen) return len;
  if (cLen > len) return 0;
  for (int i = 0; i < N; i++) {
    if (i != u && table2[u][i] != 0) {
      int dist = havePath2(i, v, len, cLen + table2[u][i]);
      if (dist) return dist;
    }
  }
  return 0;
}

int main(int argc, char *argv[]) {
  std::cin >> N;

  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      std::cin >> table[y][x];
    }
  }

  std::vector<Path> paths;
  std::vector<Path> paths_use;

  for (int u = 0; u < N; u++) {
    for (int v = u + 1; v < N; v++) {
      paths.push_back(Path(u, v, table[u][v]));
      if (havePath(u, v, table[u][v])) {
        std::cout << -1 << std::endl;
        return 0;
      }
    }
  }

  std::sort(paths.begin(), paths.end());

  for (int i = 0; i < paths.size(); i++) {
    // std::cout << paths[i] << std::endl;
    if (havePath2(paths[i].getFrom(), paths[i].getTo(), paths[i].getDist(),
                  0) != paths[i].getDist()) {
      paths_use.push_back(paths[i]);
      table2[paths[i].getFrom()][paths[i].getTo()] = paths[i].getDist();
      table2[paths[i].getTo()][paths[i].getFrom()] = paths[i].getDist();
      // std::cout << "use" << std::endl;
    }
  }
  uint64_t sum = 0;
  for (int i = 0; i < paths_use.size(); i++) {
    sum += paths_use[i].getDist();
  }
  std::cout << sum << std::endl;
}

