typedef long long ll;
#define FOR(var, begin, end) for (int var = (begin); var <= (end); var++)
#define RFOR(var, begin, end) for (int var = (begin); var >= (end); var--)
#define REP(var, length) FOR(var, 0, length - 1)
#define RREP(var, length) RFOR(var, length - 1, 0)
#define EACH(value, var) for (auto value : var)
#define SORT(var) sort(var.begin(), var.end())
#define REVERSE(var) reverse(var.begin(), var.end())
#define RSORT(var) SORT(var); REVERSE(var)

const ll MOD = 1e9 + 7;

map<int, vector<int>> idx;
map<int, int> to;
vector<ll> memo;

ll Count(int i) {
  ll ret = 0;
  if (i >= memo.size()) {
    return 0;
  }
  if (memo[i] != -1) {
    return memo[i];
  }
  for (auto itr = to.lower_bound(i); itr != to.end(); itr++) {
    ret += Count(itr->second) + 1;
    ret %= MOD;
  }
  memo[i] = ret;
  return ret;
}

void solve(istream& cin, ostream& cout) {
  int n;
  cin >> n;
  idx = map<int, vector<int>>{};
  to = map<int, int>{};
  memo = vector<ll>(n, -1);
  REP(i, n) {
    int input;
    cin >> input;
    idx[input].push_back(i);
  }
  EACH(v, idx) {
    int l = 0;
    while (l < v.second.size() - 1) {
      int r = l + 1;
      int br = l;
      while (v.second[br] + 1 == v.second[r] && r < v.second.size()) {
        br++;
        r++;
      }
      br = r;
      r++;
      while (v.second[br] + 1 == v.second[r] && r < v.second.size()) {
        br++;
        r++;
      }
      if (br < v.second.size()) {
        to[v.second[l]] = v.second[br];
      }
      l = br;
    }
  }

  cout << Count(0) + 1 << endl;
}

#ifndef TEST
int main() {
  solve(cin, cout);
}
