 */
namespace graph_search {

template <class V, class F,
          enable_if_t<std::is_constructible<fun<void(opt<V>, V)>, F>::value,
                      nullptr_t> = nullptr>
void dfs_impl(graph<V> const &g, V const &v, F const &process,
              u_set<V> &visited) {
  if (g.find(v) == g.end())
    return;
  for (auto const &u : g.at(v)) {
    if (visited.find(u) == visited.end()) {
      visited.insert(u);
      process(opt<V>(v), u);
      dfs_impl(g, u, process, visited);
    }
  }
} // namespace graph_search
template <class V, class F,
          enable_if_t<std::is_constructible<fun<void(opt<V>, V)>, F>::value,
                      nullptr_t> = nullptr>
void dfs(graph<V> const &g, V const &root, F const &process) {
  u_set<V> visited{root};
  process(opt<V>(nullptr), root);
  dfs_impl(g, root, process, visited);
}
template <class V, class F,
          enable_if_t<std::is_constructible<fun<void(opt<V>, V)>, F>::value,
                      nullptr_t> = nullptr>
void bfs(graph<V> const &g, V const &root, F const &process) {
  list<pair<opt<V>, V>> l{{opt<V>(nullptr), root}};
  u_set<V> visited{root};
  while (!l.empty()) {
    auto parent = l.front().first;
    auto v = l.front().second;
    l.pop_front();
    process(parent, v);
    if (g.find(v) == g.end())
      return;
    for (auto const &u : g.at(v)) {
      if (visited.find(u) == visited.end()) {
        l.push_back({opt<V>(v), u});
        visited.insert(u);
      }
    }
  }
}
} // namespace graph_search

using graph_search::bfs;
using graph_search::dfs;
/* end of GRAPH_SEARCH */

using V = tuple<ll, ll>;
using E = tuple<V, V>;

void solve() {
  ll H, W, Ch, Cw, Dh, Dw;
  input(H, W, Ch, Cw, Dh, Dw);
  Ch--;
  Cw--;
  Dh--;
  Dw--;
  vecs S(H);
  input(S);
  dump(H, W, Ch, Cw, Dh, Dw);
  dump(S);

  u_set<V> vs;
  graph<V> G;
  {
    for (auto &&i : range(H)) {
      for (auto &&j : range(W)) {
        auto v = V{i, j};
        if (S[i][j] == '#')
          continue;
        vs.insert(v);
        for (auto &[k, l] :
             vec<V>{{i, j - 1}, {i, j + 1}, {i + 1, j}, {i - 1, j}}) {
          if ((!range(H).has(k)) || (!range(W).has(l)) || S[k][l] == '#')
            continue;
          auto u = V{k, l};
          dump(v, u);
          G[v].insert(u);
        };
      }
    }
  }
  vec<u_set<V>> groups;
  u_map<V, ll> group_map;
  {
    u_set<V> visited;
    for (auto const &v : vs) {
      if (visited.find(v) != visited.end())
        continue;
      ll n = groups.size();
      u_set<V> group;
      bfs(G, v, [&](auto const &oP, auto const &c) {
        visited.insert(c);
        group.insert(c);
        group_map[c] = n;
      });
      groups.push_back(group);
    }
  }
  for (auto &&i : range(H)) {
    for (auto &&j : range(W)) {
      auto v = V{i, j};
      if (S[i][j] == '#')
        continue;
      vs.insert(v);
      for (auto &&k : range(i - 5, i + 6)) {
        for (auto &&l : range(j - 5, j + 6)) {
          if ((!range(H).has(k)) || (!range(W).has(l)) || S[k][l] == '#')
            continue;
          auto u = V{k, l};
          dump(v, u);
          G[v].insert(u);
        }
      }
    }
  }
  dump(G);
  dump(groups);
  dump(group_map);

  auto dist_fun = [&](auto const &u, auto const &v) -> ll {
    if (group_map[u] == group_map[v]) {
      return 0;
    }
    if (max(abs(get<0>(u) - get<0>(v)), abs(get<1>(u) - get<1>(v))) <= 2) {
      return 1;
    }
    return 1e7;
  };
  auto ds = dijkstra(V{Ch, Cw}, G, dist_fun, vs);
  ll ans = ds[V{Dh, Dw}];
  dump(ds);
  print(ans >= 1e7 ? -1LL : ans);
}
