#include <iostream>
#include <algorithm>
using namespace std;
typedef long long int ll;
long long int n, A[4001], ans = 0;

ll solve(int s, int e, bool JOI){
	if(s == e){
		if(JOI){
			return A[s];
		} else{
			return 0;
		}
	}

	if(JOI){
		return max(solve(s + 1, e, 0) + A[s], solve(s,  e - 1, 0) + A[e]);
	} else{
