unordered_map<ll,ll> mp;

void factorize(ll p){

    while(p%2==0){
        mp[2]++;
        p/=2;
    }
    for(int i=3;i*i<=p;i++){
        while(p%i==0){
            mp[i]++;
            p/=i;
        }
    }
    if(p>2)
        mp[p]++;
}

int main(){
    ll n,p;
    cin>>n>>p;
    ll ans=1;
    factorize(p);
    for(auto x: mp){
