#include <iostream>

#include <vector>
#include <string>
#include <cstring>
#include <cassert>

using namespace std;

#define SZ(a) int((a).size())

typedef pair<int,int> II;
typedef vector<int> VI;

vector<int> z_function(const string& str, int start = 0) {
   int N = int(str.length()) - start;
   vector<int> z(N);
   for (int i = 1, L = 0, R = 0; i < N; ++i) {
      int k = 0;
      if (i <= R)
         k = min(R-i+1, z[i-L]);
      while (i+k < N && str[start + k] == str[start + i+k]) ++k;
      if (i+k-1 > R)
         L = i, R = i+k-1;
      z[i] = k;
   }
   z[0] = N;
   return z;
}

string W;
VI Z[4004];
bool is_periodic(int start, int len, int period_len) {
   return period_len < SZ(Z[start]) &&
          Z[start][period_len] >= len - period_len;
}

bool good(int start, int len) {
   if (len == 1) return true;
   for (int d = 1; d*d <= len; ++d) {
      if ((len % d) != 0) continue;
      int period_len = len / d;
      if (d > 1 && is_periodic(start, len, period_len))
         return false;
      period_len = d;
      if (is_periodic(start, len, period_len))
         return false;
   }
   return true;
}

const int MOD = 1000000007;
const int INF = 1000000000;
bool cache[4004];
II memo[4004];
II go(int start) {
   if (start >= SZ(W))
      return II(0, 1);
   if (start == SZ(W)-1)
      return II(1, 1);
   if (!cache[start]) {
      II& res = memo[start];
      res = II(INF, 0);
      for (int len = 1; start + len <= SZ(W); ++len) {
         if (!good(start, len)) continue;
         II cur = go(start + len);
      // if (start == 0)
      //    cerr << "len = " << len << ' ' << cur.first << ' ' << cur.second << endl;
         if (res.first > cur.first + 1)
            res = II(cur.first+1, cur.second);
         else if (res.first == cur.first + 1)
            res.second = (res.second + cur.second) % MOD;
      }
      cache[start] = 1;
   }
   return memo[start];
}

int main(int argc, char* argv[]) {
   ios_base::sync_with_stdio(false); 
   cin.tie(NULL);

   cin >> W;
   assert( SZ(W) < 4004 );

   for (int start = 0; start < SZ(W); ++start)
      Z[start] = z_function(W, start);

   II res = go(0);
   cout << res.first << endl;
   cout << res.second << endl;

   return 0;
}
