const int dy[] = {1, -1, 0, 0, 1, -1, 1, -1, 0, 0, 2, -2};

struct Solver {
  Solver(int n) : n(n) {}
  void setField(int F[10][10]){
    int s = 0;
    rep(i, 10){
      rep(j, 10){
        field[i][j] = F[i][j];
        s += F[i][j];
      }
    }
    sum = s;
  }
  bool isValid(int s, int m, int l){
