  bool solve(int s, int m, int l){
    if (s + m + l == 0) return true;
    if (s != 0){
      reps(y, 1, 9){
        reps(x, 1, 9){
          bool ok = push(x, y, 4);
          if (ok) {
            bool complete = solve(s - 1, m, l);
            if (complete){
              printf("%d %d 1\n", x, y);
              return true;
            }
          }
          pop(x, y, 4);
        }
      }
      return false;
    }
    if (m != 0){
      reps(y, 1, 9){
        reps(x, 1, 9){
          bool ok = push(x, y, 8);
          if (ok) {
            bool complete = solve(s, m - 1, l);
            if (complete){
              printf("%d %d 2\n", x, y);
              return true;
            }
          }
          pop(x, y, 8);
        }
      }
      return false;
    }
    if (l != 0){
      reps(y, 2, 8){
        reps(x, 2, 8){
          bool ok = push(x, y, 12);
          if (ok) {
            bool complete = solve(s, m, l - 1);
            if (complete){
              printf("%d %d 3\n", x, y);
              return true;
            }
          }
          pop(x, y, 12);
        }
      }
      return false;
    }
    return false;
  }
  bool push(int x, int y, int len){
    bool ok = true;
    rep(i, len){
      int nx, ny;
      nx = x + dx[i];
      ny = y + dy[i];
      --field[ny][nx];
      if (field[ny][nx] < 0) ok = false;
    }
    return ok;
  }
  void pop(int x, int y, int len){
    rep(i, len){
      int nx, ny;
      nx = x + dx[i];
      ny = y + dy[i];
      ++field[ny][nx];
    }
  }
  int field[10][10];
  int sum;
  int n;
};

