struct point
{
	int key;
	point *l, *r;
};

int N;
point *nil;
void init()
{
	nil = (point*)malloc(sizeof(point));
	nil->l = nil;
	nil->r = nil;
}

void insert(int k)
{
	point *p;
	p = (point*)malloc(sizeof(point));;
	p->key = k;
	nil->r->l = p;
	p->r = nil->r;
	nil->r = p;
	p->l = nil;
}

point* find(int k)
{
	point *p = nil;
	while (p->key != k)
	{
		p = p->r;
	}
	return p;
}

void ddelete(point *p)
{
	p->r->l = p->l;
	p->l->r = p->r;
	free(p);
}

void deletefirst()
{
	ddelete(nil->r);
}

void deletelast()
{
	ddelete(nil->l);
}

int main()
{
	cin >> N;
	string s;
	int k;
	init();
	for (int i = 0; i < N; i++)
	{
		cin >> s ;
		if (s[0] == 'i')
