#include <bits/stdc++.h>
using namespace std;

typedef long long int lli;

char path[1001][1001];
lli dp[1001][1001];

lli grid(int h, int w, int hmax, int wmax)
{
	if(path[h][w] == '#' || h == hmax || w == wmax) return 0;
	if(dp[h][w]>0) return dp[h][w]%1000000007;
	if(h == hmax - 1 && w == wmax - 1) return 1;

	dp[h][w] = grid(h,w+1,hmax,wmax) + grid(h+1,w,hmax,wmax);
	return dp[h][w]%1000000007;
}

int main()
{
	int h, w;
	cin >> h >> w;

	for(int i = 0; i < h; i++)
		for(int j = 0; j < w; j++)
			cin >> path[i][j];

	lli m = grid(0, 0, h, w);

	cout << m%1000000007 << endl;
	return 0;
}
