ll gcd(ll a, ll b){
  if(b<a) swap(a, b);
  ll r = a % b;
  if(r==0) return b;
  while(r!=0){
    r = a % b;
    a = b;
    b = r;
  }
  return a;
}
int main(int argc, char const *argv[]) {
  ll A, B;
  std::cin >> A >> B;
  ll tmp = gcd(A, B);
  vector<ll> ans;
  ll ra = tmp;
  for(int i=2;i*i<=tmp;i++){
    if(tmp%i==0){
      ans.push_back(i);
      while(tmp%i==0) tmp/=i;
    }
  }
  if(tmp>1) ans.push_back(tmp);
  std::cout << ans.size()+1 << '\n';
  return 0;
}
