int group[1000000]; vector<int> f[1000000];
void unite(int x, int y) {
	if (group[x] == group[y]) return;
	x = group[x], y = group[y];
	if (f[y].size() > f[x].size()) swap(x, y);
	for (int j = f[y].size() - 1; j >= 0; j--) {
		group[f[y][j]] = group[x];
		f[x].push_back(f[y][j]);
		f[y].pop_back();
	}
}
