struct data
{
    lli a,b;
    data(lli aa, lli bb)
    {
        a = aa;
        b = bb;
    }
};

bool operator<(data A,  data B)
{
    return (A.a*A.b < B.a*B.b);
}

int main()
{
    ///freopen("output.txt","w",stdout);
   // freopen("input.txt","r",stdin);
    FastIO;
    lli n,k;

    while(cin>>n)
    {

        cin>>k;

        lli a[n],b[n];
        priority_queue<data>pq;

        for(int i=0; i<n; i++)
            cin>>a[i];
        for(int j=0; j<n; j++)
        {
            cin>>b[j];

        }

        sort(b,b+n);
        sort(a,a+n);

        for(int i=0,j=n-1 ; i<n; i++, j--)
        {
            pq.push(data(a[i],b[j]));
        }

        if(n == 1)
        {
            a[0] -= k;
            a[0] = max(0LL,a[0]);
            cout<<(a[0]*b[0]);
            return 0;
        }

        while(pq.size()>1)
        {
            data A = pq.top();
            pq.pop();
            data B = pq.top();

            lli x = (A.a*A.b - B.a*B.b)/A.b;

            x = max(x, 1LL);

            if(x>=k)
            {
                A.a -= k;
                k = 0;
                pq.push(A);
                break;
            }
            k -= x;
            A.a -= x;
            if(A.a>0) pq.push(A);
        }


        data t = pq.top();
        t.a -= k;
        t.a = max(0LL , t.a);
        cout<<(t.a*t.b);
      break;
    }


    return 0;
}

