void primenum_factorization(ll n){//primesで素因数分解の結果をprimenumに格納
  rep(i,primenum.size()){
    primenum[i]=0;
  }
    ll pren = n;
  for(int i=0;primes[i]<=n && pren!=1;i++){
   // cout<<primes[i]<<" ";
    while(1){
      if(pren%primes[i]==0){
        primenum[i]++;
        pren/=primes[i];
      }else{
        break;
      }
    }
  }
  return;
}

map< int64_t, int > prime_factor(int64_t n) {
  map< int64_t, int > ret;
  for(int64_t i = 0; primes[i] <= n; i++) {
    while(n % primes[i] == 0) {
      ret[primes[i] ]++;
      n /= primes[i] ;
    }
  }
  if(n != 1) ret[n] = 1;
  return ret;
}
int main(void){
  ll n;
  cin>>n;
  vl a(n);
  rep(i,n){
    cin>>a[i];
  }
  searchprime(1001000);
  //ll Pnum = searchprime(1000000);
  //cout<<Pnum<<" "<<primes[Pnum-1]<<endl;
  map <int64_t,int> maxnums;
  vector<map <int64_t,int>> an(n);
  rep(i,n){
    map<int64_t,int> tmp = prime_factor(a[i]);
    an[i]=tmp;
    for(auto i:tmp){
      if(maxnums.find((int64_t)i.first)!=maxnums.end()){
        maxnums[(int64_t)i.first]=max(maxnums[(int64_t)i.first],i.second);
      }else{
        maxnums.insert({i.first,i.second});
      }
    }
  }
  //cout<<"ttt"<<endl;
  ll ans=0;
  rep(i,n){

    ll tmp=1;
    for(auto j:maxnums){
      if(an[i].find(j.first)!=an[i].end()){
        tmp*=digitpower(j.first,(j.second)-an[i][j.first]);
      }else{
        tmp*=digitpower(j.first,j.second);
      }
      tmp%=d9_7;
    }
    ans+=tmp;
    ans%=d9_7;
  }
  cout<<ans<<endl;
  return 0;
}
