#include <bits/stdc++.h>

using namespace std;

typedef pair<int, int> pii;
typedef pair<long long, long long> pll;
typedef long long ll;
typedef unsigned int ui;
typedef unsigned long long ull;
typedef long double ld;

const int inf = 1e9;
const ll inf64 = 1e18;

const int N = 55;
const int LOG = 18;
const int X = 1 << LOG;

int n, k;
int a[N], b[N], sz;
int S, T;
ll dp[N][X];
ll binom[N][N];

void precalc() {
    for (int i = 0; i < N; i++) {
        binom[i][0] = binom[i][i] = 1;
        for (int j = 1; j < i; j++) {
            binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
        }
    }
}

bool le(int l, int r) {
    return (l & r) == l;
}

int main() {

    precalc();

#ifdef DEBUG
    freopen("input.txt", "r", stdin);
#endif

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n >> k >> S >> T;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    ll res = 0;
    for (int I = 0; I <= T; I++) {
        if (!le(S, I))
            continue;
        for (int J = 0; J <= T; J++) {
            if (!le(I, J) || !le(J, T))
                continue;
            int tmp = __builtin_popcount(I ^ S) + __builtin_popcount(J ^ T);
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (le(I, a[i]) && le(a[i], J))
                    cnt++;
            }
            int lc = I == 0 ? 0 : 1;
            int rc = min(cnt, k);
            ll tot = 0;
            for (int c = lc; c <= rc; c++) {
                tot += binom[cnt][c];
            }
            if (tmp % 2 == 0)
                res += tot;
            else
                res -= tot;
        }
    }

    cout << res << "\n";

    return 0;
}
