using namespace std;

set<string> comstr(string x, string y, int m,int  n, int dp[][3001]){
	if (m == 0|| n== 0)
	{
		set<string> a;
		a.insert("");
		return a;
	}
	if (x[m-1] == y[n-1])
	{
		set<string> s, g;
		g= comstr(x,y,m-1, n-1, dp);
		for(string str : g){
			s.insert(str+x[m-1]);
		}
		return s;
	}
	if(x[m-1] != y[n-1]){
		set<string> s, k;
		if (dp[m-1][n] >= dp[m][n-1])
		{
			s=comstr(x,y, m-1, n, dp);
		}
		if(dp[m][n-1] >= dp[m-1][n]){
			k=comstr(x, y, m, n-1, dp);
		}
		for(string str : s){
			k.insert(str);
		}
		return k;

	}

}

int main(int argc, char const *argv[])
{
	// vector<char> final;
	string a, b, final = "";
	cin>>a>>b;
	 int n = a.length(), m = b.length();
	 memset(dp, 0, sizeof(dp));
	// int dp[n+1][m+1];

	for (int i = 0; i <= n; ++i)
	{
		for (int j = 0; j <= m; ++j)
		{
			if(i == 0 || j == 0){
				dp[i][j] = 0;
			}
			else if(a[i-1] == b[j-1]){
				dp[i][j] = 1+dp[i-1][j-1];
			}
			else if (a[i-1] != b[j-1]){
				dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
			}
		}
	}

	set<string> commonstrings = comstr(a, b, n, m, dp);
	if(commonstrings.size() > 0){
		set<string>::iterator it = commonstrings.begin();
		cout<<*it;
	}
	else{
		cout<<"";
	}
	return 0;
}


