ll pow(ll a, ll n, ll m){

    ll res = 1;

    while(n){

        if(n % 2) res = res * a % m;
        a = a * a % m;
        n /= 2;

    }

    return res;
}


ll Fact[1000005];
ll invFact[1000005];

void cal(){

    Fact[0] = 1;
    Fact[1] = 1;

    for(ll i = 2; i <= 1000000; i++){

        Fact[i] = i * Fact[i - 1] % mod;
    }

    invFact[0] = 1;


    for(ll i = 1; i <= 1000000; i++){

        invFact[i] = pow(Fact[i], mod - 2, mod);
    }
}

ll comb(ll n, ll r){

    ll res = 1;

    res = Fact[n];
    res = res * invFact[n - r] % mod;
    res = res * invFact[r] % mod;

    return res;
}

void addse(ll & a, ll b) {
        a %= mod;
        b %= mod;
        a += b;
        a %= mod;
}

void subse(ll & a, ll b) {
        a %= mod;
        b %= mod;
        a -= b;
        if(a < 0) {
                a += mod;
        }

        a %= mod;
}

void mulse(ll & a, ll b) {
        a %= mod;
        b %= mod;
        a *= b;
        a %= mod;
}


void solve() {

            ll N, M;
            cin >> N >> M;


            ll tot = 0;

            for(ll i = 0; i <= N; i++) {
                    ll now = comb(N, i);
                    mulse(now, comb(M, i));
                    mulse(now, Fact[i]);
                    mulse(now, comb(M - i, N - i));
                    mulse(now, Fact[N - i]);
                    mulse(now, comb(M - i, N - i));
                    mulse(now, Fact[N - i]);
                    trace(i, now);
                    if(i % 2) {
                            subse(tot, now);
                    } else {
                            addse(tot, now);
                    }
            }


            cout << tot << endl;
}


int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);



    cal();

    int t = 1;
   // cin >> t;
    for(int i = 1; i <= t; i++) {
            solve();
    }


    return 0;

}
