void dfs(vector<unordered_set<int>> &friendship,
  vector<unordered_set<int>> &blockship, int i, int host, vector<int> &marked,
  int &friends) {
  if (marked[i] == 1) {
    return;
  } else {
    marked[i] = 1;
    if (i != host && friendship[host].find(i) == friendship[host].end() &&
        blockship[host].find(i) == blockship[host].end()) {
      friends++;
    }
    for (int next : friendship[i]) {
      dfs(friendship, blockship, next, host, marked, friends);
    }
  }
}


