ll dfs(ll remain, vector<ll> A, vector<ll> B, ll a, ll b)
{
    if (A.size() == a || B.size() == 0)
        return 0;
    if (A.size() <= a)
        return dfs(remain - B[b], A, B, a, b + 1) + 1;
    if (B.size() <= b)
        return dfs(remain - A[a], A, B, a + 1, b) + 1;
    ll a_top = A[a], b_top = B[b];
    if (remain < a_top && remain < b_top)
        return 0;
    ll a_result = 0, b_result = 0;
    if (a_top <= remain)
        a_result = dfs(remain - a_top, A, B, a + 1, b) + 1;
    if (b_top <= remain)
        b_result = dfs(remain - b_top, A, B, a, b + 1) + 1;
    return a_result > b_result ? a_result : b_result;
}

void func(long long N, long long M, long long K, std::vector<long long> A, std::vector<long long> B)
{
    ll result = dfs(K, A, B, 0, 0);
    cout << result << endl;
}

