/*
* @title Mo's Algorithm
* @docs kyopro/docs/mo.md
*/

template<typename ADD, typename DEL, typename REM, typename T = int>
struct mo {
	int sqn, q, l, r, p;
	T ret;
	vector<tuple<int, int, int>> query;
	vector<T> ans;

	mo(const int& n, const int& q) : sqn((int)sqrt(n)), q(q), l(0), r(0), p(0), ret(T(0)), query(q), ans(q) {}

	inline void insert(const int& l, const int& r) {
		query[p] = { l, r, p++ };
	}

	inline void read(const bool& oneindexed) {
		for (auto& [left, right, idx] : query) {
			scanf("%d%d", &left, &right);
			if (oneindexed)--left;
			idx = p++;
		}
	}

	void build() {
		sort(all(query), [&](const tuple<int, int, int>& a, const tuple<int, int, int>& b) {
			if (get<0>(a) / sqn != get<0>(b) / sqn)return get<0>(a) < get<0>(b);
			return ((get<0>(a) / sqn) & 1) ? get<2>(a) > get<2>(b) : get<2>(a) < get<2>(b);
			});
	}

	inline void run(const ADD& add, const DEL& del, const REM& rem) {
		for (const auto& [ql, qr, qo] : query) {
			while (l > ql)add(--l, ret);
			while (r < qr)add(r++, ret);
			while (l < ql)del(l++, ret);
			while (r > qr)del(--r, ret);
			rem(qo, ans, ret);
		}
	}

	T operator [](const int& idx) {
		return ans[idx];
	}

	void allrun(const bool& oneindexed, const ADD& add, const DEL& del, const REM& rem) {
		read(oneindexed);
		build();
		run(add, del, rem);
	}

};

int main() {

	int n, q;
	scanf("%d%d", &n, &q);
	vector<int> a(n);
	rep(i, n) scanf("%d", &a[i]);
	vector<int> memo(n + 1);
	auto add = [&](const int& idx, int& ret) {if (memo[a[idx]]++ == 0)++ret; };
	auto del = [&](const int& idx, int& ret) {if (--memo[a[idx]] == 0)--ret; };
	auto rem = [](const int& idx, vector<int>& ans, const int& ret) {ans[idx] = ret; };
	mo<decltype(add), decltype(del), decltype(rem), int> m(n, q);
	m.allrun(true, add, del, rem);
	rep(i, q)printf("%d\n", m[i]);

	Please AC;
}
