using ll = long long;

int f(int h, int w, int x, int y, vector<string> v) {
  int res = 0;
  seq2(i, x, w) {
    if (v[y][i] == '.') {
      res++;
    } else {
      break;
    }
  }
  rev2(i, x, 0) {
    if (v[y][i] == '.') {
      res++;
    } else {
      break;
    }
  }
  seq2(i, y, h) {
    if (v[i][x] == '.') {
      res++;
    } else {
      break;
    }
  }
  rev2(i, y, 0) {
    if (v[i][x] == '.') {
      res++;
    } else {
      break;
    }
  }
  return res-3;
}

ll solve(int h, int w, vector<string> v) {
  int a=0;
  int ai=0;
  int b=0;
  int bi=0;
  seq(y,h){
    int k=0;
    seq(x,w){
      if (v[y][x] != '#')
        k++;
    }
    if(a < k){
      a=k;
      ai=y;
    }
  }
  seq(x,w){
    int k=0;
    seq(y,h){
      if (v[y][x] != '#')
        k++;
    }
    if(b < k){
      b=k;
      bi=x;
    }
  }
  int m=0;
  seq(i,h){
    m=max(m,f(h,w,bi,i,v));
  }
  seq(i,w){
    m=max(m,f(h,w,i,ai,v));
  }

  return m;
}

