// 約数の列挙
template<typename T>
set<T> div_count(T x) {
  set<T> st;
  for (int i = 1; i * i <= x; ++i) {
    if (x % i == 0) {
      st.insert(i);
      st.insert(x/i);
    }
  }
  return st;
}

int main() {
  int n;
  cin >> n;
  vector<ll> a(n);

  rep(i,n) {
    cin >> a[i];
  }
  set<ll> st;
  for (auto itr : div_count(a[0])) {
    st.insert(itr);
  }

  for (int i = 1; i < n; ++i) {
    set<ll> tmp = div_count(a[i]);
    for (auto itr : st) {
      if (tmp.find(itr) == tmp.end()) {
        st.erase(itr);
      }
    }
  }
  ll ans = -1;
  for (auto itr : st) {
    ans = max(ans, itr);
  }

  cout << ans << endl;
}
