void update(ll v,ll tl,ll tr,ll ql,ll qr,ll val){

    if(ql>qr){
        return ;
    }
    if(ql == tl and qr==tr){
        seg[v]+=val;
        lazy[v]+=val;
    }
    else{
        push(v);
        update(child,tl,tm,ql,min(qr,tm),val);
        update(child+1,tm+1,tr,max(ql,tm+1),qr,val);
        seg[v]=seg[child]+seg[child+1];
    }
}
ll rquery(ll v,ll tl,ll tr,ll ql,ll qr){
    if(ql>qr){
        return 0;
    }
    if(ql<=tl and tr<=qr){
        return seg[v];
    }
    push(v);
    return rquery(child,tl,tm,ql,min(qr,tm))+rquery(child+1,tm+1,tr,max(ql,tm+1),qr);
}
