int dfsUtil(vector<vector<char>>&v ,pair<int, int> src, pair<int, int> dest, vector<vector<bool>> visited)
{
    if (src == dest)
        return 0;
    int x = src.first, y = src.second;
    visited[x][y] = true;
    unsigned int a = 10000000, b = 10000000, c = 10000000, d = 10000000;
    if(x != 0 && !visited[x-1][y] && v[x-1][y] == '.')
        a = dfsUtil(v, {x-1,y}, dest, visited);

    if(x != v.size()-1 && !visited[x+1][y] && v[x+1][y] == '.')
        b = dfsUtil(v, {x+1,y}, dest, visited);

    if(y != 0 && !visited[x][y-1] && v[x][y-1] == '.')
        c =  dfsUtil(v, {x,y-1}, dest, visited);

    if(y != v[0].size()-1 && !visited[x][y+1] && v[x][y+1] == '.')
        d = dfsUtil(v, {x,y+1}, dest, visited);

    a =  min(min(a,b), min(c,d));
    if (a == 10000000)
    {
        for(int i = x - 2; i <= x + 2; i++)
        {
            for(int j = y - 2; j <= y+2; j++)
            {
                if(i < 0 || i >= v.size()  || j < 0 || j >= v[0].size())
                    continue;
                else if (v[i][j] == '#')
                    continue;
                else if (v[i][j] == '.' && !visited[i][j])
                    a = min(a, (unsigned int)(dfsUtil(v, {i,j}, dest, visited) + 1));
            }
        }
    }
    return a;
}

int dfs(vector<vector<char>> &v, pair<int , int> src, pair<int , int> dest, int h, int w)
{
    vector<vector<bool>> visited;
    for(int i = 0; i < h; i++)
    {
        vector<bool> temp;
        for(int j = 0; j < w; j++)
            temp.push_back(false);
        visited.push_back(temp);
    }
    int ans = dfsUtil(v, src, dest, visited);
    return ans;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int h, w;
