int solve(int n, int w, int* ws, int* vs)
{
	if(n == 0) return 0;
	if(w <= 0) return 0;

	int ret = solve(n - 1, w, ws, vs);
	if(w >= ws[n - 1])
	{
		ret = max(ret, solve(n - 1, w - ws[n - 1], ws, vs) + vs[n - 1]);
	}

	return ret;
}

