		}
	}
	bool flag = true;
	for (int i = 0; i < n; i++) {
		p[i] = a[0][i] / 3;
		if (a[1][i] < p[i] * 3 || a[1][i] > p[i] * 3 + 2 || a[2][i] < p[i] * 3 || a[2][i] > p[i] * 3 + 2) flag = false;
