using namespace std;

typedef long long ll;
typedef pair<int, int> intint;

int binarysearch(vector<ll> &v, ll x){
    ll ok = 0;
    ll ng = (ll)v.size();
    while(abs(ok - ng) != 1){
        ll mid = (ok + ng) / 2;
        if(v[mid] <= x) ok = mid;
        else ng = mid;
    }
    return ok;
}

int sign(ll x){
    if(x < 0){
        return -1;
    }
    if(x > 0){
        return 1;
    }
    return 0;
}

ll calc(vector<ll> &s, vector<ll> &t, ll x){
    vector<ll> a, b;
    ll ans = MAXINF;
    for (int i = 0; i < 2; i++) {
        if(i == 0){
            a = s; 
            b = t;
        }else{
            a = t;
            b = s; 
        }

        for (int j = 0; j < 2; j++) {
            ll apos = binarysearch(a, x) + j;
            ll ax = a[apos];
            for (int k = 0; k < 2; k++) {
                ll bpos = binarysearch(b, ax) + k;
                ll bx = b[bpos];
                // if(min > abs(ax- x) + abs(bx - ax)){
                //     min = abs(ax - x) + abs(bx - ax);
                // }

                ll delta_s = ax - x;
                ll delta_t = bx - x;
                if(sign(delta_s) * sign(delta_t) <= 0){
                    ans = min(ans, 2 * abs(delta_s - delta_t) - max(abs(delta_s), abs(delta_t)));
                }else{
                    ans = min(ans, max(abs(delta_s), abs(delta_t)));
                }
            }
        }
    }
    return ans;
}

