void recur(int i,int j,vector<vector<char> > &rect,vector<vector<int> > &dp){
	try{
		if (rect.at(i - 1).at(j) != 'X' and dp[i-1][j]>dp[i][j]+1){
			dp[i - 1][j] = dp[i][j]+1;
			recur(i-1,j,rect,dp);
		}
	}
	catch (...){}
	try{
		if (rect.at(i + 1).at(j) != 'X' and dp[i+1][j]>dp[i][j]+1){
			dp[i + 1][j] = dp[i][j]+1;
			recur(i+1,j,rect,dp);
		}
	}
	catch (...){}
	try{
		if (rect.at(i).at(j-1) != 'X' and dp[i][j-1]>dp[i][j]+1){
			dp[i][j-1] = dp[i][j]+1;
			recur(i,j-1,rect,dp);
		}
	}
	catch (...){}
	try{
		if (rect.at(i).at(j+1) != 'X' and dp[i][j+1]>dp[i][j]+1){
			dp[i][j+1] = dp[i][j]+1;
			recur(i,j+1,rect,dp);
		}
	}
	catch (...){}
	return;
}

int trvrs(char S,char G,vector<vector<char> > R){
	int count;
	//cout << S << G << endl;
	vector<vector<int> > dp(R.size(), vector<int>(R.front().size()));
	for (int i = 0; i<R.size(); i++){
		for (int j = 0; j<R.front().size(); j++){
			dp[i][j]=1000000; 
		}
	}
	for (int i = 0; i<R.size(); i++){
		for (int j = 0; j<R.front().size(); j++){
			if(R[i][j] == S) {
				dp[i][j]=0;
				recur(i,j,R,dp);
			}; 
		}
	}
	for (int i = 0; i<R.size(); i++){
		for (int j = 0; j<R.front().size(); j++){
			//cout << dp[i][j];
			if(R[i][j] == G) count=dp[i][j]; 
		}
		//cout << endl;
	}
	return count;
}

