lin calc()
{
    lin ss[4];
    rep(i, 4)
    {
        ss[i] = s[d[i + 1]] - s[d[i]];
    }

    lin mx = max(ss[0], max(ss[1], max(ss[2], ss[3])));
    lin mn = min(ss[0], min(ss[1], min(ss[2], ss[3])));
    return mx - mn;
}

lin solve(int b)
{
    if(b == 3)
        return calc();

    lin res = -1;
    loop(i, d[b] + 1, n)
    {
        d[b+1] = i;
        lin t = solve(b+1);
        if(t < 0)
            continue;

        if(res < 0)
        {
            res = t;
            continue;
        }

        if(res >= t)
        {
            res = t;
            continue;
        }

        break;
    }

    return res;
}

