void dfs(vector<vector<bool>> &g, vector<int> &dp, int node, vector<bool> &vis) {
    vis[node] = true;
    for(int i=0;i<g.size();i++){
        if(g[node][i]) {
            if(!vis[i]){
                dfs(g, dp, i, vis);
            }
            dp[node] = max(dp[node], 1 + dp[i]);
            mx = max(dp[node], mx);
        }
    }
}

