int N;
int a[200000];

bool f(int n){
  if(n == 1){
    rep(i, 1, N){
      if(a[i] <= a[i - 1]) return false;
    }
    return true;
  }
  map<int, int> mp;
  mp[a[0]] = 0;
  rep(i, 1, N){
    if(a[i] <= a[i - 1]){
      int pos = a[i];
      {
        auto it = mp.find(pos);
        if(it == mp.end()){
          mp[pos] = 0;
        }else{
          it++;
          if(it != mp.end()) mp.erase(it, mp.end());
        }
      }
      {
        while(mp[pos] == n - 1){
          mp[pos] = 0;
          pos--;
        }
        if(pos == 0){
          return false;
        }
        mp[pos]++;
      }
    }
  }
  return true;
}

int main(){
  cin >> N;
  rep(i, N) cin >> a[i];

  int hi = N;
  int lo = 0;
  while(hi - lo > 1){
    int mi = (hi + lo) / 2;
    if(f(mi)){
      hi = mi;
    }else{
      lo = mi;
    }
  }
  cout << hi << endl;
  return 0;
}
