using namespace std;

int memo[100001];
int fans = 0;

int solve(unordered_map<int,vector<int>> nei, int n){
	if(nei[n].size() == 0)
		return 0;
	if(memo[n] != -1)
		return memo[n];
	int ans = 0;
	for(int i=0;i<nei[n].size();i++)
		if(memo[nei[n][i]] != -1)
			ans = max(ans,1+memo[nei[n][i]]);
		else
			ans = max(ans,1+solve(nei,nei[n][i]));
	fans = max(fans,ans);
	return memo[n] = ans;
}

