    if( n<0 || cap<=0){
        return 0;
    }
    ll ans=0,ans1=0;
    if(wt[n] <= cap){
        ans = val[n] + knap(wt,val,n-1,cap-wt[n]);
    }
     ans1= knap(wt,val,n-1,cap); 
     return max(ans,ans1);
}

