#include <iostream>
#include <cstring>
#include <cstdlib>
using namespace std;

struct node {
  int key;
  node *next;
  node *back;
};

node *NIL;
node *front;

void print(){
  node *x;
  x = front ->next;
  while(x != NIL){
    if(x->next != NIL) cout << x -> key << " ";
    else cout << x -> key;
    x = x-> next;
  }
  cout << "\n";
}


void insert(int k){
  node *z;
  z = (node *)malloc(sizeof(node));
  z->next = NIL;
  z->back = NIL;
  z-> key = k;

  z->next = front->next;
  front->next = z;
  z->back = front;
  z->next->back = z;
  //print();
}

node* find(int k){
  node *x;
  x = front;
  while(x != NIL){
    if(x -> key == k) return x;
    else x = x -> next;
  }
  return NIL;
}

void del(int k){
  node *x;
  node *f;
  node *b;
  x = (node *)malloc(sizeof(node));
  b = (node *)malloc(sizeof(node));
  f = (node *)malloc(sizeof(node));


  x = find(k);
  b = x->back;
  f = x->next;

  //cout << "x = " << x->key << endl;
  //cout << "b = " << b->key << endl;
  //cout << "f = " << f->key << endl;


  //exit(0);
  if(x != NIL) {
    b-> next = x->next;
    f-> back = x->back;
  }
  //cout << "b -> next = " << b->next->key << endl;
  //cout << "f -> back = " << f->back->key << endl;
  free(x);
  //print();
}

void deleteFirst(){
  node *x;
  x = front -> next;
  front -> next = x -> next;
  x->next -> back = front;
  //print();
}

void deleteLast(){

  node *x;
  x = front -> next;
  if(x == NIL) return;
  while(x-> next != NIL) x = x-> next;

  x -> back -> next = NIL;
  free(x);
  //print();
}


void init(){
  NIL = (node*)malloc(sizeof(node));
  front = (node*)malloc(sizeof(node));
  front->next = NIL;
  front->back = NIL;
  NIL -> next = NIL;
}
int main(){

  int n,k;
  string com;
  cin >> n;

  init();
  for(int i = 0;i < n;i++){
    cin >> com;
    if(com == "insert"){
      cin >> k;
      //cout << k << "\n";
      insert(k);
    }
    else if(com == "delete"){
      cin >> k;
      //cout << k << "\n";
      del(k);
    }
    else if(com == "deleteFirst") deleteFirst();
    else if(com == "deleteLast") deleteLast();
  }
  print();

