public:
  KMP(){};
  KMP(string p) : pattern(p), next(vector<int>(p.size()+1)) {
    next[0] = -1;
    for(int i = 0, j = -1; i < pattern.size(); ++i, ++j, next[i] = j)
      while(j >= 0 && pattern[i] != pattern[j]) j = next[j];
  }
  int search(const string &text) {
    int i, j;
    i = j = 0;
    while(i < text.size() && j < pattern.size()) {
      if(text[i] == pattern[j]) {
	++i;
	++j;
      } else if(j == 0) {
	++i;
	j = 0;
      } else {
	j = next[j];
      }
    }
    return i - j;
  }
};

vector<KMP>kmps;

int N;
vector<string>vec;

void init(){
  vec.clear();
}

void input(){
  kmps = vector<KMP>(N);
  for(int i = 0 ; i < N ; i++){
    string str;
    cin >> str;
    vec.push_back(str);
    kmps[i] = KMP(str);
  }
}

