void solve(){
  init();
  input();
  int n = vec.size();

  int id[n];
  for(int i = 0; i < n; ++i) {
    id[i] = i;
  }

  string res = string(100,'z'+1);

  do{
    string tmp = vec[id[0]];

    for(int i = 1 ; i < n ; i++){
      int s = kmps[id[i]].search(tmp);
      if(s + vec[id[i]].size() > tmp.size()){
	tmp = tmp.substr(0,s) + vec[id[i]];
      }
    }

    if(tmp.size() == res.size()){
      if(tmp < res)res = tmp;
    }
    else if(tmp.size() < res.size()){
      res = tmp;
    }

  }while(next_permutation(id,id+n));

  cout << res << endl;
}

