    if (addFlg) {
       res = res + s[index]; 
       if (result < res) {
           result = res;
       }
    } else {
        if (result < res) {
           result = res;
       }
    }
    calcGrade(true, index + 1, res);
    calcGrade(false, index + 1, res);
    return 0;
}

