double cpp[30];
double findsum(int k)
{
    double ans=0;
    for(int i=0;i<k;i++)
    {
        int x=cpp[i];
        int y=cpp[k];
        ans+=(L[x]-L[y])*(L[x]-L[y])+(a[x]-a[y])*(a[x]-a[y])+(b[x]-b[y])*(b[x]-b[y]);
    }
   return ans;
}
void dfs(int k,int cid,double csum)
{
      if(k==m){ if(csum>sum) sum=csum; return;}
      if(cid==n){ return;}
      for(int i=cid;i<n;i++)
      {
              cpp[k]=i;
             double newsum1=findsum(k);
             dfs(k+1,i+1,csum+newsum1);
             dfs(k,i+1,csum);
      }
}
int main()
{
    while(scanf("%d%d",&n,&m)!=EOF)
    {
       for(int i=0;i<n;i++)
        scanf("%lf%lf%lf",&L[i],&a[i],&b[i]);
        sum=0;
        memset(cpp,0,sizeof(cpp));
        dfs(0,0,0);
        printf("%.6lf\n",sum);
    }
