int a[maxn], b[maxn], c[maxn];
int n;

int erfen1(int key)
{
	int left = 0, right = n - 1;
	while (left<=right)
	{
		int mid = (left + right) >> 1;
		if (c[mid] > key) right = mid - 1;
		else if (c[mid] <= key) left = mid + 1;
	}
	return left;
}

int erfen2(int key)
{
    int left=0,right=n-1;
    while(left<=right){
        int mid=(left+right)>>1;
        if(a[mid]>=key) right=mid-1;
        else if(a[mid]<key) left=mid+1;
    }
    return right;
}

int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &a[i]);
