int const d1[] = {0,0,1,-1};
int const d2[] = {1,-1,0,0};

int H, W;
vector<vector<char>> fi(410, vector<char>(410, '1'));
vector<vector<bool>> seen(410, vector<bool>(410, false));


void input() {
    cin >> H >> W;
    repr(i, 1, H+1) repr(j, 1, W+1) cin >> fi[i][j];
}

pair<int, int> bfs(int i, int j) {
    queue<pair<int, int>> qu;
    qu.push(make_pair(i, j));
    seen[i][j] = true;

    ll b = 0, w = 0;
    (fi[i][j]=='.'? w:b) += 1;
    while(!qu.empty()) {
        auto p = qu.front(); qu.pop();
        int x = p.first; int y = p.second;
        rep(k, 4) {
            int nx = x+d1[k], ny = y+d2[k];
            if (fi[nx][ny] != '1' && fi[nx][ny] != fi[x][y] && !seen[nx][ny]) {
                (fi[nx][ny]=='.'? w:b) += 1;
                seen[nx][ny] = true;
                qu.push(make_pair(nx, ny));
            }
        }
    }

    return make_pair(b, w);
}

void solve() {
    ll ans = 0;
    repr(i, 1, H+1) repr(j, 1, W+1) if(!seen[i][j]) {
        auto pa = bfs(i, j);
        ans += pa.first * pa.second;
    }
    cout << ans << endl;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    input();
    solve();

    return 0;
}
