const ll MOD = 1e9+7;

struct bipartiteGraph {
    int L, R;
    vector<vector<int>> adj;
    vector<int> mate;
    bipartiteGraph(int L, int R) : L(L), R(R), adj(L+R), mate(L+R, -1) { }
    void add_edge(int u, int v) {
        adj[u].push_back(v+L);
        adj[v+L].push_back(u);
    }
    int maximum_matching() {
        vector<int> visited(L);
        function<bool(int)> augment = [&](int u) { // DFS
            if (visited[u]) return false;
            visited[u] = true;
            for (int w: adj[u]) {
                int v = mate[w];
                if (v < 0 || augment(v)) {
                    mate[u] = w;
                    mate[w] = u;
                    return true;
                }
            }
            return false;
        };
        int match = 0;
        for (int u = 0; u < L; ++u) {
            fill(visited.begin(),visited.end(), 0);
            if (augment(u)) ++match;
        }
        return match;
    }
    int lPartner(int l){return mate[l]-L;}
    int rPartner(int r){return mate[r+L];}
};

signed main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll N;cin>>N;
  ll x[N],y[N];
  for(ll i=0;i<N;i++){
    cin>>x[i]>>y[i];
  }
  ll ans = INF;
  for(ll k=1;k<N;k++){
    ll p=x[k]-x[0],q=y[k]-y[0];
    bipartiteGraph g(N,N);
    for(ll i=0;i<N;i++){
      for(ll j=0;j<N;j++)if(i!=j){
        if(p==x[j]-x[i]&&q==y[j]-y[i]){
          g.add_edge(i,j);
        }
      }
    }
    ans = min(ans,N-g.maximum_matching());
  }
  cout<<ans<<endl;
  return 0;
}
