string cutmsb(string s) {
  ll n = s.size();
  string res="";
  bool t = false;
  rep(i,n-1){
    if (s[i] != '0' || t)
      res+=s[i];
    if (s[i]!='0')
      t = true;
  }
  if (len(res) == 0)
    res = '0';
  return res;
}

ll f(string s, string e, ll k, ll depth) {
  ll res = 0;
  ll cond;
  if (k == 0) {
    cond = 1;
    res = 1;
  } else if (s == "0" && allnine(e)) {
    cond = 2;
    res = c(len(e), k) * pow(9, k);
  } else if (s == "0" && e == "0") {
    res = (k==0) ? 1 : 0;
  } else {
    cond = 3;
    ll n = len(e);
    for (char c='0'; c<=e[n-1]; c++) {
      if (c=='0') {
        res += f("0", nine(n-1), k, depth+1);
      } else if (c == e[n-1]) {
        res += f("0", cutmsb(e), k-1, depth+1);
      } else {
        res += f("0", nine(n-1), k-1, depth+1);
      }
    }
  }
  dump(s,e,k,res,depth);
  return res;
}

