inline int rng(int x1, int y1, int x2, int y2) {
	return sum[y2][x2] + sum[y1][x1] - sum[y2][x1] - sum[y1][x2];
}
int solve(int x1, int y1, int x2, int y2) {
	if (dp[y1][x1][y2][x2] != -1) return dp[y1][x1][y2][x2];
	int rng_ = rng(x1, y1, x2, y2);
	int ret = 1000000 + rng_;
	for (int i = x1 + 1; i < x2; i++) {
		int petl = rng(x1, y1, i, y2);
		int petr = rng(i, y1, x2, y2);
		if (min(petl, petr) >= o) {
			int resl = solve(x1, y1, i, y2);
			int resr = solve(i, y1, x2, y2);
			int res = (resl + resr) * 1000000 + min(resl % 1000000, resr % 1000000);
			ret = max(ret, res);
		}
	}
	for (int i = y1 + 1; i < y2; i++) {
