#include <bits/stdc++.h>

using namespace std;
typedef pair<int,int> pii;
const int N = 2e5 + 10;

struct Node{
	int ls , rs , tag , v , pos;	
}tr[N * 50];

int tcnt , rt;

int nw(int l,int r){
	tr[++tcnt].tag = 1;
	tr[tcnt].v = 1;
	tr[tcnt].pos = l;
	return tcnt;
}
void down(int x,int l,int r){
	int mid = l + r >> 1;
	if (!tr[x].ls) tr[x].ls = nw(l , mid);
	if (!tr[x].rs) tr[x].rs = nw(mid + 1 , r);

	tr[tr[x].ls].v = tr[tr[x].ls].tag = tr[x].tag;
	tr[tr[x].rs].v = tr[tr[x].rs].tag = tr[x].tag;
	tr[x].tag = 1;
}

void up(int x,int l,int r){
	int mid = l + r >> 1;
	if (!tr[x].ls) tr[x].ls = nw(l , mid);
	if (!tr[x].rs) tr[x].rs = nw(mid + 1 , r);
	tr[x].v = min( tr[tr[x].ls].v , tr[tr[x].rs].v);
	if (tr[x].v == tr[tr[x].ls].v) tr[x].pos = tr[tr[x].ls].pos;
	else tr[x].pos = tr[tr[x].rs].pos;
}

void modify(int &x,int l,int r,int ql,int qr,int v){
	if (ql > qr) return;
//	printf("[%d %d] %d %d\n",ql,qr,l,r);

	if (!x) x = nw(l , r);
	if (ql <= l && r <= qr){
		tr[x].v = v;
		tr[x].tag = v;
		return;
	}
	int mid = l + r >> 1;
	down(x , l , r);
	if (ql <= mid) modify(tr[x].ls , l , mid , ql , qr , v);
	if (mid  < qr) modify(tr[x].rs , mid + 1 , r , ql , qr , v);
	up(x , l , r);
}


pii query(int x,int l,int r,int ql,int qr){
	if (!x) x = nw(l , r);
//	printf("%d %d %d %d [%d %d]\n",ql,qr,l,r,tr[x].v,tr[x].pos);
	if (ql <= l && r <= qr) return make_pair(tr[x].v , tr[x].pos);

	int mid = l + r >> 1;
	down(x , l , r);
	pii res = make_pair(100000000 , 100000000);
	if (ql <= mid) res = min(res , query(tr[x].ls , l , mid , ql , qr));
	if (mid < qr ) res = min(res , query(tr[x].rs , mid + 1 , r , ql , qr));
	return res;
}

