#define N 105
#define M 200005
using namespace std;
const int INF = 1e9;

int n, m, jsq, wid[N], hid[N];
char s[N][N];
int tot = 1, fir[40004], nxt[M], to[M], val[M];
int S, T, dep[40004];

inline void addE(int u, int v, int w1, int w2) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v, val[tot] = w1;
    nxt[++tot] = fir[v], fir[v] = tot, to[tot] = u, val[tot] = w2;
}

// {{{
inline bool bfs() {
    memset(dep, -1, sizeof dep);
    queue<int> q; while (!q.empty()) q.pop();
    q.push(S), dep[S] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = fir[u], v; i; i = nxt[i]) {
            v = to[i];
            if (!val[i] || dep[v] != -1) continue;
            dep[v] = dep[u] + 1, q.push(v);
        }
    }
    return dep[T] != -1;
}

int dfs(int u, int now) {
    if (u == T || !now) return now;
    for (int i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (!val[i] || dep[v] != dep[u] + 1) continue;
        int tmp = dfs(v, min(now, val[i]));
        if (!tmp) continue;
        val[i] -= tmp, val[i ^ 1] += tmp;
        return tmp;
    }
    return 0;
}

inline int dinic() {
    int res = 0, tmp;
    while (bfs()) {
        while ((tmp = dfs(S, INF)))
            res += tmp;
    }
    return res;
}
// }}}

