class ICoins {
public:
	void solve(std::istream& in, std::ostream& out)
	{
	    int n;
	    in >> n;
	    vector<double> p(n);
	    for(int i=0; i<n; i++){
	        in >> p[i];
	    }

	    Fill(dp, 0.0);
	    dp[0][0] = 1.0;
	    for(int i=0; i<n; i++){
            dp[i+1][0] = dp[i][0] * (1.0 - p[i]);
            for(int j=0; j<n; j++){
                dp[i+1][j+1] = dp[i][j+1] * (1.0-p[i]) + dp[i][j] * p[i];
            }
	    }

	    double res = 0.0;
	    for(int i=n/2+1; i<=n; i++){
	        //cout << dp[n][i] << endl;
	        res += dp[n][i];
	    }

	    out << fixed << setprecision(5) << res << endl;
	}
};


int main() {
	ICoins solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}
