#define MOD 1000000007
#define N_MAX 100000
using namespace std;

typedef pair<int, int> P;
typedef pair<long long, long long> LLP;

class Factorial {
    private:
        vector<long long int> fac;
    public:
        Factorial(long long int n_max);
        long long int getFactorial(long long int n);
};

Factorial::Factorial(long long int n_max) {
    fac.push_back(1);
    fac.push_back(1);
    for (long long int i = 2; i <= n_max; i++) {
        fac.push_back(fac[i-1] * i % MOD);
    }
}

long long int Factorial::getFactorial(long long int n) {
    return fac[n];
}

long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}

void factorization(vector<LLP>& llp, long long n) {
    if (n <= 1) return;
    long long n2 = n;
    for (long long i = 2; i * i <= n ; i++) {
        int count = 0;
        while (n2 % i == 0) {
            n2 = n2 / i;
            count ++;
        }
        if (count > 0) {
            LLP temp;
            temp.first = i;
            temp.second = count;
            llp.push_back(temp);
        }
    }
    if (n2 > 1) {
        LLP temp;
        temp.first = n2;
        temp.second = 1;
        llp.push_back(temp);
    }
}

int main() {
    int N, M;
    cin >> N >> M;

    if (M == 1) {
        cout << 1 << endl;
        return 0;
    }

    vector<LLP> pfactors;
    factorization(pfactors, M);

    if (pfactors.size() == 1) {
        cout << N << endl;
        return 0;
    }

    Factorial fact(N_MAX * 2);

    long long int res = 1;

    for (int i = 0; i < pfactors.size(); i++) {
        res = res * fact.getFactorial(N - 1 + pfactors[i].second) % MOD * modinv(fact.getFactorial(N - 1), MOD) % MOD * modinv(fact.getFactorial(pfactors[i].second), MOD) % MOD;
    }

    cout << res << endl;

    return 0;
