int solve(int n, int m) {
    int ans = 1e18;

    FOR(i, 1, n) {

        int x = m / 2;
        int y = (m + 1) / 2;
        ar<int, 3> s = {i * m, (n - i) * x, (n - i) * y};
        umin(ans, max({s[0], s[1], s[2]}) - min({s[0], s[1], s[2]}));
    }

    FOR(i, 1, n) {

        int x = (n - 1) / 2;
        int y = (n - i + 1) / 2;
        ar<int, 3> s = {i * m, m * x, m * y};
        umin(ans, max({s[0], s[1], s[2]}) - min({s[0], s[1], s[2]}));
    }


    return ans;
}

