int return_min(vector<int> dp, vector<int> h, int K, int index) {
    int tmp;
    int min_val = 10001;
    for (int hohaba = 1; hohaba <= K; hohaba++) {
        if (hohaba > index) {
            tmp = 10001;
        } else {
            tmp = dp[index - hohaba] + abs(h[index] - h[index - hohaba]);
        }
        if (min_val > tmp) {
            min_val = tmp;
        }
    }
    return min_val;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long N, K;
    cin >> N >> K;
    vector<long long> h(N);
    for (long long i = 0; i < N; i++) {
        long long tmp;
        cin >> tmp;
        h[i] = tmp;
    }

    vector<long long> dp(N);
    for (long long i = 1; i < N; i++) {
        // dp[i] = return_min(dp, h, K, i);
        long long tmp;
        long long min_val = 10001;
        for (long long hohaba = 1; hohaba <= K; hohaba++) {
            if (hohaba > i) {
                tmp = 10001;
            } else {
                tmp = dp[i - hohaba] + abs(h[i] - h[i - hohaba]);
            }
            if (min_val > tmp) {
                min_val = tmp;
            }
            dp[i] = min_val;
        }
    }
    cout << dp[N - 1] << endl;

    return 0;
}
