using namespace std;

typedef long long ll;
typedef pair < int, int > pii;
const int maxn = 100005;

inline ll read() {
    reg ll s = 0, t = 0; reg char ch = getchar();
    while (!isdigit(ch)) t |= ch == '-', ch = getchar();
    while (isdigit(ch)) s = (s << 1) + (s << 3) + (ch ^ 48), ch = getchar();
    return t ? -s : s;
}

int fa[maxn];
inline int find(reg int x) { return (x == fa[x]) ? x : (fa[x] = find(fa[x])); }

int n;
map < ll, int > Map;
queue < pii > q;
set < int > s[maxn];

inline ll calc(reg int x, reg int y) {
    if (x > y) swap(x, y);
    return 1LL * x * n + y;
}

inline void init(reg int x, reg int y) {
    s[x].insert(y), s[y].insert(x);
    reg ll num = calc(x, y); Map[num]++;
    if (Map[num] == 3) { puts("NO"); exit(0); }
    if (Map[num] == 2) q.push(pii(x, y));
}

inline void solve() {
    for (reg int i = 1; i < n; i++) {
        reg int u, v;
        while (true) {
            if (q.empty()) { puts("NO"); exit(0); }
            u = q.front().first, v = q.front().second, q.pop();
            u = find(u), v = find(v);
            if (u != v) break;
        }
        if (s[u].size() > s[v].size()) swap(u, v);
        fa[u] = v, Map.erase(calc(u, v)), s[v].erase(u);
        for (auto j : s[u]) {
            j = find(j);
            if (j == v) continue;
            Map.erase(calc(u, j)), s[j].erase(u), s[u].erase(j), init(j, v);
        }
    }
    puts("YES");
}

int main() {
    ios::sync_with_stdio(false);
    n = read(); reg int u, v;
    for (reg int i = 1; i <= 2 * n - 2; i++) u = read(), v = read(), init(u, v);
    for (reg int i = 1; i <= n; i++) fa[i] = i;
    solve();
    return 0;
}
