void solve() {
  scanf("%lld %lld", &a, &b);
  if (a > b) swap(a, b);
  sq = sqrt(a * b - 1);
  ans = sq;
  if (a <= sq) {
    ans--;
  }
  mx = (a * b - 1) / (sq + 1);
  if (b <= mx) {
    ans--;
  }
  ans += mx;
  cout << ans << endl;
}

