// get abs
ll my_abs(ll a);
// a^n
ll a_n(ll a, ll n);
// get gcd
ll my_gcd(ll a, ll b);
// a^(-1) % MOD 
ll inv(ll a);

int main() {
    ll x, a = 0;
    cin >> x;

    frep(i, -200, 200) {
        frep(j, -200, 200) {
            if((a_n(i, 5)-a_n(j, 5))==x) {
                cout << i << ' ' << j << endl;
                return 0;
            }
        }
    }

    return 0;
