// KnapSack
int max_value(int N, int W, int*w , int* v)
{
    int dp[N+1][W+1];
    memset(dp,0,sizeof(dp));
    for(int i=1 ;i<=N ; ++i)
    {
        for(int j = 0 ;j<=W ; ++j)
        {
            dp[i][j] = dp[i-1][j];
            if(j >= w[i-1])
                dp[i][j]  = max(dp[i][j] ,
                                dp[i-1][j-w[i-1]] + v[i-1]);
        }
    }
    return dp[N][W];
} 

