#include<cstdio>
#include<cstdlib>
#include<cstring>
#include<vector>
#include<map>
#include<queue>
#include<algorithm>
#include<functional>

using namespace std;

using ll=long long;
using vi=vector<int>;
using vvi=vector<vi>;
using pii=pair<int,int>;
using vll=vector<ll>;
using vvll=vector<vll>;
using vc=vector<char>;
using vpii=vector<pii>;


struct q_t
{
	int r;
	vc s;
	bool operator<(const q_t& rhs) const
	{
		if(r!=rhs.r)
		{
			return r<rhs.r;
		}
		int l=s.size();
		if(l!=rhs.s.size())
		{
			return l<rhs.s.size();
		}
		for(int i=0;i<l;i++)
		{
			if(s[i]!=rhs.s[i])
			{
				return s[i]<rhs.s[i];
			}
		}
		return 0;
	}
};


priority_queue<q_t> que;


void push(q_t q)
{
	que.push(q);
}


int pop(q_t& q)
{
	if(que.empty()) return 0;
	q=que.top();
	que.pop();
	return 1;
}


int vc_cmp(vc&a, vc&b)
{
	if(a.size()<b.size()) return -1;
	if(a.size()>b.size()) return 1;

	for(int i=0;i<a.size();i++)
	{
		if(a[i]<b[i]) return -1;
		if(a[i]>b[i]) return 1;
	}
	return 0;
}


q_t solve(vpii&a, int n)
{
	q_t q;
	q_t ret;

	while(pop(q))
		;

	int a_min=0, a_n_min=a[a_min].second;
	for(int i=1;i<a.size();i++)
	{
		if(a[a_min].second>a[i].second)
		{
			a_min=i;
			a_n_min=a[a_min].second;
		}
	}

	q.r=n;
	q.s.clear();
	push(q);
	while(pop(q))
	{
		if(q.r/a_n_min+q.s.size()<ret.s.size()) break;

		if((q.r%a_n_min)==0)
		{
			q.s.resize(q.s.size()+q.r/a_n_min, a[a_min].first);
			q.r=0;
			sort(q.s.rbegin(), q.s.rend());
			if(vc_cmp(ret.s, q.s)<0) ret=q;
			continue;
		}

		for(auto&ma:a)
		{
			if(q.s.size()>0 && q.s.back()<ma.first) continue;

			q_t nq=q;
			nq.r-=ma.second;
			nq.s.push_back(ma.first);
			if(nq.r<0) continue;
			push(nq);
//printf("%d %.*s\n", nq.r, nq.s.size(), &nq.s[0]);
		}
	}
	return ret;
}


void a_chop(vpii&a)
{
	int x[10]={};
	vpii temp;

	for(auto ma:a)
	{
		int nd=ma.second;
		if(x[nd]<ma.first) x[nd]=ma.first;
	}
	for(int i=1;i<=9;i++)
	{
		if(x[i]==0) continue;
		temp.push_back(make_pair(x[i], i));
	}
	a=temp;
}


int main(void)
{
	int needs[]={1000, 2, 5, 5, 4, 5, 6, 3, 7, 6};
	int n, m;


	while(scanf("%d%d", &n, &m)==2)
	{
		vpii a(m);

		for(int i=0;i<m;i++)
		{
			int ax;
			scanf("%d", &ax);
			a[i]=make_pair(ax+'0', needs[ax]);
		}
		a_chop(a);

		q_t ans=solve(a, n);
		ans.s.push_back(0);
		printf("%s\n", &ans.s[0]);
	}

	return 0;
}
