const ll INF = 1LL<<60;  // 10^18（const int inf   = 1<<29;）

// 0-indexed
class UnionFind {
public:
    vector<ll> par; // 各元の親を表す配列
    vector<ll> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        siz.assign(sz_, 1LL);  // assign: 再代入
        par.resize(sz_);  // resize: 再確保
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

int main() {
    // input(sunippets: inpv, inpn, inps)
    ll N;
    cin >> N;
    set<pll> edges;
    ll s_i, e, d;

    REP(i, N) {
        REP(j, N) {
            cin >> s_i;
            e = i+1;
            d = j+1;
            if (s_i) {
                if (e > d) swap(e, d);
                edges.insert(make_pair(e, d));
            }
        }
    }

    // calculation
    UnionFind uf(210);
    auto begin = edges.begin(), end = edges.end();
    for (auto iter = begin; iter != end; iter++) {
        // *iter = set's element
        pll edg = *iter;
        if (!uf.issame(edg.F, edg.S)) {
            uf.merge(edg.F, edg.S);
        } else {
            cout << -1 << "\n";
            return 0;
        }
    }

    cout << uf.size(1) << "\n";

    return 0;
