int m,n,d[N];
bool memo[2][N],used[2][N],ans;

bool dfs(int prev,int x){
  if(used[prev][x])return memo[prev][x];
  used[prev][x]=true;
  if(!prev&&d[x]){
    int nx=x+d[x];
    if(nx<0)nx=0;
    if(n+1<nx)nx=n+1;
    memo[prev][x]=dfs(1,nx);
    if(!memo[prev][x])ans=false;
    return memo[prev][x];
  }
  for(int i=1;i<=m;i++){
    int nx=x+i;
    if(n+1<nx)nx=n+1;
    memo[prev][x]|=dfs(0,nx);
  }
  if(!memo[prev][x])ans=false;
  return memo[prev][x];
}

int main(){
  while(1){
    cin>>m;
    if(!m)break;
    cin>>n;
    for(int i=1;i<=n;i++)cin>>d[i];
    memset(memo,0,sizeof(memo));
    memset(used,0,sizeof(used));
    memo[0][n+1]=memo[1][n+1]=true;
    ans=true;
    dfs(0,0);
    if(ans)cout<<"OK"<<endl;
