		else if (v != g) puts("No"), exit(0);
	}
	if (x[1][1] == -1 && v != -1e18-18) {
		mk(r, c, v);
	}
}

void mk (int r, int c, ll a) {
	if (a < 0) {
		puts("No");
		exit(0);
	}
	if (m.count(MP(r,c))) {
		if(m[MP(r,c)] != a) {
			puts("No");
			exit(0);
		} else return;
	}
	m[MP(r,c)] = a;
	fo(i, -1, 2) fo(j, -1, 2) {
		check(r+i, c+j);
	}
}

struct thing {
	bool t; ll v;
	//t = 0 means it is v+x
	//t = 1 means it is v-x
};

map<pair<int, int>, thing> k;
set<pair<int, int>> td;
ll mn, mx;

void dfs (int r, int c, bool t, ll v) {
	if (k.count(MP(r,c))) {
		if (k[MP(r,c)].t != t || k[MP(r,c)].v != v) {
			puts("No");
			exit(0);
		}
		return;
	}
	k[MP(r,c)] = {t,v};
	if (t) {
		//v-x >= 0
		//v >= x
		//x is max v
		mx = min(mx, v);
	} else {
		//v+x >= 0
		//x >= -v
		//x is at least -v
		mn = max(mn, -v);
	}
	for (auto to : sum[MP(r,c)]) {
		dfs(to.first.first, to.first.second, t^1, to.second - v);
	}
	for (auto to : sum[MP(r,c)]) {
		dfs(to.first.first, to.first.second, t, to.second + v);
	}
}

