class SegmentTree {
public:
  LL prop[800005];
  LL val[800005];
  void build()
  {
    RESET(prop,0);
    RESET(val,0);
  }
  void push(int ix, int L, int R)
  {
    val[ix*2+1] += prop[ix];
    val[ix*2+2] += prop[ix];
    prop[ix*2+1] += prop[ix];
    prop[ix*2+2] += prop[ix];
    prop[ix] = 0;
  }

  void update(int ix, int L, int R, int x, int y, LL v)
  {
    if (x <= L && R <= y)
    {
      val[ix] += v;
      prop[ix] += v;
      return;
    }
    if (R < x || y < L) return;
    push(ix,L,R);
    int M = (L + R) >> 1;
    update(ix*2+1,L,M,x,y,v);
    update(ix*2+2,M+1,R,x,y,v);
    val[ix] = max(val[ix*2+1],val[ix*2+2]);
  }

  LL query(int ix, int L, int R, int x, int y)
  {
    if (x <= L && R <= y) return val[ix];
    if (R < x || y < L) return -INFF;
    push(ix,L,R);
    int M = (L + R) >> 1;
    return max(query(ix*2+1,L,M,x,y),query(ix*2+2,M+1,R,x,y));
  }
};

