typedef pair<ll, ll> pll;

const int INF = 1e9 + 7;
const int maxn = 1e5 + 5;

int n, res, ans, cnt;
int a[maxn], w[maxn], deg[maxn];
int f[maxn][2], g[maxn];
bool del[maxn];
char s[maxn];
queue<int> q;
vector<int> gph[maxn];

void upd(int &a, int &b, int c){
    if(c >= a)
        b = a,
        a = c;
    else if(c >= b)
        b = c;
    return;
}

void calcF(int u, int p){
    int mx1 = -1, mx2 = -1;
    f[u][0] = w[u],
    f[u][1] = 0;
    FOR(i, 0, gph[u].size()){
        int v = gph[u][i];
        if(v == p || del[v])
            continue;
        calcF(v, u);
        f[u][0] = max(f[u][0], f[v][0] + w[u]);
        upd(mx1, mx2, f[v][0]);
    }
    if(~mx2)
        f[u][1] = mx1 + mx2 + w[u];
    return;
}

void calcG(int u, int p){
	g[u] += w[u];
    int mx1 = -1, mx2 = -1;
    FOR(i, 0, gph[u].size()){
        int v = gph[u][i];
        if(v == p || del[v])
            continue;
        upd(mx1, mx2, f[v][0] + w[u]);
    }
    //printf("u = %d mx1 = %d mx2 = %d g = %d\n", u + 1, mx1, mx2, g[u]);
    FOR(i, 0, gph[u].size()){
        int v = gph[u][i];
        if(v == p || del[v])
            continue;
		if(f[v][0] + w[u] == mx1)
        	g[v] = mx2;
        else
        	g[v] = mx1;
		g[v] = max(g[v], g[u]);
        calcG(v, u);
    }
    return;
}

int main(){
    scanf("%d", &n);
    FOR(i, 1, n){
        int u, v;
        scanf("%d%d", &u, &v);
        --u; --v;
        gph[u].PB(v);
        gph[v].PB(u);
        ++deg[u], ++deg[v];
    }
    scanf("%s", s);
    FOR(u, 0, n)
        if(gph[u].size() == 1 && s[u] == 'B')
            q.PH(u);
    while(q.size()){
        int u = q.front();
        q.pop();
        del[u] = 1;
        FOR(i, 0, gph[u].size()){
            int v = gph[u][i];
            if(!del[v]){
                --deg[v];
                if(deg[v] == 1 && s[v] == 'B')
                    q.PH(v);
            }
        }
    }
    // the ans should be 
    //   the number of verts with (a[i] == 1) in total
    // - the number of verts with (a[i] == 1) on the path
    // + the number of verts with (a[i] == 0) on the path
    // - the length of the path
    FOR(i, 0, n) if(!del[i]){
        a[i] = (s[i] == 'W') ^ (deg[i] & 1);
        w[i] = a[i] ? 1 : (-1);
        ++w[i];
        res += a[i];
