    calcG(0, -1);
    FOR(u, 0, n) if(!del[u]){
    	//printf("%d %d %d %d\n", u + 1, f[u][0], f[u][1], g[u]);
        ans = max(ans, f[u][0] + g[u] - w[u]);
        ans = max(ans, f[u][1]);
    }
    printf("%d\n", res - ans);
	return 0;
}
