using namespace std;

const int maxn = 1e5 + 50;

int n , sz[maxn];
long long ans = 0;
vector < pair < int , int > > Edge[maxn];

void Dfs( int u , int fa = 0 ){
	sz[u] = 1;
	for(auto it : Edge[u]){
		int v = it.first , c = it.second;
		if( v == fa )
			continue;
		Dfs( v , u );
		ans += 1LL * 2 * min( sz[v] , n - sz[v] ) * c;
		sz[u] += sz[v];
	}
}

void Dfs2( int u , int fa = 0 ){
	for(auto it : Edge[u]){
		int v = it.first;
		if( v == fa )
			continue;
		if( sz[v] == n - sz[v] )
			ans -= it.second;
		Dfs2( v , u );
	}
}

int main( int argc , char * argv[] ){
	n = read();
	int Mi = 1e9 + 7;
	for(int i = 2 ; i <= n ; ++ i){
		int u = read() , v = read() , c = read();
		Edge[u].emplace_back( make_pair( v , c ) );
		Edge[v].emplace_back( make_pair( u , c ) );
		Mi = min( Mi , c );
	}
	Dfs( 1 , 0 );
	if( n & 1 )
		ans -= Mi;
	else
		Dfs2( 1 , 0 );
	printf( "%lld\n" , ans );
