// 解き直し.
// ABC 143解説.
// https://img.atcoder.jp/abc143/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
const LL MOD = 1e9 + 7;
const int MAX = 303030;
LL A[MAX][60], ACUM[MAX][60];

// Use of dynamic bitset to convert decimal numbers.
// https://stackoverflow.com/questions/42759330/use-of-dynamic-bitset-to-convert-decimal-numbers
// 10進数 → 2進数.
// @param n: 2進数へ変換したい10進数.
// @param d: 2進数表記する桁数.
// @return: 2進数.
string decimalToBinary(LL n, int d){
    string ret;
    LL ln = abs(n);
    while(ln){
        ret = string((ln & 1) ? "1" : "0") + ret;
        ln /= 2;
    }
    while(ret.size() < d) ret = "0" + ret;
    if(n < 0) ret = "-" + ret;
    return ret;
}

int main(){

    // 1. 入力情報.
    int N;
    scanf("%d", &N);
    LL a;
    string s;
    rep(i, N){
        scanf("%lld", &a);
        s = decimalToBinary(a, 60);
        rep(j, 60) A[i][j] = s[j] - '0';
    }

    // 2. 和の計算.
    rep(i, N) rep(j, 60) ACUM[i + 1][j] = ACUM[i][j] + A[i][j];

    // 3. 解説通り.
    // 0 の 個数 × 1 の 個数.
    LL ans = 0;
    rep(i, 60){
        ans += ((N - ACUM[N][i]) * ACUM[N][i]) << (59 - i);
        ans %= MOD;
    }

    // 4. 出力.
    printf("%lld\n", ans);
    return 0;

