#include<iostream>
#include<complex>
#include<cmath>
#include<algorithm>
using namespace std;
#define REP(i,b,n) for(int i=b;i<n;i++)
#define rep(i,n)   REP(i,0,n)
#define PLUS 1
#define MINUS -1

typedef complex<double> P;
const double eps = 1e-10;

class Robot{
public:
  int flag;
  P pos;
  double r;
  bool operator<(const Robot & a)const{
    if ( abs(r-a.r)>eps)return r < a.r;
    else if ( abs(pos.real()-a.pos.real())>eps)return pos.real()<a.pos.real();
    else return pos.imag()<a.pos.imag();
  }
};

double cross(P a,P b){
  return a.real()*b.imag()-a.imag()*b.real();
}

double solve_equation(double A,double B,double C){
  //cout << A << " " << B << " " << C << endl;
  if ( B*B-4*A*C<0)return -1;
  double ret = (-B-sqrt(B*B-4*A*C))/(2*A);
  return ret;
}

double distance_lp(P b,P c){//c is point
  return abs(cross(b,c))/abs(b);
}

double dist(double x,double y){
  return sqrt(x*x+y*y);
}

void solve(int n,Robot *in,double r,P v){
  double ret = 1e100;
  sort(in,in+n);


  rep(i,n-1){
    REP(j,i+1,min(n,i+4)){
      if ( in[i].flag != in[j].flag   ){
	double A=in[i].pos.real()-in[j].pos.real();
	double B=in[i].pos.imag()-in[j].pos.imag();      
	double tmp;
	if ( in[i].flag<0)
	  tmp= solve_equation(4*v.real()*v.real()+4*v.imag()*v.imag(),
			      -4*A*v.real()-4*B*v.imag(),
			      A*A+B*B-4*r*r);
	else tmp=solve_equation(4*v.real()*v.real()+4*v.imag()*v.imag(),
				4*A*v.real()+4*B*v.imag(),
				A*A+B*B-4*r*r);
	if ( tmp>0 && 
	     in[j].r-in[i].r <=2*r-1e-8
	     )ret=min(ret,tmp);
      }
    }
  }
  if ( ret >1e99)puts("SAFE");
  else printf("%.5lf\n",ret);
}

main(){
  int n;
  while(cin>>n && n){
    Robot in[n];
    P v;
    double r;
    cin>>v.real()>>v.imag();
    cin>>r;
    rep(i,n){
      cin>>in[i].pos.real()>>in[i].pos.imag()>>in[i].flag;
      in[i].r=distance_lp(v,in[i].pos);
    }
    solve(n,in,r,v);
  }
