typedef long long ll;

ll gcd(ll a, ll b){
    if (b) return gcd(b, a%b);
    return a;
}

int div(ll n)
{
    int sq = (int)sqrt(n) + 1;
    int li = 0, cnt = 0;
    for (int i = 2; i <= sq;)
    {
        if (n % i == 0)
        {
            n /= i;
            if (i != li)
            {
                li = i;
                ++cnt;
            }
            sq = (int)sqrt(n) + 1;
        }
        else
            ++i;
    }
    return cnt + (n > 1 ? 1 : 0);
}



