		if (i == 0 and j == 0) continue;
		dp[i][j] = (i - 1 >= 0 ? dp[i - 1][j] : 0) + (j - 1 >= 0 ? dp[i][j - 1] : 0);
	}
	cout << dp.back().back() << endl;
}
