const int maxn = 2e5 + 20;
int fa[2][maxn];
int getFa(int u, int which) {
    if (fa[which][u] == u) return u;
    else return fa[which][u] = getFa(fa[which][u], which);
}
void toMerge(int x, int y, int which) {
    x = getFa(x, which);
    y = getFa(y, which);
    fa[which][y] = x;
}
int id[2][maxn];
set<int>theList[2][maxn];
int ans[maxn];
int calc(set<int> ss1, set<int> ss2) {
    int ans = 0;
    if (ss1.size() > ss2.size()) {
        for (set<int> :: iterator it = ss2.begin(); it != ss2.end(); ++it) {
            ans += ss1.count(*it);
        }
    } else {
        for (set<int> :: iterator it = ss1.begin(); it != ss1.end(); ++it) {
            ans += ss1.count(*it);
        }
    }
    return ans;
}
void work() {
    int n, k1, k2;
    scanf("%d%d%d", &n, &k1, &k2);
    for (int i = 1; i <= n; ++i) {
        fa[0][i] = fa[1][i] = i;
    }
    for (int i = 1; i <= k1; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        toMerge(u, v, 0);
    }
    for (int i = 1; i <= k2; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        toMerge(u, v, 1);
    }
    for (int i = 1; i <= n; ++i) {
        id[0][i] = getFa(i, 0);
        theList[0][id[0][i]].insert(i);
    }
    for (int i = 1; i <= n; ++i) {
        id[1][i] = getFa(i, 1);
        theList[1][id[1][i]].insert(i);
    }
    for (int i = 1; i <= n; ++i) {
//        if (theList[0][id[0][i]].size() == 0 || theList[1][id[1][i]].size() == 0) {
//            ans[i] = 1;
//            continue;
//        }
        ans[i] = calc(theList[0][id[0][i]], theList[1][id[1][i]]);
    }
    for (int i = 1; i <= n; ++i) {
        if (ans[i] == 0) ans[i] = 1;
//        printf("%d ", ans[i]);
    }
    for (int i = 1; i <= n - 1; ++i) {
        printf("%d ", ans[i]);
    }
    printf("%d\n", ans[n]);
}

int main() {
#ifdef local
    freopen("data.txt", "r", stdin);
//    freopen("data.txt", "w", stdout);
#endif
    work();
    return 0;
}
