int n, x;

int solve(int k)
{
    if (k*2<x) return po(2, k);

    int answer = 0;
    for (int j = 0; j<=k; j++) if (k+j<x) answer+=C(k, j);
    for (int t = x/2; t<k; t++)
    {
        if (2*t+1==x) {answer+=1; continue;}
        int n1 = 2*t-k;
        int s = x - 2*(k-t)-n1-1;
        answer+=C(n1, s);
        //cout<<k<<' '<<t<<' '<<n1<<' '<<s<<endl;
    }
    return answer;
}



