	if (s + t == 1)return 1;
	if (dp[s][t][u] >= 0)return dp[s][t][u];
	int minx = 1;
	if (s >= 2)minx = min(minx, solve(s - 2, t + 1, (u + 1) % 2));
	if (s >= 1 && t >= 1)minx = min(minx, solve(s, t - 1, u));
