#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

bool stop;
int board[8][8];
int dr[] = {0,1,1,1,0,-1,-1,-1};
int dc[] = {1,1,0,-1,-1,-1,0,1};

struct poc {
	int row;
	int col;
	int count;
	vector<int> dir;
	bool operator<(const poc& right) const {
		if (count == right.count) {
			if (row == right.row) {
				return (col < right.col);
			}
			else {
				return (row < right.row);
			}
		}
		else {
			return (count > right.count);
		}
	}
};

void update_board(int p, poc c) {
	board[c.row][c.col] = p;
	for (int i = 0; i < (c.dir).size(); ++i) {
		int nr = c.row + dr[c.dir[i]];
		int nc = c.col + dc[c.dir[i]];
		bool find = false;
		while (!find) {
			board[nr][nc] = p;
			nr += dr[c.dir[i]];
			nc += dc[c.dir[i]];
			if (board[nr][nc] == p) {
				find = true;
			}
		}
	}
	return;
}

void play_turn(int p) {
	vector<poc> cand;
	for (int i = 0; i < 8; ++i) {
		for (int j = 0; j < 8; ++j) {
			if (board[i][j] == 0) {
				int count = 0;
				vector<int> ds;
				for (int d = 0; d < 8; ++d) {
					int nr = i + dr[d];
					int nc = j + dc[d];
					int rcmin = min(nr,nc);
					int rcmax = max(nr,nc);
					if (rcmax < 8 && rcmin >= 0 && board[nr][nc] == -p) {
						bool find = false; 
						int tc = 0;
						while (!find) {
							if (board[nr][nc] == p) {
								find = true;
								stop = false;
								ds.push_back(d);
								count += tc;
							}
							else if (board[nr][nc] == -p) {
								++tc;
								nr += dr[d];
								nc += dc[d];
								rcmin = min(nr,nc);
								rcmax = max(nr,nc);
								if (rcmax >= 8 || rcmin < 0) {
									find = true;
								}
							}
							else {
								find = true;
							}
						}
					}
				}
				if (ds.size() > 0) {
					cand.push_back({i,j,count,ds});
				}
			}
		}
	}
	if (cand.size() > 0) {
		sort(cand.begin(),cand.end());
		poc prop = cand[0];
		if (p == -1) {
			int max_c = cand[0].count;
			for (int i = 0; i < cand.size() && cand[i].count == max_c; ++i) {
				prop = cand[i];
			}
		}
		update_board(p,prop);
	}
	return;
}

int main(void) {
	for (int i = 0; i < 8; ++i) {
		for (int j = 0; j < 8; ++j) {
			char c; 
			cin >> c;
			if (c == 'x') {
				board[i][j] = -1;
			}
			else if (c == '.') {
				board[i][j] = 0;
			}
			else {
				board[i][j] = 1;
			}
		}
	}

	stop = false;
	while (!stop) {
		stop = true;
		play_turn(1);
		play_turn(-1);
	}

	for (int i = 0; i < 8; ++i) {
		for (int j = 0; j < 8; ++j) {
			if (board[i][j] == -1) {
				cout << "x";
			}
			else if (board[i][j] == 0) {
				cout << ".";
			}
			else {
				cout << "○";
			}
		}
		cout << endl;
	}
	return 0;
}

