using namespace std;

using ll = long long;

ll solve(ll a, ll b, ll c, ll d) {
    if (a < b) return -1;
    ll cur = a - b;
    if (cur > c) {
        cur -= (cur - c) / b * b;
        if (cur == c) {
            return cur + d;
        }
        if (cur < b) return -1;
        cur -= b;
        cur += d;
    } else {
        cur += d;
    }
    return cur;
}

