		cout << "---";
	cout << endl;
	for(int a=0; a<=p-1; ++a){
		cout <<fill(2)<<a<<" | ";
		for(int b=0; b<=p-1; ++b)
			cout << fill(2)<<(a+b)%p<<" ";
		cout << endl;
	}

	cout << endl << " * | ";
	for(int a=1; a<=p-1; ++a)
		cout <<fill(2)<<a<<" ";
	cout << endl;
	cout << "----";
	for(int i=0;i<p-1;++i)
		cout << "---";
	cout << endl;
	for(int a=1; a<=p-1; ++a){
		cout <<fill(2)<<a<<" | ";
		for(int b=1; b<=p-1; ++b)
			cout << fill(2)<<(a*b)%p<<" ";
		cout << endl;
	}
}


