int minus_inverse(int p, int n){
	int a = p-n;
	for(int b=1; b<p; ++b)
		if((a*b)%p == 1)
			return b;
	return -1;
}
int inverse(int p, int n){
	int a=1;
	while((n*a)%p != 1)
		a++;
	return a;
}
int inverse_minus_inverese(int p, int n){
	int a = inverse(p,n);
	return inverse(p,p-a);
}
