struct UnionFind {
  UnionFind(size_t size) : v(size, -1) {}
  vector<int> v;

  int root(int x) {
    return (v[x] < 0 ? x : v[x] = root(v[x]));
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (v[x] > v[y]) swap(x, y);
      v[x] += v[y];
      v[y] = x;
    }
  }

  int size(int x) {
    return -v[root(x)];
  }
};

signed main(int argc, char *argv[]) {
  int n = in(), m = in();
  vector<int64_t> a(n);
  cin >> a;

  UnionFind uf(n + 1);
  for (int i = 0; i < m; ++i) {
    int x = in(), y = in();
    uf.unite(x, y);
  }

  vector<pair<int64_t, int>> v(n);
