#include <cstdint>
#include <iostream>
#include <vector>

using namespace std;

struct GameData
{
    vector<int64_t> healths;
    int64_t direct;
    int64_t collateral;
};

int64_t DirectNeeded(const GameData &game, int64_t health, int64_t moves)
{
    auto diff = game.direct - game.collateral;
    return (health - game.collateral * moves + diff - 1) / diff;
}

bool CanBeat(const GameData &game, int64_t moves)
{
    int64_t needed = 0;
    for (const auto &h : game.healths) {
        needed += DirectNeeded(game, h, moves);
    }
    return needed <= moves;
}

int64_t Solve(const GameData &game)
{
    int64_t moves = 0;
    int64_t power = (1LL << 60);

    while (power > 0) {
        auto next_moves = moves + power;
        power >>= 1;

        if (!CanBeat(game, next_moves)) {
            moves = next_moves;
        }
    }
    return moves + 1;
}

GameData ReadGameData()
{
    GameData game;
    int n;

    cin >> n >> game.direct >> game.collateral;
    game.healths.resize(n);

    for (auto &h : game.healths) {
        cin >> h;
    }
    return game;
}

int main()
{
    auto res = Solve(ReadGameData());
    cout << res << "\n";
    return 0;
}
