#include<bits/stdc++.h>
using namespace std;

struct seg_tree{
    int N;
    vector<int>xv,yv,xc,yc,lz;
    void init(int n,int *v){
        N=1;
        while(n>N)N*=2;
        xv.assign(N*2-1,0);
        yv.assign(N*2-1,0);
        xc.assign(N*2-1,0);
        yc.assign(N*2-1,0);
        lz.assign(N*2-1,0);

        for(int i=0;i<n-1;i++){
            if(v[i]<v[i+1])xc[i+N-1]++;
            else yc[i+N-1]++;
        }
        for(int i=N-2;i>=0;i--)update(i);

    }
    void evaluate(int k){
        xv[k]+=xc[k]*lz[k];
        yv[k]-=yc[k]*lz[k];
        if(k<N-1){
            lz[k*2+1]+=lz[k];
            lz[k*2+2]+=lz[k];
        }
        lz[k]=0;
    }
    void update(int k){
        xv[k]=xv[k*2+1]+xv[k*2+2];
        yv[k]=yv[k*2+1]+yv[k*2+2];
        xc[k]=xc[k*2+1]+xc[k*2+2];
        yc[k]=yc[k*2+1]+yc[k*2+2];
    }
    void add(int a,int b,int x){add(a,b,x,0,0,N);}
    void add(int a,int b,int x,int k,int l,int r){
        evaluate(k);
        if(r<=a||b<=l)return;
        if(a<=l&&r<=b){
            lz[k]+=x;
            evaluate(k);
            return;
        }
        add(a,b,x,k*2+1,l,(l+r)/2);
        add(a,b,x,k*2+2,(l+r)/2,r);
        update(k);
    }
    int getSum(int a,int b){return getSum(a,b,0,0,N);}
    int getSum(int a,int b,int k,int l,int r){
        evaluate(k);
        if(r<=a||b<=l)return 0;
        if(a<=l&&r<=b)return xv[k]+yv[k];
        int vl=getSum(a,b,k*2+1,l,(l+r)/2);
        int vr=getSum(a,b,k*2+2,(l+r)/2,r);
        return vl+vr;
    }
};

int N,Q;
vector<int>G[150000];

int vs[300000],in[150000],out[150000],depth[150000],par[20][150000];
seg_tree seg;
void dfs(int v,int p,int d,int &k){
    vs[k]=v;
    in[v]=out[v]=k;
    par[0][v]=p;
    depth[k++]=d;

    for(int i=0;i<G[v].size();i++){
        int to=G[v][i];
        if(to==p)continue;
        dfs(to,v,d+1,k);
        vs[k]=v;
        out[v]=k;
        depth[k++]=d;
    }
}

void init(){
    memset(par,-1,sizeof(par));
    int k=0;
    dfs(0,-1,0,k);
    seg.init(N*2-1,vs);

    for(int i=1;i<20;i++){
        for(int j=0;j<N;j++){
            if(par[i-1][j]==-1)continue;
            par[i][j]=par[i-1][par[i-1][j]];
        }
    }
}

int lca(int u,int v){
    if(depth[v]<depth[u])swap(v,u);
    for(int i=0;i<20;i++){
        if((depth[v]-depth[u])>>i&1){
            v=par[i][v];
            u=par[i][u];
        }
    }
    if(v==u)return v;
    for(int i=19;i>=0;i--){
        if(par[i][v]!=par[i][u]){
            v=par[i][v];
            u=par[i][u];
        }
    }
    return par[0][v];
}

int main(){
    scanf("%d%d",&N,&Q);
    for(int i=0;i<N-1;i++){
        int a,b;
        scanf("%d%d",&a,&b);
        G[a].push_back(b);
        G[b].push_back(a);
    }

    init();

    while(Q--){
        int type,a,b;
        scanf("%d%d%d",&type,&a,&b);
        if(type==0){
            int p=lca(a,b);
            int x=seg.getSum(0,in[a]);
            int y=seg.getSum(0,in[b]);
            int z=seg.getSum(0,in[p]);
            printf("%d\n",x+y-2*z);
        }
        else{
            seg.add(in[a],out[a],b);
        }
    }

    return 0;
