vector<Int> A(3), B(3);

Int secondB(Int N){
  if(N >= 10000) return N;
  Int res = N;
  for(Int i=0; i <= N;i++){
    for(Int j=0;j <= N;j++){
      Int a = i;
      Int b = j;
      Int r = (N - (a * B[0] + b * B[1]));
      if(r < 0) break;
      Int c = r / B[2];
      int t = r % B[2];
      Int M = a * A[0] + b * A[1] + max(c * A[2] + t, r);
      Max(res, M);
    }
  }
  return res;
}

Int firstA(Int N){
  Int res = N;
  for(Int i=0;i <= N;i++){
    for(Int j=0;j <= N;j++){
      Int a = i;
      Int b = j;
      Int r = (N - (a * A[0] + b * A[1]));
