const int maxn=131172;
int h[maxn],mem;
struct
{
    int v,w,next;
}e[maxn];
long long mid;
void add(int u,int v,int w)
{
    e[mem].v=v;
    e[mem].w=w;
    e[mem].next=h[u];
    h[u]=mem++;
}
vector<pair<long long,long long> > q[maxn];
bool cmp1(pair<long long,long long> a,pair<long long,long long> b)
{
    if(a.first!=b.first) return a.first<b.first;
    return a.second<b.second;
}
bool cmp2(pair<long long,long long> a,pair<long long,long long> b)
{
    if(a.second!=b.second) return a.second<b.second;
    return a.first<b.first;
}
void Merge(int f,int l,int r)
{
    if(q[l].size()>q[r].size())
        swap(l,r);
    if(q[l].size()==0) return ;
    sort(q[l].begin(),q[l].end(),cmp2);
    sort(q[r].begin(),q[r].end(),cmp1);

    long long mi=-1;
    int s=0;
    for(int i=q[l].size()-1;i>=0;i--)
    {
        while(s<q[r].size()&&q[r][s].first+q[l][i].second<=mid){
            s++;
            if(mi==-1) mi=q[r][s].second;
            else mi=min(mi,q[r][s].second);
        }
        if(mi!=-1){
            q[f].push_back(make_pair(q[l][i].first,mi));
        }
    }

    mi=-1;
    s=0;
    sort(q[l].begin(),q[l].end(),cmp1);
    sort(q[r].begin(),q[r].end(),cmp2);

    for(int i=q[l].size()-1;i>=0;i--)
    {
        while(s<q[r].size()&&q[r][s].second+q[l][i].first<=mid){
            s++;
            if(mi==-1) mi=q[r][s].first;
            else mi=min(q[r][s].first,mi);
        }
        if(mi!=-1){
            q[f].push_back(make_pair(mi,q[l][i].second));
        }
    }
}

void dfs(int u)
{
    q[u].clear();
    if(h[u]==-1)
    {
        q[u].push_back(make_pair(0,0));
        return ;
    }
    int ls=0,rs,lw,rw;
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        dfs(v);
        if(ls==0){
            ls=v;
            lw=e[i].w;
        }
        else{
            rs=v;
            rw=e[i].w;
        }
    }
    for(int i=0;i<q[ls].size();i++)
    {
        q[ls][i].first+=lw;
        q[ls][i].second+=lw;
    }
    for(int i=0;i<q[rs].size();i++)
    {
        q[rs][i].first+=rw;
        q[rs][i].second+=rw;
    }
    Merge(u,ls,rs);
}
