#define REP(i,b,n) for(int i=b;i<n;i++)
#define rep(i,n)   REP(i,0,n)
const int N = 16;
int dp[1<<N];
int w[1<<N];
int h[1<<N];

int solve(int n,int st,const int wlim){
  if (st == (1<<n)-1){
    return 0;
  }
  int &ret = dp[st];
  if (ret != -1){
    return ret;
  }
  ret = (1<<20);
  REP(i,1,(1<<n)){
    if (i&st)continue;
    int score = h[i];
    if (wlim < w[i])continue;
    solve(n,st|i,wlim);
    ret = min(ret,solve(n,st|i,wlim)+score*2);
  }
  return ret;
}

main(){
  int n,m,wlim;
  while(cin>>n>>m>>wlim && n){
    m--;
    int mh = 0;
    vector<int> height,weight;
    rep(i,n){
      int cnt;
      cin>>cnt;
      rep(j,cnt){
	int tmp;cin>>tmp;height.push_back(i);weight.push_back(tmp);
	mh = max(mh,i);
      }
    }
    if (mh == 0){
      cout << 0 << endl;
      continue;
    }

    int size = height.size();
