int main() {
  int l;
  cin >> l;

  double dl = l;

  double max = 0;

  for(double i = 0.01 ; i <= dl; i += 0.01)
  {
    double j;
    for(j = 0.1; j <= dl - i; j += 0.1)
    {
      double k = dl - j - i;
      if((i*j*k) > max )
      max = i*j*k;
    }
  }
  cout << max << endl;
  return 0;
}

// funcの実体
// ------------------------------------------------
int CalcSumOfDigit(int n)
{
  int s = 0;
  while(n)
  {
    s += n % 10;
    n = n / 10;
  }
  return s;
