vll func_(ll M){
  vll C(M+1);
  for(ll x = 1; x<=M; x++){
    for(ll y = 1; y<=M; y++){
      for(ll z = 1; z<=M; z++){
        ll n = x*x +y*y + x*y + z*z +x*z+y*z;
        if(n<M){
          C[n] +=1;
        }
      }
    }
  }
  return C;
}
