                getV.push_back(v[i]);
            }
            sort(getV.begin(), getV.end());
            for (int i = 0; i < K - k; i++) {
                if (getV.size() > 0 && getV[i] < 0) {
                    sum -= getV[i];
                }
                else {
                    break;
                }
            }
            score.push_back(sum);
        }
    }

    cout << *max_element(score.begin(), score.end()) << endl;

    return 0;
}
