int solve(int n, int a[], int b[]){
	int dp[n + 1];
	dp[0] = 0;
	for (int i = 1; i <= n; i++){
		dp[i] = 0;
		for (int j = 0; j < 3; j++){
			if (i - a[j] >= 0) dp[i] = max(dp[i], dp[i - a[j]] + b[j]);
		}
	}
	return dp[n];
}
